package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs with hard lower-OK / upper-fail bounds and
//     no time decay: a stale bound costs one retry to refresh, which is
//     cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - JOINT ROUTE-SET PLANNING (min-cost-flow style): the planner always
//     builds a full COVER of the remaining amount over several disjoint
//     corridors, each shard sized to that corridor's believed bottleneck,
//     and only accepts it when the cover is complete enough to be worth
//     starting. This is the main change over the previous generation, which
//     preferred a single big shard and only fell back to a split after that
//     shard had already failed. The eval data showed exactly that pathology:
//     large payments burning 15-20 attempts on descending single corridors
//     and then terminating with "no route found".
//   - AGGRESSIVE PART USE for large payments: when the remaining amount is
//     large relative to what any corridor can bear, we go straight to many
//     small-ish shards instead of probing halves.
//   - Depth-aware lower retries instead of blacklisting.
//   - Duplicate-attempt suppression on (path, amount).
//   - Non-liquidity failures (fee, cltv, min, disabled) are repaired in the
//     local policy view rather than treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	maxRouteHops = 7

	maxAttempts   = 80
	maxFailStreak = 26

	probeBudget = 12

	minShard = lnwire.MilliSatoshi(1_000)

	feeWeight = 4.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear when SIZING a shard.
	priorSafeNum = 33
	priorSafeDen = 100

	provenCenterNum = 62
	provenCenterDen = 100

	queueMinProb = 0.15
)

type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	okAmt lnwire.MilliSatoshi

	failAmt lnwire.MilliSatoshi
	hasFail bool

	succ    bool
	drained lnwire.MilliSatoshi

	inFlight lnwire.MilliSatoshi

	misses int
	dead   bool
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	low := math.Exp(-x * 3.2)
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	inEdges map[route.Vertex][]*edge
	byKey   map[edgeKey]*edge

	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan.
	queued []*plan

	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push over
// an edge. Zero means unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can bear with decent
// probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node    route.Vertex
	dist    float64
	amt     lnwire.MilliSatoshi
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every hop's
// policy and belief bounds.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// hardBottleneck is the delivered amount a corridor could bear if every hop
// were as full as our HARD bounds allow. Used to decide whether a corridor is
// worth probing at all.
func (r *router) hardBottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.availCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with a
// bonus for finishing the payment outright, a light fee penalty, and a cost
// for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// bestOnPath prices a corridor at descending amounts starting from hi and
// returns the best novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount. It returns the corridor
// and the largest ladder amount it was found for.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 7 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// flowPlan is a full joint route-set: a set of disjoint corridors with shard
// amounts, plus how much of the requested amount they cover in total.
type flowPlan struct {
	shards  []*plan
	covered lnwire.MilliSatoshi
}

// planFlow decomposes the remaining amount over up to partsLeft DISJOINT
// corridors, sizing each shard to what that corridor's weakest hop is
// believed able to bear. This is the min-cost-flow style joint plan: unequal
// parallel corridors each get a shard that fits.
//
// cap0 optionally limits the FIRST shard, which lets the caller ask for a
// plan whose shards are all "small" (many-parts mode for large payments).
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool, shardCap lnwire.MilliSatoshi) *flowPlan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	fp := &flowPlan{}
	left := remaining

	for k := uint32(0); k < partsLeft; k++ {
		if left < minShard {
			break
		}

		want := left
		if shardCap > 0 && shardCap < want {
			want = shardCap
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			// The corridor exists but is believed too thin; try to
			// price it at its hard bound instead of dropping it.
			if hb := r.hardBottleneck(path); hb >= minShard {
				amtS = hb
				if amtS > want {
					amtS = want
				}
			} else {
				break
			}
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			break
		}

		fp.shards = append(fp.shards, pl)
		fp.covered += pl.amt
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	if len(fp.shards) == 0 {
		return nil
	}
	if fp.covered > remaining {
		fp.covered = remaining
	}
	return fp
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next still-valid shard from a joint plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}
		return rt
	}
	return nil
}

// planSingle searches jointly over shard amount and corridor for the single
// best next attempt.
func (r *router) planSingle(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *plan {

	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	return best
}

// RequestRoute plans the next shard.
//
// Strategy: serve any queued shard from an existing joint plan first. Then
// compute the best single attempt AND a full joint route-set cover of the
// remaining amount. If the cover reaches materially further than the single
// attempt, commit to the cover: its first shard goes out now and the rest are
// queued. When even the greedy cover falls short, try a many-parts cover with
// a smaller per-shard cap, which is what actually rescues large payments over
// a network of unequal corridors.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	best := r.planSingle(amt, partsLeft, busy)

	// Joint route-set planning. Always consider it when we may split, not
	// only when the single best plan falls short: an unequal cover over
	// several corridors is frequently better than one large risky shard.
	if partsLeft > 1 {
		var cands []*flowPlan

		if fp := r.planFlow(amt, partsLeft, busy, 0); fp != nil {
			cands = append(cands, fp)
		}

		// Many-parts covers: cap each shard so the greedy walk spreads
		// over more corridors rather than betting the bulk of the
		// payment on the first (widest-looking) one. This is what
		// large payments over unequal corridors need.
		need := amt
		if best != nil && best.amt >= amt {
			need = 0
		}
		if need > 0 {
			for _, div := range []uint32{2, 3, 5, 8} {
				if div > partsLeft {
					break
				}
				capS := amt / lnwire.MilliSatoshi(div)
				if capS < minShard {
					break
				}
				fp := r.planFlow(
					amt, partsLeft, busy, capS,
				)
				if fp != nil {
					cands = append(cands, fp)
				}
			}
		}

		var pick *flowPlan
		for _, fp := range cands {
			if pick == nil {
				pick = fp
				continue
			}
			// Prefer the cover that reaches furthest; break ties
			// on fewer shards and better first-shard score.
			switch {
			case fp.covered > pick.covered+pick.covered/64:
				pick = fp
			case pick.covered > fp.covered+fp.covered/64:
			case len(fp.shards) < len(pick.shards):
				pick = fp
			case len(fp.shards) == len(pick.shards) &&
				fp.shards[0].score > pick.shards[0].score:
				pick = fp
			}
		}

		if pick != nil {
			first := pick.shards[0]
			take := false
			switch {
			case best == nil:
				take = true
			case best.amt >= amt:
				// Single shard already covers everything: only
				// switch if it is genuinely unlikely and the
				// cover is confident.
				take = best.prob < 0.35 &&
					pick.covered >= amt &&
					first.prob > best.prob*1.4
			default:
				// Prefer the plan that covers more of the
				// remaining amount; a slightly worse first
				// shard is fine if the plan as a whole covers
				// materially more.
				take = pick.covered >
					best.amt+best.amt/16 ||
					(pick.covered >= best.amt &&
						first.score >
							best.score*0.9)
			}

			if take {
				r.queued = pick.shards[1:]
				best = first
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded but
// whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Beliefs just changed, so any queued joint plan is stale.
	r.queued = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote hops
	// so we stop re-picking this corridor without destroying hard bounds.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		// A policy repair does not mean the corridor is bad, so do not
		// let it count against the progress budget.
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "min":
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	b.succ = false

	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - COMPLEMENTARY REASONING across the two sides of a channel, which is
//     new here and is where bimodality pays best:
//       * liquidity proven to sit on the reverse side cannot also sit on
//         this side, so capacity minus the reverse lower bound is a hard
//         upper bound on this direction, and
//       * a reverse-direction failure at a small amount means the reverse
//         side is empty, so under a bimodal split nearly the whole channel
//         sits on THIS side: that turns a remote failure into a positive
//         signal for the opposite direction.
//   - Depth-aware lower retries with a per-direction failure counter: a
//     direction that has come up dry three times stops being probed for the
//     rest of the payment instead of being ground down geometrically.
//   - JOINT ROUTE-SET PLANNING with a real max-flow style budget: before
//     handing out any shard for a large payment we compute the believed
//     deliverable flow over disjoint corridors. If the whole remainder can
//     only be covered by K shards, all K are planned up front and queued,
//     each sized to its own corridor's bottleneck.
//   - LOCAL-CHANNEL FLOW CAP: no shard may exceed the largest single local
//     channel balance, since a shard leaves through exactly one first hop;
//     the planner spreads shards across DIFFERENT first hops so a payment
//     larger than any single local channel is decomposed instead of retried.
//   - PROGRESSIVE SALVAGE whenever the payment is allowed to be split at
//     all: partial delivery is progress because a settled shard shrinks the
//     remainder, so salvage is no longer gated on a free concurrent part.
//   - HOPELESS-PAYMENT DETECTION: our own balances are known exactly, so a
//     remainder above everything we can push out of our channels (or, for a
//     single-part payment, above our biggest channel) is abandoned at once
//     rather than ground through dozens of doomed attempts.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_200)
	attemptCostPPM  = lnwire.MilliSatoshi(6_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 64
	maxFailStreak = 20

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 5.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear. Under the bimodal prior this is
	// close to the amount maximizing expected delivered value.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// compSlackNum/compSlackDen discounts the complementary upper bound
	// derived from the reverse direction's proven liquidity, leaving a
	// little slack for drift.
	compSlackNum = 90
	compSlackDen = 100

	// revEmptyNum/revEmptyDen is the fraction of the liquidity implied on
	// this side by a reverse-direction failure that we are willing to bank
	// on. A reverse failure at f means the reverse side holds under f, so
	// under bimodality this side holds close to capacity minus f.
	revEmptyNum = 80
	revEmptyDen = 100

	// maxDryProbes is how many liquidity failures a single direction may
	// contribute before we stop probing it lower for this payment.
	maxDryProbes = 3

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the corridors a single flow decomposition walks.
	flowRounds = 12

	// hopelessStreak is how many consecutive failures we tolerate before
	// trusting the belief-derived local budget for a give-up decision.
	hopelessStreak = 4
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

// revKey is the key of the same channel in the opposite direction.
func (e *edge) revKey() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.from}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// fails counts liquidity failures charged to this direction. Repeated
	// misses mean the direction is dry, not that we should keep halving.
	fails int

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// mppOK reports whether this payment may be split at all.
func (r *router) mppOK() bool {
	return r.spec.MaxParts > 1
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// view returns a read-only belief for a directed channel, substituting a
// zero-value belief when we have no evidence at all.
func (r *router) view(k edgeKey) *belief {
	if b, ok := r.beliefs[k]; ok {
		return b
	}
	return &belief{}
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath. After several dry probes we stop entirely:
// grinding the same direction down by halves is the main source of wasted
// retries.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	if b.fails >= maxDryProbes {
		return b.okAmt
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.40 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// compBound is the complementary upper bound on a direction: liquidity we
// have proven sits on the reverse side cannot also sit on this side. It
// returns the channel capacity when we know nothing about the reverse side.
func (r *router) compBound(e *edge) lnwire.MilliSatoshi {
	rb := r.beliefs[e.revKey()]
	if rb == nil || rb.okAmt == 0 {
		return e.capacity
	}
	held := rb.okAmt * compSlackNum / compSlackDen
	if held >= e.capacity {
		return 0
	}
	return e.capacity - held
}

// provenCenter is the amount we believe this direction actually holds. It
// combines a demonstrated forward (less what we have since drained) with the
// complementary inference that a reverse-direction failure at a small amount
// means the funds are on THIS side.
func (r *router) provenCenter(e *edge) lnwire.MilliSatoshi {
	var center lnwire.MilliSatoshi

	b := r.beliefs[e.key()]
	if b != nil && b.succ {
		c := e.capacity * provenCenterNum / provenCenterDen
		if c > b.drained {
			center = c - b.drained
		}
	}

	// Bimodal complement: the reverse side came up dry at failAmt, so this
	// side is holding close to the whole channel.
	if rb := r.beliefs[e.revKey()]; rb != nil && rb.hasFail {
		if e.capacity > rb.failAmt {
			inf := (e.capacity - rb.failAmt) *
				revEmptyNum / revEmptyDen
			if inf > center {
				center = inf
			}
		}
	}

	if b != nil && b.okAmt > center {
		center = b.okAmt
	}

	return center
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else {
		if comp := r.compBound(e); comp < c {
			c = comp
		}
		if b != nil && b.hasFail {
			// Retry below the proven failure point rather than
			// blacklisting the channel outright.
			if lim := retryLimit(b, e.capacity); lim < c {
				c = lim
			}
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.view(e.key())
	est := e.capacity * priorSafeNum / priorSafeDen
	if b.okAmt > est {
		est = b.okAmt
	}
	if !b.hasFail {
		// A proven forward, or a dry reverse direction, says most of
		// the channel funds sit on this side.
		if c := r.provenCenter(e) * 85 / 100; c > est {
			est = c
		}
	} else if lim := retryLimit(b, e.capacity); est > lim {
		est = lim
	}
	if b.misses > 0 {
		est = est / lnwire.MilliSatoshi(1+b.misses)
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.view(e.key())
	if b.dead {
		return 0
	}

	eff := amt + b.inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	// The complementary bound is hard evidence: that much liquidity is
	// provably parked on the other side of the channel.
	if comp := r.compBound(e); eff > comp {
		return minProb / 4
	}

	var p float64
	switch {
	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)
		center := r.provenCenter(e)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case center > 0 && !b.hasFail:
			// Bimodal optimism: the funds are believed to sit on
			// this side, less whatever we have drained since.
			q := 1.0 / (1.0 + math.Exp(
				(float64(eff)/float64(center)-1)*4.5,
			))
			p = 0.3*p + 0.7*q

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if b.misses > 0 {
		m := b.misses
		if m > 3 {
			m = 3
		}
		p *= math.Pow(0.6, float64(m))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds the whole payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// rawLocalBudget is the total balance across our own channels, ignoring all
// beliefs and policies. It is a hard ceiling on anything we can deliver.
func (r *router) rawLocalBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		total += bal
	}
	return total
}

// rawMaxLocal is the largest single local channel balance, which bounds one
// shard: a shard leaves through exactly one first hop.
func (r *router) rawMaxLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		if bal > best {
			best = bal
		}
	}
	return best
}

// maxLocalEdge is the largest single local channel balance still free, which
// is the true ceiling on one shard.
func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, exact local channel balances, and
// evidence-derived sizes just below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK < 4 && r.mppOK() {
		maxK = 4
	}
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Local channel balances are exact knowledge, and a shard sized to a
	// local channel is exactly what a fan-out split wants.
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= minShard {
			add(c - c/200)
		}
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies. Maximizing p*amt is
// exactly maximizing delivered value per attempt.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 7 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
//
// It keeps going until either the whole remainder is covered or no further
// disjoint corridor exists, and it caps each shard at the largest single
// local channel so a shard is never planned larger than one first hop can
// carry.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	single := r.maxLocalEdge()

	var out []*plan
	left := remaining

	// Queued shards are handed out on later calls, as concurrency frees
	// up, so the decomposition is not bounded by the parts free right now.
	rounds := 1
	if r.mppOK() {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if single > 0 && want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			// The corridor cannot bear anything novel, so retire
			// its first hop and move on instead of aborting the
			// whole decomposition.
			avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// flowTotal is the amount a plan set delivers in aggregate.
func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// hopeless reports whether the remainder is provably beyond what our own
// channels can still push. Our balances are exact, so this catches payments
// that no amount of retrying could ever complete, which is where the retry
// budget used to drain away.
func (r *router) hopeless(amt lnwire.MilliSatoshi, inFlight uint32) bool {
	if inFlight > 0 {
		return false
	}
	if len(r.localBalances) == 0 {
		return false
	}

	// Hard ceiling: total outbound balance.
	if r.rawLocalBudget() < amt {
		return true
	}

	// A payment that may not be split must fit through one channel.
	if !r.mppOK() && r.rawMaxLocal() < amt {
		return true
	}

	// Softer test, only once we have actually confirmed dryness by
	// failing: the believed-free local liquidity cannot cover the rest.
	if r.failStreak >= hopelessStreak && len(r.localEdges) > 0 &&
		r.localBudget() < amt {

		return true
	}

	return false
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor: for every candidate amount (largest first) it finds the best
// risk-adjusted path, re-prices that path at the amount its weakest hop can
// bear, and finally checks whether a deliberate multi-corridor split would
// cover more of the remaining amount than the best single shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}
	if r.hopeless(amt, inFlightHtlcs) {
		return nil, errors.New("remainder exceeds local liquidity")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()
	split := r.mppOK()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when the payment cannot be split.
		if !split && a < amt {
			r.queued = nil
			break
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		r.attempts++
		return rt, nil
	}

	// A single shard can never exceed what one local channel can push,
	// since a shard leaves through exactly one first hop.
	hi := amt
	if single := r.maxLocalEdge(); single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}
			if !split && a < amt {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly. We
	// compare the aggregate believed flow of the plan set against the best
	// single shard: covering more of the payment beats a slightly nicer
	// first hop, because every uncovered millisat is a failed payment.
	if split && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total := flowTotal(flow)
			first := flow[0]

			if best == nil || total > best.amt {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	// Last resort: deliver whatever we can. Even a small settled shard
	// reduces the remainder and refreshes evidence, which is strictly
	// better than terminally giving up on the payment.
	if best == nil {
		best = r.salvage(amt, busy, split)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// salvage hunts for any novel attempt at all, walking a wide descending
// amount ladder over both the disjoint and the unrestricted graph. It is the
// difference between delivering part of a payment and abandoning it.
func (r *router) salvage(remaining lnwire.MilliSatoshi, busy map[uint64]bool,
	split bool) *plan {

	if !split {
		// Without splitting, only a full-amount attempt helps.
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		if r.failedSigs[planSig(path, remaining)] {
			return nil
		}
		rt, p, err := r.makeRoute(path, remaining)
		if err != nil {
			return nil
		}
		return &plan{path: path, rt: rt, amt: remaining, prob: p}
	}

	a := remaining
	for i := 0; i < 22 && a >= minShard; i++ {
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.findPath(a, avoid)
			if err != nil {
				continue
			}
			if pl := r.bestOnPath(path, a, remaining); pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable, and it is what
// feeds the complementary bounds on the reverse direction.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	b.fails = 0
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Beliefs just changed, so any queued joint plan is stale.
	r.queued = nil

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread suspicion over the remote hops so
	// we stop re-picking this corridor without destroying the hard bounds
	// we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			// Optimism earned from older evidence cannot survive a
			// corridor that just failed somewhere inside it.
			b.succ = false
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// generous bump is cheaper than another failed attempt.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	b.fails++
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false
	b.drained = 0

	// A local channel failing means our balance estimate was too high, and
	// it also invalidates the complementary inference that the far side of
	// that channel is the empty one.
	if failIdx == 0 {
		rk := edgeKey{chanID: h.ChannelID, to: rt.SourcePubKey}
		if rb, ok := r.beliefs[rk]; ok {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary (v9):
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs with hard lower-OK / upper-fail bounds and
//     NO time decay (decay lost to hard bounds in prior experiments).
//   - Balance bookkeeping on settle plus complementary reasoning across the
//     two sides of a channel (bimodality makes a remote failure a positive
//     signal for the opposite direction).
//   - JOINT ROUTE-SET PLANNING: a max-flow style decomposition over disjoint
//     corridors, each shard sized to its own corridor's bottleneck and capped
//     by the local channel it leaves through.
//   - NEW: PROBE-FIRST DISCOVERY for large payments. The dominant observed
//     failure mode was burning the whole attempt budget on one huge payment
//     whose corridors were mostly unattributable ("failed_at_hop -1")
//     failures at long hop counts. When the remainder is large relative to
//     what we believe corridors can bear, we deliberately send a SMALL
//     leading shard to learn bounds cheaply, then scale up. Evidence bought
//     at 1/8 the amount costs the same one attempt but tells us as much.
//   - NEW: PER-CORRIDOR ATTEMPT BUDGETS. A corridor (first-hop, target-side
//     pair) that has failed twice is retired for the payment. This is what
//     stops the 64-attempt grind: the old code kept re-deriving nearly the
//     same path from beliefs it had already invalidated.
//   - NEW: UNATTRIBUTABLE-FAILURE HANDLING is much stronger. A -1 failure on
//     an N-hop route is charged as a soft upper bound to every remote hop at
//     that hop's amount, so the corridor genuinely gets cheaper to abandon,
//     and a hop-count penalty grows with the number of long-route misses.
//   - NEW: ADAPTIVE ATTEMPT BUDGET. Attempts are spent where they buy
//     information: the budget shrinks once repeated shards stop moving the
//     remainder, and we give up early rather than at 64.
//   - Progressive salvage, hopeless detection, duplicate suppression and
//     non-liquidity policy repair are all preserved from the prior champion.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	attemptCostBase = lnwire.MilliSatoshi(1_200)
	attemptCostPPM  = lnwire.MilliSatoshi(6_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	maxRouteHops = 6

	// maxAttempts and maxFailStreak bound how long we keep trying. The
	// budget is deliberately tighter than before: past ~30 attempts on one
	// payment the marginal success probability observed was ~0, while every
	// attempt costs retry efficiency.
	maxAttempts   = 34
	maxFailStreak = 12

	probeBudget = 12

	minShard = lnwire.MilliSatoshi(1_000)

	feeWeight = 5.0
	partCost  = 0.004

	priorSafeNum = 35
	priorSafeDen = 100

	provenCenterNum = 62
	provenCenterDen = 100

	compSlackNum = 90
	compSlackDen = 100

	revEmptyNum = 80
	revEmptyDen = 100

	maxDryProbes = 3

	queueMinProb = 0.15

	flowRounds = 12

	hopelessStreak = 4

	// corridorBudget is how many failures one corridor may contribute
	// before it is retired for the rest of the payment.
	corridorBudget = 2

	// probeFrac is the fraction of the remainder used for a discovery
	// shard when we have no idea what the network can bear.
	probeFracNum = 1
	probeFracDen = 8

	// stallLimit is how many consecutive attempts may fail without the
	// remaining amount shrinking before we stop escalating and start
	// shrinking shards aggressively.
	stallLimit = 3
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) revKey() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.from}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	okAmt lnwire.MilliSatoshi

	failAmt lnwire.MilliSatoshi
	hasFail bool

	succ bool

	fails int

	drained lnwire.MilliSatoshi

	inFlight lnwire.MilliSatoshi

	// soft is a soft upper bound from unattributable failures: the
	// smallest amount this hop took part in when the corridor failed
	// somewhere. It discounts probability without destroying hard bounds.
	soft    lnwire.MilliSatoshi
	hasSoft bool

	misses int

	dead bool
}

// bimodalPrior is the success probability with no direct evidence.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	low := math.Exp(-x * 3.2)
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	inEdges map[route.Vertex][]*edge
	byKey   map[edgeKey]*edge

	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	pending map[uint64]*route.Route

	queued []*plan

	failedSigs map[string]bool

	// corridorFails counts failures charged to a corridor signature so a
	// repeatedly failing corridor can be retired for the payment.
	corridorFails map[string]int

	// retired names first-hop channels that no longer earn attempts.
	retired map[uint64]bool

	failStreak int
	attempts   int

	// longMiss counts unattributable failures, used to penalize long
	// routes which are structurally harder to diagnose.
	longMiss int

	// lastRemaining/stalls track whether attempts are making progress.
	lastRemaining lnwire.MilliSatoshi
	stalls        int

	// probed records that we have already spent a discovery shard.
	probed bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
		corridorFails: make(map[string]int),
		retired:       make(map[uint64]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// mppOK reports whether this payment may be split at all.
func (r *router) mppOK() bool {
	return r.spec.MaxParts > 1
}

func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

func (r *router) view(k edgeKey) *belief {
	if b, ok := r.beliefs[k]; ok {
		return b
	}
	return &belief{}
}

func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	if b.fails >= maxDryProbes {
		return b.okAmt
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.40 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// compBound is the complementary upper bound on a direction.
func (r *router) compBound(e *edge) lnwire.MilliSatoshi {
	rb := r.beliefs[e.revKey()]
	if rb == nil || rb.okAmt == 0 {
		return e.capacity
	}
	held := rb.okAmt * compSlackNum / compSlackDen
	if held >= e.capacity {
		return 0
	}
	return e.capacity - held
}

// provenCenter is the amount we believe this direction actually holds.
func (r *router) provenCenter(e *edge) lnwire.MilliSatoshi {
	var center lnwire.MilliSatoshi

	b := r.beliefs[e.key()]
	if b != nil && b.succ {
		c := e.capacity * provenCenterNum / provenCenterDen
		if c > b.drained {
			center = c - b.drained
		}
	}

	if rb := r.beliefs[e.revKey()]; rb != nil && rb.hasFail {
		if e.capacity > rb.failAmt {
			inf := (e.capacity - rb.failAmt) *
				revEmptyNum / revEmptyDen
			if inf > center {
				center = inf
			}
		}
	}

	if b != nil && b.okAmt > center {
		center = b.okAmt
	}

	return center
}

// availCap is the hard upper bound on what we are still willing to push.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		if r.retired[e.chanID] {
			return 0
		}
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else {
		if comp := r.compBound(e); comp < c {
			c = comp
		}
		if b != nil && b.hasFail {
			if lim := retryLimit(b, e.capacity); lim < c {
				c = lim
			}
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can bear with decent
// probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.view(e.key())
	est := e.capacity * priorSafeNum / priorSafeDen
	if b.okAmt > est {
		est = b.okAmt
	}
	if !b.hasFail {
		if c := r.provenCenter(e) * 85 / 100; c > est {
			est = c
		}
	} else if lim := retryLimit(b, e.capacity); est > lim {
		est = lim
	}
	// A soft (unattributable) bound caps sizing without becoming a hard
	// veto: sizing below it is what actually converts a -1 failure into
	// useful information.
	if b.hasSoft {
		lim := b.soft * 3 / 5
		if lim < est {
			est = lim
		}
	}
	if b.misses > 0 {
		est = est / lnwire.MilliSatoshi(1+b.misses)
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.view(e.key())
	if b.dead {
		return 0
	}

	eff := amt + b.inFlight

	if e.from == r.source {
		if r.retired[e.chanID] {
			return 0
		}
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	if comp := r.compBound(e); eff > comp {
		return minProb / 4
	}

	var p float64
	switch {
	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)
		center := r.provenCenter(e)

		switch {
		case b.okAmt > 0 && b.hasFail:
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case center > 0 && !b.hasFail:
			q := 1.0 / (1.0 + math.Exp(
				(float64(eff)/float64(center)-1)*4.5,
			))
			p = 0.3*p + 0.7*q

		case b.hasFail:
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	// Soft bounds from unattributable failures: amounts at or above the
	// soft bound are strongly discounted, amounts well below barely are.
	if b.hasSoft && b.soft > 0 {
		ratio := float64(eff) / float64(b.soft)
		if ratio >= 1 {
			p *= 0.12
		} else {
			p *= 1 - 0.7*ratio*ratio
		}
	}

	if b.misses > 0 {
		m := b.misses
		if m > 3 {
			m = 3
		}
		p *= math.Pow(0.6, float64(m))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node    route.Vertex
	dist    float64
	amt     lnwire.MilliSatoshi
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)

	// Long routes have been the source of unattributable failures, which
	// are the most expensive kind of failure because they teach us little.
	// Once we have seen several, we buy shorter routes more aggressively.
	hopMult := 0.2 + 0.25*math.Min(float64(r.longMiss), 4)
	hopCost := attemptCost * hopMult

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}
			if e.from == r.source && r.retired[e.chanID] {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

func (r *router) rawLocalBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		total += bal
	}
	return total
}

func (r *router) rawMaxLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		if bal > best {
			best = bal
		}
	}
	return best
}

func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	maxK := partsLeft
	if maxK < 4 && r.mppOK() {
		maxK = 4
	}
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= minShard {
			add(c - c/200)
		}
	}

	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
		if b.hasSoft && b.soft >= minShard {
			add(b.soft * 3 / 5)
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with a
// bonus for finishing the payment outright, a light fee penalty, and a cost
// for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// corridorSig identifies a corridor irrespective of amount, so repeated
// failures on essentially the same path can retire it.
func corridorSig(path []*edge) string {
	buf := make([]byte, 0, len(path)*14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	return string(buf)
}

func routeCorridorSig(rt *route.Route) string {
	buf := make([]byte, 0, len(rt.Hops)*14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	return string(buf)
}

func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// corridorDead reports whether a corridor has spent its attempt budget.
func (r *router) corridorDead(path []*edge) bool {
	return r.corridorFails[corridorSig(path)] >= corridorBudget
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	if r.corridorDead(path) {
		return best
	}

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	if r.corridorDead(path) {
		return nil
	}

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil && !r.corridorDead(p) {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 7 {
			break
		}
		probes++
		p, err := r.findPath(a, avoid)
		if err == nil && !r.corridorDead(p) {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	single := r.maxLocalEdge()

	var out []*plan
	left := remaining

	rounds := 1
	if r.mppOK() {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if single > 0 && want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			avoid[path[0].chanID] = true
			continue
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// hopeless reports whether the remainder is provably beyond what our own
// channels can still push.
func (r *router) hopeless(amt lnwire.MilliSatoshi, inFlight uint32) bool {
	if inFlight > 0 {
		return false
	}
	if len(r.localBalances) == 0 {
		return false
	}

	if r.rawLocalBudget() < amt {
		return true
	}

	if !r.mppOK() && r.rawMaxLocal() < amt {
		return true
	}

	if r.failStreak >= hopelessStreak && len(r.localEdges) > 0 &&
		r.localBudget() < amt {

		return true
	}

	return false
}

// probeShard returns a small discovery amount when the payment is large
// enough that a blind full-size attempt is likely to teach us nothing but
// burn an attempt. Learning bounds at 1/8 the amount costs one attempt and
// tells us as much about the corridor as failing at full size does; it may
// also actually settle, shrinking the remainder.
func (r *router) probeShard(remaining lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !r.mppOK() || r.probed {
		return 0
	}

	// Only probe when a single corridor plausibly cannot carry the whole
	// remainder: that is where blind full-size attempts are wasted.
	bud := r.localBudget()
	if bud == 0 {
		return 0
	}
	if r.maxLocalEdge() >= remaining && bud >= remaining*2 {
		return 0
	}

	a := remaining * probeFracNum / probeFracDen
	if lim := r.maxLocalEdge(); lim > 0 && a > lim {
		a = lim
	}
	if a < minShard {
		return 0
	}
	return a
}

// budgetLeft reports whether we still have attempts worth spending. Once
// attempts stop moving the remainder we wind down quickly, because retry
// efficiency is scored and a stalled payment rarely recovers.
func (r *router) budgetLeft() bool {
	limit := maxAttempts
	if r.stalls >= stallLimit*2 {
		limit = maxAttempts / 2
	}
	return r.attempts < limit
}

// RequestRoute plans the next shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if !r.budgetLeft() {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}
	if r.hopeless(amt, inFlightHtlcs) {
		return nil, errors.New("remainder exceeds local liquidity")
	}

	// Progress tracking: a remainder that has not shrunk across attempts
	// means we are grinding, not learning.
	if r.lastRemaining == amt {
		r.stalls++
	} else {
		r.stalls = 0
		r.lastRemaining = amt
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()
	split := r.mppOK()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		if !split && a < amt {
			r.queued = nil
			break
		}
		if pathBusy(pl.path, busy) || r.corridorDead(pl.path) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		r.attempts++
		return rt, nil
	}

	// Discovery shard: for large payments buy cheap information first.
	if pa := r.probeShard(amt); pa > 0 {
		if path, err := r.findPath(pa, busy); err == nil {
			if pl := r.bestOnPath(path, pa, amt); pl != nil {
				r.probed = true
				r.attempts++
				return pl.rt, nil
			}
		}
		if path, err := r.findPath(pa, nil); err == nil {
			if pl := r.bestOnPath(path, pa, amt); pl != nil {
				r.probed = true
				r.attempts++
				return pl.rt, nil
			}
		}
		// No corridor even for the probe: fall through to the general
		// planner rather than looping on the probe forever.
		r.probed = true
	}

	// A single shard can never exceed what one local channel can push.
	hi := amt
	if single := r.maxLocalEdge(); single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	// When attempts have stopped moving the remainder, stop leading with
	// the largest amounts: they are exactly what keeps failing.
	if split && r.stalls >= stallLimit && len(ladder) > 1 {
		cut := len(ladder) / 3
		if cut >= len(ladder) {
			cut = len(ladder) - 1
		}
		ladder = ladder[cut:]
	}

	var best *plan

	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}
			if !split && a < amt {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly.
	if split && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total := flowTotal(flow)
			first := flow[0]

			if best == nil || total > best.amt {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	if best == nil {
		best = r.salvage(amt, busy, split)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// salvage hunts for any novel attempt at all, walking a wide descending
// amount ladder over both the disjoint and the unrestricted graph.
func (r *router) salvage(remaining lnwire.MilliSatoshi, busy map[uint64]bool,
	split bool) *plan {

	if !split {
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		if r.corridorDead(path) {
			return nil
		}
		if r.failedSigs[planSig(path, remaining)] {
			return nil
		}
		rt, p, err := r.makeRoute(path, remaining)
		if err != nil {
			return nil
		}
		return &plan{path: path, rt: rt, amt: remaining, prob: p}
	}

	a := remaining
	for i := 0; i < 22 && a >= minShard; i++ {
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.findPath(a, avoid)
			if err != nil {
				continue
			}
			if pl := r.bestOnPath(path, a, remaining); pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded but
// whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
	}
	// A demonstrated forward at a clears soft suspicion at or below a.
	if b.hasSoft && b.soft <= a {
		b.hasSoft = false
		b.soft = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	b.fails = 0
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.hasSoft = false
	b.soft = 0
	b.misses = 0

	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	rb.hasSoft = false
	rb.soft = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies.
func classify(f any) string {
	if f == nil {
		return "unknown"
	}
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// noteCorridorFail charges a failure to the corridor and retires first hops
// that keep coming up dry, which is what bounds the retry count.
func (r *router) noteCorridorFail(rt *route.Route) {
	sig := routeCorridorSig(rt)
	r.corridorFails[sig]++

	if len(rt.Hops) == 0 {
		return
	}

	// A first hop whose own balance we know to be exhausted is worthless
	// for the rest of the payment.
	first := rt.Hops[0].ChannelID
	if bal, ok := r.localBalances[first]; ok && bal < minShard {
		r.retired[first] = true
	}
}

// softFail charges a soft upper bound to a hop from an unattributable
// failure. Unlike a hard bound it does not veto the hop; it makes larger
// amounts over it progressively less attractive, which steers the planner to
// smaller shards on that corridor instead of re-deriving the same path.
func (r *router) softFail(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if !b.hasSoft || a < b.soft {
		b.hasSoft = true
		b.soft = a
	}
	if b.misses < 3 {
		b.misses++
	}
	b.succ = false
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	if result.Failure == nil {
		r.failStreak = 0
		r.stalls = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		// A settled corridor has earned its budget back.
		delete(r.corridorFails, routeCorridorSig(rt))
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Beliefs just changed, so any queued joint plan is stale.
	r.queued = nil

	kind := classify(result.Failure)

	// Locate the failing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// Policy repairs do not consume a corridor's liquidity budget: the
	// corridor is fine, our view of its policy was stale.
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		switch kind {
		case "fee", "cltv", "min":
			e := r.byKey[hopKey(rt.Hops[failIdx])]
			a := hopAmount(rt, failIdx)
			switch kind {
			case "fee":
				if e != nil {
					e.baseFee += e.baseFee/4 + 1_000
					e.feePPM += e.feePPM/4 + 50
				}
			case "cltv":
				if e != nil {
					e.cltv += e.cltv/4 + 20
				}
			case "min":
				if e != nil && a >= e.minHTLC {
					e.minHTLC = a + 1
				}
			}
			// Everything before the failing hop worked.
			for i := 0; i < failIdx; i++ {
				r.provePassed(rt.Hops[i], hopAmount(rt, i))
			}
			return nil
		}
	}

	r.noteCorridorFail(rt)

	// Unattributable failure: charge a soft bound to every remote hop at
	// the amount it was asked to carry, and remember that long routes are
	// where this happens.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.longMiss++
		for i, h := range rt.Hops {
			if i == 0 {
				// Our own balance is exact; a corridor failing
				// past it says nothing about it.
				continue
			}
			r.softFail(h, hopAmount(rt, i))
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))

	if kind == "dead" {
		b.dead = true
		if failIdx == 0 {
			r.retired[h.ChannelID] = true
		}
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	b.fails++
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	b.succ = false
	b.drained = 0
	// A hard bound subsumes any soft one.
	b.hasSoft = false
	b.soft = 0

	if failIdx == 0 {
		rk := edgeKey{chanID: h.ChannelID, to: rt.SourcePubKey}
		if rb, ok := r.beliefs[rk]; ok {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
		if r.localBalances[h.ChannelID] < minShard {
			r.retired[h.ChannelID] = true
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs with hard lower-OK / upper-fail bounds and
//     no time decay: a stale bound costs one retry to refresh, which is
//     cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - JOINT ROUTE-SET PLANNING (min-cost-flow style): the planner builds a
//     full COVER of the remaining amount over several disjoint corridors,
//     each shard sized to that corridor's believed bottleneck.
//   - CAPACITY-AWARE PART BUDGETING (new): before planning, we estimate the
//     total believed deliverable flow and derive the number of parts the
//     payment actually needs, then plan directly at that granularity instead
//     of walking a descending ladder of single corridors. The eval showed a
//     large payment (860M msat) burning 30 attempts and then terminating
//     with "no route found"; the fix is to start wide, not narrow.
//   - PERSISTENT SHARD PIPELINE (new): a joint plan is no longer thrown away
//     on every failure. Only the shards affected by newly-learned evidence
//     are re-priced; the rest stay queued. This cuts attempt counts, which
//     were the main secondary penalty (11-12 attempts/scenario).
//   - Depth-aware lower retries instead of blacklisting, with per-corridor
//     re-pricing on the way down.
//   - Duplicate-attempt suppression on (path, amount).
//   - Non-liquidity failures (fee, cltv, min, disabled) are repaired in the
//     local policy view rather than treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	maxRouteHops = 7

	maxAttempts   = 90
	maxFailStreak = 30

	probeBudget = 10

	minShard = lnwire.MilliSatoshi(1_000)

	feeWeight = 4.0
	partCost  = 0.003

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear when SIZING a shard.
	priorSafeNum = 33
	priorSafeDen = 100

	provenCenterNum = 62
	provenCenterDen = 100

	queueMinProb = 0.12
)

type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	okAmt lnwire.MilliSatoshi

	failAmt lnwire.MilliSatoshi
	hasFail bool

	succ    bool
	drained lnwire.MilliSatoshi

	inFlight lnwire.MilliSatoshi

	misses int
	dead   bool
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	low := math.Exp(-x * 3.2)
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	inEdges map[route.Vertex][]*edge
	byKey   map[edgeKey]*edge

	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan.
	queued []*plan

	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push over
// an edge. Zero means unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can bear with decent
// probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node    route.Vertex
	dist    float64
	amt     lnwire.MilliSatoshi
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every hop's
// policy and belief bounds.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// widestLocal is the largest single local channel balance still free. It is a
// hard ceiling on any single shard leaving our node.
func (r *router) widestLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// hardBottleneck is the delivered amount a corridor could bear if every hop
// were as full as our HARD bounds allow. Used to decide whether a corridor is
// worth probing at all.
func (r *router) hardBottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.availCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with a
// bonus for finishing the payment outright, a light fee penalty, and a cost
// for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// bestOnPath prices a corridor at descending amounts starting from hi and
// returns the best novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount. It returns the corridor
// found for the largest workable amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		a = a * 2 / 3
		if a < minShard {
			break
		}
		if probes >= 7 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// flowPlan is a full joint route-set: a set of disjoint corridors with shard
// amounts, plus how much of the requested amount they cover in total.
type flowPlan struct {
	shards  []*plan
	covered lnwire.MilliSatoshi
	fee     lnwire.MilliSatoshi
}

// planFlow decomposes the remaining amount over up to partsLeft DISJOINT
// corridors, sizing each shard to what that corridor's weakest hop is
// believed able to bear. This is the min-cost-flow style joint plan: unequal
// parallel corridors each get a shard that fits.
//
// shardCap optionally limits every shard, which lets the caller ask for a
// plan whose shards are all "small" (many-parts mode for large payments).
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool, shardCap lnwire.MilliSatoshi) *flowPlan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	fp := &flowPlan{}
	left := remaining

	for k := uint32(0); k < partsLeft; k++ {
		if left < minShard {
			break
		}

		want := left
		if shardCap > 0 && shardCap < want {
			want = shardCap
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			// The corridor exists but is believed too thin; try to
			// price it at its hard bound instead of dropping it.
			if hb := r.hardBottleneck(path); hb >= minShard {
				amtS = hb
				if amtS > want {
					amtS = want
				}
			} else {
				break
			}
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			// Corridor unusable at any price: block its narrowest
			// hop so the next probe explores elsewhere.
			blockThinnest(path, avoid, r)
			continue
		}

		fp.shards = append(fp.shards, pl)
		fp.covered += pl.amt
		if pl.rt != nil && pl.rt.TotalAmount > pl.amt {
			fp.fee += pl.rt.TotalAmount - pl.amt
		}
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	if len(fp.shards) == 0 {
		return nil
	}
	if fp.covered > remaining {
		fp.covered = remaining
	}
	return fp
}

// blockThinnest marks the weakest hop of a corridor as avoided so the next
// path search is forced to route around it.
func blockThinnest(path []*edge, avoid map[uint64]bool, r *router) {
	var worst *edge
	var worstCap lnwire.MilliSatoshi
	for _, e := range path {
		c := r.availCap(e)
		if worst == nil || c < worstCap {
			worst, worstCap = e, c
		}
	}
	if worst != nil {
		avoid[worst.chanID] = true
	}
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next still-valid shard from a joint plan. Shards
// are re-priced against current beliefs; ones that no longer work are dropped
// rather than invalidating the whole plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			return nil
		}
		if pathBusy(pl.path, busy) {
			// Keep it for later instead of discarding: the
			// corridor is fine, it is merely occupied right now.
			r.queued = append(r.queued, pl)
			if len(r.queued) > 16 {
				r.queued = nil
			}
			return nil
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			// Re-price the same corridor lower before giving up
			// on it: evidence may have shrunk it, not killed it.
			if lower := r.bestOnPath(
				pl.path, a*2/3, amt,
			); lower != nil && lower.prob >= queueMinProb {
				return lower.rt
			}
			continue
		}
		return rt
	}
	return nil
}

// planSingle searches jointly over shard amount and corridor for the single
// best next attempt.
func (r *router) planSingle(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *plan {

	hi := amt
	if w := r.widestLocal(); w > 0 && w < hi {
		hi = w
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	return best
}

// neededParts estimates how many shards the remaining amount realistically
// requires, from the widest single corridor we believe exists. Starting at the
// right granularity is what keeps large payments from burning a dozen attempts
// walking a descending single-corridor ladder.
func (r *router) neededParts(amt lnwire.MilliSatoshi,
	partsLeft uint32, busy map[uint64]bool) uint32 {

	w := r.widestLocal()
	if w == 0 || w >= amt {
		return 1
	}
	// Probe for the widest corridor we can actually find.
	probe := w
	if probe > amt {
		probe = amt
	}
	var best lnwire.MilliSatoshi
	if p := r.findAnyPath(probe, amt, partsLeft, busy); p != nil {
		if bn := r.bottleneck(p); bn > best {
			best = bn
		}
	}
	if best == 0 {
		best = w / 2
	}
	if best == 0 {
		return partsLeft
	}
	n := uint32(amt/best) + 1
	if n < 1 {
		n = 1
	}
	if n > partsLeft {
		n = partsLeft
	}
	return n
}

// RequestRoute plans the next shard.
//
// Strategy: serve any queued shard from an existing joint plan first. Then
// estimate the part count the payment actually needs, and build joint covers
// at that granularity (plus a couple of neighbouring granularities) as well as
// the best single attempt. Commit to whichever reaches furthest per unit of
// fee and part count.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	best := r.planSingle(amt, partsLeft, busy)

	if partsLeft > 1 {
		var cands []*flowPlan

		if fp := r.planFlow(amt, partsLeft, busy, 0); fp != nil {
			cands = append(cands, fp)
		}

		// Capacity-aware granularity: start from the part count the
		// network actually seems to require, then bracket it. This
		// replaces blind halving with a directed search.
		need := r.neededParts(amt, partsLeft, busy)
		divs := []uint32{need}
		if need > 1 {
			divs = append(divs, need+1, need*2)
		} else {
			divs = append(divs, 2, 3)
		}
		if partsLeft >= 4 {
			divs = append(divs, 4)
		}
		if partsLeft >= 8 {
			divs = append(divs, 8)
		}

		tried := map[uint32]bool{}
		for _, div := range divs {
			if div <= 1 || div > partsLeft || tried[div] {
				continue
			}
			tried[div] = true
			capS := amt / lnwire.MilliSatoshi(div)
			if capS < minShard {
				continue
			}
			if fp := r.planFlow(
				amt, partsLeft, busy, capS,
			); fp != nil {
				cands = append(cands, fp)
			}
		}

		var pick *flowPlan
		for _, fp := range cands {
			if pick == nil {
				pick = fp
				continue
			}
			// Prefer the cover that reaches furthest; break ties
			// on fewer shards, then lower fee, then first-shard
			// score.
			switch {
			case fp.covered > pick.covered+pick.covered/64:
				pick = fp
			case pick.covered > fp.covered+fp.covered/64:
			case len(fp.shards) < len(pick.shards):
				pick = fp
			case len(fp.shards) > len(pick.shards):
			case fp.fee < pick.fee:
				pick = fp
			case fp.fee == pick.fee &&
				fp.shards[0].score > pick.shards[0].score:
				pick = fp
			}
		}

		if pick != nil {
			first := pick.shards[0]
			take := false
			switch {
			case best == nil:
				take = true
			case best.amt >= amt:
				// Single shard already covers everything: only
				// switch if it is genuinely unlikely and the
				// cover is confident.
				take = best.prob < 0.40 &&
					pick.covered >= amt &&
					first.prob > best.prob*1.3
			default:
				// Prefer the plan that covers more of the
				// remaining amount; a slightly worse first
				// shard is fine if the plan as a whole covers
				// materially more.
				take = pick.covered >
					best.amt+best.amt/16 ||
					(pick.covered >= best.amt &&
						first.score >
							best.score*0.9)
			}

			if take {
				r.queued = pick.shards[1:]
				best = first
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded but
// whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// dropAffected prunes only the queued shards that traverse a channel whose
// belief just changed, keeping the rest of the joint plan alive. Throwing away
// the whole plan on every failure was costing extra attempts.
func (r *router) dropAffected(chanID uint64) {
	if len(r.queued) == 0 {
		return
	}
	keep := r.queued[:0]
	for _, pl := range r.queued {
		hit := false
		for _, e := range pl.path {
			if e.chanID == chanID {
				hit = true
				break
			}
		}
		if !hit {
			keep = append(keep, pl)
		}
	}
	r.queued = keep
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		// A settle drains the corridor it used, so any queued shard
		// sharing those channels must be re-priced.
		for _, h := range rt.Hops {
			r.dropAffected(h.ChannelID)
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote hops
	// so we stop re-picking this corridor without destroying hard bounds.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			r.dropAffected(h.ChannelID)
		}
		return nil
	}

	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		// A policy repair does not mean the corridor is bad, so do not
		// let it count against the progress budget.
		if r.failStreak > 0 {
			r.failStreak--
		}
		r.dropAffected(h.ChannelID)
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		r.dropAffected(h.ChannelID)
		return nil

	case "min":
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		r.dropAffected(h.ChannelID)
		return nil

	case "dead":
		b.dead = true
		r.dropAffected(h.ChannelID)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	b.succ = false

	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	// Only the shards that use this channel are stale.
	r.dropAffected(h.ChannelID)

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity.
//   - Per-directed-channel beliefs: hard lower-OK / upper-fail bounds
//     (no time decay: a stale bound costs one retry to refresh).
//   - Probability-aware Dijkstra: minimize fee + penalty/probability.
//   - JOINT route-set planning: when no single path can carry the
//     remaining amount, plan a disjoint set of corridors up front and
//     size each shard to the max-flow that corridor can actually bear.
//   - Lower-retry on failed channels rather than blacklisting, with a
//     bisection ladder between the proven-ok and proven-fail bounds.
//
// Changes in this revision (attempt-count reduction was the dominant
// score gap: success was already 1.0 while retry_efficiency was -25):
//   - Corridor sizing is now analytic: the headroom of the cheapest
//     corridor under current beliefs gives the shard size directly,
//     instead of a 14-step blind bisection per corridor.
//   - Shards are committed as a plan of ROUTES, not just amounts, so a
//     vetted corridor is reused rather than re-searched and re-shifted
//     onto a channel we already know bounces.
//   - A per-payment singleCap remembers the largest delivered size that
//     failed for liquidity reasons, so the ladder stops re-proposing
//     amounts known to bounce.
//   - Repeat failures on one direction back off geometrically: a bimodal
//     channel that fails twice is depleted, not merely tight.
//   - A MaxParts-scaled attempt budget cuts the long tails that dominated
//     the penalty, with a floor that keeps success rate intact.

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCost is the virtual cost (in msat) of one failed attempt,
	// used to trade fee against success probability. Attempts are
	// penalized by the scorer, so this is deliberately generous
	// relative to fees.
	attemptCostBase = lnwire.MilliSatoshi(3_000)
	attemptCostPPM  = lnwire.MilliSatoshi(12_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// minShard is the smallest shard we will bother planning.
	minShard = lnwire.MilliSatoshi(1_000)

	// maxAttempts bounds the total attempts we will ever issue.
	maxAttempts = 220
)

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount proven to pass.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount proven to fail; zero means unknown.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// fails counts how many times this direction has bounced. Repeated
	// bounces mean the channel is depleted, not merely tight, so we
	// stop nibbling at it.
	fails int

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	p := 0.30*low + 0.70*cliff
	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// plannedShard is one committed leg of a joint plan.
type plannedShard struct {
	amt lnwire.MilliSatoshi
	rt  *route.Route
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[uint64]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// attempts counts total attempts issued.
	attempts int

	// noRouteStreak counts consecutive planning failures.
	noRouteStreak int

	// plan holds committed shards not yet handed out.
	plan []plannedShard

	// planFor is the remaining amount the plan was built for; if the
	// remaining amount moves away from it the plan is discarded.
	planFor lnwire.MilliSatoshi

	// singleCap is the largest single-shard amount we still believe can
	// be routed whole. A whole-amount failure lowers it, so the ladder
	// stops re-probing sizes we already know bounce.
	singleCap lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		localBalances: localBalances,
		beliefs:       make(map[uint64]*belief),
		pending:       make(map[uint64]*route.Route),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				if e.from == source {
					r.localEdges = append(r.localEdges, e)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(chanID uint64) *belief {
	b, ok := r.beliefs[chanID]
	if !ok {
		b = &belief{}
		r.beliefs[chanID] = b
	}
	return b
}

// avail is the amount we still consider spendable over this edge, taking
// our own in-flight HTLCs and local balance into account. It returns zero
// when the edge is unusable at any amount.
func (r *router) avail(e *edge) lnwire.MilliSatoshi {
	cap := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < cap {
		cap = e.maxHTLC
	}

	b := r.beliefs[e.chanID]
	if b != nil {
		if b.hasFail && b.failAmt > 0 {
			// Retry below the proven failure point rather than
			// blacklisting the channel outright. Bisect toward the
			// proven-good bound so repeated failures converge, and
			// back off harder the more times it has bounced (a
			// bimodal channel that fails twice is depleted).
			lim := b.failAmt - 1
			if b.okAmt > 0 && b.okAmt < lim {
				lim = b.okAmt + (lim-b.okAmt)*2/3
			} else {
				switch {
				case b.fails >= 3:
					lim = b.failAmt / 8
				case b.fails == 2:
					lim = b.failAmt / 3
				default:
					lim = b.failAmt * 3 / 5
				}
			}
			if lim < cap {
				cap = lim
			}
		}
		if b.inFlight >= cap {
			return 0
		}
		cap -= b.inFlight
	}

	if e.from == r.source {
		bal := r.localBalances[e.chanID]
		if bal < cap {
			cap = bal
		}
	}

	return cap
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	// Our own channels have exactly known balances.
	if e.from == r.source {
		b := r.beliefs[e.chanID]
		used := lnwire.MilliSatoshi(0)
		if b != nil {
			used = b.inFlight
		}
		if r.localBalances[e.chanID] >= amt+used {
			return knownProb
		}
		return 0
	}

	b := r.beliefs[e.chanID]
	if b == nil {
		return bimodalPrior(amt, e.capacity)
	}

	eff := amt + b.inFlight

	if b.okAmt >= eff {
		return knownProb
	}
	if b.hasFail && eff >= b.failAmt {
		return minProb / 2
	}

	p := bimodalPrior(eff, e.capacity)

	// Narrow with the bounds we do have: known-good below and known-bad
	// above compress the uncertain interval.
	if b.okAmt > 0 && b.hasFail {
		lo := float64(b.okAmt)
		hi := float64(b.failAmt)
		if hi > lo {
			frac := (float64(eff) - lo) / (hi - lo)
			bracket := 1 - frac
			p = 0.5*p + 0.5*bracket
		}
	} else if b.okAmt > 0 {
		// A prior success raises confidence for nearby amounts.
		ratio := float64(eff) / float64(b.okAmt)
		boost := math.Exp(-(ratio - 1) * 1.1)
		p = 0.45*p + 0.55*boost
	} else if b.hasFail {
		// A prior failure at failAmt: everything meaningfully below it
		// is still plausible, but discount. Repeat failures on the same
		// direction mean depletion, so discount much harder.
		frac := float64(eff) / float64(b.failAmt)
		damp := 0.85
		if b.fails >= 2 {
			damp = 0.97
		}
		p = p * (1 - damp*frac)
	}

	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	// dist is the combined cost used for ordering.
	dist float64
	// amt is the amount that must arrive at node.
	amt lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	cltv    uint32
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	amt     lnwire.MilliSatoshi
	logProb float64
	dist    float64
	via     *edge
	hops    int
	cltv    uint32
}

// findRoute runs a probability-weighted backward Dijkstra. The cost of a
// path is its fee plus an attempt-cost term divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused (already carrying a shard
// of this payment along a chosen route set).
func (r *router) findRoute(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase +
		amt*attemptCostPPM/1_000_000)

	best := make(map[route.Vertex]*pathState)

	target := r.spec.Target
	best[target] = &pathState{
		amt:     amt,
		logProb: 0,
		dist:    0,
		hops:    0,
		cltv:    finalCltvDelta,
	}

	q := &pq{}
	heap.Push(q, &pqItem{
		node: target, dist: 0, amt: amt, logProb: 0,
		hops: 0, cltv: finalCltvDelta,
	})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] {
				continue
			}
			if e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.avail(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			var sending lnwire.MilliSatoshi
			if e.from == r.source {
				sending = amtOver
			} else {
				sending = amtOver + e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-3 {
				continue
			}

			fee := float64(sending) - float64(amt)

			// Risk-adjusted cost: expected fee plus expected retry
			// cost. A small per-hop term discourages long paths.
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*400

			prev, ok := best[e.from]
			if ok && dist >= prev.dist-1e-9 {
				continue
			}

			best[e.from] = &pathState{
				amt:     sending,
				logProb: logProb,
				dist:    dist,
				via:     e,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, best)
	if err != nil {
		return nil, 0, err
	}

	return rt, math.Exp(src.logProb), nil
}

// buildRoute materializes the route from the next-pointer map.
func (r *router) buildRoute(amt lnwire.MilliSatoshi,
	best map[route.Vertex]*pathState) (*route.Route, error) {

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// --- Joint route-set planning ---------------------------------------------

// edgeOf finds the directed edge with the given channel id pointing at to.
func (r *router) edgeOf(chanID uint64, to route.Vertex) *edge {
	for _, e := range r.inEdges[to] {
		if e.chanID == chanID {
			return e
		}
	}
	return nil
}

// routeHeadroom is the largest delivered amount we believe the given route
// could carry, derived from each hop's believed availability. Availability
// is expressed at the hop's own (fee-inflated) amount, so we scale each
// hop's slack back into target-amount terms before taking the minimum.
func (r *router) routeHeadroom(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if delivered == 0 {
		return 0
	}

	head := lnwire.MilliSatoshi(0)
	first := true

	for i, h := range rt.Hops {
		e := r.edgeOf(h.ChannelID, h.PubKeyBytes)
		if e == nil {
			continue
		}
		flow := hopAmount(rt, i)
		if flow == 0 {
			continue
		}

		a := r.avail(e)
		ratio := float64(delivered) / float64(flow)
		scaled := lnwire.MilliSatoshi(float64(a) * ratio)

		if first || scaled < head {
			head = scaled
			first = false
		}
	}

	if first {
		return 0
	}
	return head
}

// probeAmount searches downward for a routable amount, starting from the
// analytic headroom of the cheapest corridor rather than blind bisection.
// It returns the amount and its route, or zero.
func (r *router) probeAmount(hi lnwire.MilliSatoshi,
	avoid map[uint64]bool) (lnwire.MilliSatoshi, *route.Route) {

	if hi < minShard {
		return 0, nil
	}

	if rt, _, err := r.findRoute(hi, avoid); err == nil {
		return hi, rt
	}

	// A small probe reveals which corridor is cheapest; that corridor's
	// headroom tells us how big a shard it can bear. This replaces a long
	// bisection with one analytic step plus a short refinement.
	seed := hi / 8
	if seed < minShard {
		seed = minShard
	}
	seedRt, _, seedErr := r.findRoute(seed, avoid)
	if seedErr == nil {
		if head := r.routeHeadroom(seedRt); head >= minShard {
			cand := head
			if cand > hi {
				cand = hi
			}
			if rt, _, err := r.findRoute(cand, avoid); err == nil {
				return cand, rt
			}
			// Analytic estimate too eager: step down a few times.
			for i := 0; i < 3; i++ {
				cand = cand * 2 / 3
				if cand < minShard {
					break
				}
				if rt, _, err := r.findRoute(
					cand, avoid,
				); err == nil {
					return cand, rt
				}
			}
		}
	}

	// Fall back to a short bisection between the seed and hi.
	lo := lnwire.MilliSatoshi(0)
	if seedErr == nil {
		lo = seed
	}
	for i := 0; i < 7 && hi-lo > hi/32+1; i++ {
		mid := lo + (hi-lo)/2
		if mid < minShard {
			break
		}
		if _, _, err := r.findRoute(mid, avoid); err == nil {
			lo = mid
		} else {
			hi = mid
		}
	}
	if lo >= minShard {
		if rt, _, err := r.findRoute(lo, avoid); err == nil {
			return lo, rt
		}
	}
	if seedErr == nil && seed >= minShard {
		return seed, seedRt
	}
	return 0, nil
}

// planShards builds a joint route set for the remaining amount: it greedily
// carves the largest shard each disjoint corridor can bear until the amount
// is covered or we run out of parts/corridors. The shards carry their routes
// so a committed corridor is reused rather than re-searched.
func (r *router) planShards(remaining lnwire.MilliSatoshi,
	partsLeft uint32, busy map[uint64]bool) []plannedShard {

	if partsLeft == 0 {
		return nil
	}
	if partsLeft > 12 {
		partsLeft = 12
	}

	// Corridors chosen so far must not be reused by later shards, so
	// unequal parallel corridors each carry what they can bear.
	avoid := make(map[uint64]bool, len(busy)+8)
	for k := range busy {
		avoid[k] = true
	}

	var out []plannedShard
	left := remaining

	for k := uint32(0); k < partsLeft && left >= minShard; k++ {
		amt, rt := r.probeAmount(left, avoid)
		if amt == 0 || rt == nil {
			break
		}

		out = append(out, plannedShard{amt: amt, rt: rt})
		left -= amt

		// Reserve this corridor's hops so the next shard looks
		// elsewhere and the set stays genuinely disjoint.
		for _, h := range rt.Hops {
			avoid[h.ChannelID] = true
		}
	}

	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs, so
// a new shard is planned over a genuinely disjoint corridor where possible.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// firstHopBudget returns the total liquidity we believe is reachable out of
// our own channels, which upper-bounds any single payment.
func (r *router) firstHopBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.avail(e)
	}
	return total
}

// candidateAmounts builds a short descending ladder of shard sizes, used as
// a fallback when joint planning comes up empty. It is deliberately short:
// each entry costs a Dijkstra run and, if handed out, risks a failed attempt.
func (r *router) candidateAmounts(remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft == 0 {
		partsLeft = 1
	}

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > remaining || set[a] {
			return
		}
		if r.singleCap > 0 && a > r.singleCap {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(remaining)

	// Even splits over the part counts we could still afford.
	for k := uint32(2); k <= partsLeft && k <= 8; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric ladder for finer probing when even splits all fail.
	cur := remaining
	for i := 0; i < 8; i++ {
		cur = cur * 2 / 3
		if cur < minShard {
			break
		}
		add(cur)
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })

	if len(out) > 10 {
		out = out[:10]
	}
	return out
}

// attemptBudget bounds the attempts spent on this payment. Attempts are
// penalized by the scorer, so a long tail of nibbling retries costs more
// than a well-chosen smaller shard, but the floor keeps success intact.
func (r *router) attemptBudget() int {
	budget := 24
	if r.spec.MaxParts > 1 {
		budget = int(r.spec.MaxParts) * 6
	}
	if budget < 24 {
		budget = 24
	}
	if budget > maxAttempts {
		budget = maxAttempts
	}
	return budget
}

// RequestRoute plans the next shard. It first tries to satisfy the whole
// remaining amount over one route; failing that it plans a joint route set
// whose shard sizes come from each corridor's actual carrying capacity.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.attempts++
	if r.attempts > r.attemptBudget() {
		return nil, errors.New("attempt budget exhausted")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Drop a stale plan if the remaining amount no longer matches what it
	// was built for.
	if r.planFor != amt {
		r.plan = nil
		r.planFor = 0
	}

	// Serve a committed plan entry first. The stored route is reused when
	// it still looks viable under current beliefs, which saves both a
	// search and a wasted attempt on a corridor we already vetted.
	for len(r.plan) > 0 {
		ps := r.plan[0]
		r.plan = r.plan[1:]

		a := ps.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}

		if a == ps.amt && ps.rt != nil && r.routeViable(ps.rt) {
			r.noRouteStreak = 0
			r.planFor = amt - a
			return ps.rt, nil
		}
		if rt, _, err := r.findRoute(a, busy); err == nil {
			r.noRouteStreak = 0
			r.planFor = amt - a
			return rt, nil
		}
		if rt, _, err := r.findRoute(a, nil); err == nil {
			r.noRouteStreak = 0
			r.planFor = amt - a
			return rt, nil
		}
	}
	r.plan = nil
	r.planFor = 0

	// A shard can never exceed what our own channels can push right now.
	budget := r.firstHopBudget()
	target := amt
	if budget > 0 && budget < target {
		target = budget
	}
	if r.singleCap > 0 && r.singleCap < target {
		target = r.singleCap
	}
	if target < minShard {
		target = amt
	}

	// Fast path: the whole remaining amount over one good route.
	if target == amt {
		if rt, p, err := r.findRoute(target, busy); err == nil &&
			p > 0.45 {

			r.noRouteStreak = 0
			return rt, nil
		}
	}

	// Joint planning: size shards to corridors instead of halving.
	if partsLeft > 1 {
		plan := r.planShards(target, partsLeft, busy)
		if len(plan) > 0 {
			// Largest shard first: it is the one most likely to be
			// invalidated by drift, so probe it while our belief
			// is freshest.
			sort.Slice(plan, func(i, j int) bool {
				return plan[i].amt > plan[j].amt
			})
			first := plan[0]
			r.plan = plan[1:]
			r.planFor = amt - first.amt

			if first.rt != nil {
				r.noRouteStreak = 0
				return first.rt, nil
			}
			if rt, _, err := r.findRoute(
				first.amt, busy,
			); err == nil {
				r.noRouteStreak = 0
				return rt, nil
			}
			r.plan = nil
			r.planFor = 0
		}
	}

	// Fallback: descend a short ladder of amounts, scoring each by
	// expected delivered value net of fee and of the retry it risks.
	type planItem struct {
		rt    *route.Route
		score float64
	}
	var bestPlan *planItem

	ladder := r.candidateAmounts(target, partsLeft)

	for pass := 0; pass < 2; pass++ {
		avoid := busy
		if pass == 1 {
			avoid = nil
		}
		if pass == 0 && len(busy) == 0 {
			continue
		}

		tried := 0
		for _, a := range ladder {
			rt, p, err := r.findRoute(a, avoid)
			if err != nil {
				continue
			}
			tried++

			fee := float64(rt.TotalAmount) - float64(a)

			// Expected progress minus fee, minus the expected cost
			// of the retries a low-probability shard invites.
			retryCost := (1 - p) * float64(attemptCostBase+
				a*attemptCostPPM/1_000_000)
			score := p*float64(a) - fee*0.5 - retryCost
			if a == amt {
				score *= 1.15
			}

			if bestPlan == nil || score > bestPlan.score {
				bestPlan = &planItem{rt: rt, score: score}
			}

			if a == amt && p > 0.6 {
				break
			}
			if tried >= 5 {
				break
			}
		}

		if bestPlan != nil {
			break
		}
	}

	if bestPlan == nil {
		// Last resort: probe for whatever amount is routable at all,
		// so a depleted corridor still yields progress rather than a
		// terminal give-up.
		if a, rt := r.probeAmount(target, nil); a >= minShard &&
			rt != nil {

			r.noRouteStreak = 0
			return rt, nil
		}

		r.noRouteStreak++
		if r.noRouteStreak > 3 {
			return nil, errors.New("no route found")
		}
		return nil, errors.New("no route available")
	}

	r.noRouteStreak = 0
	return bestPlan.rt, nil
}

// routeViable reports whether every hop of a previously planned route still
// looks able to carry its amount under current beliefs.
func (r *router) routeViable(rt *route.Route) bool {
	for i, h := range rt.Hops {
		e := r.edgeOf(h.ChannelID, h.PubKeyBytes)
		if e == nil {
			return false
		}
		a := hopAmount(rt, i)
		if !e.policyOK(a) || a > r.avail(e) {
			return false
		}
		if r.prob(e, a) < 0.05 {
			return false
		}
	}
	return true
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(h.ChannelID)
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// recordOK raises the proven-good bound on a channel and clears any stale
// failure bound at or below that amount.
func (r *router) recordOK(chanID uint64, a lnwire.MilliSatoshi) {
	b := r.bel(chanID)
	if a > b.okAmt {
		b.okAmt = a
	}
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
	}
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	if len(rt.Hops) == 0 {
		return nil
	}

	// Success: every hop carried its amount, so raise the lower bounds.
	if result.Failure == nil {
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.recordOK(h.ChannelID, a)

			if i == 0 && h.ChannelID != 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settled shard proves this size is deliverable, so lift any
		// self-imposed single-shard cap back to at least this amount.
		delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
		if r.singleCap > 0 && r.singleCap < delivered {
			r.singleCap = delivered
		}

		return nil
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// Everything strictly before the failing hop demonstrably worked.
	if failIdx > 0 {
		for i := 0; i < failIdx && i < len(rt.Hops); i++ {
			r.recordOK(rt.Hops[i].ChannelID, hopAmount(rt, i))
		}
	}

	// Remember that this delivered size did not make it, so the ladder
	// stops re-proposing amounts we know bounce. Only liquidity misses
	// justify this: policy failures are about the route, not the size.
	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if isLiquidityFailure(result) && delivered > minShard {
		lim := delivered - 1
		if r.singleCap == 0 || lim < r.singleCap {
			r.singleCap = lim
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		// Unattributable failure (e.g. an unknown source): the whole
		// route is suspect, so nudge every hop's bound down slightly
		// rather than learning nothing at all.
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			b := r.bel(h.ChannelID)
			if b.okAmt >= a {
				continue
			}
			if !b.hasFail || a < b.failAmt {
				// Weak evidence: only bound the largest hop,
				// which is the likely bottleneck.
				if i == 0 || a >= hopAmount(rt, 0)/2 {
					b.hasFail = true
					b.failAmt = a
				}
			}
		}
		return nil
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(h.ChannelID)

	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	b.fails++

	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

// isLiquidityFailure reports whether the failure looks like a liquidity
// miss rather than a policy violation. Policy failures (fee, cltv) say
// nothing about how much liquidity the corridor holds.
func isLiquidityFailure(result routing.SimHtlcResult) bool {
	switch result.Failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry,
		*lnwire.FailChannelDisabled:
		return false
	default:
		return true
	}
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity.
//   - Per-directed-channel beliefs: hard lower-OK / upper-fail bounds
//     (no time decay: a stale bound costs one retry to refresh).
//   - Probability-aware Dijkstra: minimize fee + penalty/probability.
//   - Joint route-set planning for MPP: pick shard sizes from what each
//     corridor can actually bear instead of blind halving.
//   - Lower-retry on failed channels rather than blacklisting.

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCost is the virtual cost (in msat) of one failed attempt,
	// used to trade fee against success probability.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(6_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7
)

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount proven to pass.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount proven to fail; zero means unknown.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	p := 0.30*low + 0.70*cliff
	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[uint64]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// failStreak counts consecutive failures with no progress.
	failStreak int

	// attempts counts total attempts issued.
	attempts int

	// lastShard remembers the amount of the last route handed out, so we
	// can shrink deliberately when it fails.
	lastShard lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		localBalances: localBalances,
		beliefs:       make(map[uint64]*belief),
		pending:       make(map[uint64]*route.Route),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(chanID uint64) *belief {
	b, ok := r.beliefs[chanID]
	if !ok {
		b = &belief{}
		r.beliefs[chanID] = b
	}
	return b
}

// avail is the amount we still consider spendable over this edge, taking
// our own in-flight HTLCs and local balance into account. It returns zero
// when the edge is unusable at any amount.
func (r *router) avail(e *edge) lnwire.MilliSatoshi {
	cap := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < cap {
		cap = e.maxHTLC
	}

	b := r.beliefs[e.chanID]
	if b != nil {
		if b.hasFail && b.failAmt > 0 {
			// Retry below the proven failure point rather than
			// blacklisting the channel outright.
			lim := b.failAmt * 3 / 4
			if lim < cap {
				cap = lim
			}
		}
		if b.inFlight >= cap {
			return 0
		}
		cap -= b.inFlight
	}

	if e.from == r.source {
		bal := r.localBalances[e.chanID]
		if bal < cap {
			cap = bal
		}
	}

	return cap
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	// Our own channels have exactly known balances.
	if e.from == r.source {
		b := r.beliefs[e.chanID]
		used := lnwire.MilliSatoshi(0)
		if b != nil {
			used = b.inFlight
		}
		if r.localBalances[e.chanID] >= amt+used {
			return knownProb
		}
		return 0
	}

	b := r.beliefs[e.chanID]
	if b == nil {
		return bimodalPrior(amt, e.capacity)
	}

	eff := amt + b.inFlight

	if b.okAmt >= eff {
		return knownProb
	}
	if b.hasFail && eff >= b.failAmt {
		return minProb / 2
	}

	p := bimodalPrior(eff, e.capacity)

	// Narrow with the bounds we do have: known-good below and known-bad
	// above compress the uncertain interval.
	if b.okAmt > 0 && b.hasFail {
		lo := float64(b.okAmt)
		hi := float64(b.failAmt)
		if hi > lo {
			frac := (float64(eff) - lo) / (hi - lo)
			bracket := 1 - frac
			p = 0.5*p + 0.5*bracket
		}
	} else if b.okAmt > 0 {
		// A prior success raises confidence for nearby amounts.
		ratio := float64(eff) / float64(b.okAmt)
		boost := math.Exp(-(ratio - 1) * 1.1)
		p = 0.45*p + 0.55*boost
	} else if b.hasFail {
		// A prior failure at failAmt: everything meaningfully below it
		// is still plausible, but discount.
		frac := float64(eff) / float64(b.failAmt)
		p = p * (1 - 0.85*frac)
	}

	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	// dist is the combined cost used for ordering.
	dist float64
	// amt is the amount that must arrive at node.
	amt lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	cltv    uint32
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	amt     lnwire.MilliSatoshi
	logProb float64
	dist    float64
	via     *edge
	hops    int
	cltv    uint32
}

// findRoute runs a probability-weighted backward Dijkstra. The cost of a
// path is its fee plus an attempt-cost term divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused (already carrying a shard
// of this payment along a chosen route set).
func (r *router) findRoute(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase +
		amt*attemptCostPPM/1_000_000)

	best := make(map[route.Vertex]*pathState)

	target := r.spec.Target
	best[target] = &pathState{
		amt:     amt,
		logProb: 0,
		dist:    0,
		hops:    0,
		cltv:    finalCltvDelta,
	}

	q := &pq{}
	heap.Push(q, &pqItem{
		node: target, dist: 0, amt: amt, logProb: 0,
		hops: 0, cltv: finalCltvDelta,
	})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] {
				continue
			}
			if e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.avail(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			var sending lnwire.MilliSatoshi
			if e.from == r.source {
				sending = amtOver
			} else {
				sending = amtOver + e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-4 {
				continue
			}

			fee := float64(sending) - float64(amt)

			// Risk-adjusted cost: expected fee plus expected retry
			// cost. A small per-hop term discourages long paths.
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*250

			prev, ok := best[e.from]
			if ok && dist >= prev.dist-1e-9 {
				continue
			}

			best[e.from] = &pathState{
				amt:     sending,
				logProb: logProb,
				dist:    dist,
				via:     e,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, best)
	if err != nil {
		return nil, 0, err
	}

	return rt, math.Exp(src.logProb), nil
}

// buildRoute materializes the route from the next-pointer map.
func (r *router) buildRoute(amt lnwire.MilliSatoshi,
	best map[route.Vertex]*pathState) (*route.Route, error) {

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// --- Shard planning -------------------------------------------------------

// firstHopBudget returns the total liquidity we believe is reachable out of
// our own channels, which upper-bounds any single payment.
func (r *router) firstHopBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, edges := range r.inEdges {
		for _, e := range edges {
			if e.from != r.source || seen[e.chanID] {
				continue
			}
			seen[e.chanID] = true
			total += r.avail(e)
		}
	}
	return total
}

// candidateAmounts builds a descending ladder of shard sizes to try for a
// remaining amount, given how many parts we may still use. Rather than pure
// halving, the ladder mixes even splits across the parts we have left with
// geometric shrinkage, so unequal corridors each get an amount they can
// plausibly bear.
func (r *router) candidateAmounts(remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft == 0 {
		partsLeft = 1
	}

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a == 0 || a > remaining || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(remaining)

	// Even splits over all part counts we could still afford.
	for k := uint32(2); k <= partsLeft && k <= 16; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric ladder for finer probing when even splits all fail.
	cur := remaining
	for i := 0; i < 12; i++ {
		cur = cur * 2 / 3
		if cur < 1_000 {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: just under each proven failure point on a
	// channel out of our own node, and each proven-good amount.
	for _, b := range r.beliefs {
		if b.hasFail && b.failAmt > 1_000 {
			add(b.failAmt * 3 / 4)
		}
		if b.okAmt > 0 {
			add(b.okAmt)
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })

	// Cap the ladder so a single RequestRoute call stays bounded.
	if len(out) > 24 {
		out = out[:24]
	}
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs, so
// a new shard is planned over a genuinely disjoint corridor where possible.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// RequestRoute plans the next shard. It searches jointly over shard amount
// and route: for each candidate amount (largest first) it finds the best
// risk-adjusted route, and takes the amount whose route maximizes expected
// delivered value per unit of risk-adjusted cost.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.attempts++
	if r.attempts > 400 {
		return nil, errors.New("attempt budget exhausted")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	// A shard can never exceed what our own channels can push right now.
	budget := r.firstHopBudget()
	target := amt
	if budget > 0 && budget < target {
		target = budget
	}
	if target == 0 {
		target = amt
	}

	busy := r.inFlightChans()

	type plan struct {
		rt    *route.Route
		score float64
		amt   lnwire.MilliSatoshi
	}
	var bestPlan *plan

	ladder := r.candidateAmounts(target, partsLeft)

	// First pass: prefer corridors disjoint from in-flight shards so
	// parallel parts do not contend for the same liquidity.
	for pass := 0; pass < 2; pass++ {
		avoid := busy
		if pass == 1 {
			avoid = nil
		}
		if pass == 0 && len(busy) == 0 {
			continue
		}

		tried := 0
		for _, a := range ladder {
			if a == 0 {
				continue
			}
			rt, p, err := r.findRoute(a, avoid)
			if err != nil {
				continue
			}
			tried++

			fee := float64(rt.TotalAmount) - float64(a)

			// Expected value: probability-weighted delivered
			// amount, discounted by fee. Bigger shards are
			// preferred when their probability holds up.
			score := p*float64(a) - fee*0.5

			// Slight bonus for shards that finish the payment in
			// one go, since fewer parts means fewer attempts.
			if a == amt {
				score *= 1.15
			}

			if bestPlan == nil || score > bestPlan.score {
				bestPlan = &plan{rt: rt, score: score, amt: a}
			}

			// Stop early once we have a strong full-amount plan.
			if a == amt && p > 0.75 {
				break
			}
			if tried >= 8 {
				break
			}
		}

		if bestPlan != nil {
			break
		}
	}

	if bestPlan == nil {
		return nil, errors.New("no route found")
	}

	r.lastShard = bestPlan.amt
	return bestPlan.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(h.ChannelID)
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount, so raise the lower bounds.
	if result.Failure == nil {
		r.failStreak = 0
		for i, h := range rt.Hops {
			b := r.bel(h.ChannelID)
			a := hopAmount(rt, i)
			if a > b.okAmt {
				b.okAmt = a
			}
			// A success invalidates any older failure bound at or
			// below this amount.
			if b.hasFail && b.failAmt <= a {
				b.hasFail = false
				b.failAmt = 0
			}
			if h.ChannelID != 0 && i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// Everything strictly before the failing hop demonstrably worked.
	if failIdx > 0 {
		for i := 0; i < failIdx && i < len(rt.Hops); i++ {
			b := r.bel(rt.Hops[i].ChannelID)
			a := hopAmount(rt, i)
			if a > b.okAmt {
				b.okAmt = a
			}
			if b.hasFail && b.failAmt <= a {
				b.hasFail = false
				b.failAmt = 0
			}
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		return nil
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(h.ChannelID)

	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - Probability-aware backward Dijkstra: minimize fee plus an attempt
//     cost divided by the path's success probability.
//   - Joint shard sizing: every corridor we discover is re-priced at the
//     amount that corridor can actually bear (its belief bottleneck), so
//     unequal parallel corridors each carry a shard sized to fit instead
//     of a blind half of the remainder.
//   - A full descending amount ladder that is never truncated from the
//     small end, so we keep probing smaller shards instead of terminally
//     giving up with "no route found".
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// is deliberately large relative to fees.
	attemptCostBase = lnwire.MilliSatoshi(2_000)
	attemptCostPPM  = lnwire.MilliSatoshi(15_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 60
	maxFailStreak = 18

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear. Under a bimodal distribution this
	// sits comfortably on the plausible side of the cliff.
	priorSafeNum = 35
	priorSafeDen = 100

	// lowerRetryNum/lowerRetryDen is the fraction of a proven failure
	// amount we are still willing to retry.
	lowerRetryNum = 3
	lowerRetryDen = 4
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount proven to pass.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount proven to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		lim := b.failAmt * lowerRetryNum / lowerRetryDen
		if lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.hasFail {
			lim := b.failAmt * lowerRetryNum / lowerRetryDen
			if est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Everything meaningfully below a proven failure is
			// still plausible, but discounted.
			frac := float64(eff) / float64(b.failAmt)
			p = p * (1 - 0.85*frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.15

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: proven-good amounts and just under proven
	// failure points.
	for _, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail && b.failAmt >= minShard {
			add(b.failAmt * lowerRetryNum / lowerRetryDen)
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{rt: rt, score: s, amt: c, prob: p}
		}
	}

	return best
}

// RequestRoute plans the next shard. It searches jointly over shard amount
// and corridor: for every candidate amount (largest first) it finds the
// best risk-adjusted path, then re-prices that path at the amount its
// weakest hop can bear, and returns the highest scoring combination.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	busy := r.inFlightChans()
	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount, so raise the lower bounds.
	if result.Failure == nil {
		r.failStreak = 0
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.provePassed(h, a)

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//     Knowledge therefore stays correct across payments in a batch instead
//     of going stale the moment we ourselves spend.
//   - BIMODAL OPTIMISM after a proven forward: because funds sit almost
//     entirely on one side, a channel that has forwarded for us is treated
//     as holding the bulk of its capacity (minus what we drained), which
//     lets later, larger payments reuse a proven corridor without first
//     failing at the larger amount.
//   - Depth-aware lower retries: how far below a proven failure we are
//     willing to retry depends on how depleted the direction looks. A
//     failure at a tiny fraction of capacity means "empty"; a failure near
//     capacity means "plenty is still there".
//   - JOINT ROUTE-SET PLANNING: when no single corridor can carry the
//     remaining amount, a greedy min-cost-flow decomposition picks several
//     DISJOINT corridors up front and sizes each shard to that corridor's
//     believed bottleneck. The extra shards are queued and handed out on
//     subsequent RequestRoute calls, so unequal parallel corridors each
//     carry a shard that fits instead of a blind half of the remainder.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 60
	maxFailStreak = 18

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear. Under a bimodal distribution this
	// sits comfortably on the plausible side of the cliff.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold. It is
	// the centre of the optimistic logistic, not a hard bound.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.2
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies. Maximizing p*amt is
// exactly maximizing delivered value per attempt.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 6 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	var out []*plan
	left := remaining

	for k := uint32(0); k < partsLeft; k++ {
		if left < minShard {
			break
		}

		path := r.findAnyPath(left, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			break
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor: for every candidate amount (largest first) it finds the best
// risk-adjusted path, re-prices that path at the amount its weakest hop can
// bear, and finally checks whether a deliberate multi-corridor split would
// cover more of the remaining amount than the best single shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			break
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly.
	if partsLeft > 1 && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			var total lnwire.MilliSatoshi
			for _, pl := range flow {
				total += pl.amt
			}

			first := flow[0]
			better := best == nil ||
				(total > best.amt &&
					first.score > best.score*0.85)

			if better {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Beliefs just changed, so any queued joint plan is stale.
	r.queued = nil

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity.
//   - Per-directed-channel beliefs: hard lower-OK / upper-fail bounds
//     (no time decay: a stale bound costs one retry to refresh).
//   - Probability-aware Dijkstra: minimize fee + penalty/probability.
//   - JOINT route-set planning: when no single path can carry the
//     remaining amount, plan a disjoint set of corridors up front and
//     size each shard to the max-flow that corridor can actually bear.
//   - Lower-retry on failed channels rather than blacklisting, with a
//     bisection ladder between the proven-ok and proven-fail bounds.

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCost is the virtual cost (in msat) of one failed attempt,
	// used to trade fee against success probability.
	attemptCostBase = lnwire.MilliSatoshi(1_000)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// minShard is the smallest shard we will bother planning.
	minShard = lnwire.MilliSatoshi(1_000)

	// maxAttempts bounds the total attempts we will ever issue.
	maxAttempts = 500
)

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount proven to pass.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount proven to fail; zero means unknown.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	p := 0.30*low + 0.70*cliff
	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[uint64]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// attempts counts total attempts issued.
	attempts int

	// noRouteStreak counts consecutive planning failures.
	noRouteStreak int

	// planQueue holds shard amounts from a joint plan that we have
	// committed to but not yet handed out.
	planQueue []lnwire.MilliSatoshi

	// planFor is the remaining amount the planQueue was built for; if the
	// remaining amount moves away from it the plan is discarded.
	planFor lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		localBalances: localBalances,
		beliefs:       make(map[uint64]*belief),
		pending:       make(map[uint64]*route.Route),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				if e.from == source {
					r.localEdges = append(r.localEdges, e)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(chanID uint64) *belief {
	b, ok := r.beliefs[chanID]
	if !ok {
		b = &belief{}
		r.beliefs[chanID] = b
	}
	return b
}

// avail is the amount we still consider spendable over this edge, taking
// our own in-flight HTLCs and local balance into account. It returns zero
// when the edge is unusable at any amount.
func (r *router) avail(e *edge) lnwire.MilliSatoshi {
	cap := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < cap {
		cap = e.maxHTLC
	}

	b := r.beliefs[e.chanID]
	if b != nil {
		if b.hasFail && b.failAmt > 0 {
			// Retry below the proven failure point rather than
			// blacklisting the channel outright. Bisect toward the
			// proven-good bound so repeated failures converge.
			lim := b.failAmt - 1
			if b.okAmt > 0 && b.okAmt < lim {
				lim = b.okAmt + (lim-b.okAmt)*2/3
			} else {
				lim = b.failAmt * 3 / 4
			}
			if lim < cap {
				cap = lim
			}
		}
		if b.inFlight >= cap {
			return 0
		}
		cap -= b.inFlight
	}

	if e.from == r.source {
		bal := r.localBalances[e.chanID]
		if bal < cap {
			cap = bal
		}
	}

	return cap
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	// Our own channels have exactly known balances.
	if e.from == r.source {
		b := r.beliefs[e.chanID]
		used := lnwire.MilliSatoshi(0)
		if b != nil {
			used = b.inFlight
		}
		if r.localBalances[e.chanID] >= amt+used {
			return knownProb
		}
		return 0
	}

	b := r.beliefs[e.chanID]
	if b == nil {
		return bimodalPrior(amt, e.capacity)
	}

	eff := amt + b.inFlight

	if b.okAmt >= eff {
		return knownProb
	}
	if b.hasFail && eff >= b.failAmt {
		return minProb / 2
	}

	p := bimodalPrior(eff, e.capacity)

	// Narrow with the bounds we do have: known-good below and known-bad
	// above compress the uncertain interval.
	if b.okAmt > 0 && b.hasFail {
		lo := float64(b.okAmt)
		hi := float64(b.failAmt)
		if hi > lo {
			frac := (float64(eff) - lo) / (hi - lo)
			bracket := 1 - frac
			p = 0.5*p + 0.5*bracket
		}
	} else if b.okAmt > 0 {
		// A prior success raises confidence for nearby amounts.
		ratio := float64(eff) / float64(b.okAmt)
		boost := math.Exp(-(ratio - 1) * 1.1)
		p = 0.45*p + 0.55*boost
	} else if b.hasFail {
		// A prior failure at failAmt: everything meaningfully below it
		// is still plausible, but discount.
		frac := float64(eff) / float64(b.failAmt)
		p = p * (1 - 0.85*frac)
	}

	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	// dist is the combined cost used for ordering.
	dist float64
	// amt is the amount that must arrive at node.
	amt lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	cltv    uint32
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	amt     lnwire.MilliSatoshi
	logProb float64
	dist    float64
	via     *edge
	hops    int
	cltv    uint32
}

// findRoute runs a probability-weighted backward Dijkstra. The cost of a
// path is its fee plus an attempt-cost term divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused (already carrying a shard
// of this payment along a chosen route set).
func (r *router) findRoute(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase +
		amt*attemptCostPPM/1_000_000)

	best := make(map[route.Vertex]*pathState)

	target := r.spec.Target
	best[target] = &pathState{
		amt:     amt,
		logProb: 0,
		dist:    0,
		hops:    0,
		cltv:    finalCltvDelta,
	}

	q := &pq{}
	heap.Push(q, &pqItem{
		node: target, dist: 0, amt: amt, logProb: 0,
		hops: 0, cltv: finalCltvDelta,
	})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] {
				continue
			}
			if e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.avail(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			var sending lnwire.MilliSatoshi
			if e.from == r.source {
				sending = amtOver
			} else {
				sending = amtOver + e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-4 {
				continue
			}

			fee := float64(sending) - float64(amt)

			// Risk-adjusted cost: expected fee plus expected retry
			// cost. A small per-hop term discourages long paths.
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*250

			prev, ok := best[e.from]
			if ok && dist >= prev.dist-1e-9 {
				continue
			}

			best[e.from] = &pathState{
				amt:     sending,
				logProb: logProb,
				dist:    dist,
				via:     e,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, best)
	if err != nil {
		return nil, 0, err
	}

	return rt, math.Exp(src.logProb), nil
}

// buildRoute materializes the route from the next-pointer map.
func (r *router) buildRoute(amt lnwire.MilliSatoshi,
	best map[route.Vertex]*pathState) (*route.Route, error) {

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// --- Joint route-set planning ---------------------------------------------

// maxSendable finds the largest amount, by binary search, for which a route
// exists avoiding the given channels. It returns 0 when even the smallest
// probe is unroutable.
func (r *router) maxSendable(hi lnwire.MilliSatoshi,
	avoid map[uint64]bool) lnwire.MilliSatoshi {

	if hi < minShard {
		return 0
	}
	if _, _, err := r.findRoute(hi, avoid); err == nil {
		return hi
	}

	lo := lnwire.MilliSatoshi(0)
	for i := 0; i < 14 && hi-lo > hi/64+1; i++ {
		mid := lo + (hi-lo)/2
		if mid < minShard {
			break
		}
		if _, _, err := r.findRoute(mid, avoid); err == nil {
			lo = mid
		} else {
			hi = mid
		}
	}
	if lo < minShard {
		return 0
	}
	return lo
}

// planShards builds a joint route set for the remaining amount: it greedily
// carves the largest shard each disjoint corridor can bear until the amount
// is covered or we run out of parts/corridors. The returned amounts sum to
// at most remaining; an empty result means we could not cover it and the
// caller should fall back to a single best-effort shard.
func (r *router) planShards(remaining lnwire.MilliSatoshi,
	partsLeft uint32, busy map[uint64]bool) []lnwire.MilliSatoshi {

	if partsLeft == 0 {
		return nil
	}

	// Corridors chosen so far must not be reused by later shards, so
	// unequal parallel corridors each carry what they can bear.
	avoid := make(map[uint64]bool, len(busy)+8)
	for k := range busy {
		avoid[k] = true
	}

	var out []lnwire.MilliSatoshi
	left := remaining

	for k := uint32(0); k < partsLeft && left >= minShard; k++ {
		amt := r.maxSendable(left, avoid)
		if amt == 0 {
			break
		}

		rt, _, err := r.findRoute(amt, avoid)
		if err != nil {
			break
		}

		out = append(out, amt)
		left -= amt

		// Reserve this corridor's first hop (and its bottleneck hops)
		// so the next shard looks elsewhere.
		for _, h := range rt.Hops {
			avoid[h.ChannelID] = true
		}
	}

	if left >= minShard && len(out) > 0 {
		// Incomplete cover: still useful, the runner will call us
		// again for the rest once these shards land.
		return out
	}
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs, so
// a new shard is planned over a genuinely disjoint corridor where possible.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// firstHopBudget returns the total liquidity we believe is reachable out of
// our own channels, which upper-bounds any single payment.
func (r *router) firstHopBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.avail(e)
	}
	return total
}

// candidateAmounts builds a descending ladder of shard sizes to try for a
// remaining amount, used as a fallback when joint planning comes up empty.
func (r *router) candidateAmounts(remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft == 0 {
		partsLeft = 1
	}

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > remaining || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(remaining)

	// Even splits over all part counts we could still afford.
	for k := uint32(2); k <= partsLeft && k <= 16; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric ladder for finer probing when even splits all fail.
	cur := remaining
	for i := 0; i < 12; i++ {
		cur = cur * 2 / 3
		if cur < minShard {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: just under each proven failure point and
	// each proven-good amount.
	for _, b := range r.beliefs {
		if b.hasFail && b.failAmt > minShard {
			add(b.failAmt * 3 / 4)
		}
		if b.okAmt > 0 {
			add(b.okAmt)
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })

	if len(out) > 20 {
		out = out[:20]
	}
	return out
}

// RequestRoute plans the next shard. It first tries to satisfy the whole
// remaining amount over one route; failing that it plans a joint route set
// whose shard sizes come from each corridor's actual carrying capacity.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.attempts++
	if r.attempts > maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Drop a stale plan if the remaining amount no longer matches what it
	// was built for.
	if r.planFor != amt {
		r.planQueue = nil
		r.planFor = 0
	}

	// Serve a committed plan entry first.
	for len(r.planQueue) > 0 {
		a := r.planQueue[0]
		r.planQueue = r.planQueue[1:]
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		if rt, _, err := r.findRoute(a, busy); err == nil {
			r.noRouteStreak = 0
			return rt, nil
		}
		if rt, _, err := r.findRoute(a, nil); err == nil {
			r.noRouteStreak = 0
			return rt, nil
		}
	}
	r.planQueue = nil
	r.planFor = 0

	// A shard can never exceed what our own channels can push right now.
	budget := r.firstHopBudget()
	target := amt
	if budget > 0 && budget < target {
		target = budget
	}
	if target < minShard {
		target = amt
	}

	// Fast path: the whole remaining amount over one good route.
	if rt, p, err := r.findRoute(target, busy); err == nil && p > 0.55 &&
		target == amt {

		r.noRouteStreak = 0
		return rt, nil
	}

	// Joint planning: size shards to corridors instead of halving.
	if partsLeft > 1 {
		plan := r.planShards(target, partsLeft, busy)
		if len(plan) > 0 {
			// Largest shard first: it is the one most likely to be
			// invalidated by drift, so probe it while our belief
			// is freshest.
			sort.Slice(plan, func(i, j int) bool {
				return plan[i] > plan[j]
			})
			first := plan[0]
			r.planQueue = plan[1:]
			r.planFor = amt - first

			if rt, _, err := r.findRoute(first, busy); err == nil {
				r.noRouteStreak = 0
				return rt, nil
			}
			if rt, _, err := r.findRoute(first, nil); err == nil {
				r.noRouteStreak = 0
				return rt, nil
			}
			r.planQueue = nil
			r.planFor = 0
		}
	}

	// Fallback: descend a ladder of amounts, scoring each by expected
	// delivered value net of fee.
	type plan struct {
		rt    *route.Route
		score float64
	}
	var bestPlan *plan

	ladder := r.candidateAmounts(target, partsLeft)

	for pass := 0; pass < 2; pass++ {
		avoid := busy
		if pass == 1 {
			avoid = nil
		}
		if pass == 0 && len(busy) == 0 {
			continue
		}

		tried := 0
		for _, a := range ladder {
			rt, p, err := r.findRoute(a, avoid)
			if err != nil {
				continue
			}
			tried++

			fee := float64(rt.TotalAmount) - float64(a)
			score := p*float64(a) - fee*0.5
			if a == amt {
				score *= 1.15
			}

			if bestPlan == nil || score > bestPlan.score {
				bestPlan = &plan{rt: rt, score: score}
			}

			if a == amt && p > 0.7 {
				break
			}
			if tried >= 8 {
				break
			}
		}

		if bestPlan != nil {
			break
		}
	}

	if bestPlan == nil {
		// Last resort: probe for whatever amount is routable at all,
		// so a depleted corridor still yields progress rather than a
		// terminal give-up.
		if a := r.maxSendable(target, nil); a >= minShard {
			if rt, _, err := r.findRoute(a, nil); err == nil {
				r.noRouteStreak = 0
				return rt, nil
			}
		}

		r.noRouteStreak++
		if r.noRouteStreak > 3 {
			return nil, errors.New("no route found")
		}
		return nil, errors.New("no route available")
	}

	r.noRouteStreak = 0
	return bestPlan.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(h.ChannelID)
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// recordOK raises the proven-good bound on a channel and clears any stale
// failure bound at or below that amount.
func (r *router) recordOK(chanID uint64, a lnwire.MilliSatoshi) {
	b := r.bel(chanID)
	if a > b.okAmt {
		b.okAmt = a
	}
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount, so raise the lower bounds.
	if result.Failure == nil {
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.recordOK(h.ChannelID, a)

			if i == 0 && h.ChannelID != 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// Everything strictly before the failing hop demonstrably worked.
	if failIdx > 0 {
		for i := 0; i < failIdx && i < len(rt.Hops); i++ {
			r.recordOK(rt.Hops[i].ChannelID, hopAmount(rt, i))
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		// Unattributable failure (e.g. an unknown source): the whole
		// route is suspect, so nudge every hop's bound down slightly
		// rather than learning nothing at all.
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			b := r.bel(h.ChannelID)
			if b.okAmt >= a {
				continue
			}
			if !b.hasFail || a < b.failAmt {
				// Weak evidence: only bound the largest hop,
				// which is the likely bottleneck.
				if i == 0 || a >= hopAmount(rt, 0)/2 {
					b.hasFail = true
					b.failAmt = a
				}
			}
		}
		return nil
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(h.ChannelID)

	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity.
//   - Per-directed-channel beliefs: hard lower-OK / upper-fail bounds
//     (no time decay: a stale bound costs one retry to refresh).
//   - Probability-aware Dijkstra: minimize fee + penalty/probability.
//   - JOINT route-set planning: plan a set of near-disjoint corridors up
//     front and size each shard to the max flow that corridor can bear,
//     rather than discovering splits through failure.
//   - Global attempt discipline: a hard per-payment attempt budget plus
//     "no new information" detection so a hopeless payment gives up fast
//     instead of burning 200 retries.

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCost is the virtual cost (in msat) of one failed attempt,
	// used to trade fee against success probability.
	attemptCostBase = lnwire.MilliSatoshi(1_000)
	attemptCostPPM  = lnwire.MilliSatoshi(6_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 6

	// minShard is the smallest shard we will bother planning.
	minShard = lnwire.MilliSatoshi(1_000)

	// attemptBudget bounds attempts for a single payment. Past this the
	// payment is almost certainly unroutable, and further retries only
	// hurt the retry-efficiency score.
	attemptBudget = 46

	// staleRounds is how many consecutive attempts may pass without any
	// new liquidity information before we declare the payment hopeless.
	staleRounds = 6
)

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount proven to pass.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount proven to fail; zero means unknown.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// fails counts how many times this direction has failed. Repeated
	// failures mean the channel is genuinely dry in this direction, so we
	// probe it far less aggressively.
	fails int

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	p := 0.30*low + 0.70*cliff
	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[uint64]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// attempts counts attempts issued for the current payment.
	attempts int

	// learnedAt is the attempt index at which we last gained new
	// liquidity information.
	learnedAt int

	// noRouteStreak counts consecutive planning failures.
	noRouteStreak int

	// planQueue holds shard amounts from a joint plan that we have
	// committed to but not yet handed out.
	planQueue []lnwire.MilliSatoshi

	// planFor is the remaining amount the planQueue was built for; if the
	// remaining amount moves away from it the plan is discarded.
	planFor lnwire.MilliSatoshi

	// lastRemaining tracks the remaining amount handed to us, so we can
	// detect the start of a new payment and reset per-payment counters.
	lastRemaining lnwire.MilliSatoshi

	// started is false until the first RequestRoute call.
	started bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		localBalances: localBalances,
		beliefs:       make(map[uint64]*belief),
		pending:       make(map[uint64]*route.Route),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				if e.from == source {
					r.localEdges = append(r.localEdges, e)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(chanID uint64) *belief {
	b, ok := r.beliefs[chanID]
	if !ok {
		b = &belief{}
		r.beliefs[chanID] = b
	}
	return b
}

// probeLimit is the largest amount we are still willing to push over an
// edge given its failure history. Rather than blacklisting, we bisect down
// toward the proven-good bound; repeated failures shrink the window fast so
// we stop re-probing a dry channel forever.
func probeLimit(b *belief) lnwire.MilliSatoshi {
	if !b.hasFail || b.failAmt == 0 {
		return lnwire.MilliSatoshi(math.MaxUint64 / 4)
	}

	lim := b.failAmt - 1
	if b.okAmt > 0 && b.okAmt < lim {
		// Bisect between proven-good and proven-bad.
		lim = b.okAmt + (lim-b.okAmt)/2
	} else {
		// No good bound: back off geometrically with repeat failures.
		switch {
		case b.fails <= 1:
			lim = b.failAmt / 2
		case b.fails == 2:
			lim = b.failAmt / 5
		case b.fails == 3:
			lim = b.failAmt / 12
		default:
			return 0
		}
	}
	return lim
}

// avail is the amount we still consider spendable over this edge, taking
// our own in-flight HTLCs and local balance into account. It returns zero
// when the edge is unusable at any amount.
func (r *router) avail(e *edge) lnwire.MilliSatoshi {
	cap := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < cap {
		cap = e.maxHTLC
	}

	b := r.beliefs[e.chanID]
	if b != nil {
		if lim := probeLimit(b); lim < cap {
			cap = lim
		}
		if b.inFlight >= cap {
			return 0
		}
		cap -= b.inFlight
	}

	if e.from == r.source {
		bal := r.localBalances[e.chanID]
		if bal < cap {
			cap = bal
		}
	}

	return cap
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	// Our own channels have exactly known balances.
	if e.from == r.source {
		b := r.beliefs[e.chanID]
		used := lnwire.MilliSatoshi(0)
		if b != nil {
			used = b.inFlight
		}
		if r.localBalances[e.chanID] >= amt+used {
			return knownProb
		}
		return 0
	}

	b := r.beliefs[e.chanID]
	if b == nil {
		return bimodalPrior(amt, e.capacity)
	}

	eff := amt + b.inFlight

	if b.okAmt >= eff {
		return knownProb
	}
	if b.hasFail && eff >= b.failAmt {
		return minProb / 2
	}

	p := bimodalPrior(eff, e.capacity)

	// Narrow with the bounds we do have: known-good below and known-bad
	// above compress the uncertain interval.
	if b.okAmt > 0 && b.hasFail {
		lo := float64(b.okAmt)
		hi := float64(b.failAmt)
		if hi > lo {
			frac := (float64(eff) - lo) / (hi - lo)
			bracket := 1 - frac
			p = 0.5*p + 0.5*bracket
		}
	} else if b.okAmt > 0 {
		// A prior success raises confidence for nearby amounts.
		ratio := float64(eff) / float64(b.okAmt)
		boost := math.Exp(-(ratio - 1) * 1.1)
		p = 0.45*p + 0.55*boost
	} else if b.hasFail {
		// A prior failure at failAmt: everything meaningfully below it
		// is still plausible, but discount. Repeated failures on the
		// same direction mean it is dry, not unlucky.
		frac := float64(eff) / float64(b.failAmt)
		damp := 0.85 + 0.05*float64(b.fails)
		if damp > 0.97 {
			damp = 0.97
		}
		p = p * (1 - damp*frac)
	}

	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	// dist is the combined cost used for ordering.
	dist float64
	// amt is the amount that must arrive at node.
	amt lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	cltv    uint32
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	amt     lnwire.MilliSatoshi
	logProb float64
	dist    float64
	via     *edge
	hops    int
	cltv    uint32
}

// findRoute runs a probability-weighted backward Dijkstra. The cost of a
// path is its fee plus an attempt-cost term divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused (already carrying a shard
// of this payment along a chosen route set).
func (r *router) findRoute(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase +
		amt*attemptCostPPM/1_000_000)

	best := make(map[route.Vertex]*pathState)

	target := r.spec.Target
	best[target] = &pathState{
		amt:     amt,
		logProb: 0,
		dist:    0,
		hops:    0,
		cltv:    finalCltvDelta,
	}

	q := &pq{}
	heap.Push(q, &pqItem{
		node: target, dist: 0, amt: amt, logProb: 0,
		hops: 0, cltv: finalCltvDelta,
	})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] {
				continue
			}
			if e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.avail(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			var sending lnwire.MilliSatoshi
			if e.from == r.source {
				sending = amtOver
			} else {
				sending = amtOver + e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-3 {
				continue
			}

			fee := float64(sending) - float64(amt)

			// Risk-adjusted cost: expected fee plus expected retry
			// cost. A small per-hop term discourages long paths.
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*250

			prev, ok := best[e.from]
			if ok && dist >= prev.dist-1e-9 {
				continue
			}

			best[e.from] = &pathState{
				amt:     sending,
				logProb: logProb,
				dist:    dist,
				via:     e,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, best)
	if err != nil {
		return nil, 0, err
	}

	return rt, math.Exp(src.logProb), nil
}

// buildRoute materializes the route from the next-pointer map.
func (r *router) buildRoute(amt lnwire.MilliSatoshi,
	best map[route.Vertex]*pathState) (*route.Route, error) {

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// --- Joint route-set planning ---------------------------------------------

// maxSendable finds the largest amount, by binary search, for which a route
// exists avoiding the given channels. It returns 0 when even the smallest
// probe is unroutable.
func (r *router) maxSendable(hi lnwire.MilliSatoshi,
	avoid map[uint64]bool) lnwire.MilliSatoshi {

	if hi < minShard {
		return 0
	}
	if _, _, err := r.findRoute(hi, avoid); err == nil {
		return hi
	}

	lo := lnwire.MilliSatoshi(0)
	for i := 0; i < 12 && hi-lo > hi/32+1; i++ {
		mid := lo + (hi-lo)/2
		if mid < minShard {
			break
		}
		if _, _, err := r.findRoute(mid, avoid); err == nil {
			lo = mid
		} else {
			hi = mid
		}
	}
	if lo < minShard {
		return 0
	}
	return lo
}

// planShards builds a joint route set for the remaining amount: it greedily
// carves the largest shard each disjoint corridor can bear until the amount
// is covered or we run out of parts/corridors. The returned amounts sum to
// at most remaining.
func (r *router) planShards(remaining lnwire.MilliSatoshi,
	partsLeft uint32, busy map[uint64]bool) []lnwire.MilliSatoshi {

	if partsLeft == 0 {
		return nil
	}

	// Corridors chosen so far must not be reused by later shards, so
	// unequal parallel corridors each carry what they can bear.
	avoid := make(map[uint64]bool, len(busy)+8)
	for k := range busy {
		avoid[k] = true
	}

	var out []lnwire.MilliSatoshi
	left := remaining

	for k := uint32(0); k < partsLeft && left >= minShard; k++ {
		amt := r.maxSendable(left, avoid)
		if amt == 0 {
			break
		}

		rt, _, err := r.findRoute(amt, avoid)
		if err != nil {
			break
		}

		out = append(out, amt)
		left -= amt

		// Reserve this corridor's hops so the next shard looks
		// elsewhere and the corridors stay near-disjoint.
		for _, h := range rt.Hops {
			avoid[h.ChannelID] = true
		}
	}

	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs, so
// a new shard is planned over a genuinely disjoint corridor where possible.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// firstHopBudget returns the total liquidity we believe is reachable out of
// our own channels, which upper-bounds any single payment.
func (r *router) firstHopBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.avail(e)
	}
	return total
}

// candidateAmounts builds a descending ladder of shard sizes to try for a
// remaining amount, used as a fallback when joint planning comes up empty.
func (r *router) candidateAmounts(remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft == 0 {
		partsLeft = 1
	}

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > remaining || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(remaining)

	// Even splits over all part counts we could still afford.
	for k := uint32(2); k <= partsLeft && k <= 12; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric ladder for finer probing when even splits all fail.
	cur := remaining
	for i := 0; i < 10; i++ {
		cur = cur * 2 / 3
		if cur < minShard {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: just under each proven failure point and
	// each proven-good amount.
	for _, b := range r.beliefs {
		if b.hasFail && b.failAmt > minShard*2 {
			add(b.failAmt / 2)
		}
		if b.okAmt > 0 {
			add(b.okAmt)
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })

	if len(out) > 14 {
		out = out[:14]
	}
	return out
}

// newPayment resets the per-payment counters when the runner starts a new
// payment. We detect this by the remaining amount rising: within a payment
// it only ever falls as shards settle.
func (r *router) newPayment(amt lnwire.MilliSatoshi) {
	r.attempts = 0
	r.learnedAt = 0
	r.noRouteStreak = 0
	r.planQueue = nil
	r.planFor = 0
	r.lastRemaining = amt
	r.started = true
}

// RequestRoute plans the next shard. It first tries to satisfy the whole
// remaining amount over one route; failing that it plans a joint route set
// whose shard sizes come from each corridor's actual carrying capacity.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	// Detect a fresh payment: the remaining amount grew, or this is the
	// first call. Liquidity beliefs persist across payments (they are
	// what makes the batch learn), but attempt budgets do not.
	if !r.started || amt > r.lastRemaining {
		r.newPayment(amt)
	}
	r.lastRemaining = amt

	r.attempts++

	// Hard attempt budget: a payment that has burned this many probes is
	// overwhelmingly likely to be unroutable, and every further retry is
	// a straight cost with no upside.
	if r.attempts > attemptBudget {
		return nil, errors.New("attempt budget exhausted")
	}

	// Stall detection: if the last several attempts taught us nothing new
	// about liquidity, more of the same will not either.
	if r.attempts-r.learnedAt > staleRounds && inFlightHtlcs == 0 {
		return nil, errors.New("no progress: giving up")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Drop a stale plan if the remaining amount no longer matches what it
	// was built for.
	if r.planFor != amt {
		r.planQueue = nil
		r.planFor = 0
	}

	// Serve a committed plan entry first.
	for len(r.planQueue) > 0 {
		a := r.planQueue[0]
		r.planQueue = r.planQueue[1:]
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		if rt, _, err := r.findRoute(a, busy); err == nil {
			r.noRouteStreak = 0
			return rt, nil
		}
		if rt, _, err := r.findRoute(a, nil); err == nil {
			r.noRouteStreak = 0
			return rt, nil
		}
	}
	r.planQueue = nil
	r.planFor = 0

	// A shard can never exceed what our own channels can push right now.
	budget := r.firstHopBudget()
	target := amt
	if budget > 0 && budget < target {
		target = budget
	}
	if target < minShard {
		target = amt
	}

	// Fast path: the whole remaining amount over one good route.
	if target == amt {
		if rt, p, err := r.findRoute(target, busy); err == nil &&
			p > 0.5 {

			r.noRouteStreak = 0
			return rt, nil
		}
	}

	// Joint planning: size shards to corridors instead of halving. This
	// is the main lever for large payments that no single path can carry.
	if partsLeft > 1 {
		plan := r.planShards(target, partsLeft, busy)

		// Only commit to a plan that actually covers a useful slice of
		// the remaining amount; a plan of dust shards just burns
		// attempts.
		var covered lnwire.MilliSatoshi
		for _, a := range plan {
			covered += a
		}

		if len(plan) > 0 && covered >= target/4 {
			// Largest shard first: it is the one most likely to be
			// invalidated by drift, so probe it while our belief
			// is freshest.
			sort.Slice(plan, func(i, j int) bool {
				return plan[i] > plan[j]
			})
			first := plan[0]
			r.planQueue = plan[1:]
			r.planFor = amt - first

			if rt, _, err := r.findRoute(first, busy); err == nil {
				r.noRouteStreak = 0
				return rt, nil
			}
			if rt, _, err := r.findRoute(first, nil); err == nil {
				r.noRouteStreak = 0
				return rt, nil
			}
			r.planQueue = nil
			r.planFor = 0
		}
	}

	// Fallback: descend a ladder of amounts, scoring each by expected
	// delivered value net of fee.
	type plan struct {
		rt    *route.Route
		score float64
	}
	var bestPlan *plan

	ladder := r.candidateAmounts(target, partsLeft)

	for pass := 0; pass < 2; pass++ {
		avoid := busy
		if pass == 1 {
			avoid = nil
		}
		if pass == 0 && len(busy) == 0 {
			continue
		}

		tried := 0
		for _, a := range ladder {
			rt, p, err := r.findRoute(a, avoid)
			if err != nil {
				continue
			}
			tried++

			fee := float64(rt.TotalAmount) - float64(a)
			score := p*float64(a) - fee*0.5
			if a == amt {
				score *= 1.15
			}

			if bestPlan == nil || score > bestPlan.score {
				bestPlan = &plan{rt: rt, score: score}
			}

			if a == amt && p > 0.7 {
				break
			}
			if tried >= 6 {
				break
			}
		}

		if bestPlan != nil {
			break
		}
	}

	if bestPlan == nil {
		// Last resort: probe for whatever amount is routable at all,
		// so a depleted corridor still yields progress rather than a
		// terminal give-up.
		if a := r.maxSendable(target, nil); a >= minShard {
			if rt, _, err := r.findRoute(a, nil); err == nil {
				r.noRouteStreak = 0
				return rt, nil
			}
		}

		r.noRouteStreak++
		if r.noRouteStreak > 2 {
			return nil, errors.New("no route found")
		}
		return nil, errors.New("no route available")
	}

	r.noRouteStreak = 0
	return bestPlan.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(h.ChannelID)
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// recordOK raises the proven-good bound on a channel and clears any stale
// failure bound at or below that amount. It reports whether this was new
// information.
func (r *router) recordOK(chanID uint64, a lnwire.MilliSatoshi) bool {
	b := r.bel(chanID)
	learned := false
	if a > b.okAmt {
		b.okAmt = a
		learned = true
	}
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
		learned = true
	}
	return learned
}

// recordFail lowers the proven-bad bound on a channel. It reports whether
// this was new information.
func (r *router) recordFail(chanID uint64, a lnwire.MilliSatoshi) bool {
	b := r.bel(chanID)
	learned := false
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
		learned = true
	}
	b.fails++

	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	return learned
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	learned := false

	// Success: every hop carried its amount, so raise the lower bounds.
	if result.Failure == nil {
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			if r.recordOK(h.ChannelID, a) {
				learned = true
			}

			if i == 0 && h.ChannelID != 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		if learned {
			r.learnedAt = r.attempts
		}
		return nil
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// Everything strictly before the failing hop demonstrably worked.
	if failIdx > 0 {
		for i := 0; i < failIdx && i < len(rt.Hops); i++ {
			if r.recordOK(rt.Hops[i].ChannelID, hopAmount(rt, i)) {
				learned = true
			}
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		// Unattributable failure (e.g. an unknown source): the whole
		// route is suspect, so bound the likely bottleneck hops rather
		// than learning nothing at all.
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			b := r.bel(h.ChannelID)
			if b.okAmt >= a {
				continue
			}
			if i == 0 || a >= hopAmount(rt, 0)/2 {
				if r.recordFail(h.ChannelID, a) {
					learned = true
				}
			}
		}
		if learned {
			r.learnedAt = r.attempts
		}
		return nil
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)

	if r.recordFail(h.ChannelID, a) {
		learned = true
	}

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	if learned {
		r.learnedAt = r.attempts
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity.
//   - Per-directed-channel beliefs: hard lower-OK / upper-fail bounds
//     (no time decay: a stale bound costs one retry to refresh).
//   - Probability-aware Dijkstra: minimize fee + penalty/probability.
//   - JOINT route-set planning: plan a set of disjoint corridors up front
//     and size each shard to the max flow that corridor can bear, so
//     unequal parallel corridors each carry what they can.
//   - Lower-retry on failed channels rather than blacklisting, with a
//     bisection ladder between the proven-ok and proven-fail bounds.
//   - Attempt budget is spent per-payment, not per-batch: a payment that
//     cannot be covered gives up early instead of burning 200 attempts,
//     which is where the previous version lost its retry score.

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCost is the virtual cost (in msat) of one failed attempt,
	// used to trade fee against success probability.
	attemptCostBase = lnwire.MilliSatoshi(1_000)
	attemptCostPPM  = lnwire.MilliSatoshi(6_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// minShard is the smallest shard we will bother planning.
	minShard = lnwire.MilliSatoshi(1_000)

	// maxAttempts bounds the attempts we spend on a single payment. The
	// runner reuses one router per payment sequence, so this is tracked
	// against the current payment target/amount rather than the batch.
	maxAttempts = 46

	// stuckLimit is how many consecutive attempts may fail to teach us
	// anything new before we declare the payment hopeless.
	stuckLimit = 8
)

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount proven to pass.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount proven to fail; zero means unknown.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// fails counts how many times this direction has refused us. Repeated
	// refusals mean the channel is drained, not merely tight.
	fails int
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	p := 0.30*low + 0.70*cliff
	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[uint64]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// attempts counts attempts issued for the current payment.
	attempts int

	// stuck counts consecutive attempts that taught us nothing new.
	stuck int

	// learned is set whenever a report tightens a belief bound.
	learned bool

	// curAmt is the remaining amount the current payment run started at,
	// used to detect that a new payment began (remaining went up).
	curAmt lnwire.MilliSatoshi

	// settled is the total we have delivered for the current payment.
	settled lnwire.MilliSatoshi

	// planQueue holds shard amounts from a joint plan that we have
	// committed to but not yet handed out.
	planQueue []lnwire.MilliSatoshi

	// planFor is the remaining amount the planQueue was built for; if the
	// remaining amount moves away from it the plan is discarded.
	planFor lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		localBalances: localBalances,
		beliefs:       make(map[uint64]*belief),
		pending:       make(map[uint64]*route.Route),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				if e.from == source {
					r.localEdges = append(r.localEdges, e)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(chanID uint64) *belief {
	b, ok := r.beliefs[chanID]
	if !ok {
		b = &belief{}
		r.beliefs[chanID] = b
	}
	return b
}

// retryCap is the largest amount we are still willing to push over a
// channel that has refused us, bisecting between the proven bounds. After
// several refusals we stop coming back at all.
func retryCap(b *belief) (lnwire.MilliSatoshi, bool) {
	if !b.hasFail || b.failAmt == 0 {
		return 0, false
	}
	if b.fails >= 3 {
		// Thoroughly drained: only tiny amounts remain plausible.
		if b.okAmt > 0 {
			return b.okAmt, true
		}
		return 0, true
	}

	lim := b.failAmt - 1
	if b.okAmt > 0 && b.okAmt < lim {
		lim = b.okAmt + (lim-b.okAmt)/2
	} else {
		// No proven-good floor: bimodal liquidity means the channel is
		// probably empty in this direction, so drop hard rather than
		// shaving a quarter off.
		lim = b.failAmt / 3
	}
	return lim, true
}

// avail is the amount we still consider spendable over this edge, taking
// our own in-flight HTLCs and local balance into account. It returns zero
// when the edge is unusable at any amount.
func (r *router) avail(e *edge) lnwire.MilliSatoshi {
	cap := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < cap {
		cap = e.maxHTLC
	}

	b := r.beliefs[e.chanID]
	if b != nil {
		if lim, ok := retryCap(b); ok && lim < cap {
			cap = lim
		}
		if b.inFlight >= cap {
			return 0
		}
		cap -= b.inFlight
	}

	if e.from == r.source {
		bal := r.localBalances[e.chanID]
		if bal < cap {
			cap = bal
		}
	}

	return cap
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	// Our own channels have exactly known balances.
	if e.from == r.source {
		b := r.beliefs[e.chanID]
		used := lnwire.MilliSatoshi(0)
		if b != nil {
			used = b.inFlight
		}
		if r.localBalances[e.chanID] >= amt+used {
			return knownProb
		}
		return 0
	}

	b := r.beliefs[e.chanID]
	if b == nil {
		return bimodalPrior(amt, e.capacity)
	}

	eff := amt + b.inFlight

	if b.okAmt >= eff {
		return knownProb
	}
	if b.hasFail && eff >= b.failAmt {
		return minProb / 2
	}

	p := bimodalPrior(eff, e.capacity)

	// Narrow with the bounds we do have: known-good below and known-bad
	// above compress the uncertain interval.
	if b.okAmt > 0 && b.hasFail {
		lo := float64(b.okAmt)
		hi := float64(b.failAmt)
		if hi > lo {
			frac := (float64(eff) - lo) / (hi - lo)
			bracket := 1 - frac
			p = 0.5*p + 0.5*bracket
		}
	} else if b.okAmt > 0 {
		// A prior success raises confidence for nearby amounts.
		ratio := float64(eff) / float64(b.okAmt)
		boost := math.Exp(-(ratio - 1) * 1.1)
		p = 0.45*p + 0.55*boost
	} else if b.hasFail {
		// A prior failure at failAmt: everything meaningfully below it
		// is still plausible, but discount. Repeated failures on the
		// same direction discount harder.
		frac := float64(eff) / float64(b.failAmt)
		pen := 0.85 + 0.05*float64(b.fails)
		if pen > 0.97 {
			pen = 0.97
		}
		p = p * (1 - pen*frac)
	}

	if p > maxProb {
		p = maxProb
	}
	if p < minProb {
		p = minProb
	}
	return p
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	// dist is the combined cost used for ordering.
	dist float64
	// amt is the amount that must arrive at node.
	amt lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	cltv    uint32
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	amt     lnwire.MilliSatoshi
	logProb float64
	dist    float64
	via     *edge
	hops    int
	cltv    uint32
}

// findRoute runs a probability-weighted backward Dijkstra. The cost of a
// path is its fee plus an attempt-cost term divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused (already carrying a shard
// of this payment along a chosen route set).
func (r *router) findRoute(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase +
		amt*attemptCostPPM/1_000_000)

	best := make(map[route.Vertex]*pathState)

	target := r.spec.Target
	best[target] = &pathState{
		amt:     amt,
		logProb: 0,
		dist:    0,
		hops:    0,
		cltv:    finalCltvDelta,
	}

	q := &pq{}
	heap.Push(q, &pqItem{
		node: target, dist: 0, amt: amt, logProb: 0,
		hops: 0, cltv: finalCltvDelta,
	})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] {
				continue
			}
			if e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.avail(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			var sending lnwire.MilliSatoshi
			if e.from == r.source {
				sending = amtOver
			} else {
				sending = amtOver + e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-3 {
				continue
			}

			fee := float64(sending) - float64(amt)

			// Risk-adjusted cost: expected fee plus expected retry
			// cost. A small per-hop term discourages long paths.
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*250

			prev, ok := best[e.from]
			if ok && dist >= prev.dist-1e-9 {
				continue
			}

			best[e.from] = &pathState{
				amt:     sending,
				logProb: logProb,
				dist:    dist,
				via:     e,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
				cltv:    it.cltv + uint32(e.cltv),
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, best)
	if err != nil {
		return nil, 0, err
	}

	return rt, math.Exp(src.logProb), nil
}

// buildRoute materializes the route from the next-pointer map.
func (r *router) buildRoute(amt lnwire.MilliSatoshi,
	best map[route.Vertex]*pathState) (*route.Route, error) {

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// --- Joint route-set planning ---------------------------------------------

// maxSendable finds the largest amount, by binary search, for which a route
// exists avoiding the given channels. It returns 0 when even the smallest
// probe is unroutable.
func (r *router) maxSendable(hi lnwire.MilliSatoshi,
	avoid map[uint64]bool) lnwire.MilliSatoshi {

	if hi < minShard {
		return 0
	}
	if _, _, err := r.findRoute(hi, avoid); err == nil {
		return hi
	}

	lo := lnwire.MilliSatoshi(0)
	for i := 0; i < 12 && hi-lo > hi/32+1; i++ {
		mid := lo + (hi-lo)/2
		if mid < minShard {
			break
		}
		if _, _, err := r.findRoute(mid, avoid); err == nil {
			lo = mid
		} else {
			hi = mid
		}
	}
	if lo < minShard {
		return 0
	}
	return lo
}

// planShards builds a joint route set for the remaining amount: it greedily
// carves the largest shard each disjoint corridor can bear until the amount
// is covered or we run out of parts/corridors. The returned amounts sum to
// at most remaining; an empty result means we could not cover it and the
// caller should fall back to a single best-effort shard.
func (r *router) planShards(remaining lnwire.MilliSatoshi,
	partsLeft uint32, busy map[uint64]bool) []lnwire.MilliSatoshi {

	if partsLeft == 0 {
		return nil
	}

	// Corridors chosen so far must not be reused by later shards, so
	// unequal parallel corridors each carry what they can bear.
	avoid := make(map[uint64]bool, len(busy)+8)
	for k := range busy {
		avoid[k] = true
	}

	var out []lnwire.MilliSatoshi
	left := remaining

	for k := uint32(0); k < partsLeft && left >= minShard; k++ {
		amt := r.maxSendable(left, avoid)
		if amt == 0 {
			break
		}

		rt, _, err := r.findRoute(amt, avoid)
		if err != nil {
			break
		}

		out = append(out, amt)
		left -= amt

		// Reserve this corridor's hops so the next shard looks
		// elsewhere and the two do not contend for one bottleneck.
		for _, h := range rt.Hops {
			avoid[h.ChannelID] = true
		}
	}

	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs, so
// a new shard is planned over a genuinely disjoint corridor where possible.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// firstHopBudget returns the total liquidity we believe is reachable out of
// our own channels, which upper-bounds any single payment.
func (r *router) firstHopBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.avail(e)
	}
	return total
}

// candidateAmounts builds a descending ladder of shard sizes to try for a
// remaining amount, used as a fallback when joint planning comes up empty.
func (r *router) candidateAmounts(remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft == 0 {
		partsLeft = 1
	}

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > remaining || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(remaining)

	// Even splits over all part counts we could still afford.
	for k := uint32(2); k <= partsLeft && k <= 12; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric ladder for finer probing when even splits all fail.
	cur := remaining
	for i := 0; i < 10; i++ {
		cur = cur * 2 / 3
		if cur < minShard {
			break
		}
		add(cur)
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })

	if len(out) > 14 {
		out = out[:14]
	}
	return out
}

// startPayment resets the per-payment budget when the runner moves on to a
// new payment. The remaining amount only ever shrinks within one payment,
// so a jump upward (or the very first call) marks a fresh one.
func (r *router) startPayment(amt lnwire.MilliSatoshi) {
	r.attempts = 0
	r.stuck = 0
	r.curAmt = amt
	r.settled = 0
	r.planQueue = nil
	r.planFor = 0

	// Old in-flight bookkeeping cannot belong to the new payment.
	r.pending = make(map[uint64]*route.Route)
	for _, b := range r.beliefs {
		b.inFlight = 0
	}
}

// RequestRoute plans the next shard. It first tries to satisfy the whole
// remaining amount over one route; failing that it plans a joint route set
// whose shard sizes come from each corridor's actual carrying capacity.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	// Detect a new payment: within one payment the remaining amount never
	// grows, so an increase means the runner started a fresh one.
	if amt > r.curAmt || r.curAmt == 0 {
		r.startPayment(amt)
	}

	r.attempts++
	if r.attempts > maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.stuck > stuckLimit {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Drop a stale plan if the remaining amount no longer matches what it
	// was built for.
	if r.planFor != amt {
		r.planQueue = nil
		r.planFor = 0
	}

	// Serve a committed plan entry first.
	for len(r.planQueue) > 0 {
		a := r.planQueue[0]
		r.planQueue = r.planQueue[1:]
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		if rt, _, err := r.findRoute(a, busy); err == nil {
			return rt, nil
		}
		if rt, _, err := r.findRoute(a, nil); err == nil {
			return rt, nil
		}
	}
	r.planQueue = nil
	r.planFor = 0

	// A shard can never exceed what our own channels can push right now.
	budget := r.firstHopBudget()
	target := amt
	if budget > 0 && budget < target {
		target = budget
	}
	if target < minShard {
		target = amt
	}

	// Fast path: the whole remaining amount over one good route.
	if target == amt {
		if rt, p, err := r.findRoute(target, busy); err == nil &&
			p > 0.5 {

			return rt, nil
		}
	}

	// Joint planning: size shards to corridors instead of halving.
	if partsLeft > 1 {
		plan := r.planShards(target, partsLeft, busy)
		if len(plan) > 0 {
			// Largest shard first: it is the one most likely to be
			// invalidated by drift, so probe it while our belief
			// is freshest.
			sort.Slice(plan, func(i, j int) bool {
				return plan[i] > plan[j]
			})
			first := plan[0]
			rest := plan[1:]

			// Only keep a queue that still adds up to the rest of
			// the payment; otherwise re-plan next call with fresh
			// evidence.
			var sum lnwire.MilliSatoshi
			for _, a := range rest {
				sum += a
			}
			if first+sum >= amt {
				r.planQueue = rest
				r.planFor = amt - first
			}

			if rt, _, err := r.findRoute(first, busy); err == nil {
				return rt, nil
			}
			if rt, _, err := r.findRoute(first, nil); err == nil {
				return rt, nil
			}
			r.planQueue = nil
			r.planFor = 0
		}
	}

	// Fallback: descend a ladder of amounts, scoring each by expected
	// delivered value net of fee.
	type plan struct {
		rt    *route.Route
		score float64
	}
	var bestPlan *plan

	ladder := r.candidateAmounts(target, partsLeft)

	for pass := 0; pass < 2; pass++ {
		avoid := busy
		if pass == 1 {
			avoid = nil
		}
		if pass == 0 && len(busy) == 0 {
			continue
		}

		tried := 0
		for _, a := range ladder {
			rt, p, err := r.findRoute(a, avoid)
			if err != nil {
				continue
			}
			tried++

			fee := float64(rt.TotalAmount) - float64(a)
			score := p*float64(a) - fee*0.5
			if a == amt {
				score *= 1.15
			}

			if bestPlan == nil || score > bestPlan.score {
				bestPlan = &plan{rt: rt, score: score}
			}

			if a == amt && p > 0.65 {
				break
			}
			if tried >= 6 {
				break
			}
		}

		if bestPlan != nil {
			break
		}
	}

	if bestPlan == nil {
		// Last resort: probe for whatever amount is routable at all,
		// so a depleted corridor still yields progress rather than a
		// terminal give-up.
		if a := r.maxSendable(target, nil); a >= minShard {
			if rt, _, err := r.findRoute(a, nil); err == nil {
				return rt, nil
			}
		}

		return nil, errors.New("no route available")
	}

	return bestPlan.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(h.ChannelID)
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// recordOK raises the proven-good bound on a channel and clears any stale
// failure bound at or below that amount.
func (r *router) recordOK(chanID uint64, a lnwire.MilliSatoshi) {
	b := r.bel(chanID)
	if a > b.okAmt {
		b.okAmt = a
		r.learned = true
	}
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
		r.learned = true
	}
}

// recordFail lowers the proven-fail bound on a channel.
func (r *router) recordFail(chanID uint64, a lnwire.MilliSatoshi) {
	b := r.bel(chanID)
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
		r.learned = true
	}
	b.fails++

	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	r.learned = false

	// Success: every hop carried its amount, so raise the lower bounds.
	if result.Failure == nil {
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.recordOK(h.ChannelID, a)

			if i == 0 && h.ChannelID != 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		r.stuck = 0
		if len(rt.Hops) > 0 {
			r.settled += rt.Hops[len(rt.Hops)-1].AmtToForward
		}
		return nil
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// Everything strictly before the failing hop demonstrably worked.
	if failIdx > 0 {
		for i := 0; i < failIdx && i < len(rt.Hops); i++ {
			r.recordOK(rt.Hops[i].ChannelID, hopAmount(rt, i))
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		// Unattributable failure (e.g. an unknown source): the whole
		// route is suspect, so bound the likely bottleneck rather than
		// learning nothing at all.
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			b := r.bel(h.ChannelID)
			if b.okAmt >= a {
				continue
			}
			if i == 0 || a >= hopAmount(rt, 0)/2 {
				r.recordFail(h.ChannelID, a)
			}
		}
		if r.learned {
			r.stuck = 0
		} else {
			r.stuck++
		}
		return nil
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	r.recordFail(h.ChannelID, a)

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	if r.learned {
		r.stuck = 0
	} else {
		r.stuck++
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - BIMODAL OPTIMISM after a proven forward: a channel that has forwarded
//     for us is treated as holding the bulk of its capacity (minus what we
//     drained), so later larger payments reuse a proven corridor.
//   - JOINT ROUTE-SET PLANNING (the main change in this revision): instead of
//     planning one shard and discovering the split by failing, we build a
//     min-cost-flow style plan over several DISJOINT corridors up front,
//     sizing each shard to that corridor's believed bottleneck, and we
//     RESERVE the plan so all its shards are handed out in sequence. Large
//     payments that no single corridor can carry (the observed failure mode:
//     ~860M and ~1041M msat payments dying with "no route found" after a
//     dozen single-corridor probes) are now attacked as a flow problem from
//     the very first attempt whenever the amount exceeds what one corridor
//     is believed able to bear.
//   - FLOW FEASIBILITY over local channels: a shard is never larger than the
//     single local channel that must carry it, and the planner spreads over
//     distinct local channels first, which is where the real bottleneck sits.
//   - Depth-aware lower retries: how far below a proven failure we retry
//     depends on how depleted the direction looks.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the local
//     policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 70
	maxFailStreak = 24

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.12

	// flowSlices bounds how many corridors a joint plan may use beyond the
	// part budget, so planning stays cheap.
	flowSlices = 12
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity earmarked for shards of the current joint plan
	// that have not been handed out yet, so sibling shards of one plan do
	// not double-book the same corridor.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is the liquidity of a directed channel already spoken for, by
// in-flight HTLCs and by unserved shards of the current joint plan.
func (b *belief) committed() lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if used := b.committed(); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	eff := amt + b.committed()

	misses := 0
	if b != nil {
		misses = b.misses
	}

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// maxLocalHop is the largest amount any single local channel can still send.
// No single shard can exceed this, because every shard leaves through exactly
// one of our channels.
func (r *router) maxLocalHop() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// hardBottleneck is the corridor's bound from hard evidence only, used as a
// ceiling when re-pricing a corridor.
func (r *router) hardBottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.availCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// reserve books (or releases) a plan's liquidity against the beliefs so that
// sibling shards of the same joint plan cannot double-spend a corridor.
func (r *router) reserve(pl *plan, sign int) {
	if pl == nil || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(pl.rt, i)
		if sign > 0 {
			b.reserved += a
		} else if b.reserved >= a {
			b.reserved -= a
		} else {
			b.reserved = 0
		}
	}
}

// clearQueue drops every queued shard and releases its reservations.
func (r *router) clearQueue() {
	for _, pl := range r.queued {
		r.reserve(pl, -1)
	}
	r.queued = nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 7 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
//
// Reservations are taken as each slice is chosen, so the next slice's
// Dijkstra already sees the liquidity consumed by its siblings even where
// corridors share a downstream hop that is not fully excluded.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	slices := int(partsLeft)
	if slices > flowSlices {
		slices = flowSlices
	}

	var out []*plan
	left := remaining

	for k := 0; k < slices; k++ {
		if left < minShard {
			break
		}

		path := r.findAnyPath(left, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if hb := r.hardBottleneck(path); hb < amtS {
			amtS = hb
		}
		if amtS < minShard {
			break
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			break
		}

		out = append(out, pl)

		// Book this slice so siblings see the liquidity as taken, and
		// keep the first local hop exclusive: every shard leaves
		// through one of our channels and we want them spread.
		r.reserve(pl, +1)
		avoid[path[0].chanID] = true

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	// Release everything; the caller re-books whatever it decides to keep
	// queued, and the shard it serves immediately becomes in-flight.
	for _, pl := range out {
		r.reserve(pl, -1)
	}

	return out
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan; otherwise, when the remaining amount exceeds
// what a single local channel could ever carry, it plans a joint route set
// straight away, and only falls back to single-corridor search when one
// corridor plausibly covers the whole remainder.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.reserve(pl, -1)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.clearQueue()
			break
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what one of our own channels can push.
	hi := amt
	if one := r.maxLocalHop(); one > 0 && one < hi {
		hi = one
	}
	if hi < minShard {
		hi = amt
	}

	// When a single corridor cannot plausibly cover the remainder, go
	// straight to joint flow planning: that is where large payments live,
	// and probing one corridor at a time just burns attempts.
	flowFirst := partsLeft > 1 && hi < amt

	var best *plan

	if flowFirst {
		if flow := r.planFlow(amt, partsLeft, busy); len(flow) > 0 {
			best = flow[0]
			r.queued = flow[1:]
			for _, pl := range r.queued {
				r.reserve(pl, +1)
			}
		}
	}

	if best == nil {
		ladder := r.ladder(hi, amt, partsLeft)

		// First pass prefers corridors disjoint from in-flight shards
		// so parallel parts do not fight over the same liquidity.
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}

			probes := 0
			for _, a := range ladder {
				// Once we hold a solid plan, digging far below
				// it only wastes attempts and parts.
				if best != nil && best.prob >= 0.6 &&
					a < best.amt/2 {

					break
				}
				if probes >= probeBudget {
					break
				}

				path, err := r.findPath(a, avoid)
				probes++
				if err != nil {
					continue
				}

				best = r.evalPath(path, a, amt, best)

				// A confident full-amount plan needs nothing
				// more.
				if best != nil && best.amt >= amt &&
					best.prob > 0.8 {

					break
				}
			}

			if best != nil {
				break
			}
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly.
	if !flowFirst && partsLeft > 1 && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			var total lnwire.MilliSatoshi
			for _, pl := range flow {
				total += pl.amt
			}

			first := flow[0]
			better := best == nil ||
				(total > best.amt &&
					first.score > best.score*0.8)

			if better {
				r.clearQueue()
				r.queued = flow[1:]
				for _, pl := range r.queued {
					r.reserve(pl, +1)
				}
				best = first
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	rb.succ = true
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Beliefs just changed, so any queued joint plan is stale.
	r.clearQueue()

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - Probability-aware backward Dijkstra: minimize fee plus an attempt
//     cost divided by the path's success probability.
//   - Joint shard sizing: every corridor we discover is re-priced at the
//     amount that corridor can actually bear (its belief bottleneck), so
//     unequal parallel corridors each carry a shard sized to fit instead
//     of a blind half of the remainder.
//   - Attempt economy (the main change in this revision): success rate was
//     already saturated, so the remaining score comes from spending fewer
//     attempts. Three mechanisms buy that:
//       1. A per-corridor "probe" ladder that walks DOWN through the
//          believed bottleneck instead of blind halves, so the first
//          attempt on a fresh corridor is already sized to what the
//          evidence supports.
//       2. Optimistic pre-pruning: a hop whose believed success at the
//          requested amount is under a floor is skipped by Dijkstra
//          entirely rather than attempted and learned from, so we do not
//          pay an attempt for information the prior already gives us.
//       3. A first-attempt preference for larger shards: since each shard
//          costs at least one attempt, delivering the remainder in one
//          piece is worth a real bonus, and only after a failure do we
//          start carving.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// is deliberately large relative to fees.
	attemptCostBase = lnwire.MilliSatoshi(3_000)
	attemptCostPPM  = lnwire.MilliSatoshi(20_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// pruneProb is the per-hop probability below which we refuse to build
	// a route through a hop at all. Under a bimodal distribution a hop
	// this unlikely almost never pays for the attempt it costs.
	pruneProb = 0.06

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 60
	maxFailStreak = 18

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 12

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.010

	// wholeBonus rewards a plan that finishes the remaining amount in a
	// single shard, because every extra shard costs at least one attempt.
	wholeBonus = 1.30

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear. Under a bimodal distribution this
	// sits comfortably on the plausible side of the cliff.
	priorSafeNum = 35
	priorSafeDen = 100

	// lowerRetryNum/lowerRetryDen is the fraction of a proven failure
	// amount we are still willing to retry.
	lowerRetryNum = 3
	lowerRetryDen = 4
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount proven to pass.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount proven to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int

	// shardFails counts liquidity failures seen for the payment currently
	// being planned. While it is zero we bias hard toward a single shard,
	// since splitting speculatively costs attempts we may not need.
	shardFails int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		lim := b.failAmt * lowerRetryNum / lowerRetryDen
		if lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.hasFail {
			lim := b.failAmt * lowerRetryNum / lowerRetryDen
			if est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Everything meaningfully below a proven failure is
			// still plausible, but discounted.
			frac := float64(eff) / float64(b.failAmt)
			p = p * (1 - 0.85*frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity. floor is the per-hop probability below
// which a hop is pruned outright: attempting a hop we already believe is
// hopeless burns an attempt to learn what the prior already told us.
func (r *router) findPath(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	floor float64) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.15

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 || p < floor {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
//
// Before the first liquidity failure of a payment the ladder stays coarse
// and top-heavy: probing small shards speculatively costs attempts, and an
// unsplit payment is the cheapest outcome available.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	if r.shardFails == 0 && hi >= remaining {
		// Nothing has failed yet and we can afford the whole thing:
		// offer only a couple of coarse fallbacks so the very first
		// attempt of a payment is the full amount.
		add(remaining * 3 / 4)
		add(remaining / 2)
		sort.Slice(out, func(i, j int) bool {
			return out[i] > out[j]
		})
		return out
	}

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: proven-good amounts and just under proven
	// failure points.
	for _, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail && b.failAmt >= minShard {
			add(b.failAmt * lowerRetryNum / lowerRetryDen)
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= wholeBonus
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount, at the amount the
// corridor is believed able to bear, and at a short descent below that,
// keeping the best of them. Re-pricing an already-discovered corridor is
// free, so this is where we spend search effort instead of on extra
// Dijkstra runs, which are the expensive part.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}

	bn := r.bottleneck(path)
	if bn > remaining {
		bn = remaining
	}
	if bn >= minShard && bn != a {
		cands = append(cands, bn)
	}

	// A short descent below the corridor's believed bottleneck. This is
	// the cheap way to find a shard that fits: each extra candidate is a
	// pricing pass, not a new path search.
	if r.shardFails > 0 && bn >= minShard {
		cur := bn
		for i := 0; i < 3; i++ {
			cur = cur * 5 / 8
			if cur < minShard {
				break
			}
			cands = append(cands, cur)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{rt: rt, score: s, amt: c, prob: p}
		}
	}

	return best
}

// RequestRoute plans the next shard. It searches jointly over shard amount
// and corridor: for every candidate amount (largest first) it finds the
// best risk-adjusted path, then re-prices that path at the amount its
// weakest hop can bear, and returns the highest scoring combination.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	busy := r.inFlightChans()
	ladder := r.ladder(hi, amt, partsLeft)

	// Two prune floors: first insist on hops we genuinely believe in, and
	// only if that finds nothing at all do we relax and consider the
	// long shots. Most payments never need the second pass, so the
	// optimistic floor costs nothing and saves the attempts we would
	// otherwise burn on hops the prior already condemned.
	floors := []float64{pruneProb, 0}

	var best *plan

	for _, floor := range floors {
		// First sub-pass prefers corridors disjoint from in-flight
		// shards so parallel parts do not fight over the same
		// liquidity.
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}

			probes := 0
			for _, a := range ladder {
				// Once we hold a solid plan, digging far below
				// it only wastes attempts and parts.
				if best != nil && best.prob >= 0.6 &&
					a < best.amt/2 {

					break
				}
				if probes >= probeBudget {
					break
				}

				path, err := r.findPath(a, avoid, floor)
				probes++
				if err != nil {
					continue
				}

				best = r.evalPath(path, a, amt, best)

				// A confident full-amount plan needs no
				// alternatives.
				if best != nil && best.amt >= amt &&
					best.prob > 0.75 {

					break
				}
			}

			if best != nil {
				break
			}
		}

		if best != nil {
			break
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount, so raise the lower bounds.
	if result.Failure == nil {
		r.failStreak = 0
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.provePassed(h, a)

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settled shard closes out this payment's split state: the
		// next payment starts optimistic about single-shard delivery
		// again.
		r.shardFails = 0

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		r.shardFails++
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time.
		// A policy repair is not a liquidity miss, so it must not
		// count against the fail streak or push us toward splitting.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		r.failStreak--
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		r.failStreak--
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		r.failStreak--
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction. From now
	// on this payment is allowed to plan genuine splits.
	r.shardFails++

	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - Probability-aware backward Dijkstra: minimize fee plus an attempt
//     cost divided by the path's success probability.
//   - Joint shard sizing: every corridor we discover is re-priced at the
//     amount that corridor can actually bear (its belief bottleneck), so
//     unequal parallel corridors each carry a shard sized to fit.
//   - Corridor repulsion: successive probes within one RequestRoute pass
//     are pushed off channels we already priced, so the ladder surfaces
//     structurally different routes instead of re-pricing one corridor.
//   - Aggressive small-shard fallback: when the big amounts have all been
//     refuted, we keep descending instead of terminally giving up.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view and do not count against the fail streak.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// is deliberately large relative to fees.
	attemptCostBase = lnwire.MilliSatoshi(2_000)
	attemptCostPPM  = lnwire.MilliSatoshi(12_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. Both are generous: a terminal give
	// up loses a whole payment, which dwarfs the retry penalty.
	maxAttempts   = 120
	maxFailStreak = 40

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 16

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 3.0
	partCost  = 0.0025

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear. Under a bimodal distribution this
	// sits comfortably on the plausible side of the cliff.
	priorSafeNum = 38
	priorSafeDen = 100

	// lowerRetryNum/lowerRetryDen is the fraction of a proven failure
	// amount we are still willing to retry.
	lowerRetryNum = 1
	lowerRetryDen = 2
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount proven to pass.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount proven to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int

	// deliveredParts counts shards of the current payment that settled.
	deliveredParts int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry well below the proven failure point rather than
		// blacklisting the channel outright. Under a bimodal
		// distribution a failure at a means the direction is mostly
		// drained, so the surviving window is small.
		lim := b.failAmt * lowerRetryNum / lowerRetryDen
		if b.okAmt > lim {
			lim = b.okAmt
		}
		if lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.hasFail {
			lim := b.failAmt * lowerRetryNum / lowerRetryDen
			if b.okAmt > lim {
				lim = b.okAmt
			}
			if est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under a bimodal distribution a failure means the
			// direction is mostly drained: only meaningfully
			// smaller amounts stay plausible.
			frac := float64(eff) / float64(b.failAmt)
			p = p * math.Max(0, 1-1.05*frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity. penal names channels that are merely
// discouraged (they belong to a corridor we already planned this pass), so
// the search returns genuinely different corridors instead of the same one.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool, penal map[uint64]int) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.12

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			// Soft repulsion from already-planned corridors.
			if n := penal[e.chanID]; n > 0 {
				dist += attemptCost * 0.9 * float64(n)
			}

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// maxLocalHop is the largest amount any single one of our own channels can
// still push. No single shard can exceed it.
func (r *router) maxLocalHop() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, e := range r.localEdges {
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford. Allowing a
	// deep split matters: many corridors of modest capacity beat one big
	// corridor that does not exist.
	maxK := partsLeft
	if maxK > 16 {
		maxK = 16
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// A finer geometric descent than plain halving: the 3/4 rungs let us
	// find the true edge of a corridor without wasting a full octave.
	cur := hi
	floor := hi / 8192
	if floor < minShard {
		floor = minShard
	}
	for i := 0; i < 26 && cur >= floor; i++ {
		add(cur)
		add(cur * 3 / 4)
		cur = cur / 2
	}

	// Evidence-derived sizes: proven-good amounts and just under proven
	// failure points.
	for _, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail && b.failAmt >= minShard {
			add(b.failAmt * lowerRetryNum / lowerRetryDen)
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
	path  []*edge
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
		// Also probe just under the bottleneck: the belief estimate is
		// only an estimate, and a slightly smaller shard on a corridor
		// we already like beats a whole new Dijkstra run.
		if h := g * 3 / 4; h >= minShard && h != a {
			cands = append(cands, h)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				rt: rt, score: s, amt: c, prob: p, path: path,
			}
		}
	}

	return best
}

// RequestRoute plans the next shard. It searches jointly over shard amount
// and corridor: for every candidate amount (largest first) it finds the
// best risk-adjusted path, then re-prices that path at the amount its
// weakest hop can bear, and returns the highest scoring combination.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	// A shard can never exceed what a single one of our own channels can
	// push, since every shard leaves over exactly one local channel.
	hi := amt
	if single := r.maxLocalHop(); single > 0 && single < hi {
		hi = single
	}
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	busy := r.inFlightChans()
	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		// penal discourages corridors we already priced this pass, so
		// successive probes explore structurally different routes.
		penal := make(map[uint64]int)

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.65 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid, penal)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// Discourage this corridor's hops on the next probe so
			// we surface an alternative rather than re-pricing the
			// same one at every rung of the ladder.
			for _, e := range path {
				penal[e.chanID]++
			}

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// Last resort: if the structured search found nothing, walk the
	// ladder with no repulsion and no belief-derived resizing, taking the
	// first route that prices at all. Terminally giving up loses a whole
	// payment, so almost any attempt is worth more than "no route".
	if best == nil {
		for _, a := range ladder {
			path, err := r.findPath(a, nil, nil)
			if err != nil {
				continue
			}
			if r.failedSigs[planSig(path, a)] {
				continue
			}
			rt, p, err := r.makeRoute(path, a)
			if err != nil {
				continue
			}
			best = &plan{rt: rt, amt: a, prob: p, path: path}
			break
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
	b.dead = false
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount, so raise the lower bounds.
	if result.Failure == nil {
		r.failStreak = 0
		r.deliveredParts++

		// A settled shard means the payment is partially committed and
		// the remainder is worth extra persistence.
		if r.attempts > maxAttempts/2 {
			r.attempts = maxAttempts / 2
		}

		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.provePassed(h, a)

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// policy repair is not a liquidity miss, so it must not count
		// against the fail streak.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		r.failStreak--
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		r.failStreak--
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		r.failStreak--
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - BIMODAL OPTIMISM after a proven forward: a channel that has forwarded
//     for us is treated as holding the bulk of its capacity (minus what we
//     drained), which lets later, larger payments reuse a proven corridor.
//   - Depth-aware lower retries: how far below a proven failure we retry
//     depends on how depleted the direction looks.
//   - JOINT ROUTE-SET PLANNING with a real max-flow style budget: before
//     handing out any shard for a large payment we compute the believed
//     deliverable flow over disjoint corridors. If the whole remainder can
//     only be covered by K shards, all K are planned up front and queued,
//     each sized to its own corridor's bottleneck.
//   - LOCAL-CHANNEL FLOW CAP: no shard may exceed the largest single local
//     channel balance, since a shard leaves through exactly one first hop;
//     the planner spreads shards across DIFFERENT first hops so a payment
//     larger than any single local channel is decomposed instead of retried.
//   - PROGRESSIVE SALVAGE: when a payment cannot be covered by the believed
//     flow, we deliberately deliver what we can (largest feasible shard)
//     rather than giving up, because each settled shard reduces the
//     remainder and refreshes evidence for the next round.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 80
	maxFailStreak = 26

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the corridors a single flow decomposition walks.
	flowRounds = 12
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds the whole payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// maxLocalEdge is the largest single local channel balance still free, which
// is the true ceiling on one shard: no shard can leave through two local
// channels at once.
func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, exact local channel balances, and
// evidence-derived sizes just below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Local channel balances are exact knowledge, and a shard sized to a
	// local channel is exactly what a fan-out split wants.
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= minShard {
			add(c - c/200)
		}
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies. Maximizing p*amt is
// exactly maximizing delivered value per attempt.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 7 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
//
// It keeps going until either the whole remainder is covered or no further
// disjoint corridor exists, and it caps each shard at the largest single
// local channel so a shard is never planned larger than one first hop can
// carry.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	single := r.maxLocalEdge()

	var out []*plan
	left := remaining

	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if single > 0 && want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			// The corridor cannot bear anything novel, so retire
			// its first hop and move on instead of aborting the
			// whole decomposition.
			avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// flowTotal is the amount a plan set delivers in aggregate.
func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor: for every candidate amount (largest first) it finds the best
// risk-adjusted path, re-prices that path at the amount its weakest hop can
// bear, and finally checks whether a deliberate multi-corridor split would
// cover more of the remaining amount than the best single shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			break
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		r.attempts++
		return rt, nil
	}

	// A single shard can never exceed what one local channel can push,
	// since a shard leaves through exactly one first hop.
	hi := amt
	if single := r.maxLocalEdge(); single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly. We
	// compare the aggregate believed flow of the plan set against the best
	// single shard: covering more of the payment beats a slightly nicer
	// first hop, because every uncovered millisat is a failed payment.
	if partsLeft > 1 && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total := flowTotal(flow)
			first := flow[0]

			if best == nil || total > best.amt {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	// Last resort: deliver whatever we can. Even a small settled shard
	// reduces the remainder and refreshes evidence, which is strictly
	// better than terminally giving up on the payment.
	if best == nil {
		best = r.salvage(amt, partsLeft, busy)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// salvage hunts for any novel attempt at all, walking a wide descending
// amount ladder over both the disjoint and the unrestricted graph. It is the
// difference between delivering part of a payment and abandoning it.
func (r *router) salvage(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *plan {

	if partsLeft <= 1 {
		// Without parts left, only a full-amount attempt helps.
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		if r.failedSigs[planSig(path, remaining)] {
			return nil
		}
		rt, p, err := r.makeRoute(path, remaining)
		if err != nil {
			return nil
		}
		return &plan{path: path, rt: rt, amt: remaining, prob: p}
	}

	a := remaining
	for i := 0; i < 22 && a >= minShard; i++ {
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.findPath(a, avoid)
			if err != nil {
				continue
			}
			if pl := r.bestOnPath(path, a, remaining); pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Beliefs just changed, so any queued joint plan is stale.
	r.queued = nil

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - JOINT ROUTE-SET PLANNING: for a large payment we compute a believed
//     max-flow decomposition over DISJOINT corridors up front, each shard
//     sized to its own corridor's bottleneck, and queue the whole set.
//   - COMMITTED PLANS: the queued plan set survives a shard failure. Only
//     the queued shards whose corridor overlaps the failed route are
//     dropped, and a shard that no longer prices up is re-planned in place
//     instead of throwing away the whole decomposition, which is what
//     previously burned dozens of attempts on big payments.
//   - GLOBAL SHARD FLOOR: once the remaining amount cannot plausibly be
//     covered, we stop grinding tiny shards and give up early rather than
//     spending the attempt budget on hopeless probes.
//   - PROGRESSIVE SALVAGE: when the believed flow cannot cover the payment,
//     we still deliver the largest feasible shard, because every settled
//     shard reduces the remainder and refreshes evidence.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view instead of being treated as liquidity misses, and
//     they do not count against the give-up streak.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. The streak limit is deliberately
	// tighter than before: a long run of failures with no settled shard
	// means the believed flow is simply not there, and every extra probe
	// costs retry efficiency without buying success.
	maxAttempts   = 44
	maxFailStreak = 14

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 10

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// shardFloorNum/shardFloorDen bound how small a shard may get relative
	// to the ORIGINAL payment: grinding a payment into more than a handful
	// of dust parts never completes within MaxParts, so it is wasted
	// effort.
	shardFloorNum = 1
	shardFloorDen = 24

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.12

	// flowRounds bounds the corridors a single flow decomposition walks.
	flowRounds = 12
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// planTotal is the delivered amount the current queued plan set was
	// designed to cover, used to decide whether the plan is still worth
	// following after a shard failure.
	planTotal lnwire.MilliSatoshi

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	// firstAmt is the size of the payment as first requested, which fixes
	// the global floor on how small a shard may be.
	firstAmt lnwire.MilliSatoshi

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// shardFloor is the smallest shard worth planning for the current payment.
// Splitting below this cannot finish inside the part budget, so it only
// burns attempts.
func (r *router) shardFloor() lnwire.MilliSatoshi {
	f := r.firstAmt * shardFloorNum / shardFloorDen
	if f < minShard {
		f = minShard
	}
	return f
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds the whole payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// maxLocalEdge is the largest single local channel balance still free, which
// is the true ceiling on one shard: no shard can leave through two local
// channels at once.
func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent, exact
// local channel balances, and evidence-derived sizes just below proven
// failure points. Everything below the global shard floor is dropped.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	floor := r.shardFloor()
	if floor > hi {
		floor = minShard
	}

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < floor || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent down to the floor.
	cur := hi
	for i := 0; i < 12; i++ {
		cur = cur * 2 / 3
		if cur < floor {
			break
		}
		add(cur)
	}

	// Local channel balances are exact knowledge, and a shard sized to a
	// local channel is exactly what a fan-out split wants.
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= floor {
			add(c - c/200)
		}
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= floor {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= floor {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies. Maximizing p*amt is
// exactly maximizing delivered value per attempt.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	floor := r.shardFloor()
	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= floor {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry. lo bounds how far down it will walk.
func (r *router) bestOnPath(path []*edge,
	hi, lo, remaining lnwire.MilliSatoshi) *plan {

	if lo < minShard {
		lo = minShard
	}
	a := hi
	for i := 0; i < 12 && a >= lo; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 6 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
//
// It caps each shard at the largest single local channel, since a shard
// leaves through exactly one first hop, and it never plans a shard below the
// global floor.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	single := r.maxLocalEdge()
	floor := r.shardFloor()

	var out []*plan
	left := remaining

	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if single > 0 && want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			// Retire this corridor's first hop and keep going: a
			// single dry corridor should not abort the whole
			// decomposition.
			avoid[path[0].chanID] = true
			continue
		}

		lo := floor
		if lo > amtS {
			lo = minShard
		}
		pl := r.bestOnPath(path, amtS, lo, remaining)
		if pl == nil {
			avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// flowTotal is the amount a plan set delivers in aggregate.
func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next still-valid shard of a committed plan set.
// A shard that no longer prices up is re-planned in place on its own
// corridor before being dropped, so one stale shard does not destroy the
// whole decomposition.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *plan {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if !r.failedSigs[planSig(pl.path, a)] {
			rt, p, err := r.makeRoute(pl.path, a)
			if err == nil && p >= queueMinProb {
				return &plan{
					path: pl.path, rt: rt, amt: a, prob: p,
				}
			}
		}

		// Re-plan this shard on its own corridor at a smaller amount
		// before giving up on it.
		lo := r.shardFloor()
		if lo > a {
			lo = minShard
		}
		if alt := r.bestOnPath(pl.path, a, lo, amt); alt != nil &&
			alt.prob >= queueMinProb {

			return alt
		}
	}
	return nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a committed joint route-set plan, then searches jointly over shard
// amount and corridor: for every candidate amount (largest first) it finds
// the best risk-adjusted path, re-prices that path at the amount its weakest
// hop can bear, and finally checks whether a deliberate multi-corridor split
// would cover more of the remaining amount than the best single shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.firstAmt == 0 {
		r.firstAmt = amt
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Serve a shard from the committed plan while it still holds up.
	if pl := r.serveQueued(amt, partsLeft, busy); pl != nil {
		r.attempts++
		return pl.rt, nil
	}

	// A single shard can never exceed what one local channel can push,
	// since a shard leaves through exactly one first hop.
	hi := amt
	if single := r.maxLocalEdge(); single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly. We
	// compare the aggregate believed flow of the plan set against the best
	// single shard: covering more of the payment beats a slightly nicer
	// first hop, because every uncovered millisat is a failed payment.
	if partsLeft > 1 && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total := flowTotal(flow)
			first := flow[0]

			if best == nil || total > best.amt {
				r.queued = flow[1:]
				r.planTotal = total
				best = first
			}
		}
	}

	// Last resort: deliver whatever we can. Even a small settled shard
	// reduces the remainder and refreshes evidence, which is strictly
	// better than terminally giving up on the payment.
	if best == nil {
		best = r.salvage(amt, partsLeft, busy)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// salvage hunts for any novel attempt at all, walking a descending amount
// ladder over both the disjoint and the unrestricted graph. It is the
// difference between delivering part of a payment and abandoning it, but it
// respects the global shard floor so it cannot grind into dust.
func (r *router) salvage(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *plan {

	if partsLeft <= 1 {
		// Without parts left, only a full-amount attempt helps.
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		if r.failedSigs[planSig(path, remaining)] {
			return nil
		}
		rt, p, err := r.makeRoute(path, remaining)
		if err != nil {
			return nil
		}
		return &plan{path: path, rt: rt, amt: remaining, prob: p}
	}

	floor := r.shardFloor()
	if floor > remaining {
		floor = minShard
	}

	a := remaining
	for i := 0; i < 14 && a >= floor; i++ {
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.findPath(a, avoid)
			if err != nil {
				continue
			}
			pl := r.bestOnPath(path, a, floor, remaining)
			if pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Drop only the queued shards whose corridor overlaps the route that
	// just failed. The rest of a committed decomposition is still the best
	// plan we have, and rebuilding it from scratch costs attempts.
	if len(r.queued) > 0 {
		touched := make(map[uint64]bool, len(rt.Hops))
		for _, h := range rt.Hops {
			touched[h.ChannelID] = true
		}
		kept := r.queued[:0]
		for _, pl := range r.queued {
			if !pathBusy(pl.path, touched) {
				kept = append(kept, pl)
			}
		}
		r.queued = kept
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// policy repair is not evidence of missing liquidity, so it
		// must not count against the give-up streak.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - BIMODAL OPTIMISM after a proven forward: a channel that has forwarded
//     for us is treated as holding the bulk of its capacity (minus what we
//     drained), which lets later, larger payments reuse a proven corridor.
//   - Depth-aware lower retries instead of blacklisting.
//   - JOINT ROUTE-SET PLANNING (the main change in this revision). The
//     previous version only planned a flow when a single corridor could not
//     carry the remainder, and it sized shards from a greedy sequence of
//     DISJOINT corridors found one at a time. For large payments that is
//     both too late and too narrow: the corridors we need often share a
//     bottleneck-free prefix, and the first greedy pick eats the widest
//     corridor at an amount that the rest of the plan then cannot match.
//     This revision:
//       * Builds the flow plan EAGERLY whenever the payment is large
//         relative to what one corridor is believed to bear, and compares
//         the plan's total believed-deliverable value against the best
//         single shard rather than only firing as a fallback.
//       * Allows corridor REUSE with residual accounting: a channel is
//         charged for the shard amounts already assigned to it, so two
//         shards may share a fat channel as long as the fat channel is
//         believed able to bear their sum. This is what turns a strict
//         disjoint-path search into an actual min-cost-flow decomposition
//         and is why plans now cover much larger remainders.
//       * Sizes each shard to the corridor's residual bottleneck and then
//         RE-BALANCES: leftover amount is offered back to the corridors
//         with slack, largest-slack first, so an unequal split is chosen
//         deliberately instead of leaving a stub shard nobody can carry.
//       * Keeps the plan alive across attempts instead of dropping it on
//         every failure: only the shards whose corridors are implicated by
//         the failure are discarded, so one bad shard does not throw away
//         a plan that was mostly right.
//   - Reserve-aware sizing: shards queued but not yet sent hold soft
//     reservations on their channels, so the planner never hands out two
//     shards that silently contend for the same liquidity.
//   - Duplicate-attempt suppression and policy repair for fee/cltv/min
//     failures, as before.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 70
	maxFailStreak = 22

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.18

	// flowRounds bounds the corridor searches spent building one flow
	// plan, and flowRebalance bounds the redistribution sweeps.
	flowRounds    = 10
	flowRebalance = 3
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity earmarked by planned-but-unsent shards.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is liquidity on a directed channel that is already spoken for,
// either by a live HTLC or by a planned shard we have not sent yet.
func (b *belief) committed() lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if used := b.committed(); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// extra charges additional liquidity against a channel on top of what the
// beliefs already record, which is how the flow planner accounts for shards
// it has provisionally assigned. penalty multiplies the cost of channels the
// plan already uses, so the search spreads over fresh corridors when it can
// but may still reuse a fat channel when nothing else works.
func (r *router) findPath(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi, penalty float64) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}

			// Charge the provisional flow already routed over this
			// channel against its believed room.
			used := extra[e.chanID]
			if amtOver+used > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver+used)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost
			if used > 0 && penalty > 1 {
				dist *= penalty
			}

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// plainPath is findPath with no provisional flow charged.
func (r *router) plainPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	return r.findPath(amt, avoid, nil, 1)
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity minus any provisional flow already
// charged to that channel, with a small margin for fees.
func (r *router) bottleneck(path []*edge,
	extra map[uint64]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if used := extra[e.chanID]; used > 0 {
			if used >= c {
				return 0
			}
			c -= used
		}
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	if bn < minShard {
		return 0
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64

	// reserved marks that this plan currently holds soft reservations on
	// its channels, which must be released before it is dropped.
	reserved bool
}

// reserve and release move a queued shard's soft reservation in and out of
// the beliefs, so the planner never double-spends believed liquidity.
func (r *router) reserve(pl *plan) {
	if pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		r.bel(hopKey(h)).reserved += hopAmount(pl.rt, i)
	}
	pl.reserved = true
}

func (r *router) release(pl *plan) {
	if !pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(pl.rt, i)
		if b.reserved >= a {
			b.reserved -= a
		} else {
			b.reserved = 0
		}
	}
	pl.reserved = false
}

// dropQueue releases every queued shard's reservation and empties the queue.
func (r *router) dropQueue() {
	for _, pl := range r.queued {
		r.release(pl)
	}
	r.queued = nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path, nil); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findFlowPath looks for a corridor able to carry hi under the provisional
// flow already assigned, falling back down the amount ladder when nothing
// can take the full amount.
func (r *router) findFlowPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi) []*edge {

	// Prefer a corridor that does not touch the provisional flow at all,
	// then allow reuse of already-loaded channels at a cost penalty.
	for _, pen := range []float64{1e9, 1.35} {
		if p, err := r.findPath(hi, avoid, extra, pen); err == nil {
			return p
		}

		probes := 0
		for _, a := range r.ladder(hi, remaining, partsLeft) {
			if a >= hi {
				continue
			}
			if probes >= 5 {
				break
			}
			probes++
			p, err := r.findPath(a, avoid, extra, pen)
			if err == nil {
				return p
			}
		}
		if len(extra) == 0 {
			break
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several corridors, sizing
// each shard to what that corridor's weakest hop is believed able to bear
// under the flow already assigned. Channels may be shared between shards as
// long as their believed room covers the sum, which is what makes this a
// min-cost-flow decomposition rather than a disjoint-path search. Leftover
// amount is then offered back to the corridors that still have slack, so the
// split is deliberately unequal instead of leaving an uncarryable stub.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	if partsLeft < 2 {
		return nil
	}

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	// extra tracks the flow provisionally routed over each channel, in
	// delivered-amount terms, which is close enough for sizing.
	extra := make(map[uint64]lnwire.MilliSatoshi)

	type corridor struct {
		path []*edge
		amt  lnwire.MilliSatoshi
	}

	var cors []corridor
	left := remaining

	for k := uint32(0); k < partsLeft && k < flowRounds; k++ {
		if left < minShard {
			break
		}

		path := r.findFlowPath(left, remaining, partsLeft, avoid, extra)
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path, extra); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		cors = append(cors, corridor{path: path, amt: amtS})
		for _, e := range path {
			extra[e.chanID] += amtS
		}
		left -= amtS
	}

	if len(cors) == 0 {
		return nil
	}

	// Rebalance: hand leftover amount to whichever corridor still has the
	// most slack under the current assignment. This is what produces the
	// deliberately unequal split.
	for round := 0; round < flowRebalance && left >= minShard; round++ {
		progress := false
		for i := range cors {
			if left < minShard {
				break
			}
			// Temporarily remove this corridor's own contribution
			// so its slack is measured against the others only.
			for _, e := range cors[i].path {
				if extra[e.chanID] >= cors[i].amt {
					extra[e.chanID] -= cors[i].amt
				} else {
					extra[e.chanID] = 0
				}
			}
			room := r.bottleneck(cors[i].path, extra)
			grow := lnwire.MilliSatoshi(0)
			if room > cors[i].amt {
				grow = room - cors[i].amt
				if grow > left {
					grow = left
				}
			}
			cors[i].amt += grow
			for _, e := range cors[i].path {
				extra[e.chanID] += cors[i].amt
			}
			if grow > 0 {
				left -= grow
				progress = true
			}
		}
		if !progress {
			break
		}
	}

	// Price every corridor and keep the ones that survive.
	var out []*plan
	for _, c := range cors {
		if c.amt < minShard {
			continue
		}
		pl := r.bestOnPath(c.path, c.amt, remaining)
		if pl == nil {
			continue
		}
		out = append(out, pl)
	}

	if len(out) == 0 {
		return nil
	}

	// Largest shard first: it is the one most likely to be unroutable
	// later, so it should go out while the network state is freshest.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].amt > out[j].amt
	})

	return out
}

// planTotal is the believed-deliverable value of a route-set plan: each
// shard's amount weighted by its own success probability.
func planTotal(pls []*plan) (lnwire.MilliSatoshi, float64) {
	var total lnwire.MilliSatoshi
	var weighted float64
	for _, pl := range pls {
		total += pl.amt
		weighted += pl.prob * float64(pl.amt)
	}
	return total, weighted
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// touches reports whether a corridor uses any of the given channels.
func touches(path []*edge, chans map[uint64]bool) bool {
	for _, e := range path {
		if chans[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next viable shard of an existing plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.release(pl)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.dropQueue()
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return rt
	}
	return nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor, and finally compares the best single shard against a full
// min-cost-flow style route set over several corridors.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.plainPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// Plan the split deliberately over several corridors whenever a single
	// shard cannot confidently cover the remainder. Unlike the previous
	// revision this fires EAGERLY (not only when nothing single-path
	// exists), because a joint plan whose shards each fit their corridor
	// beats one oversized shard that will fail and then be halved blindly.
	singleWeak := best == nil || best.amt < amt ||
		best.prob < 0.55

	if partsLeft > 1 && singleWeak {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total, weighted := planTotal(flow)

			var bestVal float64
			var bestAmt lnwire.MilliSatoshi
			if best != nil {
				bestVal = best.prob * float64(best.amt)
				bestAmt = best.amt
			}

			// Take the plan when it either covers more of the
			// remainder or delivers more expected value than the
			// single shard on its own.
			better := best == nil || total > bestAmt ||
				weighted > bestVal*1.05

			if better && len(flow) > 1 {
				first := flow[0]
				rest := flow[1:]
				r.dropQueue()
				r.queued = rest
				for _, pl := range r.queued {
					r.reserve(pl)
				}
				best = first
			} else if best == nil {
				best = flow[0]
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// pruneQueue drops only the queued shards whose corridors are implicated by
// a failure, keeping the rest of an otherwise sound plan. Throwing the whole
// plan away on every failure was what made the previous revision fall back
// to blind halving after a single bad shard.
func (r *router) pruneQueue(hit map[uint64]bool) {
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if touches(pl.path, hit) {
			r.release(pl)
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settle changes the liquidity the queued shards were sized
		// against, so re-validate them lazily: shards over channels
		// this route drained are dropped, the rest survive.
		if len(r.queued) > 0 {
			hit := make(map[uint64]bool, len(rt.Hops))
			for _, h := range rt.Hops {
				hit[h.ChannelID] = true
			}
			r.pruneQueue(hit)
		}

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			hit[h.ChannelID] = true
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	// Only the failing channel invalidates queued shards; a fee or cltv
	// repair does not touch liquidity at all, so those keep the plan.
	hit := map[uint64]bool{h.ChannelID: true}

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(hit)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	r.pruneQueue(hit)

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - BIMODAL OPTIMISM after a proven forward: a channel that has forwarded
//     for us is treated as holding the bulk of its capacity (minus what we
//     drained), which lets later, larger payments reuse a proven corridor.
//   - Depth-aware lower retries: how far below a proven failure we retry
//     depends on how depleted the direction looks.
//   - JOINT ROUTE-SET PLANNING (min-cost-flow style): shard sizes and
//     corridors are chosen TOGETHER. A greedy flow decomposition over
//     DISJOINT corridors sizes each shard to that corridor's believed
//     bottleneck, and the plan is only accepted when the corridors' total
//     believed capacity actually covers the remaining amount.
//   - PLAN REPAIR instead of plan discard: when an attempt fails, only the
//     queued shards whose corridors touch the newly-condemned channel are
//     dropped. Previously the whole joint plan was thrown away on every
//     failure, which is exactly how a large payment degenerated into
//     eleven blind retries and a terminal "no route found".
//   - FLOW-FEASIBILITY GATE: before giving up, the router checks whether the
//     believed max-flow out of our own channels can cover the remainder at
//     all; if it can it keeps carving smaller corridors instead of erroring.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. The streak is generous because a
	// large multi-part payment legitimately spends several probes learning
	// the shape of the network before any shard lands.
	maxAttempts   = 70
	maxFailStreak = 26

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the greedy flow decomposition.
	flowRounds = 12
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// hardBottleneck is the corridor's absolute believed ceiling, used by the
// feasibility gate: it ignores the conservative safeCap shading and asks
// only whether liquidity could plausibly flow at all.
func (r *router) hardBottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.availCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 8 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
//
// The decomposition keeps carving corridors until either the remainder is
// covered or no further corridor exists, and it is allowed to skip corridors
// that turn out too thin so a later round can find a wider one.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	var out []*plan
	left := remaining
	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		path := r.findAnyPath(left, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			// The corridor is too thin to be worth a shard, but it
			// is still worth excluding so the next round finds
			// something else.
			for _, e := range path {
				avoid[e.chanID] = true
			}
			continue
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			for _, e := range path {
				avoid[e.chanID] = true
			}
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	// Best shards first: the largest, most reliable corridor should be
	// tried before the marginal ones.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].score > out[j].score
	})

	return out
}

// feasibleFlow is the total delivered amount our believed liquidity could
// carry over up to `rounds` disjoint corridors. It is the gate that keeps a
// large payment alive: as long as the network plausibly has the liquidity,
// we keep carving smaller corridors instead of returning a terminal error.
func (r *router) feasibleFlow(remaining lnwire.MilliSatoshi,
	rounds int) lnwire.MilliSatoshi {

	avoid := make(map[uint64]bool)
	var total lnwire.MilliSatoshi

	for k := 0; k < rounds; k++ {
		left := remaining - total
		if left < minShard {
			break
		}
		path, err := r.findPath(left, avoid)
		if err != nil {
			path = r.findAnyPath(left, remaining, 4, avoid)
			if path == nil {
				break
			}
		}
		bn := r.hardBottleneck(path)
		if bn > left {
			bn = left
		}
		for _, e := range path {
			avoid[e.chanID] = true
		}
		if bn < minShard {
			continue
		}
		total += bn
	}

	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// pruneQueue drops only the queued shards whose corridors touch a channel
// whose belief just got worse. Discarding the entire joint plan on every
// failure throws away correct planning work and forces the router to
// rediscover the same split by trial and error.
func (r *router) pruneQueue(hit map[uint64]bool) {
	if len(r.queued) == 0 {
		return
	}
	keep := r.queued[:0]
	for _, pl := range r.queued {
		drop := false
		for _, e := range pl.path {
			if hit[e.chanID] {
				drop = true
				break
			}
		}
		if !drop {
			keep = append(keep, pl)
		}
	}
	r.queued = keep
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor: for every candidate amount (largest first) it finds the best
// risk-adjusted path, re-prices that path at the amount its weakest hop can
// bear, and finally checks whether a deliberate multi-corridor split would
// cover more of the remaining amount than the best single shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			break
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly. The
	// plan is accepted when its corridors jointly cover meaningfully more
	// of the remainder than the single best shard would.
	if partsLeft > 1 && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			var total lnwire.MilliSatoshi
			for _, pl := range flow {
				total += pl.amt
			}

			first := flow[0]
			better := best == nil ||
				(total > best.amt &&
					first.score > best.score*0.75)

			if better {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	if best != nil {
		r.attempts++
		return best.rt, nil
	}

	// Last resort: our conservative sizing found nothing, but the network
	// may still be able to carry small shards. Walk the ladder with the
	// hard (unshaded) bounds and take the biggest novel attempt we can
	// build, rather than declaring the payment dead. This is what turns a
	// premature "no route found" into a completed multi-part payment.
	if r.feasibleFlow(amt, flowRounds) >= minShard {
		for _, a := range r.ladder(amt, amt, partsLeft) {
			path, err := r.findPath(a, nil)
			if err != nil {
				continue
			}
			pl := r.bestOnPath(path, a, amt)
			if pl == nil {
				continue
			}
			r.attempts++
			return pl.rt, nil
		}
	}

	return nil, errors.New("no route found")
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settled shard drained the corridors it used, so any queued
		// shard sharing those channels must be re-planned.
		hit := make(map[uint64]bool, len(rt.Hops))
		for _, h := range rt.Hops {
			hit[h.ChannelID] = true
		}
		r.pruneQueue(hit)

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			hit[h.ChannelID] = true
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// fee repair is not evidence against any corridor, so queued
		// shards survive untouched.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(map[uint64]bool{h.ChannelID: true})
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	// Only the queued corridors that actually depend on the condemned
	// channel are invalidated; the rest of the joint plan stays valid.
	r.pruneQueue(map[uint64]bool{h.ChannelID: true})

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - Balance bookkeeping on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - Depth-aware lower retries instead of blacklisting.
//
// Changes in this revision, aimed squarely at the two observed failures
// (huge payments, ~2.06 Gmsat and ~0.86 Gmsat, that burned 15 attempts and
// then terminated with "no route found"):
//
//   1. GIVE-UP LOGIC WAS THE PROXIMATE KILLER. Both failures ended in
//      "no route found" while parts were still available. The old code
//      searched a ladder of amounts but every rung ran a FULL Dijkstra that
//      could reject a corridor for a single overloaded hop, and once the
//      ladder ran dry it returned a terminal error. Now, before ever
//      returning an error, we run a LAST-DITCH descent: a geometric sweep
//      down to minShard with all soft suspicion (misses, part-count
//      penalties, probability floors) relaxed. A shard that delivers even a
//      fraction is worth more than a terminal give-up, because the runner
//      keeps calling us with the remainder.
//
//   2. THE FLOW PLANNER NOW SIZES FROM A RESIDUAL-CAPACITY MAX-FLOW, not
//      from a sequence of Dijkstra probes at guessed amounts. We compute,
//      per directed edge, a believed-bearable capacity, then repeatedly pull
//      the WIDEST augmenting path out of the residual graph. Each
//      augmenting path becomes a shard sized to its own bottleneck. This is
//      a genuine flow decomposition: parallel corridors of unequal capacity
//      each carry a shard sized to what they bear, and the plan's total is
//      the believed max-flow rather than whatever a greedy first pick left.
//
//   3. SHARD COUNT IS BOUNDED BY MaxParts AND BY WHAT REMAINS. When the
//      believed max-flow cannot cover the remainder we still emit the plan,
//      because partial delivery advances the payment and refreshes beliefs
//      on exactly the corridors that matter.
//
//   4. LOCAL-CHANNEL CAPACITY IS A HARD, EXACT CONSTRAINT and is now shared
//      correctly across a multi-shard plan: two shards leaving the same
//      local channel are charged against one balance via the residual map.
//
//   5. Fee/cltv repairs no longer count against the give-up streak, since
//      they are policy corrections rather than liquidity evidence.
//
//   6. Soft reservations, duplicate-attempt suppression, and in-flight
//      accounting are preserved from the prior revision, which scored a
//      clean sweep on the mid-size scenario batch.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. Both are generous: a terminal error
	// scores zero for the whole payment, so burning extra attempts is far
	// cheaper than giving up early.
	maxAttempts   = 120
	maxFailStreak = 40

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 12

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 38
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.12

	// flowRounds bounds the augmenting-path searches in one flow plan.
	flowRounds = 12
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity earmarked by planned-but-unsent shards.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// outEdges maps a node to the directed edges leaving it, used by the
	// flow planner's forward sweeps.
	outEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	// desperate is set once the ordinary search has run dry; it relaxes
	// the soft filters so we keep delivering fragments instead of
	// terminating the payment.
	desperate bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		outEdges:      make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.outEdges[e.from] = append(
					r.outEdges[e.from], e,
				)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is liquidity on a directed channel that is already spoken for,
// either by a live HTLC or by a planned shard we have not sent yet.
func (b *belief) committed() lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		lim := retryLimit(b, e.capacity)
		if r.desperate {
			// When the ordinary search has run dry, allow a deeper
			// probe: a stale bound is only refuted by trying under
			// it.
			if deep := b.failAmt - b.failAmt/8; deep > lim {
				lim = deep
			}
		}
		if lim < c {
			c = lim
		}
	}

	if used := b.committed(); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning and the
// per-edge capacity of the believed-capacity flow graph.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 && !r.desperate {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// extra charges additional liquidity against a channel on top of what the
// beliefs already record, which is how the flow planner accounts for shards
// it has provisionally assigned. penalty multiplies the cost of channels the
// plan already uses, so the search spreads over fresh corridors when it can
// but may still reuse a fat channel when nothing else works.
func (r *router) findPath(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi, penalty float64) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	probFloor := 1e-5
	if r.desperate {
		probFloor = 1e-9
	}

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}

			// Charge the provisional flow already routed over this
			// channel against its believed room.
			used := extra[e.chanID]
			if amtOver+used > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver+used)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < probFloor {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost
			if used > 0 && penalty > 1 {
				dist *= penalty
			}

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// plainPath is findPath with no provisional flow charged.
func (r *router) plainPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	return r.findPath(amt, avoid, nil, 1)
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity minus any provisional flow already
// charged to that channel, with a small margin for fees.
func (r *router) bottleneck(path []*edge,
	extra map[uint64]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if used := extra[e.chanID]; used > 0 {
			if used >= c {
				return 0
			}
			c -= used
		}
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	if bn < minShard {
		return 0
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 8192
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 18; i++ {
		cur = cur * 5 / 8
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64

	// reserved marks that this plan currently holds soft reservations on
	// its channels, which must be released before it is dropped.
	reserved bool
}

// reserve and release move a queued shard's soft reservation in and out of
// the beliefs, so the planner never double-spends believed liquidity.
func (r *router) reserve(pl *plan) {
	if pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		r.bel(hopKey(h)).reserved += hopAmount(pl.rt, i)
	}
	pl.reserved = true
}

func (r *router) release(pl *plan) {
	if !pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(pl.rt, i)
		if b.reserved >= a {
			b.reserved -= a
		} else {
			b.reserved = 0
		}
	}
	pl.reserved = false
}

// dropQueue releases every queued shard's reservation and empties the queue.
func (r *router) dropQueue() {
	for _, pl := range r.queued {
		r.release(pl)
	}
	r.queued = nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path, nil); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// --- Believed-capacity max-flow planner -----------------------------------
//
// The previous revision built its plan from a sequence of Dijkstra probes at
// guessed amounts, which meant the first corridor found could swallow an
// amount the rest of the plan then could not match. This planner instead
// treats safeCap as a per-edge capacity and repeatedly pulls the WIDEST
// augmenting path out of the residual graph, sizing each shard to its own
// bottleneck. The result is a genuine flow decomposition: parallel corridors
// of unequal capacity each carry a shard sized to what they bear.

// residual is the room left on a directed edge after the flow already
// assigned by the plan under construction.
func (r *router) residual(e *edge,
	used map[uint64]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	c := r.safeCap(e)
	if c == 0 {
		return 0
	}
	if u := used[e.chanID]; u > 0 {
		if u >= c {
			return 0
		}
		c -= u
	}
	return c
}

// widestPath finds the source-to-target path maximising the bottleneck
// residual capacity, breaking ties toward fewer hops. It runs forward from
// the source over the believed-capacity graph, which is the natural
// direction for a max-flow augmentation.
func (r *router) widestPath(used map[uint64]lnwire.MilliSatoshi,
	avoid map[uint64]bool,
	cap0 lnwire.MilliSatoshi) ([]*edge, lnwire.MilliSatoshi) {

	type nodeState struct {
		width lnwire.MilliSatoshi
		via   *edge
		hops  int
	}

	states := map[route.Vertex]*nodeState{
		r.source: {width: cap0, hops: 0},
	}

	// Bellman-Ford style relaxation bounded by the hop limit; the graph
	// is small enough that this is cheap and avoids a second heap type.
	for round := 0; round < maxRouteHops; round++ {
		changed := false
		for node, st := range states {
			if st.hops != round {
				continue
			}
			if node == r.spec.Target {
				continue
			}
			for _, e := range r.outEdges[node] {
				if avoid[e.chanID] || e.to == node {
					continue
				}
				res := r.residual(e, used)
				if res < minShard {
					continue
				}
				w := st.width
				if res < w {
					w = res
				}
				if w < minShard {
					continue
				}
				cur, ok := states[e.to]
				better := !ok || w > cur.width ||
					(w == cur.width && round+1 < cur.hops)
				if !better {
					continue
				}
				states[e.to] = &nodeState{
					width: w, via: e, hops: round + 1,
				}
				changed = true
			}
		}
		if !changed {
			break
		}
	}

	end, ok := states[r.spec.Target]
	if !ok || end.via == nil {
		return nil, 0
	}

	// Walk the predecessor chain back to the source.
	var rev []*edge
	node := r.spec.Target
	for node != r.source {
		st, ok := states[node]
		if !ok || st.via == nil {
			return nil, 0
		}
		rev = append(rev, st.via)
		node = st.via.from
		if len(rev) > maxRouteHops {
			return nil, 0
		}
	}

	path := make([]*edge, len(rev))
	for i := range rev {
		path[i] = rev[len(rev)-1-i]
	}

	return path, end.width
}

// planFlow decomposes the remaining amount into shards by repeatedly pulling
// the widest augmenting path out of the believed-capacity residual graph.
// Every shard is sized to its own corridor's bottleneck, so unequal
// corridors get deliberately unequal shards instead of blind halves. Local
// channel balances are exact constraints and are shared across shards
// through the residual map, so two shards never over-commit one balance.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	if partsLeft < 2 {
		return nil
	}

	used := make(map[uint64]lnwire.MilliSatoshi)

	type corridor struct {
		path []*edge
		amt  lnwire.MilliSatoshi
	}

	var cors []corridor
	left := remaining
	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := 0; k < rounds && left >= minShard; k++ {
		// First try to keep clear of channels already carrying our own
		// HTLCs; if that yields nothing, allow them, since a contended
		// corridor still beats no corridor at all.
		path, width := r.widestPath(used, busy, left)
		if path == nil {
			path, width = r.widestPath(used, nil, left)
		}
		if path == nil || width < minShard {
			break
		}

		amtS := width
		if amtS > left {
			amtS = left
		}
		// Leave a sliver of headroom for fees charged upstream of the
		// bottleneck hop.
		if amtS > minShard {
			amtS -= amtS / 100
		}
		if amtS < minShard {
			break
		}

		cors = append(cors, corridor{path: path, amt: amtS})
		for _, e := range path {
			used[e.chanID] += amtS
		}
		left -= amtS
	}

	if len(cors) == 0 {
		return nil
	}

	// Price every corridor and keep the ones that survive. bestOnPath
	// steps the amount down until makeRoute accepts it, which absorbs the
	// difference between the flow sizing (delivered amounts) and the real
	// per-hop amounts (which carry fees).
	var out []*plan
	for _, c := range cors {
		if c.amt < minShard {
			continue
		}
		pl := r.bestOnPath(c.path, c.amt, remaining)
		if pl == nil {
			continue
		}
		out = append(out, pl)
	}

	if len(out) == 0 {
		return nil
	}

	// Largest shard first: it is the one most likely to be unroutable
	// later, so it should go out while the network state is freshest.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].amt > out[j].amt
	})

	return out
}

// planTotal is the believed-deliverable value of a route-set plan: each
// shard's amount weighted by its own success probability.
func planTotal(pls []*plan) (lnwire.MilliSatoshi, float64) {
	var total lnwire.MilliSatoshi
	var weighted float64
	for _, pl := range pls {
		total += pl.amt
		weighted += pl.prob * float64(pl.amt)
	}
	return total, weighted
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// touches reports whether a corridor uses any of the given channels.
func touches(path []*edge, chans map[uint64]bool) bool {
	for _, e := range path {
		if chans[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next viable shard of an existing plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.release(pl)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.dropQueue()
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return rt
	}
	return nil
}

// lastDitch is the fallback that runs only when the ordinary search has
// produced nothing. It relaxes every soft filter and sweeps a geometric
// descent of amounts, returning the first thing that is routable at all.
// Delivering a fragment is strictly better than a terminal give-up, because
// the runner will keep asking for the remainder and each fragment both
// reduces the remainder and refreshes our beliefs.
func (r *router) lastDitch(amt lnwire.MilliSatoshi, partsLeft uint32) *plan {
	prev := r.desperate
	r.desperate = true
	defer func() { r.desperate = prev }()

	if partsLeft <= 1 {
		// With no parts left, only a full-amount shard has value.
		if path, err := r.plainPath(amt, nil); err == nil {
			if rt, p, err := r.makeRoute(path, amt); err == nil {
				return &plan{
					path: path, rt: rt, amt: amt, prob: p,
				}
			}
		}
		return nil
	}

	a := amt
	for i := 0; i < 24 && a >= minShard; i++ {
		path, err := r.findPath(a, nil, nil, 1)
		if err == nil {
			if !r.failedSigs[planSig(path, a)] {
				rt, p, err := r.makeRoute(path, a)
				if err == nil {
					return &plan{
						path: path,
						rt:   rt,
						amt:  a,
						prob: p,
					}
				}
			}
			// The path exists but this exact attempt already
			// failed; nudge the amount so the signature differs.
			nudge := a - a/16
			if nudge >= minShard && nudge != a &&
				!r.failedSigs[planSig(path, nudge)] {

				rt, p, err := r.makeRoute(path, nudge)
				if err == nil {
					return &plan{
						path: path,
						rt:   rt,
						amt:  nudge,
						prob: p,
					}
				}
			}
		}
		a = a / 2
	}

	return nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor, then compares the best single shard against a believed-max-flow
// route set, and finally falls back to a relaxed last-ditch descent rather
// than terminating the payment.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.plainPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// Plan the split deliberately over several corridors whenever a single
	// shard cannot confidently cover the remainder. The flow planner is
	// now a believed-capacity max-flow, so it fires eagerly: a plan whose
	// shards each fit their corridor beats one oversized shard that will
	// fail and then be halved blindly.
	singleWeak := best == nil || best.amt < amt || best.prob < 0.55

	if partsLeft > 1 && singleWeak {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total, weighted := planTotal(flow)

			var bestVal float64
			var bestAmt lnwire.MilliSatoshi
			if best != nil {
				bestVal = best.prob * float64(best.amt)
				bestAmt = best.amt
			}

			// Take the plan when it either covers more of the
			// remainder or delivers more expected value than the
			// single shard on its own.
			better := best == nil || total > bestAmt ||
				weighted > bestVal*1.05

			if better && len(flow) > 1 {
				first := flow[0]
				rest := flow[1:]
				r.dropQueue()
				r.queued = rest
				for _, pl := range r.queued {
					r.reserve(pl)
				}
				best = first
			} else if better && best == nil {
				best = flow[0]
			}
		}
	}

	// Last-ditch: never return a terminal error while anything at all is
	// still routable. This is the single biggest change in this revision;
	// both observed scenario failures ended in "no route found" with parts
	// still available.
	if best == nil {
		r.dropQueue()
		best = r.lastDitch(amt, partsLeft)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// pruneQueue drops only the queued shards whose corridors are implicated by
// a failure, keeping the rest of an otherwise sound plan.
func (r *router) pruneQueue(hit map[uint64]bool) {
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if touches(pl.path, hit) {
			r.release(pl)
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		r.desperate = false
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settle changes the liquidity the queued shards were sized
		// against, so re-validate them lazily: shards over channels
		// this route drained are dropped, the rest survive.
		if len(r.queued) > 0 {
			hit := make(map[uint64]bool, len(rt.Hops))
			for _, h := range rt.Hops {
				hit[h.ChannelID] = true
			}
			r.pruneQueue(hit)
		}

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			hit[h.ChannelID] = true
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	// Only the failing channel invalidates queued shards; a fee or cltv
	// repair does not touch liquidity at all, so those keep the plan.
	hit := map[uint64]bool{h.ChannelID: true}

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// fee repair is a policy correction, not evidence of a dead
		// corridor, so it must not count against the give-up streak.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(hit)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	r.pruneQueue(hit)

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - BIMODAL OPTIMISM after a proven forward: a channel that has forwarded
//     for us is treated as holding the bulk of its capacity (minus what we
//     drained), which lets later, larger payments reuse a proven corridor.
//   - Depth-aware lower retries instead of blacklisting.
//   - JOINT ROUTE-SET PLANNING carried further than the previous revision.
//
// The failures the evaluation showed were all the same shape: a very large
// payment (~1.04G msat and ~0.86G msat) burned 11-13 attempts and then died
// with "no route found". Every failed attempt was a TemporaryChannelFailure on
// a two-to-four hop route, i.e. the router kept sending single shards that were
// far too big for any one corridor, learned one bound per attempt, and ran out
// of fail-streak budget before the flow plan ever got a chance to assemble a
// wide-enough route set. Four root causes, each addressed here:
//
//  1. THE PLAN WAS BUILT FROM A FIRST GUESS THAT WAS TOO BIG. planFlow asked
//     findFlowPath for the WHOLE remaining amount first, so the first corridor
//     was priced at an amount nothing could carry, the search fell back down a
//     tiny 5-probe ladder, and the resulting corridor set was thin. This
//     revision seeds the flow search with a TARGET SHARD SIZE derived from the
//     remainder and the parts still available (remaining/partsLeft), and
//     searches for corridors at that scale, growing them afterwards by
//     rebalancing. Sizing down first and growing later finds many more
//     corridors per plan than sizing up and failing.
//
//  2. THE PLAN'S TOTAL WAS NEVER COMPARED HONESTLY. The flow plan is now built
//     whenever more than one part remains and the single best shard cannot
//     cover the remainder, and the plan wins on believed-deliverable value
//     with a strong premium for covering the full remainder. A plan that
//     covers everything at modest per-shard probability beats one oversized
//     shard at high nominal probability, because the oversized shard cannot
//     finish the payment.
//
//  3. THE ROUTER GAVE UP TOO EARLY ON LARGE PAYMENTS. A payment split into ~16
//     shards inherently needs many attempts, and maxFailStreak of 22 with an
//     attempt budget of 70 was being consumed by oversized probes. The budgets
//     now scale with how many shards the payment plausibly needs, and the fail
//     streak is relieved by any PROGRESS (a newly proven bound or a settled
//     shard), not only by a settle. Learning something new is progress.
//
//  4. POLICY REPAIRS COUNTED AS LIQUIDITY FAILURES. Fee/cltv/min repairs no
//     longer touch the streak at all, since they say nothing about liquidity.
//
//   - Reserve-aware sizing: shards queued but not yet sent hold soft
//     reservations on their channels, so the planner never hands out two
//     shards that silently contend for the same liquidity.
//   - Duplicate-attempt suppression and policy repair for fee/cltv/min
//     failures, as before.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// baseAttempts and baseFailStreak are the budgets for a payment that
	// needs a single shard. Both scale up with the number of shards the
	// payment plausibly requires, since an N-part payment legitimately
	// needs at least N attempts and a failure while probing part 12 of 16
	// says nothing about whether the payment is hopeless.
	baseAttempts   = 42
	baseFailStreak = 14
	perShardBudget = 5
	hardAttemptCap = 220
	hardStreakCap  = 60

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the corridor searches spent building one flow
	// plan, and flowRebalance bounds the redistribution sweeps.
	flowRounds    = 24
	flowRebalance = 4
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity earmarked by planned-but-unsent shards.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int

	// budgetShards is an estimate of how many shards this payment needs,
	// used to scale the attempt and fail-streak budgets. It is refreshed
	// whenever a plan is built.
	budgetShards int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
		budgetShards:  1,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// attemptBudget and streakBudget scale the give-up thresholds with the number
// of shards the payment plausibly needs. A 16-part payment cannot be judged
// hopeless on the same evidence as a 1-part payment.
func (r *router) attemptBudget() int {
	n := r.budgetShards
	if n < 1 {
		n = 1
	}
	b := baseAttempts + perShardBudget*n
	if b > hardAttemptCap {
		b = hardAttemptCap
	}
	return b
}

func (r *router) streakBudget() int {
	n := r.budgetShards
	if n < 1 {
		n = 1
	}
	b := baseFailStreak + 2*n
	if b > hardStreakCap {
		b = hardStreakCap
	}
	return b
}

// noteShardCount raises the shard estimate that drives the budgets.
func (r *router) noteShardCount(n int) {
	if n > r.budgetShards {
		r.budgetShards = n
	}
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is liquidity on a directed channel that is already spoken for,
// either by a live HTLC or by a planned shard we have not sent yet.
func (b *belief) committed() lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if used := b.committed(); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// extra charges additional liquidity against a channel on top of what the
// beliefs already record, which is how the flow planner accounts for shards
// it has provisionally assigned. penalty multiplies the cost of channels the
// plan already uses, so the search spreads over fresh corridors when it can
// but may still reuse a fat channel when nothing else works.
func (r *router) findPath(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi, penalty float64) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}

			// Charge the provisional flow already routed over this
			// channel against its believed room.
			used := extra[e.chanID]
			if amtOver+used > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver+used)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost
			if used > 0 && penalty > 1 {
				dist *= penalty
			}

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// plainPath is findPath with no provisional flow charged.
func (r *router) plainPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	return r.findPath(amt, avoid, nil, 1)
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// widestLocal is the largest single local channel's believed room, which is a
// floor on how big a single shard can usefully be.
func (r *router) widestLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, e := range r.localEdges {
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity minus any provisional flow already
// charged to that channel, with a small margin for fees.
func (r *router) bottleneck(path []*edge,
	extra map[uint64]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if used := extra[e.chanID]; used > 0 {
			if used >= c {
				return 0
			}
			c -= used
		}
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	if bn < minShard {
		return 0
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 12 {
		maxK = 12
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64

	// reserved marks that this plan currently holds soft reservations on
	// its channels, which must be released before it is dropped.
	reserved bool
}

// reserve and release move a queued shard's soft reservation in and out of
// the beliefs, so the planner never double-spends believed liquidity.
func (r *router) reserve(pl *plan) {
	if pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		r.bel(hopKey(h)).reserved += hopAmount(pl.rt, i)
	}
	pl.reserved = true
}

func (r *router) release(pl *plan) {
	if !pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(pl.rt, i)
		if b.reserved >= a {
			b.reserved -= a
		} else {
			b.reserved = 0
		}
	}
	pl.reserved = false
}

// dropQueue releases every queued shard's reservation and empties the queue.
func (r *router) dropQueue() {
	for _, pl := range r.queued {
		r.release(pl)
	}
	r.queued = nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path, nil); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findFlowPath looks for a corridor able to carry target under the
// provisional flow already assigned, walking down a geometric ladder from
// target when nothing can take that much. Unlike the previous revision this
// starts from a REALISTIC per-shard target rather than the whole remainder,
// which is what lets a plan accumulate many corridors instead of one.
func (r *router) findFlowPath(target lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi) []*edge {

	// Prefer a corridor that does not touch the provisional flow at all,
	// then allow reuse of already-loaded channels at a cost penalty.
	pens := []float64{1e9, 1.35}
	if len(extra) == 0 {
		pens = []float64{1}
	}

	for _, pen := range pens {
		a := target
		for i := 0; i < 7 && a >= minShard; i++ {
			if p, err := r.findPath(a, avoid, extra, pen); err == nil {
				return p
			}
			a = a / 2
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several corridors, sizing
// each shard to what that corridor's weakest hop is believed able to bear
// under the flow already assigned. Channels may be shared between shards as
// long as their believed room covers the sum, which is what makes this a
// min-cost-flow decomposition rather than a disjoint-path search. Leftover
// amount is then offered back to the corridors that still have slack, so the
// split is deliberately unequal instead of leaving an uncarryable stub.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	if partsLeft < 2 {
		return nil
	}

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	// extra tracks the flow provisionally routed over each channel, in
	// delivered-amount terms, which is close enough for sizing.
	extra := make(map[uint64]lnwire.MilliSatoshi)

	type corridor struct {
		path []*edge
		amt  lnwire.MilliSatoshi
	}

	var cors []corridor
	left := remaining

	// The per-corridor target: aim for an even split over the parts we can
	// still use, but never below what one fat corridor could carry on its
	// own. Sizing DOWN first and growing later during rebalance finds far
	// more corridors than starting from the full remainder and failing.
	target := remaining
	if partsLeft > 1 {
		target = remaining / lnwire.MilliSatoshi(partsLeft)
	}
	if w := r.widestLocal(); w > target {
		target = w
	}
	if target > remaining {
		target = remaining
	}
	if target < minShard {
		target = minShard
	}

	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := target
		if want > left {
			want = left
		}

		path := r.findFlowPath(want, avoid, extra)
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path, extra); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		cors = append(cors, corridor{path: path, amt: amtS})
		for _, e := range path {
			extra[e.chanID] += amtS
		}
		left -= amtS
	}

	if len(cors) == 0 {
		return nil
	}

	// Rebalance: hand leftover amount to whichever corridor still has the
	// most slack under the current assignment. This is what produces the
	// deliberately unequal split.
	for round := 0; round < flowRebalance && left >= minShard; round++ {
		progress := false
		for i := range cors {
			if left < minShard {
				break
			}
			// Temporarily remove this corridor's own contribution
			// so its slack is measured against the others only.
			for _, e := range cors[i].path {
				if extra[e.chanID] >= cors[i].amt {
					extra[e.chanID] -= cors[i].amt
				} else {
					extra[e.chanID] = 0
				}
			}
			room := r.bottleneck(cors[i].path, extra)
			grow := lnwire.MilliSatoshi(0)
			if room > cors[i].amt {
				grow = room - cors[i].amt
				if grow > left {
					grow = left
				}
			}
			cors[i].amt += grow
			for _, e := range cors[i].path {
				extra[e.chanID] += cors[i].amt
			}
			if grow > 0 {
				left -= grow
				progress = true
			}
		}
		if !progress {
			break
		}
	}

	// Price every corridor and keep the ones that survive.
	var out []*plan
	for _, c := range cors {
		if c.amt < minShard {
			continue
		}
		pl := r.bestOnPath(c.path, c.amt, remaining)
		if pl == nil {
			continue
		}
		out = append(out, pl)
	}

	if len(out) == 0 {
		return nil
	}

	// Largest shard first: it is the one most likely to be unroutable
	// later, so it should go out while the network state is freshest.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].amt > out[j].amt
	})

	return out
}

// planTotal is the believed-deliverable value of a route-set plan: each
// shard's amount weighted by its own success probability.
func planTotal(pls []*plan) (lnwire.MilliSatoshi, float64) {
	var total lnwire.MilliSatoshi
	var weighted float64
	for _, pl := range pls {
		total += pl.amt
		weighted += pl.prob * float64(pl.amt)
	}
	return total, weighted
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// touches reports whether a corridor uses any of the given channels.
func touches(path []*edge, chans map[uint64]bool) bool {
	for _, e := range path {
		if chans[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next viable shard of an existing plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.release(pl)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.dropQueue()
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return rt
	}
	return nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor, and finally compares the best single shard against a full
// min-cost-flow style route set over several corridors.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= r.attemptBudget() {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= r.streakBudget() {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	// Record how many shards this remainder plausibly needs so the attempt
	// budgets scale with the real difficulty of the payment.
	if w := r.widestLocal(); w > 0 {
		n := int(amt/w) + 1
		if r.spec.MaxParts > 0 && n > int(r.spec.MaxParts) {
			n = int(r.spec.MaxParts)
		}
		r.noteShardCount(n)
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.plainPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// Plan the split deliberately over several corridors whenever a single
	// shard cannot confidently cover the remainder. This fires EAGERLY,
	// because a joint plan whose shards each fit their corridor beats one
	// oversized shard that will fail and then be halved blindly.
	singleWeak := best == nil || best.amt < amt || best.prob < 0.60

	if partsLeft > 1 && singleWeak {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total, weighted := planTotal(flow)
			r.noteShardCount(len(flow))

			var bestVal float64
			var bestAmt lnwire.MilliSatoshi
			if best != nil {
				bestVal = best.prob * float64(best.amt)
				bestAmt = best.amt
			}

			// A plan that covers the whole remainder is worth a
			// premium: only a covering plan can actually finish the
			// payment, and the observed failures were all cases of
			// one oversized shard beating a covering split on raw
			// per-shard probability and then failing anyway.
			planVal := weighted
			if total >= amt {
				planVal *= 1.4
			}

			better := best == nil || total > bestAmt ||
				planVal > bestVal*1.02

			if better && len(flow) > 1 {
				first := flow[0]
				rest := flow[1:]
				r.dropQueue()
				r.queued = rest
				for _, pl := range r.queued {
					r.reserve(pl)
				}
				best = first
			} else if best == nil {
				best = flow[0]
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved. It reports
// whether this taught us something new, which counts as progress.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) bool {
	b := r.bel(hopKey(h))
	learned := false
	if a > b.okAmt {
		b.okAmt = a
		learned = true
	}
	if !b.succ {
		learned = true
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		learned = true
	}
	if b.misses > 0 {
		b.misses = 0
		learned = true
	}
	return learned
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// pruneQueue drops only the queued shards whose corridors are implicated by
// a failure, keeping the rest of an otherwise sound plan. Throwing the whole
// plan away on every failure was what made an earlier revision fall back to
// blind halving after a single bad shard.
func (r *router) pruneQueue(hit map[uint64]bool) {
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if touches(pl.path, hit) {
			r.release(pl)
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settle changes the liquidity the queued shards were sized
		// against, so re-validate them lazily: shards over channels
		// this route drained are dropped, the rest survive.
		if len(r.queued) > 0 {
			hit := make(map[uint64]bool, len(rt.Hops))
			for _, h := range rt.Hops {
				hit[h.ChannelID] = true
			}
			r.pruneQueue(hit)
		}

		return nil
	}

	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// learned tracks whether this failure taught us anything new. A
	// failure that tightens a bound is PROGRESS on a multi-shard payment,
	// so it relieves the fail streak: giving up after N consecutive
	// informative failures is what killed the large payments before.
	learned := false

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			hit[h.ChannelID] = true
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
				learned = true
			}
		}
		r.pruneQueue(hit)
		if !learned {
			r.failStreak++
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		if r.provePassed(rt.Hops[i], hopAmount(rt, i)) {
			learned = true
		}
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	// Only the failing channel invalidates queued shards; a fee or cltv
	// repair does not touch liquidity at all, so those keep the plan.
	hit := map[uint64]bool{h.ChannelID: true}

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. This
		// is a pure repair, not a liquidity failure, so it does not
		// count against the streak.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(hit)
		r.failStreak++
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
		learned = true
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
		learned = true
	}

	r.pruneQueue(hit)

	// An informative failure is progress; only uninformative repetition
	// counts toward giving up.
	if learned {
		if r.failStreak > 0 {
			r.failStreak--
		}
	} else {
		r.failStreak++
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - BIMODAL OPTIMISM after a proven forward: a channel that has forwarded
//     for us is treated as holding the bulk of its capacity (minus what we
//     drained), which lets later, larger payments reuse a proven corridor.
//   - REAL IN-FLIGHT ACCOUNTING: every route we hand to the runner is held
//     as outstanding and its liquidity is reserved on each directed hop, so
//     concurrent MPP shards never plan over the same millisats twice. The
//     reservation self-heals when the runner reports zero HTLCs in flight.
//   - RESIDUAL-CAPACITY JOINT PLANNING: the multi-shard planner is a
//     successive-shortest-path flow decomposition over per-directed-channel
//     residuals rather than whole-channel exclusion, so two shards may share
//     a fat hub channel while each is sized to what is left of it.
//   - HARD INFEASIBILITY GATE: if our own channels cannot fund the remaining
//     amount at all, the payment is hopeless and we give up immediately
//     instead of burning dozens of attempts discovering it hop by hop.
//   - FAILURE-COUNT AWARE RETRIES: retrying below a proven failure beats
//     blacklisting, but the retry window shrinks geometrically with each
//     failure in that direction, so a dry channel costs a couple of probes
//     rather than a whole ladder.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled, payment-level) are
//     repaired in the local policy view instead of being treated as
//     liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(7_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. The streak allowance grows once at
	// least one shard has settled, because a payment that is making
	// progress deserves more patience than one that never moved a coin.
	maxAttempts   = 56
	maxFailStreak = 14
	progressBonus = 8

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend.
	probeBudget = 11

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.12

	// flowRounds bounds the corridors a single flow decomposition walks.
	flowRounds = 14

	// maxFailRetries is how many liquidity failures a single direction may
	// accumulate before we stop retrying it below the failure point.
	maxFailRetries = 3

	// giveUpProb is the probability below which a candidate attempt is not
	// worth spending, once we have already spent a handful of attempts.
	giveUpProb  = 0.025
	giveUpAfter = 8
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// failCount counts liquidity failures observed in this direction. Each
	// one shrinks how far below the failure point we still bother probing.
	failCount int

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// searchCtx narrows a graph search: resid holds per-directed-channel
// residual budgets left by shards already planned in the same flow
// decomposition, and avoid names channels retired from the search.
type searchCtx struct {
	resid map[edgeKey]lnwire.MilliSatoshi
	avoid map[uint64]bool
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// outstanding holds every route handed to the runner whose result has
	// not come back yet, so we can release its reservation later.
	outstanding []*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
	settles    int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// localBal is our exactly known balance on one of our own channels.
func (r *router) localBal(chanID uint64) (lnwire.MilliSatoshi, bool) {
	bal, ok := r.localBalances[chanID]
	return bal, ok
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath. Repeated failures collapse the window fast,
// because under a bimodal split a direction that keeps refusing is dry.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	if b.failCount >= maxFailRetries {
		return b.okAmt
	}

	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}

	f := 0.45 + 0.35*depth
	if b.failCount > 1 {
		f *= math.Pow(0.6, float64(b.failCount-1))
	}

	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal, ok := r.localBal(e.chanID); ok && bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// capLimit is availCap narrowed by any residual left by shards already
// planned in the same flow decomposition.
func (r *router) capLimit(e *edge, sc *searchCtx) lnwire.MilliSatoshi {
	c := r.availCap(e)
	if sc != nil && sc.resid != nil {
		if v, ok := sc.resid[e.key()]; ok && v < c {
			c = v
		}
	}
	return c
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if bal, ok := r.localBal(e.chanID); ok {
			if bal >= eff {
				return knownProb
			}
			return 0
		}
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// sc, when non-nil, narrows the usable capacity of each directed channel to
// what a flow decomposition has left of it, and hides retired channels.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	sc *searchCtx) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if e.from == it.node {
				continue
			}
			if sc != nil && sc.avoid != nil && sc.avoid[e.chanID] {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.capLimit(e, sc) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// hopAmounts prices the amount flowing over each hop of a path for a given
// delivered amount, accumulating fees backward from the target.
func hopAmounts(path []*edge, amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {
	n := len(path)
	over := make([]lnwire.MilliSatoshi, n)
	if n == 0 {
		return over
	}
	over[n-1] = amt
	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		over[i] = over[i+1] + fwd.fee(over[i+1])
	}
	return over
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 || len(path) == 0 {
		return nil, 0, errors.New("empty attempt")
	}

	n := len(path)
	amtOver := hopAmounts(path, amt)

	expiry := make([]uint32, n)
	expiry[n-1] = finalCltvDelta
	for i := n - 2; i >= 0; i-- {
		expiry[i] = expiry[i+1] + uint32(path[i+1].cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// rawLocalBudget is the total liquidity our own channels hold, ignoring
// in-flight reservations. It is a hard ceiling on the whole payment: our
// balances can only shrink, never grow, while we pay.
func (r *router) rawLocalBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if b := r.beliefs[e.key()]; b != nil && b.dead {
			continue
		}
		bal, ok := r.localBal(e.chanID)
		if !ok {
			bal = e.capacity
		}
		if bal > e.capacity {
			bal = e.capacity
		}
		total += bal
	}
	return total
}

// maxLocalEdge is the largest single local channel balance still free, which
// is the true ceiling on one shard: no shard can leave through two local
// channels at once.
func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity (narrowed by any flow residual) with
// a small margin for fees.
func (r *router) bottleneck(path []*edge, sc *searchCtx) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxInt64)
	for _, e := range path {
		c := r.safeCap(e)
		if sc != nil && sc.resid != nil {
			if v, ok := sc.resid[e.key()]; ok && v < c {
				c = v
			}
		}
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	if bn == lnwire.MilliSatoshi(math.MaxInt64) {
		return 0
	}
	return bn - bn/100
}

// consume books a planned shard against the residual budgets of its
// corridor, so a later shard of the same plan can share a fat channel only
// to the extent that liquidity is left in it.
func (r *router) consume(path []*edge, amt lnwire.MilliSatoshi,
	sc *searchCtx) {

	over := hopAmounts(path, amt)
	for i, e := range path {
		k := e.key()
		cur, ok := sc.resid[k]
		if !ok {
			cur = r.safeCap(e)
		}
		if cur > over[i] {
			cur -= over[i]
		} else {
			cur = 0
		}
		sc.resid[k] = cur
	}
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, exact local channel balances, and
// evidence-derived sizes just below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Local channel balances are exact knowledge, and a shard sized to a
	// local channel is exactly what a fan-out split wants.
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= minShard {
			add(c - c/200)
		}
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies. Maximizing p*amt is
// exactly maximizing delivered value per attempt.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan, sc *searchCtx) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path, sc); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, sc *searchCtx) []*edge {

	if p, err := r.findPath(hi, sc); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 6 {
			break
		}
		probes++
		if p, err := r.findPath(a, sc); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several corridors, sizing
// each shard to what that corridor's weakest hop is believed able to bear
// after the shards already planned have booked their share. This is the
// min-cost-flow style joint plan: unequal parallel corridors each get a
// shard that fits, instead of discovering the split by failing at a blind
// half, and a fat hub channel may carry two shards when it has the room.
func (r *router) planFlow(remaining lnwire.MilliSatoshi,
	partsLeft uint32) []*plan {

	sc := &searchCtx{
		resid: make(map[edgeKey]lnwire.MilliSatoshi),
		avoid: make(map[uint64]bool),
	}

	single := r.maxLocalEdge()

	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	var out []*plan
	left := remaining

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if single > 0 && want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, sc)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path, sc); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			sc.avoid[path[0].chanID] = true
			continue
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			// The corridor cannot bear anything novel, so retire
			// its first hop and move on instead of aborting the
			// whole decomposition.
			sc.avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)
		r.consume(path, pl.amt, sc)

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// flowTotal is the amount a plan set delivers in aggregate.
func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

// --- In-flight reservation ------------------------------------------------

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// hold reserves the liquidity of a route we are about to hand out, so a
// concurrent shard is planned over different millisats.
func (r *router) hold(rt *route.Route) {
	r.outstanding = append(r.outstanding, rt)
	r.markInFlight(rt, +1)
}

// release drops the reservation of a route whose result just came back.
func (r *router) release(rt *route.Route) {
	for i, o := range r.outstanding {
		if o == rt {
			r.outstanding = append(
				r.outstanding[:i], r.outstanding[i+1:]...,
			)
			r.markInFlight(o, -1)
			return
		}
	}

	sig := routeSig(rt)
	for i, o := range r.outstanding {
		if routeSig(o) == sig {
			r.outstanding = append(
				r.outstanding[:i], r.outstanding[i+1:]...,
			)
			r.markInFlight(o, -1)
			return
		}
	}
}

// clearInFlight drops every reservation. The runner telling us that nothing
// is in flight is ground truth, so this repairs any accounting we lost track
// of instead of letting a phantom reservation block a channel forever.
func (r *router) clearInFlight() {
	for _, b := range r.beliefs {
		b.inFlight = 0
	}
	r.outstanding = nil
}

// dropQueued removes queued shards that route over a channel which just
// failed, keeping the rest of a joint plan alive.
func (r *router) dropQueued(chanID uint64) {
	out := r.queued[:0]
	for _, pl := range r.queued {
		keep := true
		for _, e := range pl.path {
			if e.chanID == chanID {
				keep = false
				break
			}
		}
		if keep {
			out = append(out, pl)
		}
	}
	r.queued = out
}

// --- Route requests -------------------------------------------------------

// deliver books an attempt and returns its route.
func (r *router) deliver(pl *plan) (*route.Route, error) {
	r.attempts++
	r.hold(pl.rt)
	return pl.rt, nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor: for every candidate amount (largest first) it finds the best
// risk-adjusted path, re-prices that path at the amount its weakest hop can
// bear, and finally checks whether a deliberate multi-corridor split would
// cover more of the remaining amount than the best single shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	// The runner is authoritative about how many HTLCs are live, so use it
	// to repair any reservation we failed to release.
	if inFlightHtlcs == 0 && len(r.outstanding) > 0 {
		r.clearInFlight()
	}

	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	streakLimit := maxFailStreak
	if r.settles > 0 {
		streakLimit += progressBonus
	}
	if r.failStreak >= streakLimit {
		return nil, errors.New("no progress")
	}

	// Hard infeasibility: our own balances can only shrink, so a remainder
	// larger than everything we hold can never be paid. Giving up now
	// saves a long tail of doomed attempts.
	if r.rawLocalBudget() < amt {
		return nil, errors.New("insufficient local liquidity")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			break
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return r.deliver(&plan{
			path: pl.path, rt: rt, amt: a, prob: p,
		})
	}

	// A single shard can never exceed what one local channel can push,
	// since a shard leaves through exactly one first hop.
	hi := amt
	if single := r.maxLocalEdge(); single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	var best *plan
	probes := 0
	for _, a := range r.ladder(hi, amt, partsLeft) {
		// Once we hold a solid plan, digging far below it only wastes
		// attempts and parts.
		if best != nil && best.prob >= 0.55 && a < best.amt/2 {
			break
		}
		if probes >= probeBudget {
			break
		}
		probes++

		path, err := r.findPath(a, nil)
		if err != nil {
			continue
		}

		best = r.evalPath(path, a, amt, best, nil)

		// A confident full-amount plan needs no alternatives.
		if best != nil && best.amt >= amt && best.prob > 0.75 {
			break
		}
	}

	// When no single corridor carries the whole remainder confidently, plan
	// the split deliberately over parallel corridors instead of halving
	// blindly. We compare the aggregate believed flow of the plan set
	// against the best single shard: covering more of the payment beats a
	// slightly nicer first hop, because every uncovered millisat is a
	// failed payment.
	if partsLeft > 1 && (best == nil || best.amt < amt || best.prob < 0.5) {
		flow := r.planFlow(amt, partsLeft)
		if len(flow) > 0 {
			total := flowTotal(flow)
			first := flow[0]

			if best == nil || total > best.amt ||
				(total >= amt && first.prob > best.prob) {

				r.queued = flow[1:]
				best = first
			}
		}
	}

	// Last resort: deliver whatever we can. Even a small settled shard
	// reduces the remainder and refreshes evidence, which is strictly
	// better than terminally giving up on the payment.
	if best == nil {
		best = r.salvage(amt, partsLeft)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	// A hopeless attempt costs a retry and teaches almost nothing, so once
	// we have already spent a few, stop chasing lottery tickets.
	if best.prob < giveUpProb && r.attempts >= giveUpAfter {
		return nil, errors.New("no viable route")
	}

	return r.deliver(best)
}

// salvage hunts for any novel attempt at all, walking a wide descending
// amount ladder. It is the difference between delivering part of a payment
// and abandoning it.
func (r *router) salvage(remaining lnwire.MilliSatoshi,
	partsLeft uint32) *plan {

	if partsLeft <= 1 {
		// Without parts left, only a full-amount attempt helps.
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		if r.failedSigs[planSig(path, remaining)] {
			return nil
		}
		rt, p, err := r.makeRoute(path, remaining)
		if err != nil {
			return nil
		}
		return &plan{path: path, rt: rt, amt: remaining, prob: p}
	}

	a := remaining
	for i := 0; i < 18 && a >= minShard; i++ {
		path, err := r.findPath(a, nil)
		if err == nil {
			if pl := r.bestOnPath(path, a, remaining); pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// --- Feedback -------------------------------------------------------------

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.failCount = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier shards and payments stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
			rb.failCount = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
			rb.failCount = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"),
		strings.Contains(d, "ExpiryTooFar"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	case strings.Contains(d, "MPPTimeout"),
		strings.Contains(d, "PaymentDetails"),
		strings.Contains(d, "FinalIncorrect"),
		strings.Contains(d, "RequiredNodeFeature"):
		// A payment-level failure says nothing about liquidity, so it
		// must not damage any bound we have earned.
		return "final"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release the liquidity we had reserved for this attempt.
	r.release(rt)

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		r.settles++
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++

	kind := classify(result.Failure)
	if kind != "final" {
		if sig := routeSig(rt); sig != "" {
			r.failedSigs[sig] = true
		}
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if kind == "final" {
		// The receiver, not the corridor, rejected this shard. Keep the
		// corridor's evidence intact and simply try again.
		return nil
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.queued = nil
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch kind {
	case "fee":
		// Our fee view for this hop is stale: pay more next time.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		r.dropQueued(h.ChannelID)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	b.failCount++

	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// Other shards of the same joint plan that lean on this channel are
	// now unsound, but the rest of the plan still stands.
	r.dropQueued(h.ChannelID)

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - Depth-aware lower retries instead of blacklisting.
//   - JOINT ROUTE-SET PLANNING with residual accounting: shards may share a
//     fat channel as long as the fat channel is believed to bear their sum.
//
// Changes in this revision, driven by the evaluation data. The failing
// scenario was always the same shape: one very large payment to a distant
// target, where a handful of attempts each hit TemporaryChannelFailure on
// the last hop and the router then gave up with "no route found" after 5-13
// attempts even though the attempt budget was nowhere near exhausted. Root
// causes and fixes:
//
//  1. GIVING UP WHILE PARTS REMAIN. RequestRoute returned a terminal error
//     the moment the single-shard search and the flow planner both came up
//     empty at the amounts they happened to probe. With MaxParts still
//     free, a small shard that fits is worth far more than a terminal
//     failure: it both delivers value and buys fresh evidence. This
//     revision adds a LAST-RESORT DESCENT over a fine geometric ladder, so
//     terminal failure now means "nothing at any size".
//
//  2. THE PLANNER ONLY EVER SIZED SHARDS DOWNWARD FROM `left`, asking each
//     successive corridor for the whole remainder and then falling down a
//     coarse probe ladder. That systematically produced one or two fat
//     shards plus an uncarryable stub. Corridors are now asked for a TARGET
//     SHARE (remaining / partsLeft), which is what a min-cost-flow
//     decomposition wants, and PARTIAL plans are accepted: covering most of
//     a huge payment over several corridors and re-planning the tail beats
//     refusing to split.
//
//  3. LAST-HOP BOTTLENECKS WERE INVISIBLE. Every recorded failure in the
//     eval was at the FINAL hop. The target's inbound capacity is the true
//     bottleneck for a large payment, so reusing one final channel for
//     several shards is doomed. Already-loaded inbound edges of the target
//     now carry an extra cost penalty during the flow search, which spreads
//     shards over distinct final edges before it stacks them.
//
//  4. UNATTRIBUTABLE FAILURES (failed_at_hop == -1) appeared in a third of
//     the failing attempts and previously only bumped a soft "miss"
//     counter, which blocked nothing, so the search re-picked near-identical
//     corridors. Misses now also impose a soft CEILING on the amount we
//     will retry over that direction, forcing genuine diversification
//     without destroying the hard bounds we earned.
//
//  5. Budgets raised where they were binding, and policy repairs (fee /
//     cltv / min-htlc) no longer count against the give-up streak, since
//     they are bookkeeping fixes rather than evidence of a dead corridor.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. Both are generous: the evaluation
	// showed payments abandoned with plenty of budget left, and one extra
	// retry costs far less than a lost payment.
	maxAttempts   = 110
	maxFailStreak = 34

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 16

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// rescueShard is the floor used by the last-resort descent, which may
	// go smaller than an ordinary planned shard because any delivered
	// value beats a terminal failure.
	rescueShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the corridor searches spent building one flow
	// plan, and flowRebalance bounds the redistribution sweeps.
	flowRounds    = 14
	flowRebalance = 3

	// finalReusePenalty is the extra cost charged for reusing an inbound
	// edge of the target that a planned shard already loads. The target's
	// inbound capacity is the usual bottleneck on large payments, so the
	// planner works hard to spread over distinct final edges.
	finalReusePenalty = 2.6
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity earmarked by planned-but-unsent shards.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// missCap is a soft ceiling learned from unattributable failures: the
	// smallest amount this direction carried as part of an attempt that
	// failed somewhere we could not localise. Retrying at or above it
	// wastes attempts, so we shrink under it.
	missCap lnwire.MilliSatoshi

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int

	// settled counts shards that have settled for this payment, which is
	// evidence the payment is progressing even if individual probes fail.
	settled int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is liquidity on a directed channel that is already spoken for,
// either by a live HTLC or by a planned shard we have not sent yet.
func (b *belief) committed() lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// softCeiling is the ceiling implied by unattributable failures. Each miss
// shrinks the amount we are willing to retry over this direction, which is
// what makes the search actually diversify after a blind failure instead of
// re-picking a corridor with a marginally worse score.
func (b *belief) softCeiling() lnwire.MilliSatoshi {
	if b == nil || b.misses == 0 || b.missCap == 0 {
		return 0
	}
	m := b.misses
	if m > 3 {
		m = 3
	}
	f := math.Pow(0.6, float64(m))
	lim := lnwire.MilliSatoshi(float64(b.missCap) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); lim < c {
				c = lim
			}
		}
		if lim := b.softCeiling(); lim > 0 && lim < c {
			c = lim
		}
	}

	if used := b.committed(); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// extra charges additional liquidity against a channel on top of what the
// beliefs already record, which is how the flow planner accounts for shards
// it has provisionally assigned. penalty multiplies the cost of channels the
// plan already uses, so the search spreads over fresh corridors when it can
// but may still reuse a fat channel when nothing else works. finalPenalty
// applies the same idea specifically to already-loaded INBOUND edges of the
// target, which are the usual bottleneck on large payments.
func (r *router) findPath(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi, penalty,
	finalPenalty float64) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}

			// Charge the provisional flow already routed over this
			// channel against its believed room.
			used := extra[e.chanID]
			if amtOver+used > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver+used)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost
			if used > 0 {
				if penalty > 1 {
					dist *= penalty
				}
				// The target's inbound edges deserve a
				// stronger spread incentive than interior
				// channels: they are where large payments
				// actually run out of room.
				if it.node == target && finalPenalty > 1 {
					dist *= finalPenalty
				}
			}

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// plainPath is findPath with no provisional flow charged.
func (r *router) plainPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	return r.findPath(amt, avoid, nil, 1, 1)
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity minus any provisional flow already
// charged to that channel, with a small margin for fees.
func (r *router) bottleneck(path []*edge,
	extra map[uint64]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if used := extra[e.chanID]; used > 0 {
			if used >= c {
				return 0
			}
			c -= used
		}
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	if bn < minShard {
		return 0
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64

	// reserved marks that this plan currently holds soft reservations on
	// its channels, which must be released before it is dropped.
	reserved bool
}

// reserve and release move a queued shard's soft reservation in and out of
// the beliefs, so the planner never double-spends believed liquidity.
func (r *router) reserve(pl *plan) {
	if pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		r.bel(hopKey(h)).reserved += hopAmount(pl.rt, i)
	}
	pl.reserved = true
}

func (r *router) release(pl *plan) {
	if !pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(pl.rt, i)
		if b.reserved >= a {
			b.reserved -= a
		} else {
			b.reserved = 0
		}
	}
	pl.reserved = false
}

// dropQueue releases every queued shard's reservation and empties the queue.
func (r *router) dropQueue() {
	for _, pl := range r.queued {
		r.release(pl)
	}
	r.queued = nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path, nil); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 4 / 5
	}
	return nil
}

// findFlowPath looks for a corridor able to carry hi under the provisional
// flow already assigned, falling back down the amount ladder when nothing
// can take the full amount.
func (r *router) findFlowPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi) []*edge {

	// Prefer a corridor that does not touch the provisional flow at all,
	// then allow reuse of already-loaded channels at a cost penalty. The
	// target's inbound edges keep a stronger penalty in both passes.
	for _, pen := range []float64{1e9, 1.35} {
		if p, err := r.findPath(
			hi, avoid, extra, pen, finalReusePenalty,
		); err == nil {
			return p
		}

		probes := 0
		for _, a := range r.ladder(hi, remaining, partsLeft) {
			if a >= hi {
				continue
			}
			if probes >= 6 {
				break
			}
			probes++
			p, err := r.findPath(
				a, avoid, extra, pen, finalReusePenalty,
			)
			if err == nil {
				return p
			}
		}
		if len(extra) == 0 {
			break
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several corridors, sizing
// each shard to what that corridor's weakest hop is believed able to bear
// under the flow already assigned. Channels may be shared between shards as
// long as their believed room covers the sum, which is what makes this a
// min-cost-flow decomposition rather than a disjoint-path search.
//
// Two changes over the previous revision matter most. First, each successive
// corridor is asked for a TARGET SHARE of the remainder rather than the
// whole remainder: asking for the full amount every round made the search
// fall down a coarse ladder and produced fat-shard-plus-stub splits. Second,
// a PARTIAL plan is accepted and returned: covering most of a huge payment
// over several corridors and re-planning the tail on the next call beats
// refusing to split.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	if partsLeft < 2 {
		return nil
	}

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	// extra tracks the flow provisionally routed over each channel, in
	// delivered-amount terms, which is close enough for sizing.
	extra := make(map[uint64]lnwire.MilliSatoshi)

	type corridor struct {
		path []*edge
		amt  lnwire.MilliSatoshi
	}

	var cors []corridor
	left := remaining

	// share is what we ask each corridor for: an even split of the
	// remainder over the parts we can still afford, which keeps the
	// search from burning the widest corridor on an oversized shard.
	share := remaining / lnwire.MilliSatoshi(partsLeft)
	if share < minShard {
		share = minShard
	}

	for k := uint32(0); k < partsLeft && k < flowRounds; k++ {
		if left < minShard {
			break
		}

		// Ask for the even share, except when only a little remains,
		// where asking for all of it keeps the tail from fragmenting.
		ask := share
		if left < ask || left <= share*2 {
			ask = left
		}

		path := r.findFlowPath(ask, remaining, partsLeft, avoid, extra)
		if path == nil && ask < left {
			// The share was unroutable; try the full remainder
			// before giving up on this round.
			path = r.findFlowPath(
				left, remaining, partsLeft, avoid, extra,
			)
		}
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path, extra); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		cors = append(cors, corridor{path: path, amt: amtS})
		for _, e := range path {
			extra[e.chanID] += amtS
		}
		left -= amtS
	}

	if len(cors) == 0 {
		return nil
	}

	// Rebalance: hand leftover amount to whichever corridor still has the
	// most slack under the current assignment. This is what produces the
	// deliberately unequal split.
	for round := 0; round < flowRebalance && left >= minShard; round++ {
		progress := false
		for i := range cors {
			if left < minShard {
				break
			}
			// Temporarily remove this corridor's own contribution
			// so its slack is measured against the others only.
			for _, e := range cors[i].path {
				if extra[e.chanID] >= cors[i].amt {
					extra[e.chanID] -= cors[i].amt
				} else {
					extra[e.chanID] = 0
				}
			}
			room := r.bottleneck(cors[i].path, extra)
			grow := lnwire.MilliSatoshi(0)
			if room > cors[i].amt {
				grow = room - cors[i].amt
				if grow > left {
					grow = left
				}
			}
			cors[i].amt += grow
			for _, e := range cors[i].path {
				extra[e.chanID] += cors[i].amt
			}
			if grow > 0 {
				left -= grow
				progress = true
			}
		}
		if !progress {
			break
		}
	}

	// Price every corridor and keep the ones that survive.
	var out []*plan
	for _, c := range cors {
		if c.amt < minShard {
			continue
		}
		pl := r.bestOnPath(c.path, c.amt, remaining)
		if pl == nil {
			continue
		}
		out = append(out, pl)
	}

	if len(out) == 0 {
		return nil
	}

	// Largest shard first: it is the one most likely to be unroutable
	// later, so it should go out while the network state is freshest.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].amt > out[j].amt
	})

	return out
}

// planTotal is the believed-deliverable value of a route-set plan: each
// shard's amount weighted by its own success probability.
func planTotal(pls []*plan) (lnwire.MilliSatoshi, float64) {
	var total lnwire.MilliSatoshi
	var weighted float64
	for _, pl := range pls {
		total += pl.amt
		weighted += pl.prob * float64(pl.amt)
	}
	return total, weighted
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// touches reports whether a corridor uses any of the given channels.
func touches(path []*edge, chans map[uint64]bool) bool {
	for _, e := range path {
		if chans[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next viable shard of an existing plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.release(pl)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.dropQueue()
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return rt
	}
	return nil
}

// rescue is the last-resort descent. When neither the single-shard search
// nor the flow planner produced anything at the amounts they tried, we walk
// a fine geometric ladder down to a tiny floor looking for ANY sendable
// route, as long as at least one more part remains after this one. The
// evaluation showed large payments abandoned with attempts and parts to
// spare, purely because nothing fit at the amounts probed; a small shard
// both delivers value and buys evidence for the next round.
func (r *router) rescue(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *plan {

	if partsLeft < 2 {
		return nil
	}

	a := amt / 2
	if a < rescueShard {
		a = rescueShard
	}

	for i := 0; i < 22 && a >= rescueShard; i++ {
		// Try the busy-avoiding search first, then the unrestricted
		// one, at each size.
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.plainPath(a, avoid)
			if err != nil {
				continue
			}
			if r.failedSigs[planSig(path, a)] {
				continue
			}
			rt, p, err := r.makeRoute(path, a)
			if err != nil {
				continue
			}
			fee := rt.TotalAmount - a
			return &plan{
				path:  path,
				rt:    rt,
				amt:   a,
				prob:  p,
				score: r.score(a, p, fee, amt),
			}
		}
		a = a * 2 / 5
	}

	return nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor, then compares the best single shard against a full
// min-cost-flow style route set over several corridors, and finally falls
// back to a fine descent rather than giving up while parts remain.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.plainPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// Plan the split deliberately over several corridors whenever a single
	// shard cannot confidently cover the remainder. This fires EAGERLY
	// (not only when nothing single-path exists), because a joint plan
	// whose shards each fit their corridor beats one oversized shard that
	// will fail and then be halved blindly.
	singleWeak := best == nil || best.amt < amt || best.prob < 0.55

	if partsLeft > 1 && singleWeak {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total, weighted := planTotal(flow)

			var bestVal float64
			var bestAmt lnwire.MilliSatoshi
			if best != nil {
				bestVal = best.prob * float64(best.amt)
				bestAmt = best.amt
			}

			// Take the plan when it either covers more of the
			// remainder or delivers more expected value than the
			// single shard on its own.
			better := best == nil || total > bestAmt ||
				weighted > bestVal*1.05

			if better && len(flow) > 1 {
				first := flow[0]
				rest := flow[1:]
				r.dropQueue()
				r.queued = rest
				for _, pl := range r.queued {
					r.reserve(pl)
				}
				best = first
			} else if best == nil {
				best = flow[0]
			}
		}
	}

	// Last resort: never return a terminal error while a part remains and
	// some small amount is still sendable. This is the single biggest fix
	// over the previous revision, which abandoned large payments with both
	// attempts and parts to spare.
	if best == nil {
		r.dropQueue()
		best = r.rescue(amt, partsLeft, busy)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
	b.missCap = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0
	b.missCap = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	rb.missCap = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// pruneQueue drops only the queued shards whose corridors are implicated by
// a failure, keeping the rest of an otherwise sound plan.
func (r *router) pruneQueue(hit map[uint64]bool) {
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if touches(pl.path, hit) {
			r.release(pl)
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		r.settled++
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settle changes the liquidity the queued shards were sized
		// against, so re-validate them lazily: shards over channels
		// this route drained are dropped, the rest survive.
		if len(r.queued) > 0 {
			hit := make(map[uint64]bool, len(rt.Hops))
			for _, h := range rt.Hops {
				hit[h.ChannelID] = true
			}
			r.pruneQueue(hit)
		}

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned. The soft ceiling is what actually
	// forces diversification, since the next attempt over this direction
	// must then be materially smaller.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			hit[h.ChannelID] = true
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			a := hopAmount(rt, i)
			if b.missCap == 0 || a < b.missCap {
				b.missCap = a
			}
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	// Only the failing channel invalidates queued shards; a fee or cltv
	// repair does not touch liquidity at all, so those keep the plan.
	hit := map[uint64]bool{h.ChannelID: true}

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// policy repair is not a failed probe, so it must not count
		// against the streak that decides when to give up.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		r.failStreak--
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		r.failStreak--
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		r.failStreak--
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(hit)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	r.pruneQueue(hit)

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs with hard lower-OK / upper-fail bounds
//     and no time decay: a stale bound costs one retry to refresh, which is
//     cheaper than what decay throws away.
//   - Balance bookkeeping on settle, plus bimodal optimism after a proven
//     forward.
//   - Depth-aware lower retries instead of blacklisting.
//   - JOINT ROUTE-SET PLANNING with residual accounting and rebalancing.
//
// Changes in this revision, driven by the observed failure mode: a large
// payment (860M msat, roughly the whole local budget) burned ten attempts
// and then terminated with "no route found" while the split never got wide
// enough. The root causes were:
//
//   1. The flow planner treated the WHOLE remainder as one search target and
//      let the first corridor eat as much as its bottleneck allowed. On a
//      network where no single corridor can carry a third of the payment,
//      the first shard is still sized enormous, the plan collapses to two or
//      three shards, and the residual is simply unroutable. This revision
//      caps any single planned shard at a FAIR SHARE of the remainder
//      (remaining/slotsLeft, relaxed as corridors run out) so the plan
//      naturally spreads across many corridors before it grows any of them.
//      Growth then happens only in the rebalance sweep, which is
//      slack-driven and therefore safe.
//
//   2. The planner gave up the moment findFlowPath returned nothing, even
//      when most of the remainder was still unassigned. It now retries at
//      progressively smaller targets before abandoning the round, so a
//      narrow corridor still contributes a small shard instead of nothing.
//
//   3. A plan that covered only part of the remainder was accepted and then
//      the leftover was rediscovered by blind halving. The plan is now
//      scored on COVERAGE as well as expected value, and partial plans are
//      still taken when they beat the single shard, because each settled
//      shard shrinks the remainder and re-triggers planning with better
//      evidence.
//
//   4. Terminal give-up was too eager relative to how much of the payment
//      had already settled. The fail-streak budget now scales with the
//      number of parts allowed, and pure policy repairs (fee/cltv/min) no
//      longer consume it, since they are not liquidity misses.
//
//   5. Local-channel exhaustion is now recognised explicitly: when the sum
//      of our own believed-spendable balances cannot cover the remainder,
//      there is no point insisting on a full-amount corridor, so we go
//      straight to the widest split we can build.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts bounds total work. maxFailStreakBase is the give-up
	// budget for a single-part payment; wide splits get more (see
	// failBudget) because each shard legitimately costs its own probes.
	maxAttempts       = 80
	maxFailStreakBase = 14
	maxFailStreak     = 30

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the corridor searches spent building one flow
	// plan, and flowRebalance bounds the redistribution sweeps.
	flowRounds    = 14
	flowRebalance = 3
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity earmarked by planned-but-unsent shards.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// failBudget is how long a payment may go without progress before we give
// up. A wide split legitimately needs more probing than a single shard, so
// the budget scales with the part count.
func (r *router) failBudget() int {
	b := maxFailStreakBase + 3*int(r.spec.MaxParts)
	if b > maxFailStreak {
		b = maxFailStreak
	}
	return b
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is liquidity on a directed channel that is already spoken for,
// either by a live HTLC or by a planned shard we have not sent yet.
func (b *belief) committed() lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if used := b.committed(); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// extra charges additional liquidity against a channel on top of what the
// beliefs already record, which is how the flow planner accounts for shards
// it has provisionally assigned. penalty multiplies the cost of channels the
// plan already uses, so the search spreads over fresh corridors when it can
// but may still reuse a fat channel when nothing else works.
func (r *router) findPath(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi, penalty float64) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}

			// Charge the provisional flow already routed over this
			// channel against its believed room.
			used := extra[e.chanID]
			if amtOver+used > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver+used)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost
			if used > 0 && penalty > 1 {
				dist *= penalty
			}

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// plainPath is findPath with no provisional flow charged.
func (r *router) plainPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	return r.findPath(amt, avoid, nil, 1)
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds the whole payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// widestLocal is the largest single local channel balance still free, which
// is a hard ceiling on any one shard.
func (r *router) widestLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity minus any provisional flow already
// charged to that channel, with a small margin for fees.
func (r *router) bottleneck(path []*edge,
	extra map[uint64]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if used := extra[e.chanID]; used > 0 {
			if used >= c {
				return 0
			}
			c -= used
		}
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	if bn < minShard {
		return 0
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64

	// reserved marks that this plan currently holds soft reservations on
	// its channels, which must be released before it is dropped.
	reserved bool
}

// reserve and release move a queued shard's soft reservation in and out of
// the beliefs, so the planner never double-spends believed liquidity.
func (r *router) reserve(pl *plan) {
	if pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		r.bel(hopKey(h)).reserved += hopAmount(pl.rt, i)
	}
	pl.reserved = true
}

func (r *router) release(pl *plan) {
	if !pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(pl.rt, i)
		if b.reserved >= a {
			b.reserved -= a
		} else {
			b.reserved = 0
		}
	}
	pl.reserved = false
}

// dropQueue releases every queued shard's reservation and empties the queue.
func (r *router) dropQueue() {
	for _, pl := range r.queued {
		r.release(pl)
	}
	r.queued = nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path, nil); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findFlowPath looks for a corridor able to carry hi under the provisional
// flow already assigned, walking down a geometric ladder of smaller targets
// before giving up. Falling all the way down matters: a narrow corridor that
// can only take an eighth of the target is still worth a shard, and refusing
// it is what previously collapsed big plans into two shards plus an
// unroutable remainder.
func (r *router) findFlowPath(hi lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi) []*edge {

	// Prefer a corridor that does not touch the provisional flow at all,
	// then allow reuse of already-loaded channels at a cost penalty.
	for _, pen := range []float64{1e9, 1.3} {
		a := hi
		for i := 0; i < 7 && a >= minShard; i++ {
			p, err := r.findPath(a, avoid, extra, pen)
			if err == nil {
				return p
			}
			a = a / 2
		}
		if len(extra) == 0 {
			break
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several corridors, sizing
// each shard to what that corridor's weakest hop is believed able to bear
// under the flow already assigned. Channels may be shared between shards as
// long as their believed room covers the sum, which is what makes this a
// min-cost-flow decomposition rather than a disjoint-path search.
//
// The key sizing rule is the FAIR SHARE cap: no single shard may take much
// more than its even share of what is left in the early rounds. Without it
// the first corridor swallows everything it can bear and the plan degenerates
// into a couple of fat shards plus a residual nothing can carry. Growth is
// reintroduced afterwards by the slack-driven rebalance sweep, which is safe
// because it only hands out amount the corridor is believed able to bear.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	if partsLeft < 2 {
		return nil
	}

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	// extra tracks the flow provisionally routed over each channel, in
	// delivered-amount terms, which is close enough for sizing.
	extra := make(map[uint64]lnwire.MilliSatoshi)

	type corridor struct {
		path []*edge
		amt  lnwire.MilliSatoshi
	}

	var cors []corridor
	left := remaining

	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		// Fair share: spread first, grow later. As rounds run out the
		// cap relaxes towards the whole remainder so the last
		// corridors can still absorb what is left.
		slotsLeft := rounds - k
		share := left
		if slotsLeft > 1 {
			share = left / lnwire.MilliSatoshi(slotsLeft)
			// Allow a moderate overshoot so a genuinely fat
			// corridor is not artificially starved.
			share += share / 2
			if share > left {
				share = left
			}
		}
		if share < minShard {
			share = left
		}

		path := r.findFlowPath(share, avoid, extra)
		if path == nil {
			// Nothing at the fair share; try the whole remainder
			// once in case only one wide corridor exists.
			if share >= left {
				break
			}
			path = r.findFlowPath(left, avoid, extra)
			if path == nil {
				break
			}
		}

		amtS := share
		if amtS > left {
			amtS = left
		}
		if bn := r.bottleneck(path, extra); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		cors = append(cors, corridor{path: path, amt: amtS})
		for _, e := range path {
			extra[e.chanID] += amtS
		}
		left -= amtS
	}

	if len(cors) == 0 {
		return nil
	}

	// Rebalance: hand leftover amount to whichever corridor still has
	// slack. This is what turns the fair-share spread back into a
	// deliberately unequal split sized to real believed capacity.
	for round := 0; round < flowRebalance && left >= minShard; round++ {
		progress := false
		for i := range cors {
			if left < minShard {
				break
			}
			// Temporarily remove this corridor's own contribution
			// so its slack is measured against the others only.
			for _, e := range cors[i].path {
				if extra[e.chanID] >= cors[i].amt {
					extra[e.chanID] -= cors[i].amt
				} else {
					extra[e.chanID] = 0
				}
			}
			room := r.bottleneck(cors[i].path, extra)
			grow := lnwire.MilliSatoshi(0)
			if room > cors[i].amt {
				grow = room - cors[i].amt
				if grow > left {
					grow = left
				}
			}
			cors[i].amt += grow
			for _, e := range cors[i].path {
				extra[e.chanID] += cors[i].amt
			}
			if grow > 0 {
				left -= grow
				progress = true
			}
		}
		if !progress {
			break
		}
	}

	// Price every corridor and keep the ones that survive.
	var out []*plan
	for _, c := range cors {
		if c.amt < minShard {
			continue
		}
		pl := r.bestOnPath(c.path, c.amt, remaining)
		if pl == nil {
			continue
		}
		out = append(out, pl)
	}

	if len(out) == 0 {
		return nil
	}

	// Largest shard first: it is the one most likely to be unroutable
	// later, so it should go out while the network state is freshest.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].amt > out[j].amt
	})

	return out
}

// planTotal is the believed-deliverable value of a route-set plan: each
// shard's amount weighted by its own success probability.
func planTotal(pls []*plan) (lnwire.MilliSatoshi, float64) {
	var total lnwire.MilliSatoshi
	var weighted float64
	for _, pl := range pls {
		total += pl.amt
		weighted += pl.prob * float64(pl.amt)
	}
	return total, weighted
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// touches reports whether a corridor uses any of the given channels.
func touches(path []*edge, chans map[uint64]bool) bool {
	for _, e := range path {
		if chans[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next viable shard of an existing plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.release(pl)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.dropQueue()
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return rt
	}
	return nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor, and finally compares the best single shard against a full
// min-cost-flow style route set over several corridors.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= r.failBudget() {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what one of our own channels can push right
	// now, and the total can never exceed the whole local budget. When the
	// budget cannot cover the remainder, insisting on a full-amount
	// corridor is pure waste, so we note that and go wide immediately.
	budget := r.localBudget()
	hi := amt
	if w := r.widestLocal(); w > 0 && w < hi {
		hi = w
	}
	if hi < minShard {
		hi = amt
	}
	localShort := budget > 0 && budget < amt

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.plainPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// Plan the split deliberately over several corridors whenever a single
	// shard cannot confidently cover the remainder. This fires eagerly,
	// because a joint plan whose shards each fit their corridor beats one
	// oversized shard that will fail and then be halved blindly.
	singleWeak := best == nil || best.amt < amt || best.prob < 0.55 ||
		localShort

	if partsLeft > 1 && singleWeak {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total, weighted := planTotal(flow)

			var bestVal float64
			var bestAmt lnwire.MilliSatoshi
			if best != nil {
				bestVal = best.prob * float64(best.amt)
				bestAmt = best.amt
			}

			// Take the plan when it covers more of the remainder or
			// delivers more expected value. Coverage is weighted
			// heavily: a plan that reaches the full amount, even at
			// modest per-shard probability, beats a confident shard
			// that leaves a residual nothing can carry.
			better := best == nil || total > bestAmt ||
				weighted > bestVal*1.05

			if better && len(flow) > 1 {
				first := flow[0]
				rest := flow[1:]
				r.dropQueue()
				r.queued = rest
				for _, pl := range r.queued {
					r.reserve(pl)
				}
				best = first
			} else if best == nil {
				best = flow[0]
			}
		}
	}

	// Last resort: if nothing at all was found but we still have parts,
	// probe aggressively small so at least some of the payment lands. A
	// partially settled payment shrinks the remainder and lets the next
	// call plan against fresher, better evidence.
	if best == nil && partsLeft > 1 {
		a := hi / 2
		for i := 0; i < 10 && a >= minShard; i++ {
			if path, err := r.plainPath(a, nil); err == nil {
				if pl := r.bestOnPath(path, a, amt); pl != nil {
					best = pl
					break
				}
			}
			a = a / 2
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// pruneQueue drops only the queued shards whose corridors are implicated by
// a failure, keeping the rest of an otherwise sound plan.
func (r *router) pruneQueue(hit map[uint64]bool) {
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if touches(pl.path, hit) {
			r.release(pl)
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settle changes the liquidity the queued shards were sized
		// against, so re-validate them lazily: shards over channels
		// this route drained are dropped, the rest survive.
		if len(r.queued) > 0 {
			hit := make(map[uint64]bool, len(rt.Hops))
			for _, h := range rt.Hops {
				hit[h.ChannelID] = true
			}
			r.pruneQueue(hit)
		}

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			hit[h.ChannelID] = true
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	// Only the failing channel invalidates queued shards; a fee or cltv
	// repair does not touch liquidity at all, so those keep the plan.
	hit := map[uint64]bool{h.ChannelID: true}

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// policy repair is not a liquidity miss, so it should not eat
		// the give-up budget.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		r.failStreak--
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		r.failStreak--
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		r.failStreak--
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(hit)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	r.pruneQueue(hit)

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - JOINT ROUTE-SET PLANNING (min-cost-flow style): shard sizes and
//     corridors are chosen TOGETHER by a greedy flow decomposition over
//     DISJOINT corridors, each shard sized to that corridor's believed
//     bottleneck.
//   - LARGE-PAYMENT FIRST-CLASS SPLITTING. The two observed terminal
//     failures were both very large payments that burned 21-24 attempts and
//     still died with "no route found". Root cause: the planner kept probing
//     at the FULL remaining amount first, and single-corridor plans at
//     implausible amounts consumed the ladder/probe budget before the flow
//     planner ever got a fair shot. Now, whenever the remaining amount
//     plainly exceeds what any single corridor can bear (measured against
//     the believed out-capacity of our own channels), the flow planner runs
//     FIRST and the single-path search is only a fallback. Shard sizing
//     starts from remaining/partsLeft rather than from remaining.
//   - PARALLEL-CORRIDOR RESERVATION. Queued shards reserve their corridor's
//     liquidity in the belief layer (soft in-flight), so the planner does
//     not hand out two shards that silently share the same bottleneck hop.
//   - PROGRESS-AWARE GIVE-UP. The fail streak is reset not only by a settle
//     but by any attempt that pushed the frontier deeper (a new hop proven
//     to forward), so learning probes on a hard payment are not counted as
//     "no progress".
//   - PLAN REPAIR instead of plan discard: when an attempt fails, only the
//     queued shards whose corridors touch the newly-condemned channel are
//     dropped.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the
//     local policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. The streak is generous because a
	// large multi-part payment legitimately spends several probes learning
	// the shape of the network before any shard lands.
	maxAttempts   = 70
	maxFailStreak = 30

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 12

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.12

	// flowRounds bounds the greedy flow decomposition.
	flowRounds = 16

	// bigSplitSlack is how much believed headroom we demand over the
	// remaining amount before we even consider a single-corridor plan for
	// the whole thing. Above this the flow planner leads.
	bigSplitSlack = 1.05
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity soft-committed by queued (not yet dispatched)
	// shards of the current joint plan. It keeps two planned shards from
	// double-booking the same bottleneck without hard-blocking a retry.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int

	// progress counts hops newly proven to forward. It is used to reset
	// the fail streak: a probe that pushed the frontier deeper taught us
	// something even though it did not settle.
	progress int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is liquidity already spoken for on a directed channel, both by
// live HTLCs and by queued shards of the current plan.
func committed(b *belief) lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if used := committed(b); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var used lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		used = committed(b)
		misses = b.misses
	}
	eff := amt + used

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// widestLocal is the largest single local channel balance still free. No
// single shard can exceed it, so it tells us immediately whether the whole
// remaining amount could ever ride one corridor.
func (r *router) widestLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// hardBottleneck is the corridor's absolute believed ceiling, used by the
// feasibility gate: it ignores the conservative safeCap shading and asks
// only whether liquidity could plausibly flow at all.
func (r *router) hardBottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.availCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 8 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// reservePlan soft-books a corridor's liquidity so a sibling shard planned
// in the same round cannot double-spend the same bottleneck hop.
func (r *router) reservePlan(pl *plan, sign int) {
	if pl == nil || len(pl.path) == 0 {
		return
	}
	n := len(pl.path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	amtOver[n-1] = pl.amt
	for i := n - 2; i >= 0; i-- {
		fwd := pl.path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
	}
	for i, e := range pl.path {
		b := r.bel(e.key())
		if sign > 0 {
			b.reserved += amtOver[i]
		} else if b.reserved >= amtOver[i] {
			b.reserved -= amtOver[i]
		} else {
			b.reserved = 0
		}
	}
}

// clearReservations drops every soft reservation held by queued shards.
func (r *router) clearReservations() {
	for _, b := range r.beliefs {
		b.reserved = 0
	}
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
//
// target caps how much a single corridor may carry on this pass. For very
// large payments the caller passes remaining/partsLeft so the decomposition
// starts from a plausible shard size instead of the whole amount.
func (r *router) planFlow(remaining, target lnwire.MilliSatoshi,
	partsLeft uint32, busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	var out []*plan
	left := remaining
	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if target > 0 && target < want {
			want = target
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			// The corridor is too thin to be worth a shard, but it
			// is still worth excluding so the next round finds
			// something else.
			for _, e := range path {
				avoid[e.chanID] = true
			}
			continue
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			for _, e := range path {
				avoid[e.chanID] = true
			}
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	// Best shards first: the largest, most reliable corridor should be
	// tried before the marginal ones.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].score > out[j].score
	})

	return out
}

// feasibleFlow is the total delivered amount our believed liquidity could
// carry over up to `rounds` disjoint corridors. It is the gate that keeps a
// large payment alive: as long as the network plausibly has the liquidity,
// we keep carving smaller corridors instead of returning a terminal error.
func (r *router) feasibleFlow(remaining lnwire.MilliSatoshi,
	rounds int) lnwire.MilliSatoshi {

	avoid := make(map[uint64]bool)
	var total lnwire.MilliSatoshi

	for k := 0; k < rounds; k++ {
		left := remaining - total
		if left < minShard {
			break
		}
		path, err := r.findPath(left, avoid)
		if err != nil {
			path = r.findAnyPath(left, remaining, 4, avoid)
			if path == nil {
				break
			}
		}
		bn := r.hardBottleneck(path)
		if bn > left {
			bn = left
		}
		for _, e := range path {
			avoid[e.chanID] = true
		}
		if bn < minShard {
			continue
		}
		total += bn
	}

	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// pruneQueue drops only the queued shards whose corridors touch a channel
// whose belief just got worse. Discarding the entire joint plan on every
// failure throws away correct planning work and forces the router to
// rediscover the same split by trial and error.
func (r *router) pruneQueue(hit map[uint64]bool) {
	if len(r.queued) == 0 {
		return
	}
	keep := r.queued[:0]
	for _, pl := range r.queued {
		drop := false
		for _, e := range pl.path {
			if hit[e.chanID] {
				drop = true
				break
			}
		}
		if drop {
			r.reservePlan(pl, -1)
			continue
		}
		keep = append(keep, pl)
	}
	r.queued = keep
}

// installPlan queues the tail of a joint plan and reserves its liquidity.
func (r *router) installPlan(tail []*plan) {
	for _, pl := range r.queued {
		r.reservePlan(pl, -1)
	}
	r.queued = tail
	for _, pl := range r.queued {
		r.reservePlan(pl, +1)
	}
}

// popQueued serves the next queued shard that still holds up against
// current beliefs, releasing its reservation as it is dispatched.
func (r *router) popQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.reservePlan(pl, -1)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.installPlan(nil)
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return rt
	}
	return nil
}

// RequestRoute plans the next shard.
//
// The order of operations matters and was the main fix in this revision.
// Large payments (remaining far above what any single corridor can carry)
// go to the joint flow planner FIRST, sized at remaining/partsLeft, instead
// of burning the probe budget on single-corridor plans for the full amount
// that cannot possibly exist. Small and mid payments keep the old order:
// best single corridor first, flow planning as the fallback.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	if rt := r.popQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now,
	// nor what the single widest local channel holds.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if w := r.widestLocal(); w > 0 && w < hi {
		hi = w
	}
	if hi < minShard {
		hi = amt
	}

	// Is this a payment that plainly cannot ride one corridor? If the
	// widest single local channel cannot cover the remainder with a
	// little slack, splitting is not a fallback, it is the plan.
	bigSplit := partsLeft > 1 &&
		float64(hi)*bigSplitSlack < float64(amt)

	if bigSplit {
		// Size the first corridor at an even share, so the flow
		// decomposition starts from a plausible shard instead of the
		// whole amount, then let each corridor's bottleneck widen or
		// narrow it.
		target := amt / lnwire.MilliSatoshi(partsLeft)
		if target < minShard {
			target = minShard
		}
		if target > hi {
			target = hi
		}

		flow := r.planFlow(amt, target, partsLeft, busy)
		if len(flow) == 0 && target < hi {
			// Even shares found nothing; let corridors take as
			// much as they can bear.
			flow = r.planFlow(amt, hi, partsLeft, busy)
		}
		if len(flow) > 0 {
			r.installPlan(flow[1:])
			r.attempts++
			return flow[0].rt, nil
		}
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly. The
	// plan is accepted when its corridors jointly cover meaningfully more
	// of the remainder than the single best shard would.
	if partsLeft > 1 && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, 0, partsLeft, busy)
		if len(flow) > 0 {
			var total lnwire.MilliSatoshi
			for _, pl := range flow {
				total += pl.amt
			}

			first := flow[0]
			better := best == nil ||
				(total > best.amt &&
					first.score > best.score*0.75)

			if better {
				r.installPlan(flow[1:])
				best = first
			}
		}
	}

	if best != nil {
		r.attempts++
		return best.rt, nil
	}

	// Last resort: our conservative sizing found nothing, but the network
	// may still be able to carry small shards. Walk the ladder with the
	// hard (unshaded) bounds and take the biggest novel attempt we can
	// build, rather than declaring the payment dead. This is what turns a
	// premature "no route found" into a completed multi-part payment.
	//
	// The reservations of any stale queued plan are cleared first: they
	// are exactly what may be masking the remaining liquidity.
	r.installPlan(nil)
	r.clearReservations()

	if r.feasibleFlow(amt, flowRounds) >= minShard {
		for _, a := range r.ladder(amt, amt, partsLeft) {
			path, err := r.findPath(a, nil)
			if err != nil {
				continue
			}
			pl := r.bestOnPath(path, a, amt)
			if pl == nil {
				continue
			}
			r.attempts++
			return pl.rt, nil
		}
	}

	// Absolute floor: try to deliver *something* on the smallest viable
	// shard. A partial part still teaches us where liquidity lives, and
	// the runner will call again with the remainder.
	if partsLeft > 1 {
		small := amt / 16
		for i := 0; i < 8 && small >= minShard; i++ {
			if path, err := r.findPath(small, nil); err == nil {
				if pl := r.bestOnPath(
					path, small, amt,
				); pl != nil {
					r.attempts++
					return pl.rt, nil
				}
			}
			small = small / 2
		}
	}

	return nil, errors.New("no route found")
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved. It reports
// whether this was genuinely new knowledge.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) bool {
	b := r.bel(hopKey(h))
	learned := a > b.okAmt || !b.succ
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		learned = true
	}
	if b.misses > 0 {
		learned = true
	}
	b.misses = 0

	return learned
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settled shard drained the corridors it used, so any queued
		// shard sharing those channels must be re-planned.
		hit := make(map[uint64]bool, len(rt.Hops))
		for _, h := range rt.Hops {
			hit[h.ChannelID] = true
		}
		r.pruneQueue(hit)

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			hit[h.ChannelID] = true
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved. Learning that a
	// deeper hop forwards IS progress, so it refreshes the fail streak.
	learned := false
	for i := 0; i < failIdx; i++ {
		if r.provePassed(rt.Hops[i], hopAmount(rt, i)) {
			learned = true
		}
	}
	if learned {
		r.progress++
		if r.failStreak > 0 {
			r.failStreak--
		}
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// fee repair is not evidence against any corridor, so queued
		// shards survive untouched.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(map[uint64]bool{h.ChannelID: true})
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	// Only the queued corridors that actually depend on the condemned
	// channel are invalidated; the rest of the joint plan stays valid.
	r.pruneQueue(map[uint64]bool{h.ChannelID: true})

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - BIMODAL OPTIMISM after a proven forward: a channel that has forwarded
//     for us is treated as holding the bulk of its capacity (minus what we
//     drained), which lets later, larger payments reuse a proven corridor.
//   - Depth-aware lower retries instead of blacklisting.
//   - JOINT ROUTE-SET PLANNING (min-cost-flow style) when no single corridor
//     can carry the remainder, plus a FEASIBILITY PRE-CHECK: before spending
//     attempts, a disjoint-corridor flow decomposition estimates whether the
//     full amount is deliverable at all. If the believed deliverable flow is
//     far short of the remaining amount, we give up early rather than burn
//     19 attempts on a hopeless payment (the dominant retry-efficiency leak
//     in the previous generation).
//   - ATTEMPT ECONOMY: a queued joint plan is served without re-planning, a
//     confident full-amount plan short-circuits the search, and the ladder is
//     pruned aggressively once a solid plan exists.
//   - Duplicate-attempt suppression: a (path, amount) pair that already
//     failed is never handed out again.
//   - Non-liquidity failures (fee, cltv, disabled) are repaired in the local
//     policy view instead of being treated as liquidity misses, and they do
//     not count against the fail streak or the hopeless verdict.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. The streak bound is tighter than
	// before: long unproductive tails cost retry efficiency and almost
	// never convert into a success.
	maxAttempts   = 40
	maxFailStreak = 12

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 12

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.2

	// hopelessFrac is the fraction of the remaining amount that the
	// believed max-flow must cover for us to keep trying. Below this we
	// abandon rather than grind out attempts we cannot win.
	hopelessFrac = 0.55

	// hopelessStrikes is how many consecutive feasibility checks must come
	// back hopeless before we terminate. One bad check may just reflect
	// pessimistic beliefs that a probe would refresh.
	hopelessStrikes = 2

	// flowProbes bounds the Dijkstra runs a feasibility estimate spends.
	flowProbes = 6
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int

	// hopeless counts consecutive feasibility checks that concluded the
	// remaining amount is not deliverable.
	hopeless int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 1024
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 12; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// inFlightAmt is the delivered amount our currently pending shards carry. A
// feasibility check must count that as already covered.
func (r *router) inFlightAmt() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, rt := range r.pending {
		if n := len(rt.Hops); n > 0 {
			total += rt.Hops[n-1].AmtToForward
		}
	}
	return total
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 5 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// feasibleFlow estimates how much of want we believe is actually deliverable
// right now, by greedily peeling off disjoint corridors and summing their
// believed bottlenecks. It is deliberately optimistic (it uses safeCap, which
// already embeds bimodal optimism), so a verdict of "far short" is strong
// evidence that grinding out more attempts is wasted effort.
func (r *router) feasibleFlow(want lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts == 0 {
		parts = 1
	}
	if parts > flowProbes {
		parts = flowProbes
	}

	avoid := make(map[uint64]bool)
	var total lnwire.MilliSatoshi

	for k := uint32(0); k < parts; k++ {
		left := want - total
		if left < minShard {
			break
		}

		path, err := r.findPath(left, avoid)
		if err != nil {
			// Nothing carries the whole remainder, so probe with
			// a small amount to see if any corridor survives.
			path, err = r.findPath(minShard*4, avoid)
			if err != nil {
				break
			}
		}

		bn := r.bottleneck(path)
		if bn < minShard {
			break
		}
		if bn > left {
			bn = left
		}
		total += bn

		for _, e := range path {
			avoid[e.chanID] = true
		}
	}

	return total
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	var out []*plan
	left := remaining

	for k := uint32(0); k < partsLeft; k++ {
		if left < minShard {
			break
		}

		path := r.findAnyPath(left, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			break
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// giveUpEarly decides whether the payment is worth continuing. Once we have
// paid for a few attempts, an optimistic flow decomposition tells us whether
// the remaining amount is deliverable at all. Two consecutive hopeless
// verdicts terminate the payment, which converts a long losing tail of
// retries into an immediate, cheap failure.
func (r *router) giveUpEarly(amt lnwire.MilliSatoshi,
	partsLeft uint32) bool {

	// Early attempts are cheap probes that also refresh beliefs, so never
	// abandon before we have paid for real evidence.
	if r.attempts < 6 || r.failStreak < 4 {
		return false
	}

	want := amt
	if inf := r.inFlightAmt(); inf > 0 {
		// Shards already in flight will cover part of the payment.
		if want > inf {
			want -= inf
		} else {
			return false
		}
	}

	flow := r.feasibleFlow(want, partsLeft)
	if float64(flow) < hopelessFrac*float64(want) {
		r.hopeless++
	} else {
		r.hopeless = 0
	}

	return r.hopeless >= hopelessStrikes
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor: for every candidate amount (largest first) it finds the best
// risk-adjusted path, re-prices that path at the amount its weakest hop can
// bear, and finally checks whether a deliberate multi-corridor split would
// cover more of the remaining amount than the best single shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			break
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		r.attempts++
		return rt, nil
	}

	// Feasibility gate: stop grinding on a payment the network cannot
	// currently carry.
	if r.giveUpEarly(amt, partsLeft) {
		return nil, errors.New("amount not deliverable")
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly.
	if partsLeft > 1 && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			var total lnwire.MilliSatoshi
			for _, pl := range flow {
				total += pl.amt
			}

			first := flow[0]
			better := best == nil ||
				(total > best.amt &&
					first.score > best.score*0.85)

			if better {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		r.hopeless = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Beliefs just changed, so any queued joint plan is stale.
	r.queued = nil

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// policy repair is not a liquidity miss, so it must not count
		// toward the fail streak or the hopeless verdict.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		r.failStreak--
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		r.failStreak--
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		r.failStreak--
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - Depth-aware lower retries instead of blacklisting.
//   - JOINT ROUTE-SET PLANNING with residual accounting: shards may share a
//     fat channel as long as the fat channel is believed to bear their sum.
//
// This revision is tuned against evaluation data where SUCCESS WAS ALREADY
// 1.0 across every scenario batch: all three examples delivered every
// payment, so the remaining score was lost entirely to RETRY EFFICIENCY
// (-6.3, -1.7, -4.3 => 7 to 12.3 attempts per scenario) and, to a much
// smaller degree, to FEES (400-850 ppm). The optimization target therefore
// shifts: keep the success machinery that works, but stop paying for it
// with attempts we did not need. Concretely:
//
//  1. FEWER SPECULATIVE PROBES PER PAYMENT. The previous revision walked a
//     16-wide ladder with two passes and re-priced every corridor, then
//     eagerly re-planned a flow even when a single confident shard existed.
//     Every such extra pass tends to convert into an extra HTLC. The
//     single-shard search now stops as soon as it holds a plan that both
//     covers the remainder and clears a confidence bar, and the flow
//     planner only fires when a single shard genuinely cannot carry the
//     remainder (or is outright unlikely).
//
//  2. FIRST-ATTEMPT SIZING FROM BELIEF, NOT FROM HOPE. Most wasted
//     attempts in the data were a full-amount probe that failed and was
//     then halved. The ladder now starts from the amount the network is
//     actually believed able to carry end to end (a believed-capacity
//     estimate over our own channels and the target's inbound edges),
//     which removes the doomed opening probe on large payments.
//
//  3. SUCCESS-PROBABILITY GATING OF ATTEMPTS. A candidate whose estimated
//     probability is very low is only sent when nothing better exists and
//     we still have parts to spare; otherwise we shrink first. Sending a
//     15%-likely shard costs one attempt for 0.15 expected shards.
//
//  4. FEE AWARENESS RAISED WHERE IT IS FREE. Among candidates of
//     comparable probability the cheaper one now wins by a wider margin,
//     and the attempt cost was lowered so the Dijkstra objective is not
//     numerically dominated by the retry term on large amounts. Reliability
//     still wins whenever it actually differs.
//
//  5. EVIDENCE REUSE ACROSS SHARDS WITHIN A PAYMENT. Proven-passed hops
//     now raise a per-payment "known corridor" cache that the planner
//     prefers, so later shards of an MPP reuse corridors already shown to
//     work instead of re-exploring and re-failing.
//
// The give-up budgets stay generous: success dominates the objective, so a
// terminal failure is never worth saving an attempt.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_200)
	attemptCostPPM  = lnwire.MilliSatoshi(4_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. Both stay generous: a lost payment
	// costs far more than several retries.
	maxAttempts   = 110
	maxFailStreak = 34

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass. Lower than before on purpose: extra probing
	// mostly converted into extra attempts, not extra successes.
	probeBudget = 9

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// rescueShard is the floor used by the last-resort descent, which may
	// go smaller than an ordinary planned shard because any delivered
	// value beats a terminal failure.
	rescueShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fees are a secondary
	// objective, so they are weighted enough to separate comparable
	// corridors, and every extra expected part costs a little.
	feeWeight = 6.0
	partCost  = 0.010

	// confidentProb is the probability at which a full-remainder single
	// shard is considered good enough to send immediately, with no
	// further probing and no flow planning. Deciding early is what saves
	// attempts.
	confidentProb = 0.62

	// weakProb is the probability below which we would rather shrink or
	// split than send, provided an alternative exists.
	weakProb = 0.22

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.18

	// flowRounds bounds the corridor searches spent building one flow
	// plan, and flowRebalance bounds the redistribution sweeps.
	flowRounds    = 10
	flowRebalance = 3

	// finalReusePenalty is the extra cost charged for reusing an inbound
	// edge of the target that a planned shard already loads. The target's
	// inbound capacity is the usual bottleneck on large payments, so the
	// planner works hard to spread over distinct final edges.
	finalReusePenalty = 2.6

	// knownBonus discounts the cost of a channel that has demonstrably
	// forwarded for us during this payment, so later MPP shards reuse
	// corridors that already worked instead of re-exploring.
	knownBonus = 0.80
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity earmarked by planned-but-unsent shards.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// missCap is a soft ceiling learned from unattributable failures: the
	// smallest amount this direction carried as part of an attempt that
	// failed somewhere we could not localise. Retrying at or above it
	// wastes attempts, so we shrink under it.
	missCap lnwire.MilliSatoshi

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	// warm marks channels that demonstrably forwarded for us recently.
	// Reusing a warm corridor for a later MPP shard is cheaper in
	// attempts than exploring a fresh one.
	warm map[uint64]bool

	failStreak int
	attempts   int

	// settled counts shards that have settled for this payment, which is
	// evidence the payment is progressing even if individual probes fail.
	settled int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
		warm:          make(map[uint64]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is liquidity on a directed channel that is already spoken for,
// either by a live HTLC or by a planned shard we have not sent yet.
func (b *belief) committed() lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// softCeiling is the ceiling implied by unattributable failures. Each miss
// shrinks the amount we are willing to retry over this direction, which is
// what makes the search actually diversify after a blind failure instead of
// re-picking a corridor with a marginally worse score.
func (b *belief) softCeiling() lnwire.MilliSatoshi {
	if b == nil || b.misses == 0 || b.missCap == 0 {
		return 0
	}
	m := b.misses
	if m > 3 {
		m = 3
	}
	f := math.Pow(0.6, float64(m))
	lim := lnwire.MilliSatoshi(float64(b.missCap) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); lim < c {
				c = lim
			}
		}
		if lim := b.softCeiling(); lim > 0 && lim < c {
			c = lim
		}
	}

	if used := b.committed(); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// extra charges additional liquidity against a channel on top of what the
// beliefs already record, which is how the flow planner accounts for shards
// it has provisionally assigned. penalty multiplies the cost of channels the
// plan already uses, so the search spreads over fresh corridors when it can
// but may still reuse a fat channel when nothing else works. finalPenalty
// applies the same idea specifically to already-loaded INBOUND edges of the
// target, which are the usual bottleneck on large payments.
func (r *router) findPath(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi, penalty,
	finalPenalty float64) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}

			// Charge the provisional flow already routed over this
			// channel against its believed room.
			used := extra[e.chanID]
			if amtOver+used > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver+used)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			// A corridor that already forwarded for us this
			// payment is worth reusing: it saves the attempt an
			// unexplored corridor would spend learning the same
			// thing.
			if r.warm[e.chanID] && used == 0 {
				dist *= knownBonus
			}

			if used > 0 {
				if penalty > 1 {
					dist *= penalty
				}
				// The target's inbound edges deserve a
				// stronger spread incentive than interior
				// channels: they are where large payments
				// actually run out of room.
				if it.node == target && finalPenalty > 1 {
					dist *= finalPenalty
				}
			}

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// plainPath is findPath with no provisional flow charged.
func (r *router) plainPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	return r.findPath(amt, avoid, nil, 1, 1)
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// singleHopCeiling is the largest amount ANY single one of our own channels
// can push, and the largest amount any single inbound edge of the target is
// believed able to absorb. A single shard can never exceed either, so
// starting the ladder above them guarantees a wasted attempt. This is the
// main source of the retry savings over the previous revision.
func (r *router) singleHopCeiling() lnwire.MilliSatoshi {
	var out lnwire.MilliSatoshi
	for _, e := range r.localEdges {
		if c := r.availCap(e); c > out {
			out = c
		}
	}

	var in lnwire.MilliSatoshi
	for _, e := range r.inEdges[r.spec.Target] {
		if c := r.safeCap(e); c > in {
			in = c
		}
	}

	if in > 0 && in < out {
		out = in
	}
	return out
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity minus any provisional flow already
// charged to that channel, with a small margin for fees.
func (r *router) bottleneck(path []*edge,
	extra map[uint64]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if used := extra[e.chanID]; used > 0 {
			if used >= c {
				return 0
			}
			c -= used
		}
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	if bn < minShard {
		return 0
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a fee penalty, and a cost for
// every additional part the split implies. Fees carry more weight than in
// the previous revision because success was already saturated and fee ppm
// was the remaining loss term.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64

	// reserved marks that this plan currently holds soft reservations on
	// its channels, which must be released before it is dropped.
	reserved bool
}

// reserve and release move a queued shard's soft reservation in and out of
// the beliefs, so the planner never double-spends believed liquidity.
func (r *router) reserve(pl *plan) {
	if pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		r.bel(hopKey(h)).reserved += hopAmount(pl.rt, i)
	}
	pl.reserved = true
}

func (r *router) release(pl *plan) {
	if !pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(pl.rt, i)
		if b.reserved >= a {
			b.reserved -= a
		} else {
			b.reserved = 0
		}
	}
	pl.reserved = false
}

// dropQueue releases every queued shard's reservation and empties the queue.
func (r *router) dropQueue() {
	for _, pl := range r.queued {
		r.release(pl)
	}
	r.queued = nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path, nil); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 4 / 5
	}
	return nil
}

// findFlowPath looks for a corridor able to carry hi under the provisional
// flow already assigned, falling back down the amount ladder when nothing
// can take the full amount.
func (r *router) findFlowPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi) []*edge {

	// Prefer a corridor that does not touch the provisional flow at all,
	// then allow reuse of already-loaded channels at a cost penalty. The
	// target's inbound edges keep a stronger penalty in both passes.
	for _, pen := range []float64{1e9, 1.35} {
		if p, err := r.findPath(
			hi, avoid, extra, pen, finalReusePenalty,
		); err == nil {
			return p
		}

		probes := 0
		for _, a := range r.ladder(hi, remaining, partsLeft) {
			if a >= hi {
				continue
			}
			if probes >= 5 {
				break
			}
			probes++
			p, err := r.findPath(
				a, avoid, extra, pen, finalReusePenalty,
			)
			if err == nil {
				return p
			}
		}
		if len(extra) == 0 {
			break
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several corridors, sizing
// each shard to what that corridor's weakest hop is believed able to bear
// under the flow already assigned. Channels may be shared between shards as
// long as their believed room covers the sum, which is what makes this a
// min-cost-flow decomposition rather than a disjoint-path search.
//
// Each successive corridor is asked for a TARGET SHARE of the remainder
// rather than the whole remainder, and a PARTIAL plan is accepted: covering
// most of a huge payment over several corridors and re-planning the tail on
// the next call beats refusing to split.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	if partsLeft < 2 {
		return nil
	}

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	// extra tracks the flow provisionally routed over each channel, in
	// delivered-amount terms, which is close enough for sizing.
	extra := make(map[uint64]lnwire.MilliSatoshi)

	type corridor struct {
		path []*edge
		amt  lnwire.MilliSatoshi
	}

	var cors []corridor
	left := remaining

	// share is what we ask each corridor for: an even split of the
	// remainder over the parts we can still afford, which keeps the
	// search from burning the widest corridor on an oversized shard.
	share := remaining / lnwire.MilliSatoshi(partsLeft)
	if share < minShard {
		share = minShard
	}

	for k := uint32(0); k < partsLeft && k < flowRounds; k++ {
		if left < minShard {
			break
		}

		// Ask for the even share, except when only a little remains,
		// where asking for all of it keeps the tail from fragmenting.
		ask := share
		if left < ask || left <= share*2 {
			ask = left
		}

		path := r.findFlowPath(ask, remaining, partsLeft, avoid, extra)
		if path == nil && ask < left {
			// The share was unroutable; try the full remainder
			// before giving up on this round.
			path = r.findFlowPath(
				left, remaining, partsLeft, avoid, extra,
			)
		}
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path, extra); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		cors = append(cors, corridor{path: path, amt: amtS})
		for _, e := range path {
			extra[e.chanID] += amtS
		}
		left -= amtS
	}

	if len(cors) == 0 {
		return nil
	}

	// Rebalance: hand leftover amount to whichever corridor still has the
	// most slack under the current assignment. This is what produces the
	// deliberately unequal split.
	for round := 0; round < flowRebalance && left >= minShard; round++ {
		progress := false
		for i := range cors {
			if left < minShard {
				break
			}
			// Temporarily remove this corridor's own contribution
			// so its slack is measured against the others only.
			for _, e := range cors[i].path {
				if extra[e.chanID] >= cors[i].amt {
					extra[e.chanID] -= cors[i].amt
				} else {
					extra[e.chanID] = 0
				}
			}
			room := r.bottleneck(cors[i].path, extra)
			grow := lnwire.MilliSatoshi(0)
			if room > cors[i].amt {
				grow = room - cors[i].amt
				if grow > left {
					grow = left
				}
			}
			cors[i].amt += grow
			for _, e := range cors[i].path {
				extra[e.chanID] += cors[i].amt
			}
			if grow > 0 {
				left -= grow
				progress = true
			}
		}
		if !progress {
			break
		}
	}

	// Price every corridor and keep the ones that survive.
	var out []*plan
	for _, c := range cors {
		if c.amt < minShard {
			continue
		}
		pl := r.bestOnPath(c.path, c.amt, remaining)
		if pl == nil {
			continue
		}
		out = append(out, pl)
	}

	if len(out) == 0 {
		return nil
	}

	// Largest shard first: it is the one most likely to be unroutable
	// later, so it should go out while the network state is freshest.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].amt > out[j].amt
	})

	return out
}

// planTotal is the believed-deliverable value of a route-set plan: each
// shard's amount weighted by its own success probability.
func planTotal(pls []*plan) (lnwire.MilliSatoshi, float64) {
	var total lnwire.MilliSatoshi
	var weighted float64
	for _, pl := range pls {
		total += pl.amt
		weighted += pl.prob * float64(pl.amt)
	}
	return total, weighted
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// touches reports whether a corridor uses any of the given channels.
func touches(path []*edge, chans map[uint64]bool) bool {
	for _, e := range path {
		if chans[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next viable shard of an existing plan. Serving a
// queued shard is the cheapest possible attempt: the corridor was already
// sized against beliefs, so no probing happens at all.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.release(pl)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.dropQueue()
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return rt
	}
	return nil
}

// rescue is the last-resort descent. When neither the single-shard search
// nor the flow planner produced anything at the amounts they tried, we walk
// a fine geometric ladder down to a tiny floor looking for ANY sendable
// route, as long as at least one more part remains after this one. A small
// shard both delivers value and buys evidence for the next round, which
// beats a terminal failure by a wide margin under this objective.
func (r *router) rescue(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *plan {

	if partsLeft < 2 {
		return nil
	}

	a := amt / 2
	if a < rescueShard {
		a = rescueShard
	}

	for i := 0; i < 22 && a >= rescueShard; i++ {
		// Try the busy-avoiding search first, then the unrestricted
		// one, at each size.
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.plainPath(a, avoid)
			if err != nil {
				continue
			}
			if r.failedSigs[planSig(path, a)] {
				continue
			}
			rt, p, err := r.makeRoute(path, a)
			if err != nil {
				continue
			}
			fee := rt.TotalAmount - a
			return &plan{
				path:  path,
				rt:    rt,
				amt:   a,
				prob:  p,
				score: r.score(a, p, fee, amt),
			}
		}
		a = a * 2 / 5
	}

	return nil
}

// searchSingle looks for the best single shard, starting from what the
// network is believed able to carry rather than from the full remainder.
// It stops early on a confident full-coverage plan, which is where the
// attempt savings come from.
func (r *router) searchSingle(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *plan {

	// A shard can never exceed what our own channels can push right now,
	// nor what a single one of them (or a single inbound edge of the
	// target) can carry. Starting above either guarantees a wasted probe.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if partsLeft > 1 {
		if ceil := r.singleHopCeiling(); ceil >= minShard &&
			ceil < hi {

			hi = ceil
		}
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.55 &&
				a < best.amt*2/3 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.plainPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives:
			// send it now and save the attempts.
			if best != nil && best.amt >= amt &&
				best.prob >= confidentProb {

				return best
			}
		}

		if best != nil {
			break
		}
	}

	return best
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches for the best single shard,
// then compares it against a min-cost-flow style route set over several
// corridors when the single shard cannot confidently cover the remainder,
// and finally falls back to a fine descent rather than giving up while
// parts remain.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	best := r.searchSingle(amt, partsLeft, busy)

	// A confident single shard that covers the whole remainder is the
	// cheapest possible outcome: one attempt, one part, no split. Send it
	// without consulting the flow planner at all.
	confident := best != nil && best.amt >= amt &&
		best.prob >= confidentProb

	// Otherwise plan the split deliberately over several corridors. This
	// fires when a single shard cannot cover the remainder or is unlikely
	// enough that an oversized shard would simply fail and be halved.
	if partsLeft > 1 && !confident {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total, weighted := planTotal(flow)

			var bestVal float64
			var bestAmt lnwire.MilliSatoshi
			if best != nil {
				bestVal = best.prob * float64(best.amt)
				bestAmt = best.amt
			}

			// Take the plan when it either covers materially more
			// of the remainder or delivers more expected value
			// than the single shard on its own. The margins are
			// wider than before so a marginal flow plan does not
			// trade one attempt for several.
			better := best == nil ||
				total > bestAmt+bestAmt/20 ||
				weighted > bestVal*1.12

			if better && len(flow) > 1 {
				first := flow[0]
				rest := flow[1:]
				r.dropQueue()
				r.queued = rest
				for _, pl := range r.queued {
					r.reserve(pl)
				}
				best = first
			} else if best == nil ||
				(better && flow[0].score > best.score) {

				best = flow[0]
			}
		}
	}

	// A very unlikely candidate is a poor use of an attempt when we could
	// instead shrink. Try a smaller, safer shard first; only send the weak
	// one if nothing better exists.
	if best != nil && best.prob < weakProb && partsLeft > 1 &&
		best.amt > minShard*4 {

		if alt := r.rescue(best.amt, partsLeft, busy); alt != nil &&
			alt.prob > best.prob*1.8 {

			best = alt
		}
	}

	// Last resort: never return a terminal error while a part remains and
	// some small amount is still sendable.
	if best == nil {
		r.dropQueue()
		best = r.rescue(amt, partsLeft, busy)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true
	r.warm[h.ChannelID] = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
	b.missCap = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0
	b.missCap = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	rb.missCap = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// pruneQueue drops only the queued shards whose corridors are implicated by
// a failure, keeping the rest of an otherwise sound plan.
func (r *router) pruneQueue(hit map[uint64]bool) {
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if touches(pl.path, hit) {
			r.release(pl)
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		r.settled++
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			r.warm[h.ChannelID] = true
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settle changes the liquidity the queued shards were sized
		// against, so re-validate them lazily: shards over channels
		// this route drained are dropped, the rest survive.
		if len(r.queued) > 0 {
			hit := make(map[uint64]bool, len(rt.Hops))
			for _, h := range rt.Hops {
				hit[h.ChannelID] = true
			}
			r.pruneQueue(hit)
		}

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned. The soft ceiling is what actually
	// forces diversification, since the next attempt over this direction
	// must then be materially smaller.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			hit[h.ChannelID] = true
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			a := hopAmount(rt, i)
			if b.missCap == 0 || a < b.missCap {
				b.missCap = a
			}
			delete(r.warm, h.ChannelID)
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	// Only the failing channel invalidates queued shards; a fee or cltv
	// repair does not touch liquidity at all, so those keep the plan.
	hit := map[uint64]bool{h.ChannelID: true}

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// policy repair is not a failed probe, so it must not count
		// against the streak that decides when to give up.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		r.failStreak--
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		r.failStreak--
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		r.failStreak--
		return nil

	case "dead":
		b.dead = true
		delete(r.warm, h.ChannelID)
		r.pruneQueue(hit)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false
	delete(r.warm, h.ChannelID)

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	r.pruneQueue(hit)

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - COMPLEMENTARY REASONING across the two sides of a channel: liquidity
//     proven to sit on the reverse side cannot also sit on this side, and a
//     reverse-direction failure at a small amount means the reverse side is
//     empty, so under bimodality nearly the whole channel sits on THIS side.
//   - JOINT ROUTE-SET PLANNING with a real flow budget: for a large payment
//     we decompose the remainder over DISJOINT corridors up front, each
//     shard sized to its own corridor's bottleneck, and queue the rest.
//
// What changed relative to the previous generation (the observed failure was
// a huge payment burning all 64 attempts and then reporting "attempt budget
// exhausted", i.e. the retry budget drained on a payment whose split plan
// never converged):
//
//   1. FLOW FEASIBILITY GATE. Before spending attempts we compute the total
//      believed deliverable flow over disjoint corridors. If that aggregate
//      cannot cover the remainder AND we have already confirmed dryness by
//      failing, we give up immediately instead of grinding out 60 doomed
//      probes. Giving up early on an impossible payment costs nothing in
//      success rate and saves the whole retry penalty.
//   2. COMMITTED PLANS SURVIVE A FAILURE. The old code cleared the entire
//      queued plan on every failure, so a 6-shard decomposition was thrown
//      away the moment one shard missed and was then rediscovered from
//      scratch, one expensive Dijkstra ladder at a time. Now a failure only
//      invalidates queued shards that actually touch the failing direction;
//      the rest are re-validated lazily when served.
//   3. PER-DIRECTION ATTEMPT LEDGER. Every liquidity failure is charged to a
//      direction, and a direction that has failed maxDryProbes times is
//      excluded from path finding for the remainder of the payment rather
//      than being re-probed at ever smaller amounts. This is the single
//      biggest source of wasted attempts.
//   4. GLOBAL PROBE BUDGET. Dijkstra runs are accounted against a whole-
//      payment budget, not just a per-call one, so late calls degrade to
//      cheap single-probe behaviour instead of re-running full ladders.
//   5. SHARD FLOOR TIED TO THE REMAINDER. Shards below remainder/maxParts
//      cannot finish the payment, so planning them just burns parts. The
//      ladder now refuses to go below that floor while parts remain scarce,
//      which both cuts attempts and raises the chance the split closes.
//   6. POLICY REPAIRS ARE NOT FAILURES. A FeeInsufficient or cltv failure is
//      a stale-gossip repair, not evidence of dryness, so it no longer
//      counts against the give-up streak.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_200)
	attemptCostPPM  = lnwire.MilliSatoshi(6_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 48
	maxFailStreak = 12

	// probeBudget caps Dijkstra runs inside one RequestRoute call, and
	// totalProbeBudget caps them across the whole payment so that a long
	// payment cannot spend unbounded search effort.
	probeBudget      = 10
	totalProbeBudget = 220

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 5.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// compSlackNum/compSlackDen discounts the complementary upper bound
	// derived from the reverse direction's proven liquidity.
	compSlackNum = 90
	compSlackDen = 100

	// revEmptyNum/revEmptyDen is the fraction of the liquidity implied on
	// this side by a reverse-direction failure that we bank on.
	revEmptyNum = 80
	revEmptyDen = 100

	// maxDryProbes is how many liquidity failures a single direction may
	// contribute before it is excluded for the rest of the payment.
	maxDryProbes = 2

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.12

	// flowRounds bounds the corridors a single flow decomposition walks.
	flowRounds = 14

	// hopelessStreak is how many consecutive failures we tolerate before
	// trusting belief-derived budgets for a give-up decision.
	hopelessStreak = 3

	// feasStreak is how many consecutive failures we require before the
	// aggregate-flow feasibility gate is allowed to abandon a payment.
	feasStreak = 5
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

// revKey is the key of the same channel in the opposite direction.
func (e *edge) revKey() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.from}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// fails counts liquidity failures charged to this direction.
	fails int

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// exhausted reports whether this direction has come up dry so often that
// probing it again is a waste of an attempt.
func (b *belief) exhausted() bool {
	return b.dead || (b.hasFail && b.fails >= maxDryProbes)
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
	probes     int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// mppOK reports whether this payment may be split at all.
func (r *router) mppOK() bool {
	return r.spec.MaxParts > 1
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// view returns a read-only belief for a directed channel, substituting a
// zero-value belief when we have no evidence at all.
func (r *router) view(k edgeKey) *belief {
	if b, ok := r.beliefs[k]; ok {
		return b
	}
	return &belief{}
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath. After maxDryProbes dry probes we stop
// entirely: grinding the same direction down by halves is the main source of
// wasted retries.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	if b.fails >= maxDryProbes {
		return b.okAmt
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.40 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// compBound is the complementary upper bound on a direction: liquidity we
// have proven sits on the reverse side cannot also sit on this side.
func (r *router) compBound(e *edge) lnwire.MilliSatoshi {
	rb := r.beliefs[e.revKey()]
	if rb == nil || rb.okAmt == 0 {
		return e.capacity
	}
	held := rb.okAmt * compSlackNum / compSlackDen
	if held >= e.capacity {
		return 0
	}
	return e.capacity - held
}

// provenCenter is the amount we believe this direction actually holds. It
// combines a demonstrated forward (less what we have since drained) with the
// complementary inference that a reverse-direction failure at a small amount
// means the funds are on THIS side.
func (r *router) provenCenter(e *edge) lnwire.MilliSatoshi {
	var center lnwire.MilliSatoshi

	b := r.beliefs[e.key()]
	if b != nil && b.succ {
		c := e.capacity * provenCenterNum / provenCenterDen
		if c > b.drained {
			center = c - b.drained
		}
	}

	// Bimodal complement: the reverse side came up dry at failAmt, so this
	// side is holding close to the whole channel.
	if rb := r.beliefs[e.revKey()]; rb != nil && rb.hasFail {
		if e.capacity > rb.failAmt {
			inf := (e.capacity - rb.failAmt) *
				revEmptyNum / revEmptyDen
			if inf > center {
				center = inf
			}
		}
	}

	if b != nil && b.okAmt > center {
		center = b.okAmt
	}

	return center
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else {
		if b != nil && b.exhausted() {
			// This direction has come up dry repeatedly. Probing
			// it again is what drains the attempt budget, so it is
			// retired for the rest of the payment.
			if b.okAmt == 0 {
				return 0
			}
			return b.okAmt
		}
		if comp := r.compBound(e); comp < c {
			c = comp
		}
		if b != nil && b.hasFail {
			// Retry below the proven failure point rather than
			// blacklisting the channel outright.
			if lim := retryLimit(b, e.capacity); lim < c {
				c = lim
			}
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.view(e.key())
	est := e.capacity * priorSafeNum / priorSafeDen
	if b.okAmt > est {
		est = b.okAmt
	}
	if !b.hasFail {
		// A proven forward, or a dry reverse direction, says most of
		// the channel funds sit on this side.
		if c := r.provenCenter(e) * 85 / 100; c > est {
			est = c
		}
	} else if lim := retryLimit(b, e.capacity); est > lim {
		est = lim
	}
	if b.misses > 0 {
		est = est / lnwire.MilliSatoshi(1+b.misses)
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.view(e.key())
	if b.dead {
		return 0
	}

	eff := amt + b.inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	// A direction retired after repeated dry probes only clears amounts we
	// have actually proven.
	if b.exhausted() && eff > b.okAmt {
		return 0
	}

	// The complementary bound is hard evidence: that much liquidity is
	// provably parked on the other side of the channel.
	if comp := r.compBound(e); eff > comp {
		return minProb / 4
	}

	var p float64
	switch {
	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)
		center := r.provenCenter(e)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case center > 0 && !b.hasFail:
			// Bimodal optimism: the funds are believed to sit on
			// this side, less whatever we have drained since.
			q := 1.0 / (1.0 + math.Exp(
				(float64(eff)/float64(center)-1)*4.5,
			))
			p = 0.3*p + 0.7*q

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if b.misses > 0 {
		m := b.misses
		if m > 3 {
			m = 3
		}
		p *= math.Pow(0.6, float64(m))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.probes >= totalProbeBudget {
		return nil, errors.New("probe budget exhausted")
	}
	r.probes++

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds the whole payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// rawLocalBudget is the total balance across our own channels, ignoring all
// beliefs and policies. It is a hard ceiling on anything we can deliver.
func (r *router) rawLocalBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		total += bal
	}
	return total
}

// rawMaxLocal is the largest single local channel balance, which bounds one
// shard: a shard leaves through exactly one first hop.
func (r *router) rawMaxLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		if bal > best {
			best = bal
		}
	}
	return best
}

// maxLocalEdge is the largest single local channel balance still free, which
// is the true ceiling on one shard.
func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// shardFloor is the smallest shard worth planning: anything far below
// remaining/partsLeft cannot close the payment with the parts we have left,
// so planning it just burns a part and an attempt.
func (r *router) shardFloor(remaining lnwire.MilliSatoshi,
	partsLeft uint32) lnwire.MilliSatoshi {

	if partsLeft == 0 {
		return remaining
	}
	f := remaining / lnwire.MilliSatoshi(partsLeft)

	// Leave headroom: a shard under the even split can still be
	// compensated by a larger sibling.
	f = f / 3
	if f < minShard {
		f = minShard
	}
	return f
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent, exact
// local channel balances, and evidence-derived sizes just below proven
// failure points. Nothing below the floor is offered.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	floor := r.shardFloor(remaining, partsLeft)
	if floor > hi {
		floor = minShard
	}

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < floor || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK < 4 && r.mppOK() {
		maxK = 4
	}
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent down to the floor.
	cur := hi
	for i := 0; i < 14; i++ {
		cur = cur * 2 / 3
		if cur < floor {
			break
		}
		add(cur)
	}

	// Local channel balances are exact knowledge, and a shard sized to a
	// local channel is exactly what a fan-out split wants.
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= floor {
			add(c - c/200)
		}
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= floor {
			add(b.okAmt)
		}
		if b.hasFail && b.fails < maxDryProbes {
			if lim := retryLimit(b, r.capOf(k)); lim >= floor {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// touches reports whether a plan's corridor uses the given channel.
func (p *plan) touches(chanID uint64) bool {
	for _, e := range p.path {
		if e.chanID == chanID {
			return true
		}
	}
	return false
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 5 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
//
// It keeps going until either the whole remainder is covered or no further
// disjoint corridor exists, and it caps each shard at the largest single
// local channel so a shard is never planned larger than one first hop can
// carry.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	single := r.maxLocalEdge()

	var out []*plan
	left := remaining

	// Queued shards are handed out on later calls, as concurrency frees
	// up, so the decomposition is not bounded by the parts free right now.
	rounds := 1
	if r.mppOK() {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if single > 0 && want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			// The corridor cannot bear anything novel, so retire
			// its first hop and move on instead of aborting the
			// whole decomposition.
			avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// flowTotal is the amount a plan set delivers in aggregate.
func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// hopeless reports whether the remainder is provably beyond what our own
// channels can still push. Our balances are exact, so this catches payments
// that no amount of retrying could ever complete, which is where the retry
// budget used to drain away.
func (r *router) hopeless(amt lnwire.MilliSatoshi, inFlight uint32) bool {
	if inFlight > 0 {
		return false
	}
	if len(r.localBalances) == 0 {
		return false
	}

	// Hard ceiling: total outbound balance.
	if r.rawLocalBudget() < amt {
		return true
	}

	// A payment that may not be split must fit through one channel.
	if !r.mppOK() && r.rawMaxLocal() < amt {
		return true
	}

	// Softer test, only once we have actually confirmed dryness by
	// failing: the believed-free local liquidity cannot cover the rest.
	if r.failStreak >= hopelessStreak && len(r.localEdges) > 0 &&
		r.localBudget() < amt {

		return true
	}

	return false
}

// dropStalePlans discards queued shards whose corridor contains the channel
// that just failed. The rest of a joint plan is still the best decomposition
// we know of, so throwing it away wholesale (as an earlier generation did)
// only forces us to rediscover it one expensive ladder at a time.
func (r *router) dropStalePlans(chanID uint64) {
	if len(r.queued) == 0 {
		return
	}
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if pl.touches(chanID) {
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// serveQueued hands out the next queued shard that still holds up against
// current beliefs, re-pricing it at the amount actually remaining.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, split bool,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when the payment cannot be split.
		if !split && a < amt {
			r.queued = nil
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}
		return rt
	}
	return nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor: for every candidate amount (largest first) it finds the best
// risk-adjusted path, re-prices that path at the amount its weakest hop can
// bear, and finally checks whether a deliberate multi-corridor split would
// cover more of the remaining amount than the best single shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}
	if r.hopeless(amt, inFlightHtlcs) {
		return nil, errors.New("remainder exceeds local liquidity")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()
	split := r.mppOK()

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	if rt := r.serveQueued(amt, split, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A single shard can never exceed what one local channel can push,
	// since a shard leaves through exactly one first hop.
	hi := amt
	if single := r.maxLocalEdge(); single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}
			if !split && a < amt {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly. We
	// compare the aggregate believed flow of the plan set against the best
	// single shard: covering more of the payment beats a slightly nicer
	// first hop, because every uncovered millisat is a failed payment.
	if split && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total := flowTotal(flow)

			// FEASIBILITY GATE. Once we have failed enough times to
			// trust our beliefs, a decomposition that still cannot
			// cover the remainder means the payment is not going to
			// complete. Abandoning it here saves dozens of doomed
			// attempts, which is pure retry-efficiency gain with no
			// success-rate cost.
			if r.failStreak >= feasStreak && total < amt &&
				inFlightHtlcs == 0 {

				return nil, errors.New(
					"believed flow cannot cover remainder",
				)
			}

			if best == nil || total > best.amt {
				r.queued = flow[1:]
				best = flow[0]
			}
		} else if best == nil && inFlightHtlcs == 0 &&
			r.failStreak >= feasStreak {

			return nil, errors.New("no corridor left")
		}
	}

	// Last resort: deliver whatever we can. Even a small settled shard
	// reduces the remainder and refreshes evidence, which is strictly
	// better than terminally giving up on the payment.
	if best == nil {
		best = r.salvage(amt, busy, split)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// salvage hunts for any novel attempt at all, walking a descending amount
// ladder over both the disjoint and the unrestricted graph. It is the
// difference between delivering part of a payment and abandoning it.
func (r *router) salvage(remaining lnwire.MilliSatoshi, busy map[uint64]bool,
	split bool) *plan {

	if !split {
		// Without splitting, only a full-amount attempt helps.
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		if r.failedSigs[planSig(path, remaining)] {
			return nil
		}
		rt, p, err := r.makeRoute(path, remaining)
		if err != nil {
			return nil
		}
		return &plan{path: path, rt: rt, amt: remaining, prob: p}
	}

	a := remaining
	for i := 0; i < 14 && a >= minShard; i++ {
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.findPath(a, avoid)
			if err != nil {
				continue
			}
			if pl := r.bestOnPath(path, a, remaining); pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable, and it is what
// feeds the complementary bounds on the reverse direction.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	b.fails = 0
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread suspicion over the remote hops so
	// we stop re-picking this corridor without destroying the hard bounds
	// we have earned. Only queued shards sharing a channel with this
	// corridor are invalidated.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			// Optimism earned from older evidence cannot survive a
			// corridor that just failed somewhere inside it.
			b.succ = false
			r.dropStalePlans(h.ChannelID)
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// generous bump is cheaper than another failed attempt. A
		// policy repair is not evidence of dryness, so it must not
		// count against the give-up streak.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		r.dropStalePlans(h.ChannelID)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	b.fails++
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false
	b.drained = 0

	// Only the queued shards routing through this now-tightened direction
	// are stale; the rest of the joint plan still stands.
	r.dropStalePlans(h.ChannelID)

	// A local channel failing means our balance estimate was too high, and
	// it also invalidates the complementary inference that the far side of
	// that channel is the empty one.
	if failIdx == 0 {
		rk := edgeKey{chanID: h.ChannelID, to: rt.SourcePubKey}
		if rb, ok := r.beliefs[rk]; ok {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary (changes over the previous candidate are marked NEW):
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs with hard lower-OK / upper-fail bounds
//     and no time decay: a stale bound costs one retry to refresh, which
//     is cheaper than decaying evidence.
//   - Balance bookkeeping on settle, plus complementary reasoning across
//     the two sides of a channel (bimodality makes a reverse-side failure
//     a POSITIVE signal for this side).
//   - JOINT ROUTE-SET PLANNING sized per corridor bottleneck.
//
//   NEW, aimed squarely at the observed failure mode: the two failing
//   scenarios both burned all 64 attempts on ONE very large payment
//   (~0.86 and ~1.04 BTC) whose attempts kept coming back with
//   failed_at_hop = -1, i.e. UNATTRIBUTABLE failures on 4 hop routes. The
//   old code responded to those by bumping a "misses" counter and then
//   re-deriving nearly the same corridor, so it looped. Fixes:
//
//   1. UNATTRIBUTED FAILURES NOW COST THE CORRIDOR, NOT JUST A COUNTER.
//      The corridor signature is banned for the rest of the payment at
//      that amount or above, and each remote hop gets a real upper bound
//      at the amount it was asked to carry (softened, since we do not know
//      which hop was at fault). That guarantees forward progress: every
//      unattributed failure strictly shrinks the search space.
//   2. AMOUNT-INDEXED CORRIDOR BANS. A corridor banned at amount a is
//      still legal below a*banRelax, so we descend deliberately instead of
//      re-offering the same doomed attempt.
//   3. PARALLEL-FIRST BIG PAYMENTS. When the remainder exceeds what any
//      single local channel can push, we no longer waste an attempt on a
//      single-corridor probe: we go straight to flow planning, and the
//      plan is rebuilt after each failure so shard sizes track the newest
//      beliefs.
//   4. ATTEMPT BUDGET IS SPENT ON DISTINCT CORRIDORS. A per-payment cap on
//      how many attempts may leave through the same first hop stops one
//      fat local channel from absorbing the whole budget.
//   5. SALVAGE STAYS AVAILABLE: a settled shard shrinks the remainder and
//      buys fresh evidence, so partial delivery is always progress.
//
// Non-liquidity failures (fee, cltv, disabled) are repaired in the local
// policy view instead of being treated as liquidity misses.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_200)
	attemptCostPPM  = lnwire.MilliSatoshi(6_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 64
	maxFailStreak = 24

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 12

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 5.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// compSlackNum/compSlackDen discounts the complementary upper bound
	// derived from the reverse direction's proven liquidity.
	compSlackNum = 90
	compSlackDen = 100

	// revEmptyNum/revEmptyDen is the fraction of the liquidity implied on
	// this side by a reverse-direction failure that we bank on.
	revEmptyNum = 80
	revEmptyDen = 100

	// maxDryProbes is how many liquidity failures a single direction may
	// contribute before we stop probing it lower for this payment.
	maxDryProbes = 3

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the corridors a single flow decomposition walks.
	flowRounds = 14

	// hopelessStreak is how many consecutive failures we tolerate before
	// trusting the belief-derived local budget for a give-up decision.
	hopelessStreak = 5

	// banRelaxNum/banRelaxDen: a corridor banned at amount a may be tried
	// again only strictly below a*banRelax. This turns a ban into a
	// monotone descent rather than a permanent blacklist.
	banRelaxNum = 55
	banRelaxDen = 100

	// unattribPenalty softens the upper bound we charge to each remote hop
	// of a corridor that failed without naming a culprit: any one of them
	// may be the guilty party, so we do not fully believe the bound.
	unattribPenaltyNum = 115
	unattribPenaltyDen = 100

	// firstHopAttemptCap limits how many attempts of a single payment may
	// leave through the same local channel, so one channel cannot absorb
	// the whole budget.
	firstHopAttemptCap = 12
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

// revKey is the key of the same channel in the opposite direction.
func (e *edge) revKey() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.from}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us.
	succ bool

	// fails counts liquidity failures charged to this direction.
	fails int

	// drained is how much we have pushed through this direction since the
	// evidence that set succ.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan.
	queued []*plan

	// banned maps a corridor signature to the smallest amount at which it
	// is known to have failed. The corridor may be retried only strictly
	// below that amount times banRelax.
	banned map[string]lnwire.MilliSatoshi

	// firstHopUse counts attempts per local channel this payment.
	firstHopUse map[uint64]int

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		banned:        make(map[string]lnwire.MilliSatoshi),
		firstHopUse:   make(map[uint64]int),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// mppOK reports whether this payment may be split at all.
func (r *router) mppOK() bool {
	return r.spec.MaxParts > 1
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// view returns a read-only belief for a directed channel, substituting a
// zero-value belief when we have no evidence at all.
func (r *router) view(k edgeKey) *belief {
	if b, ok := r.beliefs[k]; ok {
		return b
	}
	return &belief{}
}

// capOf is the capacity of a directed channel, or zero when unknown.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath. After several dry probes we stop entirely.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	if b.fails >= maxDryProbes {
		return b.okAmt
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.40 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// compBound is the complementary upper bound on a direction: liquidity we
// have proven sits on the reverse side cannot also sit on this side.
func (r *router) compBound(e *edge) lnwire.MilliSatoshi {
	rb := r.beliefs[e.revKey()]
	if rb == nil || rb.okAmt == 0 {
		return e.capacity
	}
	held := rb.okAmt * compSlackNum / compSlackDen
	if held >= e.capacity {
		return 0
	}
	return e.capacity - held
}

// provenCenter is the amount we believe this direction actually holds.
func (r *router) provenCenter(e *edge) lnwire.MilliSatoshi {
	var center lnwire.MilliSatoshi

	b := r.beliefs[e.key()]
	if b != nil && b.succ {
		c := e.capacity * provenCenterNum / provenCenterDen
		if c > b.drained {
			center = c - b.drained
		}
	}

	// Bimodal complement: the reverse side came up dry at failAmt, so this
	// side is holding close to the whole channel.
	if rb := r.beliefs[e.revKey()]; rb != nil && rb.hasFail {
		if e.capacity > rb.failAmt {
			inf := (e.capacity - rb.failAmt) *
				revEmptyNum / revEmptyDen
			if inf > center {
				center = inf
			}
		}
	}

	if b != nil && b.okAmt > center {
		center = b.okAmt
	}

	return center
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else {
		if comp := r.compBound(e); comp < c {
			c = comp
		}
		if b != nil && b.hasFail {
			// Retry below the proven failure point rather than
			// blacklisting the channel outright.
			if lim := retryLimit(b, e.capacity); lim < c {
				c = lim
			}
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.view(e.key())
	est := e.capacity * priorSafeNum / priorSafeDen
	if b.okAmt > est {
		est = b.okAmt
	}
	if !b.hasFail {
		// A proven forward, or a dry reverse direction, says most of
		// the channel funds sit on this side.
		if c := r.provenCenter(e) * 85 / 100; c > est {
			est = c
		}
	} else if lim := retryLimit(b, e.capacity); est > lim {
		est = lim
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.view(e.key())
	if b.dead {
		return 0
	}

	eff := amt + b.inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	// The complementary bound is hard evidence: that much liquidity is
	// provably parked on the other side of the channel.
	if comp := r.compBound(e); eff > comp {
		return minProb / 4
	}

	var p float64
	switch {
	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)
		center := r.provenCenter(e)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case center > 0 && !b.hasFail:
			// Bimodal optimism: the funds are believed to sit on
			// this side, less whatever we have drained since.
			q := 1.0 / (1.0 + math.Exp(
				(float64(eff)/float64(center)-1)*4.5,
			))
			p = 0.3*p + 0.7*q

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}
			if e.from == r.source &&
				r.firstHopUse[e.chanID] >= firstHopAttemptCap {

				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Corridor bans --------------------------------------------------------

// corridorSig is the channel sequence of a path, ignoring amount.
func corridorSig(path []*edge) string {
	buf := make([]byte, 0, len(path)*14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	return string(buf)
}

// routeCorridorSig is corridorSig for an already built route.
func routeCorridorSig(rt *route.Route) string {
	buf := make([]byte, 0, len(rt.Hops)*14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	return string(buf)
}

// banCorridor records that a corridor failed at amt, so it may only be
// retried well below that amount.
func (r *router) banCorridor(sig string, amt lnwire.MilliSatoshi) {
	if sig == "" {
		return
	}
	if cur, ok := r.banned[sig]; !ok || amt < cur {
		r.banned[sig] = amt
	}
}

// corridorAllowed reports whether a corridor may still be tried at amt.
func (r *router) corridorAllowed(sig string, amt lnwire.MilliSatoshi) bool {
	lim, ok := r.banned[sig]
	if !ok {
		return true
	}
	return amt < lim*banRelaxNum/banRelaxDen
}

func (r *router) pathAllowed(path []*edge, amt lnwire.MilliSatoshi) bool {
	return r.corridorAllowed(corridorSig(path), amt)
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds the whole payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// rawLocalBudget is the total balance across our own channels, ignoring all
// beliefs and policies. It is a hard ceiling on anything we can deliver.
func (r *router) rawLocalBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		total += bal
	}
	return total
}

// rawMaxLocal is the largest single local channel balance.
func (r *router) rawMaxLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		if bal > best {
			best = bal
		}
	}
	return best
}

// maxLocalEdge is the largest single local channel balance still free, which
// is the true ceiling on one shard.
func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, exact local channel balances, and
// evidence-derived sizes just below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK < 6 && r.mppOK() {
		maxK = 6
	}
	if maxK > 12 {
		maxK = 12
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur * 2 / 3
		if cur < floor {
			break
		}
		add(cur)
	}

	// Local channel balances are exact knowledge, and a shard sized to a
	// local channel is exactly what a fan-out split wants.
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= minShard {
			add(c - c/200)
		}
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// bestOnPath prices a corridor at descending amounts and returns the best
// still-legal attempt it can carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 16 && a >= minShard; i++ {
		if r.pathAllowed(path, a) {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard || !r.pathAllowed(path, c) {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil &&
		r.pathAllowed(p, hi) {

		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 8 {
			break
		}
		probes++
		p, err := r.findPath(a, avoid)
		if err == nil && r.pathAllowed(p, a) {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	single := r.maxLocalEdge()

	var out []*plan
	left := remaining

	// Queued shards are handed out on later calls, as concurrency frees
	// up, so the decomposition is not bounded by the parts free now.
	rounds := 1
	if r.mppOK() {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if single > 0 && want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			avoid[path[0].chanID] = true
			continue
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			// The corridor cannot bear anything legal, so retire
			// its first hop and move on instead of aborting the
			// whole decomposition.
			avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// flowTotal is the amount a plan set delivers in aggregate.
func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// hopeless reports whether the remainder is provably beyond what our own
// channels can still push.
func (r *router) hopeless(amt lnwire.MilliSatoshi, inFlight uint32) bool {
	if inFlight > 0 {
		return false
	}
	if len(r.localBalances) == 0 {
		return false
	}

	// Hard ceiling: total outbound balance.
	if r.rawLocalBudget() < amt {
		return true
	}

	// A payment that may not be split must fit through one channel.
	if !r.mppOK() && r.rawMaxLocal() < amt {
		return true
	}

	// Softer test, only once we have actually confirmed dryness by
	// failing: the believed-free local liquidity cannot cover the rest.
	if r.failStreak >= hopelessStreak && len(r.localEdges) > 0 &&
		r.localBudget() < amt {

		return true
	}

	return false
}

// bigPayment reports whether the remainder is beyond any single local
// channel, in which case a single-corridor search can only ever waste an
// attempt and we should plan a parallel decomposition immediately.
func (r *router) bigPayment(amt lnwire.MilliSatoshi) bool {
	if !r.mppOK() {
		return false
	}
	single := r.maxLocalEdge()
	return single > 0 && amt > single
}

// serveQueued hands out the next queued shard of a joint plan that still
// holds up against current beliefs.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, busy map[uint64]bool,
	split bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot split.
		if !split && a < amt {
			r.queued = nil
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if !r.pathAllowed(pl.path, a) {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}
		return rt
	}
	return nil
}

// RequestRoute plans the next shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}
	if r.hopeless(amt, inFlightHtlcs) {
		return nil, errors.New("remainder exceeds local liquidity")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()
	split := r.mppOK()

	if rt := r.serveQueued(amt, busy, split); rt != nil {
		r.attempts++
		r.noteFirstHop(rt)
		return rt, nil
	}

	// Parallel-first: a remainder larger than any single local channel can
	// only be delivered by several shards, so plan the decomposition up
	// front rather than burning an attempt on a doomed single corridor.
	if r.bigPayment(amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			r.queued = flow[1:]
			r.attempts++
			r.noteFirstHop(flow[0].rt)
			return flow[0].rt, nil
		}
	}

	// A single shard can never exceed what one local channel can push.
	hi := amt
	if single := r.maxLocalEdge(); single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}
			if !split && a < amt {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly.
	if split && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total := flowTotal(flow)
			first := flow[0]

			if best == nil || total > best.amt {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	// Last resort: deliver whatever we can. Even a small settled shard
	// reduces the remainder and refreshes evidence, which is strictly
	// better than terminally giving up on the payment.
	if best == nil {
		best = r.salvage(amt, busy, split)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.noteFirstHop(best.rt)
	return best.rt, nil
}

// noteFirstHop charges an attempt to the local channel it leaves through.
func (r *router) noteFirstHop(rt *route.Route) {
	if rt == nil || len(rt.Hops) == 0 {
		return
	}
	r.firstHopUse[rt.Hops[0].ChannelID]++
}

// salvage hunts for any legal attempt at all, walking a wide descending
// amount ladder over both the disjoint and the unrestricted graph. It is the
// difference between delivering part of a payment and abandoning it.
func (r *router) salvage(remaining lnwire.MilliSatoshi, busy map[uint64]bool,
	split bool) *plan {

	if !split {
		// Without splitting, only a full-amount attempt helps.
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		if !r.pathAllowed(path, remaining) {
			return nil
		}
		rt, p, err := r.makeRoute(path, remaining)
		if err != nil {
			return nil
		}
		return &plan{path: path, rt: rt, amt: remaining, prob: p}
	}

	a := remaining
	for i := 0; i < 24 && a >= minShard; i++ {
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.findPath(a, avoid)
			if err != nil {
				continue
			}
			if pl := r.bestOnPath(path, a, remaining); pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
	}
}

// tighten records an upper bound on a direction from a liquidity miss.
func (r *router) tighten(k edgeKey, a lnwire.MilliSatoshi, hard bool) {
	b := r.bel(k)
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	if hard {
		b.fails++
		b.succ = false
		b.drained = 0
	}
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable, and it is what
// feeds the complementary bounds on the reverse direction.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	b.fails = 0
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		// A settled shard changes every belief the plan rested on.
		r.queued = nil
		return nil
	}

	r.failStreak++

	// Beliefs just changed, so any queued joint plan is stale.
	r.queued = nil

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure. The old code merely bumped a suspicion
	// counter, which let the planner re-derive nearly the same corridor
	// forever: that is exactly how the two failing scenarios burned 64
	// attempts. Now the corridor is banned at this amount and every remote
	// hop takes a real (softened) upper bound, so the search space
	// strictly shrinks with each such failure.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		last := rt.Hops[len(rt.Hops)-1].AmtToForward
		r.banCorridor(routeCorridorSig(rt), last)

		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			a := hopAmount(rt, i)
			soft := a * unattribPenaltyNum / unattribPenaltyDen
			r.tighten(hopKey(h), soft, false)
			r.bel(hopKey(h)).succ = false
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// generous bump is cheaper than another failed attempt.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		r.bel(hopKey(h)).dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction, and ban
	// the corridor at the delivered amount so we descend rather than
	// re-offer it.
	r.tighten(hopKey(h), a, true)
	r.banCorridor(
		routeCorridorSig(rt), rt.Hops[len(rt.Hops)-1].AmtToForward,
	)

	// A local channel failing means our balance estimate was too high, and
	// it also invalidates the complementary inference that the far side of
	// that channel is the empty one.
	if failIdx == 0 {
		rk := edgeKey{chanID: h.ChannelID, to: rt.SourcePubKey}
		if rb, ok := r.beliefs[rk]; ok {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary (changes over the previous candidate are marked NEW):
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs with hard lower-OK / upper-fail bounds
//     and no time decay: a stale bound costs one retry to refresh, which is
//     cheaper than decaying evidence.
//   - Balance bookkeeping on settle plus complementary reasoning across the
//     two sides of a channel (a dry reverse side means this side is full).
//   - NEW: PERSISTENT PARALLEL PLAN. The big observed failure was a large
//     payment (2.06 Gmsat) burning 20 attempts and dying on "no progress"
//     while every failure was a plain TemporaryChannelFailure. The root
//     cause was that the joint flow plan was thrown away on EVERY failure
//     (r.queued = nil), so the router collapsed back to single-corridor
//     probing and never actually held several unequal shards in flight.
//     Now the queue survives failures: only the shards whose corridors are
//     directly contradicted by new evidence are dropped, and the rest are
//     re-priced lazily when handed out.
//   - NEW: CONCURRENCY-FIRST DISPATCH. When the remainder cannot fit in a
//     single corridor and parts are free, we deliberately hand out the
//     largest believable shard immediately rather than searching the whole
//     amount ladder first. Filling MaxParts is what converts a big payment
//     into a success; ladder search only helps once concurrency is spent.
//   - NEW: RESIDUAL-AWARE FLOW PLANNING. planFlow now runs a proper
//     residual pass: each corridor's shard is capped by the min of its
//     bottleneck and the free local balance of its first hop, and local
//     first-hop budget is DECREMENTED as shards are planned, so two shards
//     never over-commit the same local channel. Previously two planned
//     shards could both be sized to the same local channel's balance.
//   - NEW: ADAPTIVE FAIL BUDGET. maxFailStreak scales with how much of the
//     payment still needs covering and how many parts we may use, so a
//     multi-shard payment is not killed by a streak that a single-shard
//     payment would deserve. Small payments still give up fast, so retry
//     efficiency on easy scenarios is preserved.
//   - NEW: PROGRESS-AWARE STREAK RESET. Any hop that demonstrably forwarded
//     (a failure deeper in the route than hop 0) counts as partial
//     progress and softens the streak, because we did learn something
//     actionable.
//   - Depth-aware lower retries with a per-direction dry-probe counter.
//   - Hopeless-payment detection from exactly known local balances.
//   - Duplicate-attempt suppression, and non-liquidity failures (fee, cltv,
//     min, disabled) repaired in the local policy view.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_200)
	attemptCostPPM  = lnwire.MilliSatoshi(6_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts bounds total attempts for one payment.
	maxAttempts = 90

	// baseFailStreak is the streak budget for a payment we believe one
	// corridor should be able to carry. Payments needing many shards get
	// a proportionally larger budget, see failBudget.
	baseFailStreak = 10

	// maxFailStreakCap is the absolute ceiling on the streak budget.
	maxFailStreakCap = 34

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 12

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 5.0
	partCost  = 0.004

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// compSlackNum/compSlackDen discounts the complementary upper bound
	// derived from the reverse direction's proven liquidity.
	compSlackNum = 90
	compSlackDen = 100

	// revEmptyNum/revEmptyDen is the fraction of the liquidity implied on
	// this side by a reverse-direction failure that we bank on.
	revEmptyNum = 80
	revEmptyDen = 100

	// maxDryProbes is how many liquidity failures a single direction may
	// contribute before we stop probing it lower for this payment.
	maxDryProbes = 3

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.12

	// flowRounds bounds the corridors a single flow decomposition walks.
	flowRounds = 14

	// hopelessStreak is how many consecutive failures we tolerate before
	// trusting the belief-derived local budget for a give-up decision.
	hopelessStreak = 6
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

// revKey is the key of the same channel in the opposite direction.
func (e *edge) revKey() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.from}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us.
	succ bool

	// fails counts liquidity failures charged to this direction.
	fails int

	// drained is how much we have pushed through this direction since the
	// evidence that set succ.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan. It is
	// NOT discarded on failure: shards whose corridors are contradicted by
	// new evidence are pruned individually and the rest are re-priced when
	// handed out.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	// failStreak counts consecutive unproductive failures.
	failStreak int

	// attempts counts every route we handed out.
	attempts int

	// delivered is how much this payment has settled so far, used to size
	// the fail budget.
	delivered lnwire.MilliSatoshi

	// firstAmt is the amount of the very first RequestRoute call, i.e. the
	// full payment amount.
	firstAmt lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// mppOK reports whether this payment may be split at all.
func (r *router) mppOK() bool {
	return r.spec.MaxParts > 1
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// view returns a read-only belief for a directed channel, substituting a
// zero-value belief when we have no evidence at all.
func (r *router) view(k edgeKey) *belief {
	if b, ok := r.beliefs[k]; ok {
		return b
	}
	return &belief{}
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// failBudget is how many consecutive failures we tolerate. A payment that
// provably needs several shards deserves more probing than one that should
// fit in a single corridor: each shard costs at least one attempt to place,
// and a shard that fails costs one more to resize. Small payments keep a
// tight budget so retry efficiency on easy scenarios does not regress.
func (r *router) failBudget() int {
	budget := baseFailStreak
	if !r.mppOK() {
		return budget
	}

	// Estimate the number of shards the payment needs from the largest
	// single local channel we could push out of.
	shards := 1
	if single := r.rawMaxLocal(); single > 0 && r.firstAmt > single {
		shards = int(r.firstAmt/single) + 1
	}
	if mp := int(r.spec.MaxParts); shards > mp && mp > 0 {
		shards = mp
	}
	if shards > 1 {
		budget += 5 * (shards - 1)
	}
	if budget > maxFailStreakCap {
		budget = maxFailStreakCap
	}
	return budget
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath. After several dry probes we stop entirely.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	if b.fails >= maxDryProbes {
		return b.okAmt
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.40 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// compBound is the complementary upper bound on a direction: liquidity we
// have proven sits on the reverse side cannot also sit on this side.
func (r *router) compBound(e *edge) lnwire.MilliSatoshi {
	rb := r.beliefs[e.revKey()]
	if rb == nil || rb.okAmt == 0 {
		return e.capacity
	}
	held := rb.okAmt * compSlackNum / compSlackDen
	if held >= e.capacity {
		return 0
	}
	return e.capacity - held
}

// provenCenter is the amount we believe this direction actually holds.
func (r *router) provenCenter(e *edge) lnwire.MilliSatoshi {
	var center lnwire.MilliSatoshi

	b := r.beliefs[e.key()]
	if b != nil && b.succ {
		c := e.capacity * provenCenterNum / provenCenterDen
		if c > b.drained {
			center = c - b.drained
		}
	}

	// Bimodal complement: the reverse side came up dry at failAmt, so this
	// side is holding close to the whole channel.
	if rb := r.beliefs[e.revKey()]; rb != nil && rb.hasFail {
		if e.capacity > rb.failAmt {
			inf := (e.capacity - rb.failAmt) *
				revEmptyNum / revEmptyDen
			if inf > center {
				center = inf
			}
		}
	}

	if b != nil && b.okAmt > center {
		center = b.okAmt
	}

	return center
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else {
		if comp := r.compBound(e); comp < c {
			c = comp
		}
		if b != nil && b.hasFail {
			// Retry below the proven failure point rather than
			// blacklisting the channel outright.
			if lim := retryLimit(b, e.capacity); lim < c {
				c = lim
			}
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.view(e.key())
	est := e.capacity * priorSafeNum / priorSafeDen
	if b.okAmt > est {
		est = b.okAmt
	}
	if !b.hasFail {
		// A proven forward, or a dry reverse direction, says most of
		// the channel funds sit on this side.
		if c := r.provenCenter(e) * 85 / 100; c > est {
			est = c
		}
	} else if lim := retryLimit(b, e.capacity); est > lim {
		est = lim
	}
	if b.misses > 0 {
		est = est / lnwire.MilliSatoshi(1+b.misses)
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.view(e.key())
	if b.dead {
		return 0
	}

	eff := amt + b.inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	// The complementary bound is hard evidence: that much liquidity is
	// provably parked on the other side of the channel.
	if comp := r.compBound(e); eff > comp {
		return minProb / 4
	}

	var p float64
	switch {
	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)
		center := r.provenCenter(e)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case center > 0 && !b.hasFail:
			// Bimodal optimism: the funds are believed to sit on
			// this side, less whatever we have drained since.
			q := 1.0 / (1.0 + math.Exp(
				(float64(eff)/float64(center)-1)*4.5,
			))
			p = 0.3*p + 0.7*q

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if b.misses > 0 {
		m := b.misses
		if m > 3 {
			m = 3
		}
		p *= math.Pow(0.6, float64(m))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds the whole payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// rawLocalBudget is the total balance across our own channels, ignoring all
// beliefs and policies. It is a hard ceiling on anything we can deliver.
func (r *router) rawLocalBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		total += bal
	}
	return total
}

// rawMaxLocal is the largest single local channel balance, which bounds one
// shard: a shard leaves through exactly one first hop.
func (r *router) rawMaxLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		if bal > best {
			best = bal
		}
	}
	return best
}

// maxLocalEdge is the largest single local channel balance still free, which
// is the true ceiling on one shard.
func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// freeLocal is the free capacity of the local channel a corridor leaves
// through, or a very large number when the corridor's first hop is not one
// of ours (which cannot happen for a valid route).
func (r *router) freeLocal(path []*edge) lnwire.MilliSatoshi {
	if len(path) == 0 {
		return 0
	}
	return r.availCap(path[0])
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, exact local channel balances, and
// evidence-derived sizes just below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK < 4 && r.mppOK() {
		maxK = 4
	}
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Local channel balances are exact knowledge, and a shard sized to a
	// local channel is exactly what a fan-out split wants.
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= minShard {
			add(c - c/200)
		}
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 7 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
//
// It runs a residual pass: local first-hop budget is decremented as shards
// are planned, so two shards can never over-commit the same local channel,
// and each shard is capped by the min of its corridor bottleneck and its
// first hop's remaining free balance.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	// Residual local budget per first-hop channel.
	residual := make(map[uint64]lnwire.MilliSatoshi, len(r.localEdges))
	for _, e := range r.localEdges {
		if _, ok := residual[e.chanID]; !ok {
			residual[e.chanID] = r.availCap(e)
		}
	}

	var out []*plan
	left := remaining

	// Queued shards are handed out on later calls, as concurrency frees
	// up, so the decomposition is not bounded by the parts free right now.
	rounds := 1
	if r.mppOK() {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		// The largest amount any still-usable local channel can push.
		var single lnwire.MilliSatoshi
		for _, c := range residual {
			if c > single {
				single = c
			}
		}
		if single < minShard {
			break
		}

		want := left
		if want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if fl := residual[path[0].chanID]; fl > 0 && fl < amtS {
			amtS = fl
		}
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			// This corridor cannot bear a useful shard, so retire
			// its first hop for this decomposition.
			avoid[path[0].chanID] = true
			residual[path[0].chanID] = 0
			continue
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)

		// Charge the shard against its first hop's residual balance and
		// retire every channel it uses from this decomposition.
		fh := path[0].chanID
		if residual[fh] > pl.amt {
			residual[fh] -= pl.amt
		} else {
			residual[fh] = 0
		}
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// flowTotal is the amount a plan set delivers in aggregate.
func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// pathUses reports whether a corridor traverses the given channel.
func pathUses(path []*edge, chanID uint64) bool {
	for _, e := range path {
		if e.chanID == chanID {
			return true
		}
	}
	return false
}

// pruneQueue drops the queued shards that a fresh failure on chanID
// contradicts, and keeps the rest. Holding on to the plan across failures is
// what lets a multi-shard payment actually fill its concurrency instead of
// collapsing back to single-corridor probing after every miss.
func (r *router) pruneQueue(chanID uint64) {
	if len(r.queued) == 0 {
		return
	}
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if pathUses(pl.path, chanID) {
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// hopeless reports whether the remainder is provably beyond what our own
// channels can still push.
func (r *router) hopeless(amt lnwire.MilliSatoshi, inFlight uint32) bool {
	if inFlight > 0 {
		return false
	}
	if len(r.localBalances) == 0 {
		return false
	}

	// Hard ceiling: total outbound balance.
	if r.rawLocalBudget() < amt {
		return true
	}

	// A payment that may not be split must fit through one channel.
	if !r.mppOK() && r.rawMaxLocal() < amt {
		return true
	}

	// Softer test, only once we have actually confirmed dryness by
	// failing: the believed-free local liquidity cannot cover the rest.
	if r.failStreak >= hopelessStreak && len(r.localEdges) > 0 &&
		r.localBudget() < amt {

		return true
	}

	return false
}

// serveQueued hands out the first still-valid shard of a joint plan. Shards
// are re-priced against current beliefs, and a shard whose corridor no
// longer holds up is dropped rather than aborting the whole plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, split bool,
	busy map[uint64]bool) *plan {

	var deferred []*plan

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when the payment cannot be split.
		if !split && a < amt {
			r.queued = nil
			break
		}
		if pathBusy(pl.path, busy) {
			// The corridor is temporarily occupied, not wrong:
			// keep it for a later call.
			deferred = append(deferred, pl)
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			// Re-price the corridor a little lower rather than
			// discarding a corridor we deliberately chose.
			if lower := r.bestOnPath(pl.path, a-a/8, amt); lower !=
				nil && lower.prob >= queueMinProb {

				r.queued = append(deferred, r.queued...)
				return lower
			}
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			// Beliefs moved against this corridor: try a smaller
			// amount on it before giving it up.
			if lower := r.bestOnPath(pl.path, a*3/4, amt); lower !=
				nil && lower.prob >= queueMinProb {

				r.queued = append(deferred, r.queued...)
				return lower
			}
			continue
		}

		r.queued = append(deferred, r.queued...)
		return &plan{path: pl.path, rt: rt, amt: a, prob: p}
	}

	r.queued = deferred
	return nil
}

// RequestRoute plans the next shard.
//
// Order of play:
//  1. Serve a shard left over from a joint route-set plan, re-priced.
//  2. When the remainder provably cannot fit through one local channel and
//     parts are still free, plan the whole decomposition up front and hand
//     out its first shard immediately. Filling concurrency with correctly
//     sized unequal shards is what turns a large payment into a success.
//  3. Otherwise search jointly over shard amount and corridor.
//  4. Fall back to a deliberate multi-corridor split, then to salvage.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.firstAmt == 0 {
		r.firstAmt = amt
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= r.failBudget() {
		return nil, errors.New("no progress")
	}
	if r.hopeless(amt, inFlightHtlcs) {
		return nil, errors.New("remainder exceeds local liquidity")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()
	split := r.mppOK()

	// Step 1: serve a queued shard from an earlier joint plan.
	if pl := r.serveQueued(amt, split, busy); pl != nil {
		r.attempts++
		return pl.rt, nil
	}

	// A single shard can never exceed what one local channel can push,
	// since a shard leaves through exactly one first hop.
	single := r.maxLocalEdge()
	hi := amt
	if single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	// Step 2: concurrency-first dispatch. When the remainder provably
	// exceeds any one local channel, ladder search over a single corridor
	// cannot succeed, so plan the whole decomposition now.
	if split && partsLeft > 1 && single > 0 && amt > single {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			r.queued = flow[1:]
			r.attempts++
			return flow[0].rt, nil
		}
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}
			if !split && a < amt {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// Step 4: when no single corridor carries the whole remainder, plan the
	// split deliberately over disjoint corridors instead of halving
	// blindly. We compare the aggregate believed flow of the plan set
	// against the best single shard: covering more of the payment beats a
	// slightly nicer first hop, because every uncovered millisat is a
	// failed payment.
	if split && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total := flowTotal(flow)
			first := flow[0]

			if best == nil || total > best.amt {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	// Last resort: deliver whatever we can. Even a small settled shard
	// reduces the remainder and refreshes evidence, which is strictly
	// better than terminally giving up on the payment.
	if best == nil {
		best = r.salvage(amt, busy, split)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return best.rt, nil
}

// salvage hunts for any novel attempt at all, walking a wide descending
// amount ladder over both the disjoint and the unrestricted graph. It is the
// difference between delivering part of a payment and abandoning it.
func (r *router) salvage(remaining lnwire.MilliSatoshi, busy map[uint64]bool,
	split bool) *plan {

	if !split {
		// Without splitting, only a full-amount attempt helps.
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		if r.failedSigs[planSig(path, remaining)] {
			return nil
		}
		rt, p, err := r.makeRoute(path, remaining)
		if err != nil {
			return nil
		}
		return &plan{path: path, rt: rt, amt: remaining, prob: p}
	}

	a := remaining
	if single := r.maxLocalEdge(); single >= minShard && single < a {
		a = single
	}
	for i := 0; i < 22 && a >= minShard; i++ {
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.findPath(a, avoid)
			if err != nil {
				continue
			}
			if pl := r.bestOnPath(path, a, remaining); pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	b.fails = 0
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		if n := len(rt.Hops); n > 0 {
			r.delivered += rt.Hops[n-1].AmtToForward
		}
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		return nil
	}

	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// A failure deep in the route means the earlier hops demonstrably
	// forwarded, which is real progress: we learned usable bounds. Charge
	// such a failure at half weight so a large multi-shard payment is not
	// killed by informative misses.
	if failIdx > 1 {
		r.failStreak++
		if r.failStreak > 0 && r.attempts%2 == 0 {
			r.failStreak--
		}
	} else {
		r.failStreak++
	}

	// An unattributable failure: spread suspicion over the remote hops so
	// we stop re-picking this corridor without destroying the hard bounds
	// we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			// Optimism earned from older evidence cannot survive a
			// corridor that just failed somewhere inside it.
			b.succ = false
			r.pruneQueue(h.ChannelID)
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// generous bump is cheaper than another failed attempt. A fee
		// repair is not a liquidity miss, so it does not count against
		// the streak and the queued plan stays valid.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		if r.failStreak > 0 {
			r.failStreak--
		}
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(h.ChannelID)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	b.fails++
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false
	b.drained = 0

	// Only the shards routed through the failing channel are invalidated:
	// the rest of a joint plan is still the best decomposition we have, and
	// throwing it away is what previously collapsed large payments back
	// into single-corridor grinding.
	r.pruneQueue(h.ChannelID)

	// A local channel failing means our balance estimate was too high, and
	// it also invalidates the complementary inference that the far side of
	// that channel is the empty one.
	if failIdx == 0 {
		rk := edgeKey{chanID: h.ChannelID, to: rt.SourcePubKey}
		if rb, ok := r.beliefs[rk]; ok {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (keyed by channel plus direction) with
//     hard lower-OK / upper-fail bounds and no time decay: a stale bound
//     costs one retry to refresh, which is cheaper than decaying evidence.
//   - BALANCE BOOKKEEPING on settle: a forward that settles moves liquidity,
//     so the forward direction's bounds are decremented and the reverse
//     direction's bounds are incremented by exactly the amount forwarded.
//   - JOINT ROUTE-SET PLANNING (min-cost-flow style): shard sizes and
//     corridors are chosen TOGETHER by a greedy flow decomposition over
//     disjoint corridors, each shard sized to that corridor's believed
//     bottleneck.
//   - CAPACITY-AWARE ADMISSION: before spending attempts on a large payment,
//     the believed max-flow from source to target is measured. If the whole
//     remainder plainly cannot flow, the router switches to "harvest mode":
//     carve the biggest shards the network can actually bear rather than
//     repeatedly probing at amounts the evidence already rules out. This is
//     what was burning 26 attempts on the 1.04 BTC payment before it died
//     with "no route found".
//   - ANTI-THRASH PROBE LEDGER: every (corridor, amount) probe is remembered
//     along with a monotone per-corridor ceiling. Once a corridor has failed
//     at amount a, we never probe it above a again, and the next probe on it
//     must be materially smaller (a geometric step), so a corridor can be
//     refined at most a handful of times. This directly cuts the retry
//     counts that dominate the retry_efficiency penalty.
//   - EARLY COMMIT ON CONFIDENCE: when the best plan is a full-amount route
//     with high believed probability, planning stops immediately instead of
//     walking the whole ladder, which trims attempts and Dijkstra work on
//     the easy scenarios that already succeed.
//   - Depth-aware lower retries and retry-at-lower-amount instead of
//     permanent blacklisting.
//   - Non-liquidity failures (fee, cltv, min-htlc, disabled) are repaired in
//     the local policy view instead of being charged to liquidity beliefs.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying. The
	// streak is generous because a large multi-part payment legitimately
	// spends several probes learning the shape of the network, but the
	// probe ledger below keeps those probes from repeating themselves.
	maxAttempts   = 64
	maxFailStreak = 22

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 12

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the greedy flow decomposition.
	flowRounds = 14

	// corridorStep is the geometric shrink a corridor must take between
	// successive probes. Without it, a corridor gets re-probed at nearly
	// the same amount over and over, which is pure attempt waste.
	corridorStep = 0.62

	// commitProb is the probability above which a full-amount plan is
	// taken immediately with no further search.
	commitProb = 0.72

	// harvestFrac is the fraction of believed max-flow we are willing to
	// ask for in one shard when the full remainder is known infeasible.
	harvestFrac = 0.9
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	// corridorCap is a monotone per-corridor ceiling: the largest amount
	// we are still willing to try over a given channel sequence. Every
	// failure on the corridor ratchets it down geometrically, so a
	// corridor can be refined only a few times before it drops out.
	corridorCap map[string]lnwire.MilliSatoshi

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
		corridorCap:   make(map[string]lnwire.MilliSatoshi),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Corridor ledger ------------------------------------------------------

// corridorSig names a channel sequence, independent of amount.
func corridorSig(path []*edge) string {
	buf := make([]byte, 0, len(path)*14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	return string(buf)
}

// routeCorridorSig is corridorSig for an already-built route.
func routeCorridorSig(rt *route.Route) string {
	buf := make([]byte, 0, len(rt.Hops)*14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	return string(buf)
}

// corridorCeil is the largest amount we are still willing to send over a
// corridor, given how it has failed before. Zero means "no ceiling yet".
func (r *router) corridorCeil(path []*edge) lnwire.MilliSatoshi {
	return r.corridorCap[corridorSig(path)]
}

// noteCorridorFail ratchets a corridor's ceiling down. The next probe on the
// same channel sequence must be materially smaller, which stops the router
// from grinding out near-identical retries.
func (r *router) noteCorridorFail(sig string, amt lnwire.MilliSatoshi) {
	next := lnwire.MilliSatoshi(float64(amt) * corridorStep)
	if cur, ok := r.corridorCap[sig]; ok && cur < next {
		return
	}
	r.corridorCap[sig] = next
}

// clampCorridor caps a candidate amount by the corridor's ledger ceiling.
func (r *router) clampCorridor(path []*edge,
	a lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if ceil := r.corridorCeil(path); ceil > 0 && a > ceil {
		return ceil
	}
	return a
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	bn -= bn / 100
	return r.clampCorridor(path, bn)
}

// hardBottleneck is the corridor's absolute believed ceiling, used by the
// feasibility gate: it ignores the conservative safeCap shading and asks
// only whether liquidity could plausibly flow at all.
func (r *router) hardBottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.availCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return r.clampCorridor(path, bn)
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK > 8 {
		maxK = 8
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
}

// build prices a corridor at an amount, respecting the corridor ledger and
// the duplicate-attempt suppression table.
func (r *router) build(path []*edge, a,
	remaining lnwire.MilliSatoshi) *plan {

	a = r.clampCorridor(path, a)
	if a < minShard {
		return nil
	}
	if r.failedSigs[planSig(path, a)] {
		return nil
	}
	rt, p, err := r.makeRoute(path, a)
	if err != nil {
		return nil
	}
	fee := rt.TotalAmount - a
	return &plan{
		path:  path,
		rt:    rt,
		amt:   a,
		prob:  p,
		score: r.score(a, p, fee, remaining),
	}
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		pl := r.build(path, c, remaining)
		if pl == nil {
			continue
		}
		if best == nil || pl.score > best.score {
			best = pl
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := r.clampCorridor(path, hi)
	for i := 0; i < 12 && a >= minShard; i++ {
		if pl := r.build(path, a, remaining); pl != nil {
			return pl
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 8 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	var out []*plan
	left := remaining
	rounds := int(partsLeft)
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		path := r.findAnyPath(left, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := left
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			// The corridor is too thin to be worth a shard, but it
			// is still worth excluding so the next round finds
			// something else.
			for _, e := range path {
				avoid[e.chanID] = true
			}
			continue
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			for _, e := range path {
				avoid[e.chanID] = true
			}
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	// Best shards first: the largest, most reliable corridor should be
	// tried before the marginal ones.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].score > out[j].score
	})

	return out
}

// believedFlow is the total delivered amount our believed liquidity could
// carry over up to `rounds` disjoint corridors. It answers two questions at
// once: whether to keep going at all, and — when the full remainder is out
// of reach — how big a shard is actually worth asking for. Sizing to this
// number instead of blindly halving is what stops a big payment from
// grinding through a dozen doomed probes.
func (r *router) believedFlow(remaining lnwire.MilliSatoshi,
	rounds int, busy map[uint64]bool) lnwire.MilliSatoshi {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}
	var total lnwire.MilliSatoshi

	for k := 0; k < rounds; k++ {
		left := remaining - total
		if left < minShard {
			break
		}
		path, err := r.findPath(left, avoid)
		if err != nil {
			path = r.findAnyPath(left, remaining, 4, avoid)
			if path == nil {
				break
			}
		}
		bn := r.hardBottleneck(path)
		if bn > left {
			bn = left
		}
		for _, e := range path {
			avoid[e.chanID] = true
		}
		if bn < minShard {
			continue
		}
		total += bn
	}

	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// pruneQueue drops only the queued shards whose corridors touch a channel
// whose belief just got worse. Discarding the entire joint plan on every
// failure throws away correct planning work and forces the router to
// rediscover the same split by trial and error.
func (r *router) pruneQueue(hit map[uint64]bool) {
	if len(r.queued) == 0 {
		return
	}
	keep := r.queued[:0]
	for _, pl := range r.queued {
		drop := false
		for _, e := range pl.path {
			if hit[e.chanID] {
				drop = true
				break
			}
		}
		if !drop {
			keep = append(keep, pl)
		}
	}
	r.queued = keep
}

// serveQueued hands out the next still-valid shard of a joint plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.queued = nil
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		npl := r.build(pl.path, a, amt)
		if npl == nil || npl.prob < queueMinProb {
			continue
		}
		return npl.rt
	}
	return nil
}

// RequestRoute plans the next shard.
//
// The call proceeds in four stages, cheapest first:
//  1. serve a still-valid shard from an earlier joint plan;
//  2. search corridors at descending amounts, committing early when a
//     full-amount plan looks confident;
//  3. when no single corridor covers the remainder, plan a deliberate
//     multi-corridor split;
//  4. when even that fails, measure the believed max-flow and harvest the
//     largest shard the network can plausibly bear, rather than declaring
//     the payment dead while liquidity clearly remains.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if hi < minShard {
		hi = amt
	}

	// Capacity-aware admission: if the believed max-flow plainly cannot
	// cover the remainder, do not waste probes at the full amount. Cap the
	// search at what the network is believed able to bear.
	var flowCap lnwire.MilliSatoshi
	if partsLeft > 1 {
		flowCap = r.believedFlow(amt, flowRounds, busy)
		if flowCap > 0 && flowCap < hi {
			// Only shrink the search when the shortfall is real,
			// not a rounding artifact.
			if float64(flowCap) < 0.95*float64(hi) {
				hi = flowCap
			}
		}
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= probeBudget {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives:
			// commit right away and save both search work and the
			// risk of talking ourselves into a needless split.
			if best != nil && best.amt >= amt &&
				best.prob > commitProb {

				r.attempts++
				return best.rt, nil
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly. The
	// plan is accepted when its corridors jointly cover meaningfully more
	// of the remainder than the single best shard would.
	if partsLeft > 1 && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			var total lnwire.MilliSatoshi
			for _, pl := range flow {
				total += pl.amt
			}

			first := flow[0]
			better := best == nil ||
				(total > best.amt &&
					first.score > best.score*0.75)

			if better {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	if best != nil {
		r.attempts++
		return best.rt, nil
	}

	// Harvest mode. Conservative sizing found nothing, but the believed
	// max-flow may still be positive. Instead of walking the whole ladder
	// blind, size the request directly to the flow the network is believed
	// to support and take the biggest novel attempt we can build.
	flow := r.believedFlow(amt, flowRounds, busy)
	if flow >= minShard {
		start := lnwire.MilliSatoshi(float64(flow) * harvestFrac)
		if start > amt {
			start = amt
		}
		if start < minShard {
			start = minShard
		}

		cands := []lnwire.MilliSatoshi{start}
		for _, a := range r.ladder(start, amt, partsLeft) {
			if a < start {
				cands = append(cands, a)
			}
		}

		probes := 0
		for _, a := range cands {
			if probes >= probeBudget {
				break
			}
			probes++
			path, err := r.findPath(a, busy)
			if err != nil {
				path, err = r.findPath(a, nil)
				if err != nil {
					continue
				}
			}
			pl := r.bestOnPath(path, a, amt)
			if pl == nil {
				continue
			}
			r.attempts++
			return pl.rt, nil
		}
	}

	return nil, errors.New("no route found")
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A corridor that just settled drained itself, so its ledger
		// ceiling drops to what it actually carried. Later shards may
		// still reuse it, just not at a larger size.
		if n := len(rt.Hops); n > 0 {
			sig := routeCorridorSig(rt)
			delivered := rt.Hops[n-1].AmtToForward
			cur, ok := r.corridorCap[sig]
			if !ok || cur > delivered {
				r.corridorCap[sig] = delivered
			}
		}

		// A settled shard drained the corridors it used, so any queued
		// shard sharing those channels must be re-planned.
		hit := make(map[uint64]bool, len(rt.Hops))
		for _, h := range rt.Hops {
			hit[h.ChannelID] = true
		}
		r.pruneQueue(hit)

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	kind := "liquidity"
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		kind = classify(result.Failure)
	}

	// Policy repairs say nothing about liquidity, so the corridor ledger
	// stays untouched for them. Every other failure ratchets the corridor
	// down so the next probe on it is materially smaller.
	if n := len(rt.Hops); n > 0 && kind != "fee" && kind != "cltv" {
		r.noteCorridorFail(
			routeCorridorSig(rt), rt.Hops[n-1].AmtToForward,
		)
	}

	// An unattributable failure: spread mild suspicion over the remote
	// hops so we stop re-picking this corridor without destroying the
	// hard bounds we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			hit[h.ChannelID] = true
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	switch kind {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// fee repair is not evidence against any corridor, so queued
		// shards survive untouched.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(map[uint64]bool{h.ChannelID: true})
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	// Only the queued corridors that actually depend on the condemned
	// channel are invalidated; the rest of the joint plan stays valid.
	r.pruneQueue(map[uint64]bool{h.ChannelID: true})

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary (success is already saturated at 100% in the current
// scenarios, so this revision keeps every success-preserving mechanism and
// attacks the two secondary terms: attempts per payment and fee ppm):
//
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs with hard lower-OK / upper-fail bounds and
//     no time decay: a stale bound costs one retry to refresh, which is
//     cheaper than decaying evidence (exp-008).
//   - BALANCE BOOKKEEPING on settle plus COMPLEMENTARY REASONING across the
//     two sides of a channel: proven reverse liquidity is a hard upper bound
//     here, and a reverse-direction failure at a small amount is a POSITIVE
//     signal for this direction under bimodality.
//   - JOINT ROUTE-SET PLANNING (min-cost-flow style) with a local-channel
//     flow cap, so a payment larger than any single local channel is
//     decomposed up front into unequal shards sized to each corridor's
//     bottleneck instead of discovered by halving on failure.
//
// New in this revision, all aimed at attempts and fees:
//
//   - FIRST-SHOT SIZING: the amount ladder is no longer walked from the top
//     blindly. We compute a believed max-flow ceiling over disjoint
//     corridors and start the ladder at min(remaining, ceiling), which skips
//     the doomed full-amount probe that used to burn the first attempt of
//     nearly every large payment.
//   - PESSIMISTIC-FIRST SHARD SIZING: a corridor is priced at the amount its
//     weakest hop is BELIEVED to bear before it is priced at the amount we
//     wish it would bear, so the very first attempt on an unexplored
//     corridor is already sized to survive.
//   - SUCCESS-ANCHORED CORRIDOR MEMORY: corridors that have settled are
//     remembered and re-tried FIRST at up to their proven amount. Repeat
//     payments in a batch then settle in one attempt on a known-good
//     corridor rather than re-deriving it, which cuts both attempts and fees.
//   - FEE AS A REAL TERM: once a plan clears a high probability bar we
//     enumerate cheaper alternatives on the same amount and keep the cheapest
//     that stays above the bar. Fee ppm was the only remaining penalty on
//     fully-successful runs.
//   - EARLY EXIT everywhere: a confident plan short-circuits the probe loop,
//     and the probe budget shrinks once a good plan is in hand.
//   - Non-liquidity failures (fee, cltv, min htlc, disabled) are repaired in
//     the local policy view rather than charged to liquidity, and a fee
//     repair is retried immediately on the SAME corridor.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_200)
	attemptCostPPM  = lnwire.MilliSatoshi(5_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless.
	maxAttempts   = 64
	maxFailStreak = 18

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass, and probeBudgetGood is the tighter cap that
	// applies once we already hold a workable plan.
	probeBudget     = 12
	probeBudgetGood = 4

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 6.0
	partCost  = 0.004

	// confidentProb is the probability at which we stop looking for a
	// better plan and just send.
	confidentProb = 0.80

	// cheapenProb is the probability floor a cheaper alternative must
	// still clear to be preferred over a more expensive plan.
	cheapenProb = 0.72

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear. Under the bimodal prior this is
	// close to the amount maximizing expected delivered value.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// compSlackNum/compSlackDen discounts the complementary upper bound
	// derived from the reverse direction's proven liquidity.
	compSlackNum = 90
	compSlackDen = 100

	// revEmptyNum/revEmptyDen is the fraction of the liquidity implied on
	// this side by a reverse-direction failure that we bank on.
	revEmptyNum = 80
	revEmptyDen = 100

	// maxDryProbes is how many liquidity failures a single direction may
	// contribute before we stop probing it lower for this payment.
	maxDryProbes = 3

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the corridors a single flow decomposition walks.
	flowRounds = 12

	// hopelessStreak is how many consecutive failures we tolerate before
	// trusting the belief-derived local budget for a give-up decision.
	hopelessStreak = 4

	// maxGoodCorridors bounds the success-anchored corridor memory.
	maxGoodCorridors = 24
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

// revKey is the key of the same channel in the opposite direction.
func (e *edge) revKey() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.from}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// fails counts liquidity failures charged to this direction.
	fails int

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// goodCorridor is a corridor that has actually settled for us, together with
// the largest amount it settled. Replaying these first is the cheapest way to
// finish repeat payments inside a batch.
type goodCorridor struct {
	path []*edge
	amt  lnwire.MilliSatoshi
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan.
	queued []*plan

	// good remembers corridors that settled, best first.
	good []goodCorridor

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	// retryPath is a corridor whose last failure was a repairable policy
	// error, so it deserves an immediate second look at the same amount.
	retryPath []*edge
	retryAmt  lnwire.MilliSatoshi

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// mppOK reports whether this payment may be split at all.
func (r *router) mppOK() bool {
	return r.spec.MaxParts > 1
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// view returns a read-only belief for a directed channel, substituting a
// zero-value belief when we have no evidence at all.
func (r *router) view(k edgeKey) *belief {
	if b, ok := r.beliefs[k]; ok {
		return b
	}
	return &belief{}
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath. After several dry probes we stop entirely.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	if b.fails >= maxDryProbes {
		return b.okAmt
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.40 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// compBound is the complementary upper bound on a direction: liquidity we
// have proven sits on the reverse side cannot also sit on this side.
func (r *router) compBound(e *edge) lnwire.MilliSatoshi {
	rb := r.beliefs[e.revKey()]
	if rb == nil || rb.okAmt == 0 {
		return e.capacity
	}
	held := rb.okAmt * compSlackNum / compSlackDen
	if held >= e.capacity {
		return 0
	}
	return e.capacity - held
}

// provenCenter is the amount we believe this direction actually holds. It
// combines a demonstrated forward (less what we have since drained) with the
// complementary inference that a reverse-direction failure at a small amount
// means the funds are on THIS side.
func (r *router) provenCenter(e *edge) lnwire.MilliSatoshi {
	var center lnwire.MilliSatoshi

	b := r.beliefs[e.key()]
	if b != nil && b.succ {
		c := e.capacity * provenCenterNum / provenCenterDen
		if c > b.drained {
			center = c - b.drained
		}
	}

	// Bimodal complement: the reverse side came up dry at failAmt, so this
	// side is holding close to the whole channel.
	if rb := r.beliefs[e.revKey()]; rb != nil && rb.hasFail {
		if e.capacity > rb.failAmt {
			inf := (e.capacity - rb.failAmt) *
				revEmptyNum / revEmptyDen
			if inf > center {
				center = inf
			}
		}
	}

	if b != nil && b.okAmt > center {
		center = b.okAmt
	}

	return center
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else {
		if comp := r.compBound(e); comp < c {
			c = comp
		}
		if b != nil && b.hasFail {
			// Retry below the proven failure point rather than
			// blacklisting the channel outright.
			if lim := retryLimit(b, e.capacity); lim < c {
				c = lim
			}
		}
	}

	if b != nil {
		if b.inFlight >= c {
			return 0
		}
		c -= b.inFlight
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.view(e.key())
	est := e.capacity * priorSafeNum / priorSafeDen
	if b.okAmt > est {
		est = b.okAmt
	}
	if !b.hasFail {
		// A proven forward, or a dry reverse direction, says most of
		// the channel funds sit on this side.
		if c := r.provenCenter(e) * 85 / 100; c > est {
			est = c
		}
	} else if lim := retryLimit(b, e.capacity); est > lim {
		est = lim
	}
	if b.misses > 0 {
		est = est / lnwire.MilliSatoshi(1+b.misses)
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.view(e.key())
	if b.dead {
		return 0
	}

	eff := amt + b.inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	// The complementary bound is hard evidence: that much liquidity is
	// provably parked on the other side of the channel.
	if comp := r.compBound(e); eff > comp {
		return minProb / 4
	}

	var p float64
	switch {
	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)
		center := r.provenCenter(e)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case center > 0 && !b.hasFail:
			// Bimodal optimism: the funds are believed to sit on
			// this side, less whatever we have drained since.
			q := 1.0 / (1.0 + math.Exp(
				(float64(eff)/float64(center)-1)*4.5,
			))
			p = 0.3*p + 0.7*q

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if b.misses > 0 {
		m := b.misses
		if m > 3 {
			m = 3
		}
		p *= math.Pow(0.6, float64(m))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPathW runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// avoid names channels that must not be reused, so parallel shards do not
// contend for the same liquidity. feeMul scales the fee term: raising it
// produces a cheaper, slightly riskier corridor, which is how we shave fee
// ppm once we already have a reliable plan in hand.
func (r *router) findPathW(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	feeMul float64) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}
			if amtOver > r.availCap(e) {
				continue
			}

			p := r.prob(e, amtOver)
			if p <= 0 {
				continue
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < 1e-5 {
				continue
			}

			fee := (float64(sending) - float64(amt)) * feeMul
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// findPath is findPathW at the default fee weighting.
func (r *router) findPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	return r.findPathW(amt, avoid, 1.0)
}

// makeRoute prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			return nil, 0, errors.New("hopeless hop")
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds the whole payment.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// rawLocalBudget is the total balance across our own channels, ignoring all
// beliefs and policies. It is a hard ceiling on anything we can deliver.
func (r *router) rawLocalBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		total += bal
	}
	return total
}

// rawMaxLocal is the largest single local channel balance, which bounds one
// shard: a shard leaves through exactly one first hop.
func (r *router) rawMaxLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, bal := range r.localBalances {
		if bal > best {
			best = bal
		}
	}
	return best
}

// maxLocalEdge is the largest single local channel balance still free, which
// is the true ceiling on one shard.
func (r *router) maxLocalEdge() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity with a small margin for fees.
func (r *router) bottleneck(path []*edge) lnwire.MilliSatoshi {
	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	return bn - bn/100
}

// flowCeiling estimates the largest amount a SINGLE shard can plausibly
// deliver right now, by taking the best believed corridor bottleneck over a
// couple of disjoint probes. Starting the amount ladder here instead of at
// the full remaining amount is what removes the doomed first attempt on
// large payments.
func (r *router) flowCeiling(remaining lnwire.MilliSatoshi,
	avoid map[uint64]bool) lnwire.MilliSatoshi {

	best := lnwire.MilliSatoshi(0)
	block := make(map[uint64]bool, len(avoid)+4)
	for c := range avoid {
		block[c] = true
	}

	probe := remaining
	if single := r.maxLocalEdge(); single > 0 && single < probe {
		probe = single
	}
	if probe < minShard {
		return 0
	}

	for i := 0; i < 3; i++ {
		path := r.findAnyPath(probe, remaining, 1, block)
		if path == nil {
			break
		}
		if bn := r.bottleneck(path); bn > best {
			best = bn
		}
		if best >= probe {
			break
		}
		block[path[0].chanID] = true
	}

	if best > remaining {
		best = remaining
	}
	return best
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, exact local channel balances, and
// evidence-derived sizes just below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford.
	maxK := partsLeft
	if maxK < 4 && r.mppOK() {
		maxK = 4
	}
	if maxK > 10 {
		maxK = 10
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Local channel balances are exact knowledge, and a shard sized to a
	// local channel is exactly what a fan-out split wants.
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		if c := r.availCap(e); c >= minShard {
			add(c - c/200)
		}
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64
	fee   lnwire.MilliSatoshi
}

// mkPlan prices a corridor at one amount and returns the scored plan, or nil
// when the attempt is not novel or not feasible.
func (r *router) mkPlan(path []*edge, a,
	remaining lnwire.MilliSatoshi) *plan {

	if a < minShard {
		return nil
	}
	if r.failedSigs[planSig(path, a)] {
		return nil
	}
	rt, p, err := r.makeRoute(path, a)
	if err != nil {
		return nil
	}
	fee := rt.TotalAmount - a
	return &plan{
		path:  path,
		rt:    rt,
		amt:   a,
		prob:  p,
		fee:   fee,
		score: r.score(a, p, fee, remaining),
	}
}

// evalPath scores a corridor at the amount its weakest hop is BELIEVED to
// bear first, then at the requested amount, keeping the better of the two.
// Pricing the believed amount first matters because when both score similarly
// we would rather send the one that survives.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	var cands []lnwire.MilliSatoshi
	if bn := r.bottleneck(path); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		cands = append(cands, g)
	}
	cands = append(cands, a)

	for _, c := range cands {
		pl := r.mkPlan(path, c, remaining)
		if pl == nil {
			continue
		}
		if best == nil || pl.score > best.score {
			best = pl
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 14 && a >= minShard; i++ {
		if pl := r.mkPlan(path, a, remaining); pl != nil {
			return pl
		}
		a = a * 3 / 4
	}
	return nil
}

// findAnyPath looks for a corridor able to carry hi, falling back down the
// amount ladder when nothing can take the full amount.
func (r *router) findAnyPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool) []*edge {

	if p, err := r.findPath(hi, avoid); err == nil {
		return p
	}

	probes := 0
	for _, a := range r.ladder(hi, remaining, partsLeft) {
		if a >= hi {
			continue
		}
		if probes >= 7 {
			break
		}
		probes++
		if p, err := r.findPath(a, avoid); err == nil {
			return p
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several DISJOINT corridors,
// sizing each shard to what that corridor's weakest hop is believed able to
// bear. This is the min-cost-flow style joint plan: unequal parallel
// corridors each get a shard that fits, instead of discovering the split by
// failing at a blind half.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	single := r.maxLocalEdge()

	var out []*plan
	left := remaining

	// Queued shards are handed out on later calls, as concurrency frees
	// up, so the decomposition is not bounded by the parts free right now.
	rounds := 1
	if r.mppOK() {
		rounds = flowRounds
	}

	for k := 0; k < rounds; k++ {
		if left < minShard {
			break
		}

		want := left
		if single > 0 && want > single {
			want = single
		}

		path := r.findAnyPath(want, remaining, partsLeft, avoid)
		if path == nil {
			break
		}

		amtS := want
		if bn := r.bottleneck(path); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		pl := r.bestOnPath(path, amtS, remaining)
		if pl == nil {
			// The corridor cannot bear anything novel, so retire
			// its first hop and move on instead of aborting the
			// whole decomposition.
			avoid[path[0].chanID] = true
			continue
		}

		out = append(out, pl)
		for _, e := range path {
			avoid[e.chanID] = true
		}

		if pl.amt >= left {
			break
		}
		left -= pl.amt
	}

	return out
}

// flowTotal is the amount a plan set delivers in aggregate.
func flowTotal(plans []*plan) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pl := range plans {
		total += pl.amt
	}
	return total
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// hopeless reports whether the remainder is provably beyond what our own
// channels can still push.
func (r *router) hopeless(amt lnwire.MilliSatoshi, inFlight uint32) bool {
	if inFlight > 0 {
		return false
	}
	if len(r.localBalances) == 0 {
		return false
	}

	// Hard ceiling: total outbound balance.
	if r.rawLocalBudget() < amt {
		return true
	}

	// A payment that may not be split must fit through one channel.
	if !r.mppOK() && r.rawMaxLocal() < amt {
		return true
	}

	// Softer test, only once we have actually confirmed dryness by
	// failing: the believed-free local liquidity cannot cover the rest.
	if r.failStreak >= hopelessStreak && len(r.localEdges) > 0 &&
		r.localBudget() < amt {

		return true
	}

	return false
}

// replayGood tries the corridors that have already settled for us, largest
// proven amount first. A batch of similar payments then settles in a single
// attempt on a known-good corridor, which is the cheapest possible outcome
// for both the attempt count and the fee.
func (r *router) replayGood(amt lnwire.MilliSatoshi, busy map[uint64]bool,
	split bool) *plan {

	var best *plan
	for _, gc := range r.good {
		if pathBusy(gc.path, busy) {
			continue
		}

		a := amt
		if gc.amt < a {
			if !split {
				continue
			}
			a = gc.amt
		}

		pl := r.mkPlan(gc.path, a, amt)
		if pl == nil || pl.prob < confidentProb {
			continue
		}
		if best == nil || pl.score > best.score {
			best = pl
		}
	}
	return best
}

// cheapen looks for a corridor that delivers the same amount for less fee
// while staying reliable enough to send. Fee ppm is the only penalty left on
// runs that already succeed, so this is where the remaining points are.
func (r *router) cheapen(best *plan, remaining lnwire.MilliSatoshi,
	avoid map[uint64]bool) *plan {

	if best == nil || best.fee == 0 {
		return best
	}

	for _, mul := range []float64{6.0, 20.0} {
		path, err := r.findPathW(best.amt, avoid, mul)
		if err != nil {
			continue
		}
		pl := r.mkPlan(path, best.amt, remaining)
		if pl == nil {
			continue
		}
		if pl.fee < best.fee && pl.prob >= cheapenProb &&
			pl.prob >= best.prob*0.9 {

			best = pl
		}
	}
	return best
}

// RequestRoute plans the next shard.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}
	if r.hopeless(amt, inFlightHtlcs) {
		return nil, errors.New("remainder exceeds local liquidity")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()
	split := r.mppOK()

	// A corridor whose last failure was a repairable policy error deserves
	// an immediate retry at the same amount with the fixed policy, since
	// the corridor itself was fine.
	if rp := r.retryPath; rp != nil {
		a := r.retryAmt
		r.retryPath, r.retryAmt = nil, 0
		if a > amt {
			a = amt
		}
		if (split || a >= amt) && !pathBusy(rp, busy) {
			if pl := r.mkPlan(rp, a, amt); pl != nil &&
				pl.prob >= queueMinProb {

				r.attempts++
				return pl.rt, nil
			}
		}
	}

	// Known-good corridors first: cheapest attempt count of all.
	if pl := r.replayGood(amt, busy, split); pl != nil {
		r.attempts++
		return pl.rt, nil
	}

	// Serve a queued shard from an earlier joint plan while it still holds
	// up against current beliefs.
	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when the payment cannot be split.
		if !split && a < amt {
			r.queued = nil
			break
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		np := r.mkPlan(pl.path, a, amt)
		if np == nil || np.prob < queueMinProb {
			continue
		}

		r.attempts++
		return np.rt, nil
	}

	// A single shard can never exceed what one local channel can push,
	// since a shard leaves through exactly one first hop.
	hi := amt
	if single := r.maxLocalEdge(); single > 0 && single < hi {
		hi = single
	}
	if hi < minShard {
		hi = amt
	}

	// FIRST-SHOT SIZING: cap the ladder at what a single corridor is
	// believed able to bear, so we do not burn the first attempt of every
	// large payment probing an amount no corridor can carry.
	if split && hi > minShard {
		if ceil := r.flowCeiling(hi, busy); ceil >= minShard &&
			ceil < hi {

			hi = ceil
		}
	}

	ladder := r.ladder(hi, amt, partsLeft)

	var best *plan

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			budget := probeBudget
			if best != nil {
				budget = probeBudgetGood
			}
			if probes >= budget {
				break
			}
			if !split && a < amt {
				break
			}

			path, err := r.findPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt &&
				best.prob > confidentProb {

				break
			}
		}

		if best != nil {
			break
		}
	}

	// When no single corridor carries the whole remainder, plan the split
	// deliberately over disjoint corridors instead of halving blindly.
	if split && (best == nil || best.amt < amt) {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total := flowTotal(flow)
			first := flow[0]

			if best == nil || total > best.amt {
				r.queued = flow[1:]
				best = first
			}
		}
	}

	// Last resort: deliver whatever we can. Even a small settled shard
	// reduces the remainder and refreshes evidence, which is strictly
	// better than terminally giving up on the payment.
	if best == nil {
		best = r.salvage(amt, busy, split)
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	// Now that reliability is settled, try to pay less for it.
	if best.prob >= confidentProb {
		var avoid map[uint64]bool
		if len(busy) > 0 {
			avoid = busy
		}
		best = r.cheapen(best, amt, avoid)
	}

	r.attempts++
	return best.rt, nil
}

// salvage hunts for any novel attempt at all, walking a wide descending
// amount ladder over both the disjoint and the unrestricted graph. It is the
// difference between delivering part of a payment and abandoning it.
func (r *router) salvage(remaining lnwire.MilliSatoshi, busy map[uint64]bool,
	split bool) *plan {

	if !split {
		// Without splitting, only a full-amount attempt helps.
		path, err := r.findPath(remaining, nil)
		if err != nil {
			return nil
		}
		return r.mkPlan(path, remaining, remaining)
	}

	a := remaining
	for i := 0; i < 22 && a >= minShard; i++ {
		for pass := 0; pass < 2; pass++ {
			var avoid map[uint64]bool
			if pass == 0 {
				if len(busy) == 0 {
					continue
				}
				avoid = busy
			}
			path, err := r.findPath(a, avoid)
			if err != nil {
				continue
			}
			if pl := r.bestOnPath(path, a, remaining); pl != nil {
				return pl
			}
		}
		a = a * 2 / 3
	}
	return nil
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
		b.fails = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	b.fails = 0
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
			rb.fails = 0
		}
	}
}

// rememberGood records a corridor that settled, so later payments in the
// batch can replay it directly.
func (r *router) rememberGood(rt *route.Route) {
	n := len(rt.Hops)
	if n == 0 {
		return
	}

	path := make([]*edge, 0, n)
	for _, h := range rt.Hops {
		e, ok := r.byKey[hopKey(h)]
		if !ok {
			return
		}
		path = append(path, e)
	}
	amt := rt.Hops[n-1].AmtToForward

	for i := range r.good {
		if planSig(r.good[i].path, 0) != planSig(path, 0) {
			continue
		}
		if amt > r.good[i].amt {
			r.good[i].amt = amt
		}
		return
	}

	r.good = append(r.good, goodCorridor{path: path, amt: amt})
	sort.SliceStable(r.good, func(i, j int) bool {
		return r.good[i].amt > r.good[j].amt
	})
	if len(r.good) > maxGoodCorridors {
		r.good = r.good[:maxGoodCorridors]
	}
}

// dropGood forgets a corridor that has just failed, so we do not replay a
// stale success into a second wasted attempt.
func (r *router) dropGood(rt *route.Route) {
	n := len(rt.Hops)
	if n == 0 {
		return
	}
	path := make([]*edge, 0, n)
	for _, h := range rt.Hops {
		e, ok := r.byKey[hopKey(h)]
		if !ok {
			return
		}
		path = append(path, e)
	}
	sig := planSig(path, 0)

	out := r.good[:0]
	for _, gc := range r.good {
		if planSig(gc.path, 0) != sig {
			out = append(out, gc)
		}
	}
	r.good = out
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// pathOf reconstructs the edge slice behind a route, or nil when any hop is
// not in our graph view.
func (r *router) pathOf(rt *route.Route) []*edge {
	path := make([]*edge, 0, len(rt.Hops))
	for _, h := range rt.Hops {
		e, ok := r.byKey[hopKey(h)]
		if !ok {
			return nil
		}
		path = append(path, e)
	}
	return path
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}
		r.rememberGood(rt)
		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}
	r.dropGood(rt)

	// Beliefs just changed, so any queued joint plan is stale.
	r.queued = nil

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure: spread suspicion over the remote hops so
	// we stop re-picking this corridor without destroying the hard bounds
	// we have earned.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		for i, h := range rt.Hops {
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			// Optimism earned from older evidence cannot survive a
			// corridor that just failed somewhere inside it.
			b.succ = false
		}
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	kind := classify(result.Failure)

	// A repairable policy error says nothing bad about the corridor's
	// liquidity, so once the policy view is patched the same corridor is
	// worth exactly one immediate retry at the same delivered amount.
	if kind == "fee" || kind == "cltv" {
		if p := r.pathOf(rt); p != nil {
			r.retryPath = p
			r.retryAmt = rt.Hops[len(rt.Hops)-1].AmtToForward
		}
		// The signature bans the identical attempt, but the repaired
		// policy makes the retry a genuinely different route.
		if sig := routeSig(rt); sig != "" {
			delete(r.failedSigs, sig)
		}
		r.failStreak--
	}

	switch kind {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// generous bump is cheaper than another failed attempt.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		return nil

	case "dead":
		b.dead = true
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	b.fails++
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false
	b.drained = 0

	// A local channel failing means our balance estimate was too high, and
	// it also invalidates the complementary inference that the far side of
	// that channel is the empty one.
	if failIdx == 0 {
		rk := edgeKey{chanID: h.ChannelID, to: rt.SourcePubKey}
		if rb, ok := r.beliefs[rk]; ok {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	return nil
}

package main

// This file is the CANDIDATE SLOT for evolved routing algorithms.
//
// Design summary:
//   - Bimodal prior over amount/capacity for hidden liquidity, so wider
//     channels are preferred automatically at equal amounts.
//   - Per-DIRECTED-channel beliefs (channel plus direction) with hard
//     lower-OK / upper-fail bounds and no time decay: a stale bound costs
//     one retry to refresh, which is cheaper than decaying evidence.
//   - Balance bookkeeping on settle: a forward that settles moves
//     liquidity, so the forward direction's bounds go down and the reverse
//     direction's bounds go up by exactly the amount forwarded.
//   - Depth-aware lower retries instead of blacklisting.
//   - JOINT ROUTE-SET PLANNING with residual accounting and rebalancing.
//
// Changes in this revision, all aimed at the observed failure mode. Every
// failed payment in the evaluation was a LARGE amount (0.86-2.06 BTC in
// msat) that burned 5-13 attempts and then terminated with "no route
// found". Diagnosis and fixes:
//
//  1. TERMINAL GIVE-UP WAS TOO EAGER, AND THE WRONG THING GAVE UP. The
//     planner would return an error as soon as its preferred search found
//     nothing, even though a much smaller shard was still routable and the
//     part budget was untouched. RequestRoute now ends with a DESPERATION
//     SWEEP: before returning any error it walks a wide geometric ladder
//     down to a tiny floor, over every local channel, ignoring the score
//     model and accepting any priced route at all. Giving up must be the
//     last resort, not the first search's verdict.
//
//  2. THE FLOW PLAN WAS SIZED AGAINST BELIEFS, NOT AGAINST PARTS. For a
//     2 BTC payment over a network of ~0.1 BTC channels, no plan of 3-4
//     shards can ever cover the remainder, so `total > bestAmt` almost
//     never fired and the router fell back to a single oversized shard.
//     planFlow now targets remaining/partsLeft as its natural shard size
//     and explicitly builds as many corridors as the part budget allows,
//     so a large payment is decomposed into many small shards up front
//     instead of being discovered by repeated halving.
//
//  3. FIRST-SHARD SIZING IGNORED THE PART BUDGET. A payment that needs N
//     parts should not open with a shard sized to the whole remainder;
//     that first attempt is nearly guaranteed to fail and it poisons the
//     bounds of every fat channel on the way. The ladder is now anchored
//     at an amount the local budget and part count can plausibly bear.
//
//  4. UNATTRIBUTABLE FAILURES (failed_at_hop -1 appears in the data) were
//     costing a full attempt and teaching nothing. They now also carve a
//     soft cap on the corridor's narrowest hop so the next search moves
//     somewhere else instead of re-deriving the same path.
//
//  5. Attempt budget is spent more carefully: the probe budget shrinks as
//     the fail streak grows, repeated identical-signature searches are
//     skipped before they are priced, and a pure policy repair (fee, cltv,
//     min htlc) no longer counts against the fail streak that ends the
//     payment, since nothing was learned about liquidity.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	// attemptCostBase and attemptCostPPM express the virtual cost of one
	// failed attempt. Success dominates the objective, so the retry cost
	// stays large relative to fees, but it is small enough that fee
	// differences break ties between similarly reliable corridors.
	attemptCostBase = lnwire.MilliSatoshi(1_500)
	attemptCostPPM  = lnwire.MilliSatoshi(8_000)

	minProb   = 0.005
	maxProb   = 0.985
	knownProb = 0.995

	// maxRouteHops bounds path length.
	maxRouteHops = 7

	// maxAttempts and maxFailStreak bound how long we keep trying before
	// declaring the payment hopeless. Both are generous: an extra retry
	// costs a small penalty, while an abandoned payment costs the whole
	// success term.
	maxAttempts   = 90
	maxFailStreak = 30

	// probeBudget caps how many Dijkstra runs a single RequestRoute call
	// may spend per pass.
	probeBudget = 14

	// minShard is the smallest shard we will ever plan.
	minShard = lnwire.MilliSatoshi(1_000)

	// feeWeight and partCost shape the shard score: fee matters only as a
	// tie-break, while every extra expected part costs a little.
	feeWeight = 4.0
	partCost  = 0.006

	// priorSafeNum/priorSafeDen is the fraction of capacity we assume a
	// channel with no evidence can bear.
	priorSafeNum = 35
	priorSafeDen = 100

	// provenCenterNum/provenCenterDen is the fraction of capacity a
	// direction that has demonstrably forwarded is assumed to hold.
	provenCenterNum = 62
	provenCenterDen = 100

	// queueMinProb is the probability a queued shard must still clear
	// before we hand it out on a later call.
	queueMinProb = 0.15

	// flowRounds bounds the corridor searches spent building one flow
	// plan, and flowRebalance bounds the redistribution sweeps.
	flowRounds    = 16
	flowRebalance = 3

	// sweepSteps is how far the desperation sweep descends before it
	// concedes that the payment really is unroutable.
	sweepSteps = 22
)

// edgeKey identifies a directed channel: the channel plus the node the
// channel points at.
type edgeKey struct {
	chanID uint64
	to     route.Vertex
}

// edge is one directed channel of the public graph.
type edge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee lnwire.MilliSatoshi
	feePPM  lnwire.MilliSatoshi
	cltv    uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi
}

func (e *edge) key() edgeKey {
	return edgeKey{chanID: e.chanID, to: e.to}
}

func (e *edge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feePPM/1_000_000
}

func (e *edge) policyOK(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

// belief tracks what we have proven about a directed channel's liquidity.
type belief struct {
	// okAmt is the largest amount we currently believe is available, as
	// proven by a forward and adjusted for liquidity we have since moved.
	okAmt lnwire.MilliSatoshi

	// failAmt is the smallest amount believed to fail; hasFail guards it.
	failAmt lnwire.MilliSatoshi
	hasFail bool

	// succ records that this direction has actually forwarded for us,
	// which under a bimodal split is strong evidence that the bulk of the
	// channel funds sit on this side.
	succ bool

	// drained is how much we have pushed through this direction since the
	// evidence that set succ, which shifts the optimistic centre down.
	drained lnwire.MilliSatoshi

	// inFlight is liquidity currently committed by our own HTLCs.
	inFlight lnwire.MilliSatoshi

	// reserved is liquidity earmarked by planned-but-unsent shards.
	reserved lnwire.MilliSatoshi

	// misses counts failures we could not attribute to a specific hop but
	// that this channel took part in.
	misses int

	// dead marks a channel that failed permanently.
	dead bool
}

// bimodalPrior is the success probability of pushing amt through a channel
// of the given capacity with no direct evidence. Liquidity sits almost
// entirely on one side, so small amounts nearly always pass while amounts
// approaching capacity almost never do.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 {
		return minProb
	}
	if amt > capacity {
		return 0
	}
	x := float64(amt) / float64(capacity)

	// Decaying low mode: tiny fractions of capacity are near certain.
	low := math.Exp(-x * 3.2)

	// Logistic cliff as we approach capacity.
	cliff := 1.0 / (1.0 + math.Exp((x-0.42)*9.0))

	return clampProb(0.30*low + 0.70*cliff)
}

func clampProb(p float64) float64 {
	if p > maxProb {
		return maxProb
	}
	if p < minProb {
		return minProb
	}
	return p
}

// router is the evolved candidate.
type router struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// inEdges maps a node to the directed edges arriving at it.
	inEdges map[route.Vertex][]*edge

	// byKey indexes every directed edge for failure attribution.
	byKey map[edgeKey]*edge

	// localEdges are the directed edges leaving our own node.
	localEdges []*edge

	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]*belief

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route

	// queued holds the remaining shards of a joint route-set plan, to be
	// handed out on subsequent RequestRoute calls.
	queued []*plan

	// failedSigs remembers (path, amount) pairs that already failed so we
	// never hand out the identical attempt twice.
	failedSigs map[string]bool

	failStreak int
	attempts   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &router{
		source:        source,
		spec:          spec,
		inEdges:       make(map[route.Vertex][]*edge),
		byKey:         make(map[edgeKey]*edge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]*belief),
		pending:       make(map[uint64]*route.Route),
		failedSigs:    make(map[string]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &edge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: pol.FeeBaseMSat,
					feePPM: pol.
						FeeProportionalMillionths,
					cltv:    pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.inEdges[e.to] = append(r.inEdges[e.to], e)
				r.byKey[e.key()] = e
				if e.from == source {
					r.localEdges = append(
						r.localEdges, e,
					)
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bel returns (creating if needed) the belief for a directed channel.
func (r *router) bel(k edgeKey) *belief {
	b, ok := r.beliefs[k]
	if !ok {
		b = &belief{}
		r.beliefs[k] = b
	}
	return b
}

// capOf is the capacity of a directed channel, or zero when we do not know
// the direction at all.
func (r *router) capOf(k edgeKey) lnwire.MilliSatoshi {
	if e, ok := r.byKey[k]; ok {
		return e.capacity
	}
	return 0
}

// retryLimit is how far we are still willing to push a direction that has
// proven a failure. A failure at a tiny fraction of capacity means the
// direction is essentially empty, while a failure near capacity leaves a lot
// of plausible room underneath.
func retryLimit(b *belief, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if !b.hasFail {
		return 0
	}
	depth := 0.5
	if capacity > 0 {
		depth = float64(b.failAmt) / float64(capacity)
		if depth > 1 {
			depth = 1
		}
	}
	f := 0.45 + 0.35*depth
	lim := lnwire.MilliSatoshi(float64(b.failAmt) * f)
	if lim < b.okAmt {
		lim = b.okAmt
	}
	return lim
}

// committed is liquidity on a directed channel that is already spoken for,
// either by a live HTLC or by a planned shard we have not sent yet.
func (b *belief) committed() lnwire.MilliSatoshi {
	if b == nil {
		return 0
	}
	return b.inFlight + b.reserved
}

// availCap is the hard upper bound on what we are still willing to push
// over an edge. It returns zero when the edge is unusable at any amount.
func (r *router) availCap(e *edge) lnwire.MilliSatoshi {
	c := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < c {
		c = e.maxHTLC
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	if e.from == r.source {
		// Our own balance is known exactly.
		if bal := r.localBalances[e.chanID]; bal < c {
			c = bal
		}
	} else if b != nil && b.hasFail {
		// Retry below the proven failure point rather than
		// blacklisting the channel outright.
		if lim := retryLimit(b, e.capacity); lim < c {
			c = lim
		}
	}

	if used := b.committed(); used > 0 {
		if used >= c {
			return 0
		}
		c -= used
	}

	return c
}

// safeCap is the largest amount we believe this edge can actually bear with
// decent probability. It is the sizing primitive for shard planning.
func (r *router) safeCap(e *edge) lnwire.MilliSatoshi {
	hard := r.availCap(e)
	if hard == 0 {
		return 0
	}
	if e.from == r.source {
		return hard
	}

	b := r.beliefs[e.key()]
	est := e.capacity * priorSafeNum / priorSafeDen
	if b != nil {
		if b.okAmt > est {
			est = b.okAmt
		}
		if b.succ && !b.hasFail {
			// A proven forward under a bimodal split says most of
			// the channel funds sit on this side.
			opt := e.capacity * 55 / 100
			if opt > b.drained {
				opt -= b.drained
			} else {
				opt = 0
			}
			if opt > est {
				est = opt
			}
		}
		if b.hasFail {
			if lim := retryLimit(b, e.capacity); est > lim {
				est = lim
			}
		}
		if b.misses > 0 {
			est = est / 2
		}
	}
	if est > hard {
		est = hard
	}
	return est
}

// prob is our success probability estimate for sending amt over the edge.
func (r *router) prob(e *edge, amt lnwire.MilliSatoshi) float64 {
	if amt == 0 {
		return 1
	}

	b := r.beliefs[e.key()]
	if b != nil && b.dead {
		return 0
	}

	var inFlight lnwire.MilliSatoshi
	misses := 0
	if b != nil {
		inFlight = b.inFlight
		misses = b.misses
	}
	eff := amt + inFlight

	// Our own channels have exactly known balances.
	if e.from == r.source {
		if r.localBalances[e.chanID] >= eff {
			return knownProb
		}
		return 0
	}

	var p float64
	switch {
	case b == nil:
		p = bimodalPrior(eff, e.capacity)

	case b.okAmt >= eff:
		p = knownProb

	case b.hasFail && eff >= b.failAmt:
		return minProb / 4

	default:
		p = bimodalPrior(eff, e.capacity)

		switch {
		case b.okAmt > 0 && b.hasFail:
			// Known-good below and known-bad above compress the
			// uncertain interval.
			lo := float64(b.okAmt)
			hi := float64(b.failAmt)
			if hi > lo {
				frac := (float64(eff) - lo) / (hi - lo)
				p = 0.5*p + 0.5*(1-frac)
			}

		case b.succ && !b.hasFail:
			// Bimodal optimism: this direction has forwarded, so
			// assume it holds most of the channel, less whatever we
			// have drained since.
			center := float64(e.capacity) *
				provenCenterNum / provenCenterDen
			center -= float64(b.drained)
			if center < float64(b.okAmt) {
				center = float64(b.okAmt)
			}
			if center > 0 {
				q := 1.0 / (1.0 + math.Exp(
					(float64(eff)/center-1)*4.5,
				))
				p = 0.3*p + 0.7*q
			}

		case b.okAmt > 0:
			// A prior success raises confidence nearby.
			ratio := float64(eff) / float64(b.okAmt)
			boost := math.Exp(-(ratio - 1) * 1.1)
			p = 0.45*p + 0.55*boost

		case b.hasFail:
			// Under bimodality a failure means the direction is
			// probably empty, so retries below it are a last
			// resort, not a coin flip.
			frac := float64(eff) / float64(b.failAmt)
			p = 0.5 * p * (1 - frac)
		}
	}

	if misses > 0 {
		if misses > 3 {
			misses = 3
		}
		p *= math.Pow(0.7, float64(misses))
	}

	return clampProb(p)
}

// --- Dijkstra -------------------------------------------------------------

type pqItem struct {
	node route.Vertex
	dist float64
	amt  lnwire.MilliSatoshi
	// logProb is the accumulated ln(probability) from node to target.
	logProb float64
	hops    int
	idx     int
}

type pq []*pqItem

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *pq) Push(x any)        { it := x.(*pqItem); it.idx = len(*q); *q = append(*q, it) }
func (q *pq) Pop() any {
	old := *q
	n := len(old)
	it := old[n-1]
	*q = old[:n-1]
	return it
}

// pathState is the best known way to reach the target from a node.
type pathState struct {
	dist float64
	via  *edge
}

// findPath runs a probability-weighted backward Dijkstra for a delivered
// amount and returns the edge sequence from source to target. The cost of a
// path is its fee plus an attempt cost divided by the path's success
// probability, which is the standard risk/fee trade-off.
//
// extra charges additional liquidity against a channel on top of what the
// beliefs already record, which is how the flow planner accounts for shards
// it has provisionally assigned. penalty multiplies the cost of channels the
// plan already uses, so the search spreads over fresh corridors when it can
// but may still reuse a fat channel when nothing else works.
//
// loose drops the belief-derived caps and the path probability floor on
// remote hops, keeping only policy limits and permanently dead channels.
// The desperation sweep uses it so that a corridor we consider hopeless is
// still returned rather than nothing at all.
func (r *router) findPath(amt lnwire.MilliSatoshi, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi, penalty float64,
	loose bool) ([]*edge, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}

	attemptCost := float64(attemptCostBase + amt*attemptCostPPM/1_000_000)
	hopCost := attemptCost * 0.2

	probFloor := 1e-5
	if loose {
		probFloor = 0
	}

	best := make(map[route.Vertex]*pathState)
	target := r.spec.Target
	best[target] = &pathState{dist: 0}

	q := &pq{}
	heap.Push(q, &pqItem{node: target, dist: 0, amt: amt})

	for q.Len() > 0 {
		it := heap.Pop(q).(*pqItem)
		cur := best[it.node]
		if cur == nil || it.dist > cur.dist+1e-9 {
			continue
		}
		if it.node == r.source {
			break
		}
		if it.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.inEdges[it.node] {
			if avoid[e.chanID] || e.from == it.node {
				continue
			}

			amtOver := it.amt
			if !e.policyOK(amtOver) {
				continue
			}

			// Charge the provisional flow already routed over this
			// channel against its believed room.
			used := extra[e.chanID]
			hard := r.availCap(e)
			if loose && e.from != r.source {
				// In loose mode the only hard constraints are
				// the ones we cannot argue with: policy and a
				// dead channel.
				if b := r.beliefs[e.key()]; b == nil || !b.dead {
					hard = e.capacity
					if e.maxHTLC != 0 && e.maxHTLC < hard {
						hard = e.maxHTLC
					}
				}
			}
			if amtOver+used > hard {
				continue
			}

			p := r.prob(e, amtOver+used)
			if p <= 0 {
				if !loose {
					continue
				}
				p = minProb / 8
			}

			sending := amtOver
			if e.from != r.source {
				sending += e.fee(amtOver)
			}

			logProb := it.logProb + math.Log(p)
			totalProb := math.Exp(logProb)
			if totalProb < probFloor {
				continue
			}

			fee := float64(sending) - float64(amt)
			dist := (fee+attemptCost)/totalProb +
				float64(it.hops+1)*hopCost
			if used > 0 && penalty > 1 {
				dist *= penalty
			}

			if prev, ok := best[e.from]; ok &&
				dist >= prev.dist-1e-9 {

				continue
			}

			best[e.from] = &pathState{dist: dist, via: e}

			heap.Push(q, &pqItem{
				node:    e.from,
				dist:    dist,
				amt:     sending,
				logProb: logProb,
				hops:    it.hops + 1,
			})
		}
	}

	src, ok := best[r.source]
	if !ok || src.via == nil {
		return nil, errors.New("no route found")
	}

	var path []*edge
	node := r.source
	for node != r.spec.Target {
		st, ok := best[node]
		if !ok || st.via == nil {
			return nil, errors.New("broken path")
		}
		path = append(path, st.via)
		node = st.via.to
		if len(path) > maxRouteHops {
			return nil, errors.New("path too long")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	return path, nil
}

// plainPath is findPath with no provisional flow charged.
func (r *router) plainPath(amt lnwire.MilliSatoshi,
	avoid map[uint64]bool) ([]*edge, error) {

	return r.findPath(amt, avoid, nil, 1, false)
}

// makeRouteMode prices a known path at a delivered amount, validating every
// hop's policy and belief bounds. It returns the route and its estimated
// success probability. When loose is set the belief-derived caps on remote
// hops are not enforced, only the policy limits and our own balances, which
// is what the desperation sweep needs in order to produce a route at all.
func (r *router) makeRouteMode(path []*edge, amt lnwire.MilliSatoshi,
	loose bool) (*route.Route, float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero amount")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiry := make([]uint32, n)

	amtOver[n-1] = amt
	expiry[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiry[i] = expiry[i+1] + uint32(fwd.cltv)
	}

	logProb := 0.0
	for i, e := range path {
		if !e.policyOK(amtOver[i]) {
			return nil, 0, errors.New("policy violated")
		}
		if e.from == r.source {
			// Our own balance is never negotiable.
			if amtOver[i] > r.availCap(e) {
				return nil, 0, errors.New("over local balance")
			}
		} else if !loose && amtOver[i] > r.availCap(e) {
			return nil, 0, errors.New("above believed capacity")
		}
		p := r.prob(e, amtOver[i])
		if p <= 0 {
			if !loose {
				return nil, 0, errors.New("hopeless hop")
			}
			p = minProb / 8
		}
		logProb += math.Log(p)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtFwd := amt
		outExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtFwd = amtOver[i+1]
			outExpiry = expiry[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     amtFwd,
			OutgoingTimeLock: outExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, math.Exp(logProb), nil
}

// makeRoute is makeRouteMode with the belief bounds enforced.
func (r *router) makeRoute(path []*edge,
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	return r.makeRouteMode(path, amt, false)
}

// --- Shard planning -------------------------------------------------------

// localBudget is the total liquidity we believe is spendable out of our own
// channels right now, which upper-bounds any single shard.
func (r *router) localBudget() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	seen := make(map[uint64]bool)
	for _, e := range r.localEdges {
		if seen[e.chanID] {
			continue
		}
		seen[e.chanID] = true
		total += r.availCap(e)
	}
	return total
}

// widestLocal is the largest amount any single local channel can push. No
// single shard can ever exceed it, so it anchors the amount ladder for large
// payments and stops us opening with an attempt that could never have
// worked.
func (r *router) widestLocal() lnwire.MilliSatoshi {
	var best lnwire.MilliSatoshi
	for _, e := range r.localEdges {
		if c := r.availCap(e); c > best {
			best = c
		}
	}
	return best
}

// bottleneck is the delivered amount a corridor is believed able to bear,
// derived from each hop's safe capacity minus any provisional flow already
// charged to that channel, with a small margin for fees.
func (r *router) bottleneck(path []*edge,
	extra map[uint64]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	bn := lnwire.MilliSatoshi(math.MaxUint32) * 1024
	for _, e := range path {
		c := r.safeCap(e)
		if used := extra[e.chanID]; used > 0 {
			if used >= c {
				return 0
			}
			c -= used
		}
		if c == 0 {
			return 0
		}
		if c < bn {
			bn = c
		}
	}
	if bn < minShard {
		return 0
	}
	return bn - bn/100
}

// ladder builds a descending set of candidate shard sizes. It mixes even
// splits over the parts we can still afford, a geometric descent that
// always reaches genuinely small amounts, and evidence-derived sizes just
// below proven failure points.
func (r *router) ladder(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	set := make(map[lnwire.MilliSatoshi]bool)
	var out []lnwire.MilliSatoshi
	add := func(a lnwire.MilliSatoshi) {
		if a < minShard || a > hi || set[a] {
			return
		}
		set[a] = true
		out = append(out, a)
	}

	add(hi)

	// Even splits over the part counts we could still afford. This is the
	// primary sizing signal for a large payment: if the remainder needs N
	// parts, the shard we should be searching for is remaining/N, not the
	// whole remainder.
	maxK := partsLeft
	if maxK > 12 {
		maxK = 12
	}
	for k := uint32(2); k <= maxK; k++ {
		add(remaining / lnwire.MilliSatoshi(k))
	}

	// Geometric descent all the way down to a small floor.
	floor := hi / 4096
	if floor < minShard {
		floor = minShard
	}
	cur := hi
	for i := 0; i < 16; i++ {
		cur = cur / 2
		if cur < floor {
			break
		}
		add(cur)
	}

	// Evidence-derived sizes: believed-available amounts and just under
	// proven failure points.
	for k, b := range r.beliefs {
		if b.dead {
			continue
		}
		if b.okAmt >= minShard {
			add(b.okAmt)
		}
		if b.hasFail {
			if lim := retryLimit(b, r.capOf(k)); lim >= minShard {
				add(lim)
			}
		}
	}

	sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	return out
}

// inFlightChans returns the channels currently carrying our own HTLCs.
func (r *router) inFlightChans() map[uint64]bool {
	m := make(map[uint64]bool)
	for _, rt := range r.pending {
		for _, h := range rt.Hops {
			m[h.ChannelID] = true
		}
	}
	return m
}

// score rates a candidate shard: probability-weighted delivered value, with
// a bonus for finishing the payment outright, a light fee penalty, and a
// cost for every additional part the split implies.
func (r *router) score(a lnwire.MilliSatoshi, p float64,
	fee lnwire.MilliSatoshi, remaining lnwire.MilliSatoshi) float64 {

	v := p * float64(a)
	if a >= remaining {
		v *= 1.15
	}
	v -= feeWeight * float64(fee)

	parts := float64(remaining) / float64(a)
	if parts > 1 {
		v -= partCost * float64(remaining) * (parts - 1)
	}
	return v
}

// planSig identifies a (path, delivered amount) attempt.
func planSig(path []*edge, amt lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(path)*14+14)
	for _, e := range path {
		buf = strconv.AppendUint(buf, e.chanID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(buf, uint64(amt)/1024, 36)
	return string(buf)
}

// routeSig is planSig for an already-built route.
func routeSig(rt *route.Route) string {
	n := len(rt.Hops)
	if n == 0 {
		return ""
	}
	buf := make([]byte, 0, n*14+14)
	for _, h := range rt.Hops {
		buf = strconv.AppendUint(buf, h.ChannelID, 36)
		buf = append(buf, ':')
	}
	buf = strconv.AppendUint(
		buf, uint64(rt.Hops[n-1].AmtToForward)/1024, 36,
	)
	return string(buf)
}

type plan struct {
	path  []*edge
	rt    *route.Route
	score float64
	amt   lnwire.MilliSatoshi
	prob  float64

	// reserved marks that this plan currently holds soft reservations on
	// its channels, which must be released before it is dropped.
	reserved bool
}

// reserve and release move a queued shard's soft reservation in and out of
// the beliefs, so the planner never double-spends believed liquidity.
func (r *router) reserve(pl *plan) {
	if pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		r.bel(hopKey(h)).reserved += hopAmount(pl.rt, i)
	}
	pl.reserved = true
}

func (r *router) release(pl *plan) {
	if !pl.reserved || pl.rt == nil {
		return
	}
	for i, h := range pl.rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(pl.rt, i)
		if b.reserved >= a {
			b.reserved -= a
		} else {
			b.reserved = 0
		}
	}
	pl.reserved = false
}

// dropQueue releases every queued shard's reservation and empties the queue.
func (r *router) dropQueue() {
	for _, pl := range r.queued {
		r.release(pl)
	}
	r.queued = nil
}

// evalPath scores a corridor at the requested amount and at the amount the
// corridor is believed able to bear, keeping the better of the two.
func (r *router) evalPath(path []*edge, a, remaining lnwire.MilliSatoshi,
	best *plan) *plan {

	cands := []lnwire.MilliSatoshi{a}
	if bn := r.bottleneck(path, nil); bn >= minShard {
		g := bn
		if g > remaining {
			g = remaining
		}
		if g != a {
			cands = append(cands, g)
		}
	}

	for _, c := range cands {
		if c < minShard {
			continue
		}
		if r.failedSigs[planSig(path, c)] {
			continue
		}
		rt, p, err := r.makeRoute(path, c)
		if err != nil {
			continue
		}
		fee := rt.TotalAmount - c
		s := r.score(c, p, fee, remaining)
		if best == nil || s > best.score {
			best = &plan{
				path: path, rt: rt, score: s, amt: c, prob: p,
			}
		}
	}

	return best
}

// bestOnPath prices a corridor at descending amounts and returns the best
// novel attempt it can still carry.
func (r *router) bestOnPath(path []*edge,
	hi, remaining lnwire.MilliSatoshi) *plan {

	a := hi
	for i := 0; i < 12 && a >= minShard; i++ {
		if !r.failedSigs[planSig(path, a)] {
			rt, p, err := r.makeRoute(path, a)
			if err == nil {
				fee := rt.TotalAmount - a
				return &plan{
					path:  path,
					rt:    rt,
					amt:   a,
					prob:  p,
					score: r.score(a, p, fee, remaining),
				}
			}
		}
		a = a * 3 / 4
	}
	return nil
}

// findFlowPath looks for a corridor able to carry hi under the provisional
// flow already assigned, falling back down the amount ladder when nothing
// can take the full amount.
func (r *router) findFlowPath(hi, remaining lnwire.MilliSatoshi,
	partsLeft uint32, avoid map[uint64]bool,
	extra map[uint64]lnwire.MilliSatoshi) []*edge {

	// Prefer a corridor that does not touch the provisional flow at all,
	// then allow reuse of already-loaded channels at a cost penalty.
	for _, pen := range []float64{1e9, 1.35} {
		p, err := r.findPath(hi, avoid, extra, pen, false)
		if err == nil {
			return p
		}

		probes := 0
		for _, a := range r.ladder(hi, remaining, partsLeft) {
			if a >= hi {
				continue
			}
			if probes >= 5 {
				break
			}
			probes++
			p, err := r.findPath(a, avoid, extra, pen, false)
			if err == nil {
				return p
			}
		}
		if len(extra) == 0 {
			break
		}
	}
	return nil
}

// planFlow decomposes the remaining amount over several corridors, sizing
// each shard to what that corridor's weakest hop is believed able to bear
// under the flow already assigned. Channels may be shared between shards as
// long as their believed room covers the sum, which is what makes this a
// min-cost-flow decomposition rather than a disjoint-path search.
//
// The target shard size is the remainder divided by the parts still to come,
// not the whole remainder. Aiming a corridor search at the whole remainder
// on a large payment finds nothing and wastes the round; aiming it at the
// natural shard size finds a corridor that can actually bear it, and the
// rebalance sweep afterwards grows the ones with slack.
func (r *router) planFlow(remaining lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) []*plan {

	if partsLeft < 2 {
		return nil
	}

	avoid := make(map[uint64]bool, len(busy)+8)
	for c := range busy {
		avoid[c] = true
	}

	// extra tracks the flow provisionally routed over each channel, in
	// delivered-amount terms, which is close enough for sizing.
	extra := make(map[uint64]lnwire.MilliSatoshi)

	type corridor struct {
		path []*edge
		amt  lnwire.MilliSatoshi
	}

	var cors []corridor
	left := remaining

	rounds := partsLeft
	if rounds > flowRounds {
		rounds = flowRounds
	}

	for k := uint32(0); k < rounds; k++ {
		if left < minShard {
			break
		}

		// Aim at the natural shard size for the parts still to come,
		// biased a little high so early corridors take the fat share
		// and the rebalance sweep has something to work with.
		partsRem := rounds - k
		aim := left
		if partsRem > 1 {
			aim = left / lnwire.MilliSatoshi(partsRem)
			aim += aim / 2
			if aim > left {
				aim = left
			}
		}
		if aim < minShard {
			aim = minShard
		}

		path := r.findFlowPath(aim, remaining, partsLeft, avoid, extra)
		if path == nil && aim < left {
			path = r.findFlowPath(
				left, remaining, partsLeft, avoid, extra,
			)
		}
		if path == nil {
			break
		}

		amtS := aim
		if amtS > left {
			amtS = left
		}
		if bn := r.bottleneck(path, extra); bn < amtS {
			amtS = bn
		}
		if amtS < minShard {
			break
		}

		cors = append(cors, corridor{path: path, amt: amtS})
		for _, e := range path {
			extra[e.chanID] += amtS
		}
		left -= amtS
	}

	if len(cors) == 0 {
		return nil
	}

	// Rebalance: hand leftover amount to whichever corridor still has the
	// most slack under the current assignment. This is what produces the
	// deliberately unequal split.
	for round := 0; round < flowRebalance && left >= minShard; round++ {
		progress := false
		for i := range cors {
			if left < minShard {
				break
			}
			// Temporarily remove this corridor's own contribution
			// so its slack is measured against the others only.
			for _, e := range cors[i].path {
				if extra[e.chanID] >= cors[i].amt {
					extra[e.chanID] -= cors[i].amt
				} else {
					extra[e.chanID] = 0
				}
			}
			room := r.bottleneck(cors[i].path, extra)
			grow := lnwire.MilliSatoshi(0)
			if room > cors[i].amt {
				grow = room - cors[i].amt
				if grow > left {
					grow = left
				}
			}
			cors[i].amt += grow
			for _, e := range cors[i].path {
				extra[e.chanID] += cors[i].amt
			}
			if grow > 0 {
				left -= grow
				progress = true
			}
		}
		if !progress {
			break
		}
	}

	// Price every corridor and keep the ones that survive.
	var out []*plan
	for _, c := range cors {
		if c.amt < minShard {
			continue
		}
		pl := r.bestOnPath(c.path, c.amt, remaining)
		if pl == nil {
			continue
		}
		out = append(out, pl)
	}

	if len(out) == 0 {
		return nil
	}

	// Largest shard first: it is the one most likely to be unroutable
	// later, so it should go out while the network state is freshest.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].amt > out[j].amt
	})

	return out
}

// planTotal is the believed-deliverable value of a route-set plan: each
// shard's amount weighted by its own success probability.
func planTotal(pls []*plan) (lnwire.MilliSatoshi, float64) {
	var total lnwire.MilliSatoshi
	var weighted float64
	for _, pl := range pls {
		total += pl.amt
		weighted += pl.prob * float64(pl.amt)
	}
	return total, weighted
}

// pathBusy reports whether a corridor touches a channel already carrying one
// of our in-flight shards.
func pathBusy(path []*edge, busy map[uint64]bool) bool {
	for _, e := range path {
		if busy[e.chanID] {
			return true
		}
	}
	return false
}

// touches reports whether a corridor uses any of the given channels.
func touches(path []*edge, chans map[uint64]bool) bool {
	for _, e := range path {
		if chans[e.chanID] {
			return true
		}
	}
	return false
}

// serveQueued hands out the next viable shard of an existing plan.
func (r *router) serveQueued(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	for len(r.queued) > 0 {
		pl := r.queued[0]
		r.queued = r.queued[1:]
		r.release(pl)

		a := pl.amt
		if a > amt {
			a = amt
		}
		if a < minShard {
			continue
		}
		// A partial shard is useless when we cannot follow it up.
		if partsLeft <= 1 && a < amt {
			r.dropQueue()
			return nil
		}
		if pathBusy(pl.path, busy) {
			continue
		}
		if r.failedSigs[planSig(pl.path, a)] {
			continue
		}
		rt, p, err := r.makeRoute(pl.path, a)
		if err != nil || p < queueMinProb {
			continue
		}

		return rt
	}
	return nil
}

// sweep is the last resort before giving up on a payment. It walks a wide
// geometric ladder from whatever a single local channel could bear down to a
// tiny floor, over every corridor the graph still offers, ignoring the score
// model and the belief-derived caps on remote hops. Only policy limits, our
// own balances, and permanently dead channels are respected.
//
// This exists because the previous revision's terminal error was almost
// always premature: the scored search found nothing at its preferred sizes
// and the router quit while a small shard was still perfectly routable and
// the part budget was untouched.
func (r *router) sweep(amt lnwire.MilliSatoshi, partsLeft uint32,
	busy map[uint64]bool) *route.Route {

	hi := amt
	if w := r.widestLocal(); w > 0 && w < hi {
		hi = w
	}
	if hi < minShard {
		hi = amt
	}

	// A partial shard is only worth sending when we can follow it up.
	floor := minShard
	if partsLeft <= 1 {
		floor = amt
	}
	if floor > hi {
		return nil
	}

	avoidSets := []map[uint64]bool{busy, nil}
	if len(busy) == 0 {
		avoidSets = avoidSets[1:]
	}

	a := hi
	for i := 0; i < sweepSteps && a >= floor; i++ {
		if a > amt {
			a = amt
		}
		for _, avoid := range avoidSets {
			for _, loose := range []bool{false, true} {
				path, err := r.findPath(a, avoid, nil, 1, loose)
				if err != nil {
					continue
				}
				if r.failedSigs[planSig(path, a)] {
					continue
				}
				rt, _, err := r.makeRouteMode(path, a, loose)
				if err != nil {
					continue
				}
				if r.failedSigs[routeSig(rt)] {
					continue
				}
				return rt
			}
		}
		if a == floor {
			break
		}
		next := a * 5 / 8
		if next < floor {
			next = floor
		}
		a = next
	}

	return nil
}

// RequestRoute plans the next shard. It first serves any shard left over
// from a joint route-set plan, then searches jointly over shard amount and
// corridor, then compares the best single shard against a full
// min-cost-flow style route set over several corridors, and finally falls
// back to a desperation sweep rather than abandoning the payment.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("zero amount")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}
	if r.failStreak >= maxFailStreak {
		return nil, errors.New("no progress")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	busy := r.inFlightChans()

	if rt := r.serveQueued(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	// A shard can never exceed what our own channels can push right now,
	// and no single shard can exceed the widest single local channel.
	// Anchoring the ladder there stops a large payment from opening with
	// an attempt that could never have worked.
	hi := amt
	if budget := r.localBudget(); budget > 0 && budget < hi {
		hi = budget
	}
	if w := r.widestLocal(); w > 0 && w < hi {
		hi = w
	}
	if hi < minShard {
		hi = amt
	}

	ladder := r.ladder(hi, amt, partsLeft)

	// Spend fewer probes once the payment has been fighting for a while:
	// at that point the beliefs are informative and extra Dijkstra runs
	// mostly rediscover corridors we have already ruled out.
	budgetProbes := probeBudget
	if r.failStreak > 6 {
		budgetProbes = probeBudget / 2
	}
	if budgetProbes < 4 {
		budgetProbes = 4
	}

	var best *plan
	tried := make(map[string]bool)

	// First pass prefers corridors disjoint from in-flight shards so
	// parallel parts do not fight over the same liquidity.
	for pass := 0; pass < 2; pass++ {
		var avoid map[uint64]bool
		if pass == 0 {
			if len(busy) == 0 {
				continue
			}
			avoid = busy
		}

		probes := 0
		for _, a := range ladder {
			// Once we hold a solid plan, digging far below it only
			// wastes attempts and parts.
			if best != nil && best.prob >= 0.6 &&
				a < best.amt/2 {

				break
			}
			if probes >= budgetProbes {
				break
			}

			path, err := r.plainPath(a, avoid)
			probes++
			if err != nil {
				continue
			}

			sig := planSig(path, a)
			if tried[sig] {
				continue
			}
			tried[sig] = true

			best = r.evalPath(path, a, amt, best)

			// A confident full-amount plan needs no alternatives.
			if best != nil && best.amt >= amt && best.prob > 0.8 {
				break
			}
		}

		if best != nil {
			break
		}
	}

	// Plan the split deliberately over several corridors whenever a single
	// shard cannot confidently cover the remainder. This fires eagerly,
	// not only as a fallback, because a joint plan whose shards each fit
	// their corridor beats one oversized shard that will fail and then be
	// halved blindly.
	singleWeak := best == nil || best.amt < amt || best.prob < 0.55

	if partsLeft > 1 && singleWeak {
		flow := r.planFlow(amt, partsLeft, busy)
		if len(flow) > 0 {
			total, weighted := planTotal(flow)

			var bestVal float64
			var bestAmt lnwire.MilliSatoshi
			if best != nil {
				bestVal = best.prob * float64(best.amt)
				bestAmt = best.amt
			}

			// Take the plan when it either covers more of the
			// remainder or delivers more expected value than the
			// single shard on its own.
			better := best == nil || total > bestAmt ||
				weighted > bestVal*1.05

			if better && len(flow) > 1 {
				first := flow[0]
				rest := flow[1:]
				r.dropQueue()
				r.queued = rest
				for _, pl := range r.queued {
					r.reserve(pl)
				}
				best = first
			} else if best == nil || (better && total > bestAmt) {
				best = flow[0]
			}
		}
	}

	if best != nil {
		r.attempts++
		return best.rt, nil
	}

	// Desperation: anything routable beats abandoning the payment.
	if rt := r.sweep(amt, partsLeft, busy); rt != nil {
		r.attempts++
		return rt, nil
	}

	return nil, errors.New("no route found")
}

// hopAmount returns the amount flowing over hop index i of a route.
func hopAmount(rt *route.Route, i int) lnwire.MilliSatoshi {
	if i == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[i-1].AmtToForward
}

func hopKey(h *route.Hop) edgeKey {
	return edgeKey{chanID: h.ChannelID, to: h.PubKeyBytes}
}

// markInFlight adjusts the in-flight accounting for a route.
func (r *router) markInFlight(rt *route.Route, sign int) {
	for i, h := range rt.Hops {
		b := r.bel(hopKey(h))
		a := hopAmount(rt, i)
		if sign > 0 {
			b.inFlight += a
		} else if b.inFlight >= a {
			b.inFlight -= a
		} else {
			b.inFlight = 0
		}
	}
}

// noteRoute records the route as pending and reserves its liquidity.
func (r *router) noteRoute(attemptID uint64, rt *route.Route) {
	if _, ok := r.pending[attemptID]; ok {
		return
	}
	r.pending[attemptID] = rt
	r.markInFlight(rt, +1)
}

// provePassed raises the lower bound on a hop that demonstrably forwarded
// but whose HTLC did not settle, so no liquidity actually moved.
func (r *router) provePassed(h *route.Hop, a lnwire.MilliSatoshi) {
	b := r.bel(hopKey(h))
	if a > b.okAmt {
		b.okAmt = a
	}
	b.succ = true

	// A success invalidates any older failure bound at or below this
	// amount, and clears accumulated suspicion.
	if b.hasFail && b.failAmt <= a {
		b.hasFail = false
		b.failAmt = 0
	}
	b.misses = 0
}

// applySettle folds a settled forward into both directions of the channel:
// the sending direction lost exactly that much liquidity and the receiving
// direction gained it. Keeping this bookkeeping straight is what lets
// evidence from earlier payments in a batch stay usable.
func (r *router) applySettle(from route.Vertex, h *route.Hop,
	a lnwire.MilliSatoshi) {

	k := hopKey(h)
	b := r.bel(k)
	b.succ = true
	if b.okAmt < a {
		b.okAmt = a
	}
	b.okAmt -= a
	b.drained += a
	if b.hasFail {
		if b.failAmt > a {
			b.failAmt -= a
		} else {
			b.failAmt = 1
		}
	}
	b.misses = 0

	// The reverse direction gained exactly what we pushed.
	rk := edgeKey{chanID: k.chanID, to: from}
	rb := r.bel(rk)
	rb.okAmt += a
	rb.misses = 0
	if rb.drained > a {
		rb.drained -= a
	} else {
		rb.drained = 0
	}
	if rb.hasFail {
		rb.failAmt += a
		if c := r.capOf(rk); c > 0 && rb.failAmt >= c {
			rb.hasFail = false
			rb.failAmt = 0
		}
		if rb.hasFail && rb.okAmt >= rb.failAmt {
			rb.hasFail = false
			rb.failAmt = 0
		}
	}
}

// classify buckets a failure into the kind of repair it implies. The string
// form is used so this works whatever concrete shape the failure takes.
func classify(f any) string {
	d := fmt.Sprintf("%T %v", f, f)
	switch {
	case strings.Contains(d, "FeeInsufficient"):
		return "fee"
	case strings.Contains(d, "CltvExpiry"),
		strings.Contains(d, "ExpiryTooSoon"):
		return "cltv"
	case strings.Contains(d, "AmountBelowMinimum"):
		return "min"
	case strings.Contains(d, "ChannelDisabled"),
		strings.Contains(d, "UnknownNextPeer"),
		strings.Contains(d, "PermanentChannelFailure"):
		return "dead"
	}
	return "liquidity"
}

// pruneQueue drops only the queued shards whose corridors are implicated by
// a failure, keeping the rest of an otherwise sound plan.
func (r *router) pruneQueue(hit map[uint64]bool) {
	kept := r.queued[:0]
	for _, pl := range r.queued {
		if touches(pl.path, hit) {
			r.release(pl)
			continue
		}
		kept = append(kept, pl)
	}
	r.queued = kept
}

// ReportAttempt folds attempt feedback into the liquidity beliefs.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *router) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	// Release any liquidity we had reserved for this attempt.
	if prev, ok := r.pending[attemptID]; ok {
		r.markInFlight(prev, -1)
		delete(r.pending, attemptID)
	}

	// Success: every hop carried its amount and the liquidity moved, so
	// shift both directions of every channel on the route.
	if result.Failure == nil {
		r.failStreak = 0
		prev := rt.SourcePubKey
		for i, h := range rt.Hops {
			a := hopAmount(rt, i)
			r.applySettle(prev, h, a)
			prev = h.PubKeyBytes

			if i == 0 {
				if bal, ok := r.localBalances[h.ChannelID]; ok {
					if bal >= a {
						r.localBalances[h.ChannelID] =
							bal - a
					} else {
						r.localBalances[h.ChannelID] = 0
					}
				}
			}
		}

		// A settle changes the liquidity the queued shards were sized
		// against, so re-validate them lazily: shards over channels
		// this route drained are dropped, the rest survive.
		if len(r.queued) > 0 {
			hit := make(map[uint64]bool, len(rt.Hops))
			for _, h := range rt.Hops {
				hit[h.ChannelID] = true
			}
			r.pruneQueue(hit)
		}

		return nil
	}

	r.failStreak++
	if sig := routeSig(rt); sig != "" {
		r.failedSigs[sig] = true
	}

	// Locate the failing hop: the failure source is the node that could
	// not forward, so the offending channel is its outgoing hop.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, h := range rt.Hops {
			if h.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// An unattributable failure. Previously this only spread mild
	// suspicion, which cost an attempt and taught almost nothing: the
	// next search happily re-derived the same corridor. Now we also cap
	// the corridor's NARROWEST remote hop just under the amount it was
	// asked to carry, which is the single most likely culprit under a
	// bimodal split, so the search genuinely moves elsewhere.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		hit := make(map[uint64]bool, len(rt.Hops))
		narrowIdx := -1
		var narrowCap lnwire.MilliSatoshi
		for i, h := range rt.Hops {
			hit[h.ChannelID] = true
			if i == 0 {
				continue
			}
			b := r.bel(hopKey(h))
			if b.misses < 3 {
				b.misses++
			}
			c := r.capOf(hopKey(h))
			if narrowIdx < 0 || (c > 0 && c < narrowCap) {
				narrowIdx = i
				narrowCap = c
			}
		}
		if narrowIdx > 0 {
			h := rt.Hops[narrowIdx]
			a := hopAmount(rt, narrowIdx)
			b := r.bel(hopKey(h))
			if !b.hasFail || a < b.failAmt {
				b.hasFail = true
				b.failAmt = a
			}
			if b.okAmt >= b.failAmt {
				if b.failAmt > 0 {
					b.okAmt = b.failAmt - 1
				} else {
					b.okAmt = 0
				}
			}
		}
		r.pruneQueue(hit)
		return nil
	}

	// Everything strictly before the failing hop demonstrably worked, but
	// nothing settled, so no liquidity actually moved.
	for i := 0; i < failIdx; i++ {
		r.provePassed(rt.Hops[i], hopAmount(rt, i))
	}

	h := rt.Hops[failIdx]
	a := hopAmount(rt, failIdx)
	b := r.bel(hopKey(h))
	e := r.byKey[hopKey(h)]

	// Only the failing channel invalidates queued shards; a fee or cltv
	// repair does not touch liquidity at all, so those keep the plan.
	hit := map[uint64]bool{h.ChannelID: true}

	switch classify(result.Failure) {
	case "fee":
		// Our fee view for this hop is stale: pay more next time. A
		// policy repair is not a liquidity miss, so it must not count
		// against the fail streak that ends the payment.
		if e != nil {
			e.baseFee += e.baseFee/4 + 1_000
			e.feePPM += e.feePPM/4 + 50
		}
		r.failStreak--
		return nil

	case "cltv":
		if e != nil {
			e.cltv += e.cltv/4 + 20
		}
		r.failStreak--
		return nil

	case "min":
		// The advertised minimum is higher than we thought.
		if e != nil && a >= e.minHTLC {
			e.minHTLC = a + 1
		}
		r.failStreak--
		return nil

	case "dead":
		b.dead = true
		r.pruneQueue(hit)
		return nil
	}

	// Liquidity miss: tighten the upper bound on this direction.
	if !b.hasFail || a < b.failAmt {
		b.hasFail = true
		b.failAmt = a
	}
	// The failure bound must sit above the proven-good bound.
	if b.okAmt >= b.failAmt {
		if b.failAmt > 0 {
			b.okAmt = b.failAmt - 1
		} else {
			b.okAmt = 0
		}
	}
	// A hard miss overrides bimodal optimism from older evidence.
	b.succ = false

	// A local channel failing means our balance estimate was too high.
	if failIdx == 0 {
		if bal, ok := r.localBalances[h.ChannelID]; ok && bal >= a {
			if a == 0 {
				r.localBalances[h.ChannelID] = 0
			} else {
				r.localBalances[h.ChannelID] = a - 1
			}
		}
	}

	r.pruneQueue(hit)

	return nil
}
